INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1462785,51,1,1,1,'태초에 하나님이 천지를 창조하시니라 !'),
(1462786,51,1,1,2,'땅이 혼돈하고 공허하며 흑암이 깊음 위에 있고 하나님의 신(神)은 수면에 운행하시니라'),
(1462787,51,1,1,3,'하나님이 가라사대 빛이 있으라 ! 하시매 빛이 있었고'),
(1462788,51,1,1,4,'그 빛이 하나님의 보시기에 좋았더라 하나님이 빛과 어두움을 나누사'),
(1462789,51,1,1,5,'빛을 낮이라 칭하시고 어두움을 밤이라 칭하시니라 저녁이 되며 아침이 되니 이는 첫째 날이니라'),
(1462790,51,1,1,6,'하나님이 가라사대 물 가운데 궁창이 있어 물과 물로 나뉘게 하리라 ! 하시고'),
(1462791,51,1,1,7,'하나님이 궁창을 만드사 궁창 아래의 물과 궁창 위의 물로 나뉘게 하시매 그대로 되니라'),
(1462792,51,1,1,8,'하나님이 궁창을 하늘이라 칭하시니라 저녁이 되며 아침이 되니 이는 둘째 날이니라'),
(1462793,51,1,1,9,'하나님이 가라사대 천하의 물이 한곳으로 모이고 뭍이 드러나라 ! 하시매 그대로 되니라'),
(1462794,51,1,1,10,'하나님이 뭍을 땅이라 칭하시고 모인 물을 바다라 칭하시니라 하나님의 보시기에 좋았더라'),
(1462795,51,1,1,11,'하나님이 가라사대 땅은 풀과 씨 맺는 채소와 각기 종류대로 씨 가진 열매 맺는 과목을 내라 하시매 그대로 되어'),
(1462796,51,1,1,12,'땅이 풀과 각기 종류대로 씨 맺는 채소와 각기 종류대로 씨 가진 열매 맺는 나무를 내니 하나님의 보시기에 좋았더라'),
(1462797,51,1,1,13,'저녁이 되며 아침이 되니 이는 세째 날이니라'),
(1462798,51,1,1,14,'하나님이 가라사대 하늘의 궁창에 광명이 있어 주야를 나뉘게 하라 또 그 광명으로 하여 징조와 사시와 일자와 연한이 이루라'),
(1462799,51,1,1,15,'또 그 광명이 하늘의 궁창에 있어 땅에 비취라 하시고 (그대로 되니라)'),
(1462800,51,1,1,16,'하나님이 두 큰 광명을 만드사 큰 광명으로 낮을 주관하게 하시고 작은 광명으로 밤을 주관하게 하시며 또 별들을 만드시고'),
(1462801,51,1,1,17,'하나님이 그것들을 하늘의 궁창에 두어 땅에 비취게 하시며'),
(1462802,51,1,1,18,'주야를 주관하게 하시며 빛과 어두움을 나뉘게 하시니라 하나님의 보시기에 좋았더라'),
(1462803,51,1,1,19,'저녁이 되며 아침이 되니 이는 네째 날이니라'),
(1462804,51,1,1,20,'하나님이 가라사대 물들은 생물로 번성케 하라 땅 위 하늘의 궁창에는 새가 날으라 하시고'),
(1462805,51,1,1,21,'하나님이 큰 물고기와 물에서 번성하여 움직이는 모든 생물을 그 종류대로, 날개 있는 모든 새를 그 종류대로 창조하시니 하나님의 보시기에 좋았더라'),
(1462806,51,1,1,22,'하나님이 그들에게 복을 주어 가라사대 생육하고 번성하여 여러 바다물에 충만하라 새들도 땅에 번성하라 하시니라'),
(1462807,51,1,1,23,'저녁이 되며 아침이 되니 이는 다섯째 날이니라'),
(1462808,51,1,1,24,'하나님이 가라사대 땅은 생물을 그 종류대로 내되 육축과 기는 것과 땅의 짐승을 종류대로 내라 하시고 (그대로 되니라)'),
(1462809,51,1,1,25,'하나님이 땅의 짐승을 그 종류대로, 육축을 그 종류대로, 땅에 기는 모든 것을 그 종류대로 만드시니 하나님의 보시기에 좋았더라'),
(1462810,51,1,1,26,'하나님이 가라사대 우리의 형상을 따라 우리의 모양대로 우리가 사람을 만들고 그로 바다의 고기와, 공중의 새와, 육축과, 온 땅과, 땅에 기는 모든 것을 다스리게 하자 하시고'),
(1462811,51,1,1,27,'하나님이 자기 형상 곧 하나님의 형상대로 사람을 창조하시되 남자와 여자를 창조하시고'),
(1462812,51,1,1,28,'하나님이 그들에게 복을 주시며 그들에게 이르시되 생육하고 번성하여 땅에 충만하라, 땅을 정복하라, 바다의 고기와 공중의 새와 땅에 움직이는 모든 생물을 다스리라 하시니라'),
(1462813,51,1,1,29,'하나님이 가라사대 내가 온 지면의 씨 맺는 모든 채소와 씨 가진 열매 맺는 모든 나무를 너희에게 주노니 너희 식물이 되리라'),
(1462814,51,1,1,30,'또 땅의 모든 짐승과 공중의 모든 새와 생명이 있어 땅에 기는 모든 것에게는 내가 모든 푸른 풀을 식물로 주노라 하시니 그대로 되니라'),
(1462815,51,1,1,31,'하나님이 그 지으신 모든 것을 보시니 보시기에 심히 좋았더라 저녁이 되며 아침이 되니 이는 여섯째 날이니라'),
(1462816,51,1,2,1,'천지와 만물이 다 이루니라'),
(1462817,51,1,2,2,'하나님의 지으시던 일이 일곱째 날이 이를 때에 마치니 그 지으시던 일이 다하므로 일곱째 날에 안식하시니라'),
(1462818,51,1,2,3,'하나님이 일곱째 날을 복 주사 거룩하게 하셨으니 이는 하나님이 그 창조하시며 만드시던 모든 일을 마치시고 이 날에 안식하셨음이더라'),
(1462819,51,1,2,4,'여호와 하나님이 천지를 창조하신 때에 천지의 창조된 대략이 이러하니라'),
(1462820,51,1,2,5,'여호와 하나님이 땅에 비를 내리지 아니하셨고 경작할 사람도 없었으므로 들에는 초목이 아직 없었고 밭에는 채소가 나지 아니하였으며'),
(1462821,51,1,2,6,'안개만 땅에서 올라와 온 지면을 적셨더라'),
(1462822,51,1,2,7,'여호와 하나님이 흙으로 사람을 지으시고 생기를 그 코에 불어 넣으시니 사람이 생령이 된지라'),
(1462823,51,1,2,8,'여호와 하나님이 동방의 에덴에 동산을 창설하시고 그 지으신 사람을 거기 두시고'),
(1462824,51,1,2,9,'여호와 하나님이 그 땅에서 보기에 아름답고 먹기에 좋은 나무가 나게 하시니 동산 가운데에는 생명나무와 선악을 알게하는 나무도 있더라'),
(1462825,51,1,2,10,'강이 에덴에서 발원하여 동산을 적시고 거기서부터 갈라져 네 근원이 되었으니'),
(1462826,51,1,2,11,'첫째의 이름은 비손이라 금이 있는 하윌라 온 땅에 둘렸으며'),
(1462827,51,1,2,12,'그 땅의 금은 정금이요 그 곳에는 베델리엄과 호마노도 있으며'),
(1462828,51,1,2,13,'둘째 강의 이름은 기혼이라 구스 온 땅에 둘렸고'),
(1462829,51,1,2,14,'세째 강의 이름은 힛데겔이라 앗수르 동편으로 흐르며 네째 강은 유브라데더라'),
(1462830,51,1,2,15,'여호와 하나님이 그 사람을 이끌어 에덴 동산에 두사 그것을 다스리며 지키게 하시고'),
(1462831,51,1,2,16,'여호와 하나님이 그 사람에게 명하여 가라사대 동산 각종 나무의 실과는 네가 임의로 먹되'),
(1462832,51,1,2,17,'선악을 알게하는 나무의 실과는 먹지 말라 ! 네가 먹는 날에는 정녕 죽으리라 ! 하시니라'),
(1462833,51,1,2,18,'여호와 하나님이 가라사대 사람의 독처하는 것이 좋지 못하니 내가 그를 위하여 돕는 배필을 지으리라 하시니라'),
(1462834,51,1,2,19,'여호와 하나님이 흙으로 각종 들짐승과 공중의 각종 새를 지으시고 아담이 어떻게 이름을 짓나 보시려고 그것들을 그에게로 이끌어 이르시니 아담이 각 생물을 일컫는 바가 곧 그 이름이라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1462835,51,1,2,20,'아담이 모든 육축과 공중의 새와 들의 모든 짐승에게 이름을 주니라 아담이 돕는 배필이 없으므로'),
(1462836,51,1,2,21,'여호와 하나님이 아담을 깊이 잠들게 하시니 잠들매 그가 그 갈빗대 하나를 취하고 살로 대신 채우시고'),
(1462837,51,1,2,22,'여호와 하나님이 아담에게서 취하신 그 갈빗대로 여자를 만드시고 그를 아담에게로 이끌어 오시니'),
(1462838,51,1,2,23,'아담이 가로되 `이는 내 뼈 중의 뼈요 ! 살 중의 살이라 ! 이것을 남자에게서 취하였은즉 여자라 칭하리라'' 하니라'),
(1462839,51,1,2,24,'이러므로 남자가 부모를 떠나 그 아내와 연합하여 둘이 한 몸을 이룰지로다 !'),
(1462840,51,1,2,25,'아담과 그 아내 두 사람이 벌거벗었으나 부끄러워 아니하니라'),
(1462841,51,1,3,1,'여호와 하나님의 지으신 들짐승 중에 뱀이 가장 간교하더라 뱀이 여자에게 물어 가로되 `하나님이 참으로 너희더러 동산 모든 나무의 실과를 먹지 말라 하시더냐 ?'''),
(1462842,51,1,3,2,'여자가 뱀에게 말하되 `동산 나무의 실과를 우리가 먹을 수 있으나'),
(1462843,51,1,3,3,'동산 중앙에 있는 나무의 실과는 하나님의 말씀에 너희는 먹지도 말고 만지지도 말라 너희가 죽을까 하노라 하셨느니라'''),
(1462844,51,1,3,4,'뱀이 여자에게 이르되 `너희가 결코 죽지 아니하리라'),
(1462845,51,1,3,5,'너희가 그것을 먹는 날에는 너희 눈이 밝아 하나님과 같이 되어 선악을 알 줄을 하나님이 아심이니라'''),
(1462846,51,1,3,6,'여자가 그 나무를 본즉 먹음직도 하고, 보암직도 하고, 지혜롭게 할 만큼 탐스럽기도 한 나무인지라 여자가 그 실과를 따먹고 자기와 함께 한 남편에게도 주매 그도 먹은지라'),
(1462847,51,1,3,7,'이에 그들의 눈이 밝아 자기들의 몸이 벗은 줄을 알고 무화과나무 잎을 엮어 치마를 하였더라'),
(1462848,51,1,3,8,'그들이 날이 서늘할 때에 동산에 거니시는 여호와 하나님의 음성을 듣고 아담과 그 아내가 여호와 하나님의 낯을 피하여 동산 나무 사이에 숨은지라'),
(1462849,51,1,3,9,'여호와 하나님이 아담을 부르시며 그에게 이르시되 네가 어디 있느냐 ?'),
(1462850,51,1,3,10,'가로되 `내가 동산에서 하나님의 소리를 듣고 내가 벗었으므로 두려워하여 숨었나이다'''),
(1462851,51,1,3,11,'가라사대 누가 너의 벗었음을 네게 고하였느냐 ? 내가 너더러 먹지 말라 명한 그 나무 실과를 네가 먹었느냐 ?'),
(1462852,51,1,3,12,'아담이 가로되 `하나님이 주셔서 나와 함께하게 하신 여자 그가 그 나무 실과를 내게 주므로 내가 먹었나이다'''),
(1462853,51,1,3,13,'여호와 하나님이 여자에게 이르시되 네가 어찌하여 이렇게 하였느냐 ? 여자가 가로되 `뱀이 나를 꾀므로 내가 먹었나이다'''),
(1462854,51,1,3,14,'여호와 하나님이 뱀에게 이르시되 네가 이렇게 하였으니 네가 모든 육축과 들의 모든 짐승보다 더욱 저주를 받아 배로 다니고 종신토록 흙을 먹을지니라'),
(1462855,51,1,3,15,'내가 너로 여자와 원수가 되게 하고 너의 후손도 여자의 후손과 원수가 되게 하리니 여자의 후손은 네 머리를 상하게 할 것이요 너는 그의 발꿈치를 상하게 할 것이니라 하시고'),
(1462856,51,1,3,16,'또 여자에게 이르시되 내가 네게 잉태하는 고통을 크게 더하리니 네가 수고하고 자식을 낳을 것이며 너는 남편을 사모하고 남편은 너를 다스릴 것이니라 하시고'),
(1462857,51,1,3,17,'아담에게 이르시되 네가 네 아내의 말을 듣고 내가 너더러 먹지 말라 한 나무 실과를 먹었은즉 땅은 너로 인하여 저주를 받고 너는 종신토록 수고하여야 그 소산을 먹으리라'),
(1462858,51,1,3,18,'땅이 네게 가시덤불과 엉겅퀴를 낼 것이라 너의 먹을 것은 밭의 채소인즉'),
(1462859,51,1,3,19,'네가 얼굴에 땀이 흘러야 식물을 먹고 필경은 흙으로 돌아가리니 그 속에서 네가 취함을 입었음이라 너는 흙이니 흙으로 돌아 갈 것이니라 하시니라'),
(1462860,51,1,3,20,'아담이 그 아내를 하와라 이름하였으니 그는 모든 산 자의 어미가 됨이더라'),
(1462861,51,1,3,21,'여호와 하나님이 아담과 그 아내를 위하여 가죽 옷을 지어 입히시니라'),
(1462862,51,1,3,22,'여호와 하나님이 가라사대 보라, 이 사람이 선악을 아는 일에 우리 중 하나같이 되었으니 그가 그 손을 들어 생명나무 실과도 먹고 영생할까 하노라 하시고'),
(1462863,51,1,3,23,'여호와 하나님이 에덴 동산에서 그 사람을 내어 보내어 그의 근본된 토지를 갈게 하시니라'),
(1462864,51,1,3,24,'이같이 하나님이 그 사람을 쫓아 내시고 에덴 동산 동편에 그룹들과 두루 도는 화염검을 두어 생명나무의 길을 지키게 하시니라'),
(1462865,51,1,4,1,'아담이 그 아내 하와와 동침하매 하와가 잉태하여 가인을 낳고 이르되 `내가 여호와로 말미암아 득남하였다'' 하니라'),
(1462866,51,1,4,2,'그가 또 가인의 아우 아벨을 낳았는데 아벨은 양 치는 자이었고, 가인은 농사하는 자이었더라'),
(1462867,51,1,4,3,'세월이 지난 후에 가인은 땅의 소산으로 제물을 삼아 여호와께 드렸고'),
(1462868,51,1,4,4,'아벨은 자기도 양의 첫 새끼와 그 기름으로 드렸더니 여호와께서 아벨과 그 제물은 열납하셨으나'),
(1462869,51,1,4,5,'가인과 그 제물은 열납하지 아니하신지라 가인이 심히 분하여 안색이 변하니'),
(1462870,51,1,4,6,'여호와께서 가인에게 이르시되 네가 분하여 함은 어찜이며 안색이 변함은 어찜이뇨 ?'),
(1462871,51,1,4,7,'네가 선을 행하면 어찌 낯을 들지 못하겠느냐 ? 선을 행치 아니하면 죄가 문에 엎드리느니라 죄의 소원은 네게 있으나 너는 죄를 다스릴지니라'),
(1462872,51,1,4,8,'가인이 그 아우 아벨에게 고하니라 그 후 그들이 들에 있을때에 가인이 그 아우 아벨을 쳐 죽이니라'),
(1462873,51,1,4,9,'여호와께서 가인에게 이르시되 네 아우 아벨이 어디 있느냐 ? 그가 가로되 `내가 알지 못하나이다 내가 내 아우를 지키는 자이니까 ?'''),
(1462874,51,1,4,10,'가라사대 네가 무엇을 하였느냐 ? 네 아우의 핏소리가 땅에서부터 내게 호소하느니라'),
(1462875,51,1,4,11,'땅이 그 입을 벌려 네 손에서부터 네 아우의 피를 받았은즉 네가 땅에서 저주를 받으리니'),
(1462876,51,1,4,12,'네가 밭 갈아도 땅이 다시는 그 효력을 네게 주지 아니할 것이요 너는 땅에서 피하며 유리하는 자가 되리라'),
(1462877,51,1,4,13,'가인이 여호와께 고하되 `내 죄벌이 너무 중하여 견딜 수 없나이다'),
(1462878,51,1,4,14,'주께서 오늘 이 지면에서 나를 쫓아 내시온즉 내가 주의 낯을 뵈옵지 못하리니 내가 땅에서 피하며 유리하는 자가 될지라 무릇 나를 만나는 자가 나를 죽이겠나이다'''),
(1462879,51,1,4,15,'여호와께서 그에게 이르시되 그렇지 않다 가인을 죽이는 자는 벌을 칠배나 받으리라 하시고 가인에게 표를 주사 만나는 누구에게든지 죽임을 면케 하시니라'),
(1462880,51,1,4,16,'가인이 여호와의 앞을 떠나 나가 에덴 동편 놋 땅에 거하였더니'),
(1462881,51,1,4,17,'아내와 동침하니 그가 잉태하여 에녹을 낳은지라 가인이 성을 쌓고 그 아들의 이름으로 성을 이름하여 에녹이라 하였더라'),
(1462882,51,1,4,18,'에녹이 이랏을 낳았고, 이랏은 므후야엘을 낳았고, 므후야엘은 므드사엘을 낳았고, 므드사엘은 라멕을 낳았더라'),
(1462883,51,1,4,19,'라멕이 두 아내를 취하였으니 하나의 이름은 아다요, 하나의 이름은 씰라며'),
(1462884,51,1,4,20,'아다는 야발을 낳았으니 그는 장막에 거하여 육축 치는 자의 조상이 되었고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1462885,51,1,4,21,'그 아우의 이름은 유발이니 그는 수금과 퉁소를 잡는 모든 자의 조상이 되었으며'),
(1462886,51,1,4,22,'씰라는 두발가인을 낳았으니 그는 동,철로 각양 날카로운 기계를 만드는 자요 두발가인의 누이는 나아마이었더라'),
(1462887,51,1,4,23,'라멕이 아내들에게 이르되 `아다와 씰라여 내 소리를 들으라 라멕의 아내들이여 ! 내 말을 들으라 나의 창상을 인하여 내가 사람을 죽였고 나의 상함을 인하여 소년을 죽였도다'),
(1462888,51,1,4,24,'가인을 위하여는 벌이 칠배일진대 라멕을 위하여는 벌이 칠십 칠배이리로다'' 하였더라'),
(1462889,51,1,4,25,'아담이 다시 아내와 동침하매 그가 아들을 낳아 그 이름을 셋이라 하였으니 `이는 하나님이 내게 가인의 죽인 아벨 대신에 다른 씨를 주셨다'' 함이며'),
(1462890,51,1,4,26,'셋도 아들을 낳고 그 이름을 에노스라 하였으며 그 때에 사람들이 비로소 여호와의 이름을 불렀더라'),
(1462891,51,1,5,1,'아담 자손의 계보가 이러하니라 하나님이 사람을 창조하실 때에 하나님의 형상대로 지으시되'),
(1462892,51,1,5,2,'남자와 여자를 창조하셨고 그들이 창조되던 날에 하나님이 그들에게 복을 주시고 그들의 이름을 사람이라 일컬으셨더라'),
(1462893,51,1,5,3,'아담이 일백 삼십세에 자기 모양 곧 자기 형상과 같은 아들을 낳아 이름을 셋이라 하였고'),
(1462894,51,1,5,4,'아담이 셋을 낳은 후 팔백년을 지내며 자녀를 낳았으며'),
(1462895,51,1,5,5,'그가 구백 삼십세를 향수하고 죽었더라'),
(1462896,51,1,5,6,'셋은 일백 오세에 에노스를 낳았고'),
(1462897,51,1,5,7,'에노스를 낳은 후 팔백 칠년을 지내며 자녀를 낳았으며'),
(1462898,51,1,5,8,'그가 구백 십이세를 향수하고 죽었더라'),
(1462899,51,1,5,9,'에노스는 구십세에 게난을 낳았고'),
(1462900,51,1,5,10,'게난을 낳은 후 팔백 십 오년을 지내며 자녀를 낳았으며'),
(1462901,51,1,5,11,'그가 구백 오세를 향수하고 죽었더라'),
(1462902,51,1,5,12,'게난은 칠십세에 마할랄렐을 낳았고'),
(1462903,51,1,5,13,'마할랄렐을 낳은 후 팔백 사십년을 지내며 자녀를 낳았으며'),
(1462904,51,1,5,14,'그가 구백 십세를 향수하고 죽었더라'),
(1462905,51,1,5,15,'마할랄렐은 육십 오세에 야렛을 낳았고'),
(1462906,51,1,5,16,'야렛을 낳은 후 팔백 삼십년을 지내며 자녀를 낳았으며'),
(1462907,51,1,5,17,'그가 팔백 구십 오세를 향수하고 죽었더라'),
(1462908,51,1,5,18,'야렛은 일백 육십 이세에 에녹을 낳았고'),
(1462909,51,1,5,19,'에녹을 낳은 후 팔백년을 지내며 자녀를 낳았으며'),
(1462910,51,1,5,20,'그가 구백 육십 이세를 향수하고 죽었더라'),
(1462911,51,1,5,21,'에녹은 육십 오세에 므두셀라를 낳았고'),
(1462912,51,1,5,22,'므두셀라를 낳은 후 삼백년을 하나님과 동행하며 자녀를 낳았으며'),
(1462913,51,1,5,23,'그가 삼백 육십 오세를 향수하였더라'),
(1462914,51,1,5,24,'에녹이 하나님과 동행하더니 하나님이 그를 데려 가시므로 세상에 있지 아니하였더라'),
(1462915,51,1,5,25,'므두셀라는 일백 팔십 칠세에 라멕을 낳았고'),
(1462916,51,1,5,26,'라멕을 낳은 후 칠백 팔십 이년을 지내며 자녀를 낳았으며'),
(1462917,51,1,5,27,'그는 구백 육십 구세를 향수하고 죽었더라'),
(1462918,51,1,5,28,'라멕은 일백 팔십 이세에 아들을 낳고'),
(1462919,51,1,5,29,'이름을 노아라 하여 가로되 `여호와께서 땅을 저주하시므로 수고로이 일하는 우리를 이 아들이 안위하리라'' 하였더라'),
(1462920,51,1,5,30,'라멕이 노아를 낳은 후 오백 구십 오년을 지내며 자녀를 낳았으며'),
(1462921,51,1,5,31,'그는 칠백 칠십 칠세를 향수하고 죽었더라'),
(1462922,51,1,5,32,'노아가 오백세 된 후에 셈과, 함과, 야벳을 낳았더라'),
(1462923,51,1,6,1,'사람이 땅 위에 번성하기 시작할 때에 그들에게서 딸들이 나니'),
(1462924,51,1,6,2,'하나님의 아들들이 사람의 딸들의 아름다움을 보고 자기들의 좋아하는 모든 자로 아내를 삼는지라'),
(1462925,51,1,6,3,'여호와께서 가라사대 나의 신(神)이 영원히 사람과 함께하지 아니하리니 이는 그들이 육체가 됨이라 그러나 그들의 날은 일백 이십년이 되리라 하시니라'),
(1462926,51,1,6,4,'당시에 땅에 네피림이 있었고 그 후에도 하나님의 아들들이 사람의 딸들을 취하여 자식을 낳았으니 그들이 용사라 고대에 유명한 사람이었더라'),
(1462927,51,1,6,5,'여호와께서 사람의 죄악이 세상에 관영함과 그 마음의 생각의 모든 계획이 항상 악할 뿐임을 보시고'),
(1462928,51,1,6,6,'땅위에 사람 지으셨음을 한탄하사 마음에 근심하시고'),
(1462929,51,1,6,7,'가라사대 나의 창조한 사람을 내가 지면에서 쓸어 버리되 사람으로부터 육축과 기는 것과 공중의 새까지 그리하리니 이는 내가 그것을 지었음을 한탄함이니라 하시니라'),
(1462930,51,1,6,8,'그러나 노아는 여호와께 은혜를 입었더라'),
(1462931,51,1,6,9,'노아의 사적은 이러하니라 노아는 의인이요 당세에 완전한 자라 그가 하나님과 동행하였으며'),
(1462932,51,1,6,10,'그가 세 아들을 낳았으니 셈과, 함과, 야벳이라'),
(1462933,51,1,6,11,'때에 온 땅이 하나님 앞에 패괴하여 강포가 땅에 충만한지라'),
(1462934,51,1,6,12,'하나님이 보신즉 땅이 패괴하였으니 이는 땅에서 모든 혈육 있는 자의 행위가 패괴함이었더라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1462935,51,1,6,13,'하나님이 노아에게 이르시되 모든 혈육있는 자의 강포가 땅에 가득하므로 그 끝날이 내 앞에 이르렀으니 내가 그들을 땅과 함께 멸하리라'),
(1462936,51,1,6,14,'너는 잣나무로 너를 위하여 방주를 짓되 그 안에 간들을 막고 역청으로 그 안팎에 칠하라'),
(1462937,51,1,6,15,'그 방주의 제도는 이러하니 장이 삼백 규빗, 광이 오십 규빗, 고가 삼십 규빗이며'),
(1462938,51,1,6,16,'거기 창을 내되 위에서부터 한 규빗에 내고 그 문은 옆으로 내고 상 중 하 삼층으로 할지니라'),
(1462939,51,1,6,17,'내가 홍수를 땅에 일으켜 무릇 생명의 기식 있는 육체를 천하에서 멸절하리니 땅에 있는 자가 다 죽으리라'),
(1462940,51,1,6,18,'그러나 너와는 내가 내 언약을 세우리니 너는 네 아들들과 네 아내와 네 자부들과 함께 그 방주로 들어가고'),
(1462941,51,1,6,19,'혈육 있는 모든 생물을 너는 각기 암,수 한쌍씩 방주로 이끌어 들여 너와 함께 생명을 보존케 하되'),
(1462942,51,1,6,20,'새가 그 종류대로, 육축이 그 종류대로, 땅에 기는 모든 것이 그 종류대로, 각기 둘씩 네게로 나아오리니 그 생명을 보존케하라'),
(1462943,51,1,6,21,'너는 먹을 모든 식물을 네게로 가져다가 저축하라 이것이 너와 그들의 식물이 되리라'),
(1462944,51,1,6,22,'노아가 그와 같이 하되 하나님이 자기에게 명하신 대로 다 준행하였더라 !'),
(1462945,51,1,7,1,'여호와께서 노아에게 이르시되 너와 네 온 집은 방주로 들어가라 네가 이 세대에 내 앞에서 의로움을 내가 보았음이니라 !'),
(1462946,51,1,7,2,'너는 모든 정결한 짐승은 암수 일곱씩 부정한 것은 암수 둘씩을 네게로 취하며'),
(1462947,51,1,7,3,'공중의 새도 암수 일곱씩을 취하여 그 씨를 온 지면에 유전케하라'),
(1462948,51,1,7,4,'지금부터 칠일이면 내가 사십 주야를 땅에 비를 내려 나의 지은 모든 생물을 지면에서 쓸어 버리리라'),
(1462949,51,1,7,5,'노아가 여호와께서 자기에게 명하신 대로 다 준행하였더라 !'),
(1462950,51,1,7,6,'홍수가 땅에 있을 때에 노아가 육백세라'),
(1462951,51,1,7,7,'노아가 아들들과 아내와 자부들과 함께 홍수를 피하여 방주에 들어갔고'),
(1462952,51,1,7,8,'정결한 짐승과 부정한 짐승과 새와 땅에 기는 모든 것이'),
(1462953,51,1,7,9,'하나님이 노아에게 명하신 대로 암수 둘씩 노아에게 나아와 방주로 들어갔더니'),
(1462954,51,1,7,10,'칠일 후에 홍수가 땅에 덮이니'),
(1462955,51,1,7,11,'노아 육백세 되던 해 이월 곧 그 달 십 칠일이라 그날에 큰 깊음의 샘들이 터지며 하늘의 창들이 열려'),
(1462956,51,1,7,12,'사십 주야를 비가 땅에 쏟아졌더라'),
(1462957,51,1,7,13,'곧 그 날에 노아와 그의 아들 셈, 함, 야벳과 노아의 처와 세 자부가 다 방주로 들어갔고'),
(1462958,51,1,7,14,'그들과 모든 들짐승이 그 종류대로, 모든 육축이 그 종류대로, 땅에 기는 모든 것이 그 종류대로, 모든 새 곧 각양의 새가 그 종류대로'),
(1462959,51,1,7,15,'무릇 기식이 있는 육체가 둘씩 노아에게 나아와 방주로 들어갔으니'),
(1462960,51,1,7,16,'들어간 것들은 모든 것의 암,수라 하나님이 그에게 명하신대로 들어가매 여호와께서 그를 닫아 넣으시니라'),
(1462961,51,1,7,17,'홍수가 땅에 사십일을 있었는지라 물이 많아져 방주가 땅에서 올랐고'),
(1462962,51,1,7,18,'물이 더 많아져 땅에 창일하매 방주가 물 위에 떠 다녔으며'),
(1462963,51,1,7,19,'물이 땅에 더욱 창일하매 천하에 높은 산이 다 덮였더니'),
(1462964,51,1,7,20,'물이 불어서 십오 규빗이 오르매 산들이 덮인지라'),
(1462965,51,1,7,21,'땅위에 움직이는 생물이 다 죽었으니 곧 새와 육축과 들짐승과 땅에 기는 모든 것과 모든 사람이라'),
(1462966,51,1,7,22,'육지에 있어 코로 생물의 기식을 호흡하는 것은 다 죽었더라'),
(1462967,51,1,7,23,'지면의 모든 생물을 쓸어버리시니 곧 사람과 짐승과 기는 것과 공중의 새까지라 이들은 땅에서 쓸어버림을 당하였으되 홀로 노아와 그와 함께 방주에 있던 자만 남았더라'),
(1462968,51,1,7,24,'물이 일백 오십일을 땅에 창일하였더라'),
(1462969,51,1,8,1,'하나님이 노아와 그와 함께 방주에 있는 모든 들짐승과 육축을 권념하사 바람으로 땅 위에 불게 하시매 물이 감하였고'),
(1462970,51,1,8,2,'깊음의 샘과 하늘의 창이 막히고 하늘에서 비가 그치매'),
(1462971,51,1,8,3,'물이 땅에서 물러가고 점점 물러가서 일백 오십일 후에 감하고'),
(1462972,51,1,8,4,'칠월 곧 그 달 십칠일에 방주가 아라랏 산에 머물렀으며'),
(1462973,51,1,8,5,'물이 점점 감하여 시월 곧 그달 일일에 산들의 봉우리가 보였더라'),
(1462974,51,1,8,6,'사십일을 지나서 노아가 그 방주에 지은 창을 열고'),
(1462975,51,1,8,7,'까마귀를 내어 놓으매 까마귀가 물이 땅에서 마르기까지 날아 왕래하였더라'),
(1462976,51,1,8,8,'그가 또 비둘기를 내어 놓아 지면에 물이 감한 여부를 알고자 하매'),
(1462977,51,1,8,9,'온 지면에 물이 있으므로 비둘기가 접족할 곳을 찾지 못하고 방주로 돌아와 그에게로 오는지라 그가 손을 내밀어 방주 속 자기에게로 받아 들이고'),
(1462978,51,1,8,10,'또 칠일을 기다려 다시 비둘기를 방주에서 내어 놓으매'),
(1462979,51,1,8,11,'저녁때에 비둘기가 그에게로 돌아왔는데 그 입에 감람 새 잎사귀가 있는지라 이에 노아가 땅에 물이 감한 줄 알았으며'),
(1462980,51,1,8,12,'또 칠일을 기다려 비둘기를 내어 놓으매 다시는 그에게로 돌아오지 아니하였더라'),
(1462981,51,1,8,13,'육백 일년 정월 곧 그 달 일일에 지면에 물이 걷힌지라 노아가 방주 뚜껑을 제치고 본즉 지면에 물이 걷혔더니'),
(1462982,51,1,8,14,'이월 이십 칠일에 땅이 말랐더라'),
(1462983,51,1,8,15,'하나님이 노아에게 말씀하여 가라사대'),
(1462984,51,1,8,16,'너는 네 아내와 네 아들들과 네 자부들로 더불어 방주에서 나오고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1462985,51,1,8,17,'너와 함께 한 모든 혈육 있는 생물 곧 새와 육축과 땅에 기는 모든 것을 다 이끌어 내라 이것들이 땅에서 생육하고 땅에서 번성하리라 하시매'),
(1462986,51,1,8,18,'노아가 그 아들들과 그 아내와 그 자부들과 함께 나왔고'),
(1462987,51,1,8,19,'땅위의 동물 곧 모든 짐승과 모든 기는 것과 모든 새도 그 종류대로 방주에서 나왔더라'),
(1462988,51,1,8,20,'노아가 여호와를 위하여 단을 쌓고 모든 정결한 짐승 중에서와 모든 정결한 새 중에서 취하여 번제로 단에 드렸더니'),
(1462989,51,1,8,21,'여호와께서 그 향기를 흠향하시고 그 중심에 이르시되 내가 다시는 사람으로 인하여 땅을 저주하지 아니하리니 이는 사람의 마음의 계획하는 바가 어려서부터 악함이라 내가 전에 행한 것 같이 모든 생물을 멸하지 아니하리니'),
(1462990,51,1,8,22,'땅이 있을 동안에는 심음과, 거둠과, 추위와, 더위와, 여름과, 겨울과, 낮과, 밤이 쉬지 아니하리라'),
(1462991,51,1,9,1,'하나님이 노아와 그 아들들에게 복을 주시며 그들에게 이르시되 생육하고 번성하여 땅에 충만하라 !'),
(1462992,51,1,9,2,'땅의 모든 짐승과 공중의 모든 새와 땅에 기는 모든 것과 바다의 모든 고기가 너희를 두려워하며 너희를 무서워하리니 이들은 너희 손에 붙이웠음이라'),
(1462993,51,1,9,3,'무릇 산 동물은 너희의 식물이 될지라 채소같이 내가 이것을 다 너희에게 주노라'),
(1462994,51,1,9,4,'그러나 고기를 그 생명 되는 피 채 먹지 말 것이니라'),
(1462995,51,1,9,5,'내가 반드시 너희 피 곧 너희 생명의 피를 찾으리니 짐승이면 그 짐승에게서, 사람이나 사람의 형제면 그에게서 그의 생명을 찾으리라'),
(1462996,51,1,9,6,'무릇 사람의 피를 흘리면 사람이 그 피를 흘릴 것이니 이는 하나님이 자기 형상대로 사람을 지었음이니라'),
(1462997,51,1,9,7,'너희는 생육하고 번성하며 땅에 편만하여 그 중에서 번성하라 하셨더라'),
(1462998,51,1,9,8,'하나님이 노아와 그와 함께 한 아들들에게 일러 가라사대'),
(1462999,51,1,9,9,'내가 내 언약을 너희와 너희 후손과'),
(1463000,51,1,9,10,'너희와 함께 한 모든 생물 곧 너희와 함께 한 새와 육축과 땅의 모든 생물에게 세우리니 방주에서 나온 모든 것 곧 땅의 모든 짐승에게니라'),
(1463001,51,1,9,11,'내가 너희와 언약을 세우리니 다시는 모든 생물을 홍수로 멸하지 아니할 것이라 땅을 침몰할 홍수가 다시 있지 아니하리라'),
(1463002,51,1,9,12,'하나님이 가라사대 내가 나와 너희와 및 너희와 함께 하는 모든 생물 사이에 영세까지 세우는 언약의 증거는 이것이라'),
(1463003,51,1,9,13,'내가 내 무지개를 구름 속에 두었나니 이것이 나의 세상과의 언약의 증거니라'),
(1463004,51,1,9,14,'내가 구름으로 땅을 덮을 때에 무지개가 구름 속에 나타나면'),
(1463005,51,1,9,15,'내가 나와 너희와 및 혈기 있는 모든 생물사이의 내 언약을 기억하리니 다시는 물이 모든 혈기 있는 자를 멸하는 홍수가 되지 아니할지라'),
(1463006,51,1,9,16,'무지개가 구름 사이에 있으리니 내가 보고 나 하나님과 땅의 무릇 혈기 있는 모든 생물 사이에 된 영원한 언약을 기억하리라'),
(1463007,51,1,9,17,'하나님이 노아에게 또 이르시되 내가 나와 땅에 있는 모든 생물 사이에 세운 언약의 증거가 이것이라 하셨더라'),
(1463008,51,1,9,18,'방주에서 나온 노아의 아들들은 셈과, 함과, 야벳이며 함은 가나안의 아비라'),
(1463009,51,1,9,19,'노아의 이 세 아들로 좇아 백성이 온 땅에 퍼지니라'),
(1463010,51,1,9,20,'노아가 농업을 시작하여 포도나무를 심었더니'),
(1463011,51,1,9,21,'포도주를 마시고 취하여 그 장막 안에서 벌거벗은지라'),
(1463012,51,1,9,22,'가나안의 아비 함이 그 아비의 하체를 보고 밖으로 나가서 두 형제에게 고하매'),
(1463013,51,1,9,23,'셈과 야벳이 옷을 취하여 자기들의 어깨에 메고 뒷걸음쳐 들어가서 아비의 하체에 덮었으며 그들이 얼굴을 돌이키고 그 아비의 하체를 보지 아니하였더라'),
(1463014,51,1,9,24,'노아가 술이 깨어 그 작은 아들이 자기에게 행한 일을 알고'),
(1463015,51,1,9,25,'이에 가로되 `가나안은 저주를 받아 그 형제의 종들의 종이 되기를 원하노라'''),
(1463016,51,1,9,26,'또 가로되 `셈의 하나님 여호와를 찬송하리로다 ! 가나안은 셈의 종이 되고'),
(1463017,51,1,9,27,'하나님이 야벳을 창대케하사 셈의 장막에 거하게 하시고 가나안은 그의 종이 되게 하시기를 원하노라'' 하였더라'),
(1463018,51,1,9,28,'홍수 후에 노아가 삼백 오십년을 지내었고'),
(1463019,51,1,9,29,'향년이 구백 오십세에 죽었더라'),
(1463020,51,1,10,1,'노아의 아들 셈과, 함과, 야벳의 후예는 이러하니라 홍수 후에 그들이 아들들을 낳았으니'),
(1463021,51,1,10,2,'야벳의 아들은 고멜과, 마곡과, 마대와, 야완과, 두발과, 메섹과, 디라스요'),
(1463022,51,1,10,3,'고멜의 아들은 아스그나스와, 리밧과, 도갈마요'),
(1463023,51,1,10,4,'야완의 아들은 엘리사와, 달시스와, 깃딤과, 도다님이라'),
(1463024,51,1,10,5,'이들로부터 여러 나라 백성으로 나뉘어서 각기 방언과 종족과 나라대로 바닷가의 땅에 머물렀더라'),
(1463025,51,1,10,6,'함의 아들은 구스와, 미스라임과, 붓과, 가나안이요'),
(1463026,51,1,10,7,'구스의 아들은 스바와, 하윌라와, 삽다와, 라아마와, 삽드가요, 라아마의 아들은 스바와, 드단이며'),
(1463027,51,1,10,8,'구스가 또 니므롯을 낳았으니 그는 세상에 처음 영걸이라'),
(1463028,51,1,10,9,'그가 여호와 앞에서 특이한 사냥군이 되었으므로 속담에 이르기를 아무는 여호와 앞에 니므롯 같은 특이한 사냥군이로다 하더라'),
(1463029,51,1,10,10,'그의 나라는 시날땅의 바벨과, 에렉과, 악갓과, 갈레에서 시작되었으며'),
(1463030,51,1,10,11,'그가 그 땅에서 앗수르로 나아가 니느웨와, 르호보딜과, 갈라와'),
(1463031,51,1,10,12,'및 니느웨와 갈라 사이의 레센(이는 큰 성이라)을 건축하였으며'),
(1463032,51,1,10,13,'미스라임은 루딤과, 아나밈과, 르하빔과, 납두힘과'),
(1463033,51,1,10,14,'바드루심과, 가슬루힘과, 갑도림을 낳았더라 (블레셋이 가슬루힘에게서 나왔더라)'),
(1463034,51,1,10,15,'가나안은 장자 시돈과, 헷을 낳고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463035,51,1,10,16,'또 여부스 족속과, 아모리 족속과, 기르가스 족속과'),
(1463036,51,1,10,17,'히위 족속과, 알가 족속과, 신 족속과'),
(1463037,51,1,10,18,'아르왓 족속과, 스말 족속과, 하맛 족속의 조상을 낳았더니 이 후로 가나안 자손의 족속이 흩어져 처하였더라'),
(1463038,51,1,10,19,'가나안의 지경은 시돈에서부터 그랄을 지나 가사까지와, 소돔과, 고모라와, 아드마와, 스보임을 지나 라사까지였더라'),
(1463039,51,1,10,20,'이들은 함의 자손이라 각기 족속과 방언과 지방과 나라대로이었더라'),
(1463040,51,1,10,21,'셈은 에벨 온 자손의 조상이요 야벳의 형이라 그에게도 자녀가 출생하였으니'),
(1463041,51,1,10,22,'셈의 아들은 엘람과, 앗수르와, 아르박삿과, 룻과, 아람이요'),
(1463042,51,1,10,23,'아람의 아들은 우스와, 훌과, 게델과, 마스며'),
(1463043,51,1,10,24,'아르박삿은 셀라를 낳고, 셀라는 에벨을 낳았으며'),
(1463044,51,1,10,25,'에벨은 두 아들을 낳고, 하나의 이름을 벨렉이라 하였으니 그 때에 세상이 나뉘었음이요 벨렉의 아우의 이름은 욕단이며'),
(1463045,51,1,10,26,'욕단은 알모닷과, 셀렙과, 하살마웹과, 예라와'),
(1463046,51,1,10,27,'하도람과, 우살과, 디글라와'),
(1463047,51,1,10,28,'오발과, 아비마엘과, 스바와'),
(1463048,51,1,10,29,'오빌과, 하윌라와, 요밥을 낳았으니 이들은 다 욕단의 아들이며'),
(1463049,51,1,10,30,'그들의 거하는 곳은 메사에서부터 스발로 가는 길의 동편 산이었더라'),
(1463050,51,1,10,31,'이들은 셈의 자손이라 그 족속과 방언과 지방과 나라대로였더라'),
(1463051,51,1,10,32,'이들은 노아 자손의 족속들이요 그 세계와 나라대로라 홍수 후에 이들에게서 땅의 열국 백성이 나뉘었더라'),
(1463052,51,1,11,1,'온 땅의 구음이 하나이요 언어가 하나이었더라'),
(1463053,51,1,11,2,'이에 그들이 동방으로 옮기다가 시날 평지를 만나 거기 거하고'),
(1463054,51,1,11,3,'서로 말하되 `자, 벽돌을 만들어 견고히 굽자'' 하고 이에 벽돌로 돌을 대신하며 역청으로 진흙을 대신하고'),
(1463055,51,1,11,4,'또 말하되 `자, 성과 대를 쌓아 대 꼭대기를 하늘에 닿게 하여 우리 이름을 내고 온 지면에 흩어짐을 면하자'' 하였더니'),
(1463056,51,1,11,5,'여호와께서 인생들의 쌓는 성과 대를 보시려고 강림하셨더라'),
(1463057,51,1,11,6,'여호와께서 가라사대 이 무리가 한 족속이요, 언어도 하나이므로 이같이 시작하였으니 이후로는 그 경영하는 일을 금지할 수 없으리로다'),
(1463058,51,1,11,7,'자, 우리가 내려가서 거기서 그들의 언어를 혼잡케 하여 그들로 서로 알아듣지 못하게 하자 하시고'),
(1463059,51,1,11,8,'여호와께서 거기서 그들을 온 지면에 흩으신 고로 그들이 성 쌓기를 그쳤더라'),
(1463060,51,1,11,9,'그러므로 그 이름을 바벨이라 하니 이는 여호와께서 거기서 온 땅의 언어를 혼잡케 하셨음이라 여호와께서 거기서 그들을 온 지면에 흩으셨더라'),
(1463061,51,1,11,10,'셈의 후예는 이러하니라 셈은 일백세 곧 홍수 후 이년에 아르박삿을 낳았고'),
(1463062,51,1,11,11,'아르박삿을 낳은 후에 오백년을 지내며 자녀를 낳았으며'),
(1463063,51,1,11,12,'아르박삿은 삼십 오세에 셀라를 낳았고'),
(1463064,51,1,11,13,'셀라를 낳은 후에 사백 삼년을 지내며 자녀를 낳았으며'),
(1463065,51,1,11,14,'셀라는 삼십세에 에벨을 낳았고'),
(1463066,51,1,11,15,'에벨을 낳은 후에 사백 삼년을 지내며 자녀를 낳았으며'),
(1463067,51,1,11,16,'에벨은 삼십 사세에 벨렉을 낳았고'),
(1463068,51,1,11,17,'벨렉을 낳은 후에 사백 삼십년을 지내며 자녀를 낳았으며'),
(1463069,51,1,11,18,'벨렉은 삼십세에 르우를 낳았고'),
(1463070,51,1,11,19,'르우를 낳은 후에 이백 구년을 지내며 자녀를 낳았으며'),
(1463071,51,1,11,20,'르우는 삼십 이세에 스룩을 낳았고'),
(1463072,51,1,11,21,'스룩을 낳은 후에 이백 칠년을 지내며 자녀를 낳았으며'),
(1463073,51,1,11,22,'스룩은 삼십세에 나홀을 낳았고'),
(1463074,51,1,11,23,'나홀을 낳은 후에 이백년을 지내며 자녀를 낳았으며'),
(1463075,51,1,11,24,'나홀은 이십 구세에 데라를 낳았고'),
(1463076,51,1,11,25,'데라를 낳은 후에 일백 십 구년을 지내며 자녀를 낳았으며'),
(1463077,51,1,11,26,'데라는 칠십세에 아브람과, 나홀과, 하란을 낳았더라'),
(1463078,51,1,11,27,'데라의 후예는 이러하니라 데라는 아브람과, 나홀과, 하란을 낳았고 하란은 롯을 낳았으며'),
(1463079,51,1,11,28,'하란은 그 아비 데라보다 먼저 본토 갈대아 우르에서 죽었더라'),
(1463080,51,1,11,29,'아브람과 나홀이 장가 들었으니 아브람의 아내 이름은 사래며 나홀의 아내 이름은 밀가니 하란의 딸이요 하란은 밀가의 아비며 또 이스가의 아비더라'),
(1463081,51,1,11,30,'사래는 잉태하지 못하므로 자식이 없었더라'),
(1463082,51,1,11,31,'데라가 그 아들 아브람과 하란의 아들 그 손자 롯과 그 자부 아브람의 아내 사래를 데리고 갈대아 우르에서 떠나 가나안 땅으로 가고자 하더니 하란에 이르러 거기 거하였으며'),
(1463083,51,1,11,32,'데라는 이백 오세를 향수하고 하란에서 죽었더라'),
(1463084,51,1,12,1,'여호와께서 아브람에게 이르시되 너는 너의 본토 친척 아비 집을 떠나 내가 네게 지시할 땅으로 가라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463085,51,1,12,2,'내가 너로 큰 민족을 이루고 네게 복을 주어 네 이름을 창대케 하리니 너는 복의 근원이 될지라 !'),
(1463086,51,1,12,3,'너를 축복하는 자에게는 내가 복을 내리고 너를 저주하는 자에게는 내가 저주하리니 땅의 모든 족속이 너를 인하여 복을 얻을 것이니라 하신지라'),
(1463087,51,1,12,4,'이에 아브람이 여호와의 말씀을 좇아 갔고 롯도 그와 함께 갔으며 아브람이 하란을 떠날 때에 그 나이 칠십 오세였더라'),
(1463088,51,1,12,5,'아브람이 그 아내 사래와 조카 롯과 하란에서 모은 모든 소유와 얻은 사람들을 이끌고 가나안 땅으로 가려고 떠나서 마침내 가나안 땅에 들어 갔더라'),
(1463089,51,1,12,6,'아브람이 그 땅을 통과하여 세겜 땅 모레 상수리 나무에 이르니 그 때에 가나안 사람이 그 땅에 거하였더라'),
(1463090,51,1,12,7,'여호와께서 아브람에게 나타나 가라사대 내가 이 땅을 네 자손에게 주리라 하신지라 그가 자기에게 나타나신 여호와를 위하여 그 곳에 단을 쌓고'),
(1463091,51,1,12,8,'거기서 벧엘 동편 산으로 옮겨 장막을 치니 서는 벧엘이요, 동은 아이라 그가 그 곳에서 여호와를 위하여 단을 쌓고 여호와의 이름을 부르더니'),
(1463092,51,1,12,9,'점점 남방으로 옮겨 갔더라'),
(1463093,51,1,12,10,'그 땅에 기근이 있으므로 아브람이 애굽에 우거하려 하여 그리로 내려갔으니 이는 그 땅에 기근이 심하였음이라'),
(1463094,51,1,12,11,'그가 애굽에 가까이 이를 때에 그 아내 사래더러 말하되 `나 알기에 그대는 아리따운 여인이라'),
(1463095,51,1,12,12,'애굽 사람이 그대를 볼 때에 이르기를 이는 그의 아내라 하고 나는 죽이고 그대는 살리리니'),
(1463096,51,1,12,13,'원컨대 그대는 나의 누이라 하라 그리하면 내가 그대로 인하여 안전하고 내 목숨이 그대로 인하여 보존하겠노라'' 하니라'),
(1463097,51,1,12,14,'아브람이 애굽에 이르렀을 때에 애굽 사람들이 그 여인의 심히 아리따움을 보았고'),
(1463098,51,1,12,15,'바로의 대신들도 그를 보고 바로 앞에 칭찬하므로 그 여인을 바로의 궁으로 취하여 들인지라'),
(1463099,51,1,12,16,'이에 바로가 그를 인하여 아브람을 후대하므로 아브람이 양과, 소와, 노비와, 암수 나귀와, 약대를 얻었더라'),
(1463100,51,1,12,17,'여호와께서 아브람의 아내 사래의 연고로 바로와 그 집에 큰 재앙을 내리신지라'),
(1463101,51,1,12,18,'바로가 아브람을 불러서 이르되 `네가 어찌하여 나를 이렇게 대접하였느냐 ? 네가 어찌하여 그를 네 아내라고 내게 고하지 아니하였느냐 ?'),
(1463102,51,1,12,19,'네가 어찌 그를 누이라 하여 나로 그를 취하여 아내를 삼게 하였느냐 ? 네 아내가 여기 있으니 이제 데려 가라'' 하고'),
(1463103,51,1,12,20,'바로가 사람들에게 그의 일을 명하매 그들이 그 아내와 그 모든 소유를 보내었더라'),
(1463104,51,1,13,1,'아브람이 애굽에서 나올새 그와 그 아내와 모든 소유며 롯도 함께 하여 남방으로 올라가니'),
(1463105,51,1,13,2,'아브람에게 육축과 은,금이 풍부하였더라'),
(1463106,51,1,13,3,'그가 남방에서부터 발행하여 벧엘에 이르며 벧엘과 아이 사이 전에 장막 쳤던 곳에 이르니'),
(1463107,51,1,13,4,'그가 처음으로 단을 쌓은 곳이라 그가 거기서 여호와의 이름을 불렀더라'),
(1463108,51,1,13,5,'아브람의 일행 롯도 양과 소와 장막이 있으므로'),
(1463109,51,1,13,6,'그 땅이 그들의 동거함을 용납지 못하였으니 곧 그들의 소유가 많아서 동거할 수 없었음이라'),
(1463110,51,1,13,7,'그러므로 아브람의 가축의 목자와 롯의 가축의 목자가 서로 다투고 또 가나안 사람과 브리스 사람도 그 땅에 거하였는지라'),
(1463111,51,1,13,8,'아브람이 롯에게 이르되 `우리는 한 골육이라 나나, 너나, 내 목자나, 네 목자나 서로 다투게 말자'),
(1463112,51,1,13,9,'네 앞에 온 땅이 있지 아니하냐 ? 나를 떠나라 네가 좌하면 나는 우하고, 네가 우하면 나는 좌하리라'''),
(1463113,51,1,13,10,'이에 롯이 눈을 들어 요단들을 바라본즉 소알까지 온 땅에 물이 넉넉하니 여호와께서 소돔과 고모라를 멸하시기 전이었는고로 여호와의 동산같고 애굽 땅과 같았더라'),
(1463114,51,1,13,11,'그러므로 롯이 요단 온 들을 택하고 동으로 옮기니 그들이 서로 떠난지라'),
(1463115,51,1,13,12,'아브람은 가나안 땅에 거하였고 롯은 평지 성읍들에 머무르며 그 장막을 옮겨 소돔까지 이르렀더라'),
(1463116,51,1,13,13,'소돔 사람은 악하여 여호와 앞에 큰 죄인이었더라'),
(1463117,51,1,13,14,'롯이 아브람을 떠난 후에 여호와께서 아브람에게 이르시되 너는 눈을 들어 너 있는 곳에서 동서남북을 바라보라 !'),
(1463118,51,1,13,15,'보이는 땅을 내가 너와 네 자손에게 주리니 영원히 이르리라'),
(1463119,51,1,13,16,'내가 네 자손으로 땅의 티끌 같게 하리니 사람이 땅의 티끌을 능히 셀수 있을진대 네 자손도 세리라'),
(1463120,51,1,13,17,'너는 일어나 그 땅을 종과 횡으로 행하여 보라 ! 내가 그것을 네게 주리라'),
(1463121,51,1,13,18,'이에 아브람이 장막을 옮겨 헤브론에 있는 마므레 상수리 수풀에 이르러 거하며 거기서 여호와를 위하여 단을 쌓았더라'),
(1463122,51,1,14,1,'당시에 시날 왕 아므라벨과, 엘라살 왕 아리옥과, 엘람 왕 그돌라오멜과, 고임 왕 디달이'),
(1463123,51,1,14,2,'소돔 왕 베라와, 고모라 왕 비르사와, 아드마 왕 시납과, 수보임 왕 세메벨과, 벨라 곧 소알 왕과 싸우니라'),
(1463124,51,1,14,3,'이들이 다 싯딤 골짜기 곧 지금 염해에 모였더라'),
(1463125,51,1,14,4,'이들이 십 이년 동안 그돌라오멜을 섬기다가 제 십 삼년에 배반한지라'),
(1463126,51,1,14,5,'제 십 사년에 그돌라오멜과 그와 동맹한 왕들이 나와서 아스드롯 가르나임에서 르바 족속을, 함에서 수스 족속을, 사웨기랴다임에서 엠 족속을 치고'),
(1463127,51,1,14,6,'호리 족속을 그 산 세일에서 쳐서 광야 근방 엘바란까지 이르렀으며'),
(1463128,51,1,14,7,'그들이 돌이켜 엔미스밧 곧 가데스에 이르러 아말렉 족속의 온 땅과 하사손다말에 사는 아모리 족속을 친지라'),
(1463129,51,1,14,8,'소돔 왕과, 고모라 왕과, 아드마 왕과, 스보임 왕과, 벨라 곧 소알 왕이 나와서 싯딤 골짜기에서 그들과 접전하였으니'),
(1463130,51,1,14,9,'곧 그 다섯 왕이 엘람 왕 그돌라오멜과, 고임 왕 디달과, 시날 왕 아므라벨과, 엘라살 왕 아리옥 네 왕과 교전하였더라'),
(1463131,51,1,14,10,'싯딤 골짜기에는 역청 구덩이가 많은지라 소돔 왕과 고모라 왕이 달아날 때에 군사가 거기 빠지고 그 나머지는 산으로 도망하매'),
(1463132,51,1,14,11,'네 왕이 소돔과 고모라의 모든 재물과 양식을 빼앗아 가고'),
(1463133,51,1,14,12,'소돔에 거하는 아브람의 조카 롯도 사로잡고 그 재물까지 노략하여 갔더라'),
(1463134,51,1,14,13,'도망한 자가 와서 히브리 사람 아브람에게 고하니 때에 아브람이 아모리 족속 마므레의 상수리 수풀 근처에 거하였더라 마므레는 에스골의 형제요 또 아넬의 형제라 이들은 아브람과 동맹한 자더라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463135,51,1,14,14,'아브람이 그 조카의 사로 잡혔음을 듣고 집에서 길리고 연습한 자 삼백 십 팔인을 거느리고 단까지 쫓아가서'),
(1463136,51,1,14,15,'그 가신을 나누어 밤을 타서 그들을 쳐서 파하고 다메섹 좌편 호바까지 쫓아가서'),
(1463137,51,1,14,16,'모든 빼앗겼던 재물과 자기 조카 롯과 그 재물과 또 부녀와 인민을 다 찾아 왔더라'),
(1463138,51,1,14,17,'아브람이 그돌라오멜과 그와 함께 한 왕들을 파하고 돌아올때에 소돔 왕이 사웨 골짜기 곧 왕곡에 나와 그를 영접하였고'),
(1463139,51,1,14,18,'살렘 왕 멜기세덱이 떡과 포도주를 가지고 나왔으니 그는 지극히 높으신 하나님의 제사장이었더라'),
(1463140,51,1,14,19,'그가 아브람에게 축복하여 가로되 `천지의 주재시요, 지극히 높으신 하나님이여 아브람에게 복을 주옵소서 !'),
(1463141,51,1,14,20,'너희 대적을 네 손에 붙이신 지극히 높으신 하나님을 찬송할지로다 !'' 하매 아브람이 그 얻은 것에서 십분 일을 멜기세덱에게 주었더라'),
(1463142,51,1,14,21,'소돔 왕이 아브람에게 이르되 `사람은 내게 보내고 물품은 네가 취하라'''),
(1463143,51,1,14,22,'아브람이 소돔 왕에게 이르되 `천지의 주재시요 지극히 높으신 하나님 여호와께 내가 손을 들어 맹세하노니'),
(1463144,51,1,14,23,'네 말이 내가 아브람으로 치부케 하였다 할까 하여 네게 속한 것은 무론 한 실이나 신들메라도 내가 취하지 아니하리라'),
(1463145,51,1,14,24,'오직 소년들의 먹은 것과 나와 동행한 아넬과 에스골과 마므레의 분깃을 제할지니 그들이 그 분깃을 취할 것이니라'''),
(1463146,51,1,15,1,'이 후에 여호와의 말씀이 이상 중에 아브람에게 임하여 가라사대 아브람아 두려워 말라! 나는 너의 방패요, 너의 지극히 큰 상급이니라'),
(1463147,51,1,15,2,'아브람이 가로되 `주 여호와여 무엇을 내게 주시려나이까 ? 나는 무자하오니 나의 상속자는 이 다메섹 엘리에셀이니이다'''),
(1463148,51,1,15,3,'아브람이 또 가로되 `주께서 내게 씨를 아니주셨으니 내 집에서 길리운 자가 나의 후사가 될 것이니이다'''),
(1463149,51,1,15,4,'여호와의 말씀이 그에게 임하여 가라사대 그 사람은 너의 후사가 아니라 네 몸에서 날 자가 네 후사가 되리라 하시고'),
(1463150,51,1,15,5,'그를 이끌고 밖으로 나가 가라사대 하늘을 우러러 뭇 별을 셀 수 있나 보라 ! 또 그에게 이르시되 네 자손이 이와 같으리라'),
(1463151,51,1,15,6,'아브람이 여호와를 믿으니 여호와께서 이를 그의 의로 여기시고'),
(1463152,51,1,15,7,'또 그에게 이르시되 나는 이 땅을 네게 주어 업을 삼게 하려고 너를 갈대아 우르에서 이끌어 낸 여호와로라 !'),
(1463153,51,1,15,8,'그가 가로되 `주, 여호와여 ! 내가 이 땅으로 업을 삼을 줄을 무엇로 알리이까 ?'''),
(1463154,51,1,15,9,'여호와께서 그에게 이르시되 나를 위하여 삼년 된 암소와, 삼년 된 암염소와, 삼년 된 수양과, 산비둘기와, 집비둘기 새끼를 취할지니라'),
(1463155,51,1,15,10,'아브람이 그 모든 것을 취하여 그 중간을 쪼개고 그 쪼갠 것을 마주 대하여 놓고 그 새는 쪼개지 아니하였으며'),
(1463156,51,1,15,11,'솔개가 그 사체위에 내릴 때에는 아브람이 쫓았더라'),
(1463157,51,1,15,12,'해질 때에 아브람이 깊이 잠든 중에 캄캄함이 임하므로 심히 두려워하더니'),
(1463158,51,1,15,13,'여호와께서 아브람에게 이르시되 너는 정녕히 알라 네 자손이 이방에서 객이 되어 그들을 섬기겠고 그들은 사백 년 동안 네 자손을 괴롭게 하리니'),
(1463159,51,1,15,14,'그 섬기는 나라를 내가 징치할지며 그 후에 네 자손이 큰 재물을 이끌고 나오리라'),
(1463160,51,1,15,15,'너는 장수하다가 평안히 조상에게로 돌아가 장사될 것이요'),
(1463161,51,1,15,16,'네 자손은 사 대만에 이 땅으로 돌아 오리니 이는 아모리 족속의 죄악이 아직 관영치 아니함이니라 하시더니'),
(1463162,51,1,15,17,'해가 져서 어둘 때에 연기 나는 풀무가 보이며 타는 횃불이 쪼갠 고기 사이로 지나더라'),
(1463163,51,1,15,18,'그 날에 여호와께서 아브람으로 더불어 언약을 세워 가라사대 내가 이땅을 애굽강에서부터 그 큰 강 유브라데까지 네 자손에게 주노니'),
(1463164,51,1,15,19,'곧 겐 족속과, 그니스 족속과, 갓몬 족속과,'),
(1463165,51,1,15,20,'헷 족속과, 브리스 족속과, 르바 족속과,'),
(1463166,51,1,15,21,'아모리 족속과, 가나안 족속과, 기르가스 족속과, 여부스 족속의 땅이니라 하셨더라'),
(1463167,51,1,16,1,'아브람의 아내 사래는 생산치 못하였고 그에게 한 여종이 있으니 애굽 사람이요 이름은 하갈이라'),
(1463168,51,1,16,2,'사래가 아브람에게 이르되 `여호와께서 나의 생산을 허락지 아니하셨으니 원컨대 나의 여종과 동침하라 내가 혹 그로 말미암아 자녀를 얻을까 하노라'' 하매 아브람이 사래의 말을 들으니라'),
(1463169,51,1,16,3,'아브람의 아내 사래가 그 여종 애굽 사람 하갈을 가져 그 남편 아브람에게 첩으로 준 때는 아브람이 가나안 땅에 거한지 십년 후이었더라'),
(1463170,51,1,16,4,'아브람이 하갈과 동침하였더니 하갈이 잉태하매 그가 자기의 잉태함을 깨닫고 그 여주인을 멸시한지라'),
(1463171,51,1,16,5,'사래가 아브람에게 이르되 `나의 받는 욕은 당신이 받아야 옳도다 내가 나의 여종을 당신의 품에 두었거늘 그가 자기의 잉태함을 깨닫고 나를 멸시하니 당신과 나 사이에 여호와께서 판단하시기를 원하노라'''),
(1463172,51,1,16,6,'아브람이 사래에게 이르되 `그대의 여종은 그대의 수중에 있으니 그대의 눈에 좋은대로 그에게 행하라'' 하매 사래가 하갈을 학대하였더니 하갈이 사래의 앞에서 도망하였더라'),
(1463173,51,1,16,7,'여호와의 사자가 광야의 샘 곁 곧 술 길 샘물 곁에서 그를 만나'),
(1463174,51,1,16,8,'가로되 `사래의 여종 하갈아 네가 어디서 왔으며 어디로 가느냐 ?'' 그가 가로되 `나는 나의 여주인 사래를 피하여 도망하나이다'''),
(1463175,51,1,16,9,'여호와의 사자가 그에게 이르되 네 여주인에게로 돌아가서 그 수하에 복종하라'),
(1463176,51,1,16,10,'여호와의 사자가 또 그에게 이르되 `내가 네 자손으로 크게 번성하여 그 수가 많아 셀 수 없게 하리라'),
(1463177,51,1,16,11,'여호와의 사자가 또 그에게 이르되 네가 잉태하였은즉 아들을 낳으리니 그 이름을 이스마엘이라 하라 이는 여호와께서 네 고통을 들으셨음이니라'),
(1463178,51,1,16,12,'그가 사람 중에 들나귀 같이 되리니 그 손이 모든 사람을 치겠고 모든 사람의 손이 그를 칠지며 그가 모든 형제의 동방에서 살리라'' 하니라'),
(1463179,51,1,16,13,'하갈이 자기에게 이르신 여호와의 이름을 감찰하시는 하나님이라 하였으니 이는 `내가 어떻게 여기서 나를 감찰하시는 하나님을 뵈었는고'' 함이라'),
(1463180,51,1,16,14,'이러므로 그 샘을 브엘라해로이라 불렀으며 그것이 가데스와 베렛 사이에 있더라'),
(1463181,51,1,16,15,'하갈이 아브람의 아들을 낳으매 아브람이 하갈의 낳은 그 아들을 이름하여 이스마엘이라 하였더라'),
(1463182,51,1,16,16,'하갈이 아브람에게 이스마엘을 낳을 때에 아브람이 팔십 육세이었더라'),
(1463183,51,1,17,1,'아브람의 구십 구세 때에 여호와께서 아브람에게 나타나서 그에게 이르시되 나는 전능한 하나님이라 ! 너는 내 앞에서 행하여 완전하라 !'),
(1463184,51,1,17,2,'내가 내 언약을 나와 너 사이에 세워 너로 심히 번성케 하리라 하시니');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463185,51,1,17,3,'아브람이 엎드린대 하나님이 또 그에게 일러 가라사대'),
(1463186,51,1,17,4,'내가 너와 내 언약을 세우니 너는 열국의 아비가 될지라'),
(1463187,51,1,17,5,'이제 후로는 네 이름을 아브람이라 하지 아니하고 아브라함이라 하리니 이는 내가 너로 열국의 아비가 되게 함이니라'),
(1463188,51,1,17,6,'내가 너로 심히 번성케 하리니 나라들이 네게로 좇아 일어나며 열왕이 네게로 좇아나리라'),
(1463189,51,1,17,7,'내가 내 언약을 나와 너와 네 대대 후손의 사이에 세워서 영원한 언약을 삼고 너와 네 후손의 하나님이 되리라'),
(1463190,51,1,17,8,'내가 너와 네 후손에게 너의 우거하는 이 땅 곧 가나안 일경으로 주어 영원한 기업이 되게 하고 나는 그들의 하나님이 되리라'),
(1463191,51,1,17,9,'하나님이 또 아브라함에게 이르시되 그런즉 너는 내 언약을 지키고 네 후손도 대대로 지키라 !'),
(1463192,51,1,17,10,'너희 중 남자는 다 할례를 받으라 ! 이것이 나와 너희와 너희 후손사이에 지킬 내 언약이니라'),
(1463193,51,1,17,11,'너희는 양피를 베어라 이것이 나와 너희 사이의 언약의 표징이니라'),
(1463194,51,1,17,12,'대대로 남자는 집에서 난 자나 혹 너희 자손이 아니요 이방 사람에게서 돈으로 산 자를 무론하고 난지 팔일 만에 할례를 받을 것이라'),
(1463195,51,1,17,13,'너희 집에서 난 자든지 너희 돈으로 산 자든지 할례를 받아야 하리니 이에 내 언약이 너희 살에 있어 영원한 언약이 되려니와'),
(1463196,51,1,17,14,'할례를 받지 아니한 남자 곧 그 양피를 베지 아니한 자는 백성 중에서 끊어지리니 그가 내 언약을 배반하였음이니라'),
(1463197,51,1,17,15,'하나님이 또 아브라함에게 이르시되 네 아내 사래는 이름을 사래라 하지 말고 그 이름을 사라라 하라'),
(1463198,51,1,17,16,'내가 그에게 복을 주어 그로 네게 아들을 낳아 주게 하며 내가 그에게 복을 주어 그로 열국의 어미가 되게 하리니 민족의 열왕이 그에게서 나리라'),
(1463199,51,1,17,17,'아브라함이 엎드리어 웃으며 심중에 이르되 `백세된 사람이 어찌 자식을 낳을까 ? 사라는 구십세니 어찌 생산하리요'' 하고'),
(1463200,51,1,17,18,'아브라함이 이에 하나님께 고하되 `이스마엘이나 하나님 앞에 살기를 원하나이다'''),
(1463201,51,1,17,19,'하나님이 가라사대 아니라 네 아내 사라가 정녕 네게 아들을 낳으리니 너는 그 이름을 이삭이라 하라 내가 그와 내 언약을 세우리리 그의 후손에게 영원한 언약이 되리라'),
(1463202,51,1,17,20,'이스마엘에게 이르러는 내가 네 말을 들었나니 내가 그에게 복을 주어 생육이 중다하여 그로 크게 번성케 할지라 그가 열 두 방백을 낳으리니 내가 그로 큰 나라가 되게 하려니와'),
(1463203,51,1,17,21,'내 언약은 내가 명년, 이 기한에 사라가 네게 낳을 이삭과 세우리라'),
(1463204,51,1,17,22,'하나님이 아브라함과 말씀을 마치시고 그를 떠나 올라가셨더라'),
(1463205,51,1,17,23,'이에 아브라함이 하나님이 자기에게 말씀하신 대로 이 날에 그 아들 이스마엘과 집에서 생장한 모든 자와 돈으로 산 모든 자 곧 아브라함의 집 사람 중 모든 남자를 데려다가 그 양피를 베었으니'),
(1463206,51,1,17,24,'아브라함이 그 양피를 벤때는 구십 구세이었고'),
(1463207,51,1,17,25,'그 아들 이스마엘이 그 양피를 벤 때는 십 삼세이었더라'),
(1463208,51,1,17,26,'당일에 아브라함과 그 아들 이스마엘이 할례를 받았고'),
(1463209,51,1,17,27,'그 집의 모든 남자 곧 집에서 생장한 자와 돈으로 이방 사람에게서 사온 자가 다 그와 함께 할례를 받았더라'),
(1463210,51,1,18,1,'여호와께서 마므레 상수리 수풀 근처에서 아브라함에게 나타나시니라 오정 즈음에 그가 장막 문에 앉았다가'),
(1463211,51,1,18,2,'눈을 들어 본즉 사람 셋이 맞은편에 섰는지라 그가 그들을 보자 곧 장막 문에서 달려나가 영접하며 몸을 땅에 굽혀'),
(1463212,51,1,18,3,'가로되 `내 주여 ! 내가 주께 은혜를 입었사오면 원컨대 종을 떠나 지나가지 마옵시고'),
(1463213,51,1,18,4,'물을 조금 가져오게 하사 당신들의 발을 씻으시고 나무 아래서 쉬소서'),
(1463214,51,1,18,5,'내가 떡을 조금 가져오리니 당신들의 마음을 쾌활케 하신 후에 지나가소서 당신들이 종에게 오셨음이니이다'' 그들이 가로되 `네 말대로 그리하라'''),
(1463215,51,1,18,6,'아브라함이 급히 장막에 들어가 사라에게 이르러 이르되 `속히 고운 가루 세 스아를 가져다가 반죽하여 떡을 만들라'' 하고'),
(1463216,51,1,18,7,'아브라함이 또 짐승 떼에 달려가서 기름지고 좋은 송아지를 취하여 하인에게 주니 그가 급히 요리한지라'),
(1463217,51,1,18,8,'아브라함이 뻐터와 우유와 하인이 요리한 송아지를 가져다가 그들의 앞에 진설하고 나무 아래 모셔 서매 그들이 먹으니라'),
(1463218,51,1,18,9,'그들이 아브라함에게 이르되 `네 아내 사라가 어디 있느냐 ?'' 대답하되 `장막에 있나이다'''),
(1463219,51,1,18,10,'그가 가라사대 `기한이 이를 때에 내가 정녕 네게로 돌아오리니 네 아내 사라에게 아들이 있으리라'' 하시니 사라가 그 뒤 장막 문에서 들었더라'),
(1463220,51,1,18,11,'아브라함과 사라가 나이 많아 늙었고 사라의 경수는 끊어졌는지라'),
(1463221,51,1,18,12,'사라가 속으로 웃고 이르되 `내가 노쇠하였고 내 주인도 늙었으니 내게 어찌 낙이 있으리요 ?'''),
(1463222,51,1,18,13,'여호와께서 아브라함에게 이르시되 사라가 왜 웃으며 이르기를 내가 늙었거늘 어떻게 아들을 낳으리요 하느냐 ?'),
(1463223,51,1,18,14,'여호와께 능치 못한 일이 있겠느냐 ! 기한이 이를 때에 내가 네게로 돌아오리니 사라에게 아들이 있으리라'),
(1463224,51,1,18,15,'사라가 두려워서 승인치 아니하여 가로되 `내가 웃지 아니하였나이다'' 가라사대 `아니라 네가 웃었느니라'''),
(1463225,51,1,18,16,'그 사람들이 거기서 일어나서 소돔으로 향하고 아브라함은 그들을 전송하러 함께 나가니라'),
(1463226,51,1,18,17,'여호와께서 가라사대 나의 하려는 것을 아브라함에게 숨기겠느냐 ?'),
(1463227,51,1,18,18,'아브라함은 강대한 나라가 되고 천하 만민은 그를 인하여 복을 받게 될 것이 아니냐 ?'),
(1463228,51,1,18,19,'내가 그로 그 자식과 권속에게 명하여 여호와의 도를 지켜 의와 공도를 행하게 하려고 그를 택하였나니 이는 나 여호와가 아브라함에게 대하여 말한 일을 이루려 함이니라'),
(1463229,51,1,18,20,'여호와께서 또 가라사대 소돔과 고모라에 대한 부르짖음이 크고 그 죄악이 심히 중하니'),
(1463230,51,1,18,21,'내가 이제 내려가서 그 모든 행한 것이 과연 내게 들린 부르짖음과 같은지 그렇지 않은지 내가 보고 알려하노라'),
(1463231,51,1,18,22,'그 사람들이 거기서 떠나 소돔으로 향하여 가고 아브라함은 여호와 앞에 그대로 섰더니'),
(1463232,51,1,18,23,'가까이 나아가 가로되 `주께서 의인을 악인과 함께 멸하시려나이까 ?'),
(1463233,51,1,18,24,'그 성 중에 의인 오십이 있을지라도 주께서 그 곳을 멸하시고 그 오십 의인을 위하여 용서치 아니하시리이까 ?'),
(1463234,51,1,18,25,'주께서 이같이 하사 의인을 악인과 함께 죽이심은 불가하오며 의인과 악인을 균등히 하심도 불가하니이다 세상을 심판하시는 이가 공의를 행하실 것이 아니니이까 ?''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463235,51,1,18,26,'여호와께서 가라사대 내가 만일 소돔 성 중에서 의인 오십을 찾으면 그들을 위하여 온 지경을 용서하리라'),
(1463236,51,1,18,27,'아브라함이 말씀하여 가로되 `티끌과 같은 나라도 감히 주께 고하나이다'),
(1463237,51,1,18,28,'오십 의인 중에 오인이 부족할 것이면 그 오인 부족함을 인하여 온 성을 멸하시리이까 ?'' 가라사대 내가 거기서 사십 오인을 찾으면 멸하지 아니하리라'),
(1463238,51,1,18,29,'아브라함이 또 고하여 가로되 `거기서 사십인을 찾으시면 어찌 하시려나이까 ?'' 가라사대 사십인을 인하여 멸하지 아니하리라'),
(1463239,51,1,18,30,'아브라함이 가로되 `내 주여 노하지 마옵시고 말씀하게 하옵소서 거기서 삼십인을 찾으시면 어찌 하시려나이까 ?'' 가라사대 내가 거기서 삼십인을 찾으면 멸하지 아니하리라'),
(1463240,51,1,18,31,'아브라함이 또 가로되 `내가 감히 내 주께 고하나이다 거기서 이십인을 찾으시면 어찌 하시려나이까 ?'' 가라사대 내가 이십인을 인하여 멸하지 아니하리라'),
(1463241,51,1,18,32,'아브라함이 또 가로되 `주는 노하지 마옵소서 내가 이번만 더 말씀하리이다 거기서 십인을 찾으시면 어찌 하시려나이까 ?'' 가라사대 내가 십인을 인하여도 멸하지 아니하리라'),
(1463242,51,1,18,33,'여호와께서 아브라함과 말씀을 마치시고 즉시 가시니 아브라함도 자기 곳으로 돌아갔더라'),
(1463243,51,1,19,1,'날이 저물 때에 그 두 천사가 소돔에 이르니 마침 롯이 소돔 성 문에 앉았다가 그들을 보고 일어나 영접하고 땅에 엎드리어 절하여'),
(1463244,51,1,19,2,'가로되 `내 주여 ! 돌이켜 종의 집으로 들어와 발을 씻고 주무시고 일찌기 일어나 갈 길을 가소서'' 그들이 가로되 `아니라 우리가 거리에서 경야하리라'''),
(1463245,51,1,19,3,'롯이 간청하매 그제야 돌이켜서 그 집으로 들어 오는지라 롯이 그들을 위하여 식탁을 베풀고 무교병을 구우니 그들이 먹으니라'),
(1463246,51,1,19,4,'그들의 눕기 전에 그 성 사람 곧 소돔 백성들이 무론 노소하고 사방에서 다 모여 그 집을 에워싸고'),
(1463247,51,1,19,5,'롯을 부르고 그에게 이르되 `이 저녁에 네게 온 사람이 어디 있느냐 ? 이끌어내라 우리가 그들을 상관하리라'''),
(1463248,51,1,19,6,'롯이 문 밖의 무리에게로 나가서 뒤로 문을 닫고'),
(1463249,51,1,19,7,'이르되 청하노니 `내 형제들아 이런 악을 행치 말라'),
(1463250,51,1,19,8,'내게 남자를 가까이 아니한 두 딸이 있노라 청컨대 내가 그들을 너희에게로 이끌어내리니 너희 눈에 좋은대로 그들에게 행하고 이 사람들은 내 집에 들어왔은즉 이 사람들에게는 아무 짓도 하지 말라'''),
(1463251,51,1,19,9,'그들이 가로되 `너는 물러나라'' 또 가로되 `이놈이 들어와서 우거하면서 우리의 법관이 되려 하는도다 이제 우리가 그들보다 너를 더 해하리라'' 하고 롯을 밀치며 가까이 나아와서 그 문을 깨치려 하는지라'),
(1463252,51,1,19,10,'그 사람들이 손을 내밀어 롯을 집으로 끌어들이고 문을 닫으며'),
(1463253,51,1,19,11,'문밖의 무리로 무론 대소하고 그 눈을 어둡게 하니 그들이 문을 찾느라고 곤비하였더라'),
(1463254,51,1,19,12,'그 사람들이 롯에게 이르되 `이 외에 네게 속한 자가 또 있느냐 ? 네 사위나 자녀나 성중에 네게 속한 자들을 다 성 밖으로 이끌어내라'),
(1463255,51,1,19,13,'그들에 대하여 부르짖음이 여호와 앞에 크므로 여호와께서 우리로 이 곳을 멸하러 보내셨나니 우리가 멸하리라'''),
(1463256,51,1,19,14,'롯이 나가서 그 딸과 정혼한 사위들에게 고하여 이르되 `여호와께서 이 성을 멸하실터이니 너희는 일어나 이 곳에서 떠나라'' 하되 그 사위들이 농담으로 여겼더라'),
(1463257,51,1,19,15,'동틀 때에 천사가 롯을 재촉하여 가로되 `일어나 여기 있는 네 아내와 두 딸을 이끌라 이 성의 죄악 중에 함께 멸망할까 하노라'''),
(1463258,51,1,19,16,'그러나 롯이 지체하매 그 사람들이 롯의 손과, 그 아내의 손과, 두 딸의 손을 잡아 인도하여 성밖에 두니 여호와께서 그에게 인자를 더하심이었더라'),
(1463259,51,1,19,17,'그 사람들이 그들을 밖으로 이끌어 낸 후에 이르되 `도망하여 생명을 보존하라 돌아보거나 들에 머무르거나 하지 말고 산으로 도망하여 멸망함을 면하라'''),
(1463260,51,1,19,18,'롯이 그들에게 이르되 `내 주여 그리 마옵소서'),
(1463261,51,1,19,19,'종이 주께 은혜를 얻었고 주께서 큰 인자를 내게 베푸사 내 생명을 구원하시오나 내가 도망하여 산까지 갈 수 없나이다 두렵건대 재앙을 만나 죽을까 하나이다'),
(1463262,51,1,19,20,'보소서 저 성은 도망하기 가깝고 작기도 하오니 나로 그 곳에 도망하게 하소서 이는 작은 성이 아니니이까 ? 내 생명이 보존되리이다'''),
(1463263,51,1,19,21,'그가 그에게 이르되 `내가 이 일에도 네 소원을 들었은즉 너의 말하는 성을 멸하지 아니하리니'),
(1463264,51,1,19,22,'그리로 속희 도망하라 네가 거기 이르기까지는 내가 아무 일도 행할 수 없노라 하였더라 그러므로 그 성 이름을 소알이라 불렀 더라'),
(1463265,51,1,19,23,'롯이 소알에 들어갈 때에 해가 돋았더라'),
(1463266,51,1,19,24,'여호와께서 하늘 곧 여호와에게로서 유황과 불을 비같이 소돔과 고모라에 내리사'),
(1463267,51,1,19,25,'그 성들과 온 들과 성에 거하는 모든 백성과 땅에 난것을 다 엎어 멸하셨더라'),
(1463268,51,1,19,26,'롯의 아내는 뒤를 돌아본고로 소금 기둥이 되었더라'),
(1463269,51,1,19,27,'아브라함이 그 아침에 일찌기 일어나 여호와의 앞에 섰던 곳에 이르러'),
(1463270,51,1,19,28,'소돔과 고모라와 그 온 들을 향하여 눈을 들어 연기가 옹기점 연기같이 치밀음을 보았더라'),
(1463271,51,1,19,29,'하나님이 들의 성들을 멸하실 때 곧 롯의 거하는 성을 엎으실 때에 아브라함을 생각하사 롯을 그 엎으시는 중에서 내어 보내셨더라'),
(1463272,51,1,19,30,'롯이 소알에 거하기를 두려워하여 두 딸과 함께 소알에서 나와 산에 올라 거하되 그 두 딸과 함께 굴에 거하였더니'),
(1463273,51,1,19,31,'큰 딸이 작은 딸에게 이르되 `우리 아버지는 늙으셨고 이 땅에는 세상의 도리를 좇아 우리의 배필 될 사람이 없으니'),
(1463274,51,1,19,32,'우리가 우리 아버지에게 술을 마시우고 동침하여 우리 아버지로 말미암아 인종을 전하자'' 하고'),
(1463275,51,1,19,33,'그 밤에 그들이 아비에게 술을 마시우고 큰 딸이 들어가서 그 아비와 동침하니라 그러나 그 아비는 그 딸의 눕고 일어나는 것을 깨닫지 못하였더라'),
(1463276,51,1,19,34,'이튿날에 큰 딸이 작은 딸에게 이르되 `어제 밤에는 내가 우리 아버지와 동침하였으니 오늘 밤에도 우리가 아버지에게 술을 마시우고 네가 들어가 동침하고 우리가 아버지로 말미암아 인종을 전하자'' 하고'),
(1463277,51,1,19,35,'이 밤에도 그들이 아비에게 술을 마시우고 작은 딸이 일어나 아비와 동침하니라 그러나 아비는 그 딸의 눕고 일어나는 것을 깨닫지 못하였더라'),
(1463278,51,1,19,36,'롯의 두 딸이 아비로 말미암아 잉태하고'),
(1463279,51,1,19,37,'큰 딸은 아들을 낳아 이름을 모압이라 하였으니 오늘날 모압 족속의 조상이요'),
(1463280,51,1,19,38,'작은 딸도 아들을 낳아 이름을 벤암미라 하였으니 오늘날 암몬 족속의 조상이었더라'),
(1463281,51,1,20,1,'아브라함이 거기서 남방으로 이사하여 가데스와 술 사이 그랄에 우거하며'),
(1463282,51,1,20,2,'그 아내 사라를 자기 누이라 하였으므로 그랄 왕 아비멜렉이 보내어 사라를 취하였더니'),
(1463283,51,1,20,3,'그 밤에 하나님이 아비멜렉에게 현몽하시고 그에게 이르시되 네가 취한 이 여인을 인하여 네가 죽으리니 그가 남의 아내임이니라'),
(1463284,51,1,20,4,'아비멜렉이 그 여인을 가까이 아니한 고로 그가 대답하되 `주여, 주께서 의로운 백성도 멸하시나이까 ?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463285,51,1,20,5,'그가 나더러 이는 내 누이라고 하지 아니하였나이까 ? 그 여인도 그는 내 오라비라 하였사오니 나는 온전한 마음과 깨끗한 손으로 이렇게 하였나이다'''),
(1463286,51,1,20,6,'하나님이 꿈에 또 그에게 이르시되 네가 온전한 마음으로 이렇게 한 줄을 나도 알았으므로 너를 막아 내게 범죄하지 않게 하였나니 여인에게 가까이 못하게 함이 이 까닭이니라'),
(1463287,51,1,20,7,'이제 그 사람의 아내를 돌려 보내라 그는 선지자라 그가 너를 위하여 기도하리니 네가 살려니와 네가 돌려 보내지 않으면 너와 네게 속한 자가 다 정녕 죽을 줄 알지니라'),
(1463288,51,1,20,8,'아비멜렉이 그 아침에 일찌기 일어나 모든 신복을 불러 그 일을 다 말하여 들리매 그 사람들이 심히 두려워하였더라'),
(1463289,51,1,20,9,'아비멜렉이 아브라함을 불러서 그에게 이르되 `네가 어찌하여 우리에게 이리 하느냐 ? 내가 무슨 죄를 네게 범하였관대 네가 나와 내 나라로 큰 죄에 빠질 뻔하게 하였느냐 ? 네가 합당치 않은 일을 네게 행하였도다` 하고'),
(1463290,51,1,20,10,'아비멜렉이 또 아브라함에게 이르되 `네가 무슨 의견으로 이렇게 하였느냐 ?'''),
(1463291,51,1,20,11,'아브라함이 가로되 `이곳에서는 하나님을 두려워함이 없으니 내 아내를 인하여 사람이 나를 죽일까 생각하였음이요'),
(1463292,51,1,20,12,'또 그는 실로 나의 이복 누이로서 내 처가 되었음이니라'),
(1463293,51,1,20,13,'하나님이 나로 내 아비 집을 떠나 두루 다니게 하실 때에 내가 아내에게 말하기를 이후로 우리의 가는 곳마다 그대는 나를 그대의 오라비라 하라 이것이 그대가 내게 베풀 은혜라 하였었노라`'),
(1463294,51,1,20,14,'아비멜렉이 양과 소와 노비를 취하여 아브라함에게 주고 그 아내 사라도 그에게 돌려보내고'),
(1463295,51,1,20,15,'아브라함에게 이르되 `내 땅이 네 앞에 있으니 너 보기에 좋은 대로 거하라'' 하고'),
(1463296,51,1,20,16,'사라에게 이르되 `내가 은 천개를 네 오라비에게 주어서 그것으로 너와 함께 한 여러 사람 앞에서 네 수치를 풀게 하였노니 네 일이 다 선히 해결되었느니라'''),
(1463297,51,1,20,17,'아브라함이 하나님께 기도하매 하나님이 아비멜렉과 그 아내와 여종을 치료하사 생산케 하셨으니'),
(1463298,51,1,20,18,'여호와께서 이왕에 아브라함의 아내 사라의 연고로 아비멜렉의 집 모든 태를 닫히셨음이더라'),
(1463299,51,1,21,1,'여호와께서 그 말씀대로 사라를 권고하셨고 여호와께서 그 말씀대로 사라에게 행하셨으므로'),
(1463300,51,1,21,2,'사라가 잉태하고 하나님의 말씀하신 기한에 미쳐 늙은 아브라함에게 아들을 낳으니'),
(1463301,51,1,21,3,'아브라함이 그 낳은 아들 곧 사라가 자기에게 낳은 아들을 이름하여 이삭이라 하였고'),
(1463302,51,1,21,4,'그 아들 이삭이 난지 팔일만에 그가 하나님의 명대로 할례를 행하였더라'),
(1463303,51,1,21,5,'아브라함이 그 아들 이삭을 낳을 때에 백세라'),
(1463304,51,1,21,6,'사라가 가로되 `하나님이 나로 웃게 하시니 듣는 자가 다 나와 함께 웃으리로다'''),
(1463305,51,1,21,7,'또 가로되 `사라가 자식들을 젖 먹이겠다고 누가 아브라함에게 말하였으리요 마는 아브라함 노경에 내가 아들을 낳았도다'' 하니라'),
(1463306,51,1,21,8,'아이가 자라매 젖을 떼고 이삭의 젖을 떼는 날에 아브라함이 대연을 배설하였더라'),
(1463307,51,1,21,9,'사라가 본즉 아브라함의 아들 애굽 여인 하갈의 소생이 이삭을 희롱하는지라'),
(1463308,51,1,21,10,'그가 아브라함에게 이르되 `이 여종과 그 아들을 내어 쫓으라 이 종의 아들은 내 아들 이삭과 함께 기업을 얻지 못하리라'' 하매'),
(1463309,51,1,21,11,'아브라함이 그 아들을 위하여 그 일이 깊이 근심이 되었더니'),
(1463310,51,1,21,12,'하나님이 아브라함에게 이르시되 네 아이나 네 여종을 위하여 근심치 말고 사라가 네게 이른 말을 다 들으라 ! 이삭에게서 나는 자라야 네 씨라 칭할 것임이니라'),
(1463311,51,1,21,13,'그러나 여종의 아들도 네 씨니 내가 그로 한 민족을 이루게 하리라 하신지라'),
(1463312,51,1,21,14,'아브라함이 아침에 일찌기 일어나 떡과 물 한 가죽부대를 취하여 하갈의 어깨에 메워 주고 그 자식을 이끌고 가게 하매 하갈이 나가서 브엘세바 들에서 방황하더니'),
(1463313,51,1,21,15,'가죽부대의 물이 다한지라 그 자식을 떨기나무 아래 두며'),
(1463314,51,1,21,16,'가로되 `자식의 죽는 것을 참아 보지 못하겠다'' 하고 살 한 바탕쯤가서 마주 앉아 바라보며 방성대곡하니'),
(1463315,51,1,21,17,'하나님이 그 아이의 소리를 들으시므로 하나님의 사자가 하늘에서부터 하갈을 불러 가라사대 `하갈아, 무슨 일이냐 ? 두려워 말라 ! 하나님이 거기 있는 아이의 소리를 들으셨나니'),
(1463316,51,1,21,18,'일어나 아이를 일으켜 네 손으로 붙들라 그로 큰 민족을 이루게 하리라'' 하시니라'),
(1463317,51,1,21,19,'하나님이 하갈의 눈을 밝히시매 샘물을 보고 가서 가죽부대에 물을 채워다가 그 아이에게 마시웠더라'),
(1463318,51,1,21,20,'하나님이 그 아이와 함께 계시매 그가 장성하여 광야에 거하며 활쏘는 자가 되었더니'),
(1463319,51,1,21,21,'그가 바란 광야에 거할 때에 그 어미가 그를 위하여 애굽땅 여인을 취하여 아내를 삼게 하였더라'),
(1463320,51,1,21,22,'때에 아비멜렉과 그 군대 장관 비골이 아브라함에게 말하여 가로되 네가 무슨 일을 하든지 하나님이 너와 함께 계시도다 !'),
(1463321,51,1,21,23,'그런즉 너는 나와 내 아들과 내 손자에게 거짓되이 행치 않기를 이제 여기서 하나님을 가리켜 내게 맹세하라 내가 네게 후대한대로 너도 나와 너의 머무는 이 땅에 행할 것이니라'),
(1463322,51,1,21,24,'아브라함이 가로되 `내가 맹세하리라'' 하고'),
(1463323,51,1,21,25,'아비멜렉의 종들이 아브라함의 우물을 늑탈한 일에 대하여 아브라함이 아비멜렉을 책망하매'),
(1463324,51,1,21,26,'아비멜렉이 가로되 `누가 그리하였는지 내가 알지 못하노라 너도 내게 고하지 아니하였고 나도 듣지 못하였더니 오늘이야 들었노라'''),
(1463325,51,1,21,27,'아브라함이 양과 소를 취하여 아비멜렉에게 주고 두 사람이 서로 언약을 세우니라'),
(1463326,51,1,21,28,'아브라함이 일곱 암양 새끼를 따로 놓으니'),
(1463327,51,1,21,29,'아비멜렉이 아브라함에게 이르되 `이 일곱 암양 새끼를 따로 놓음은 어찜이뇨 ?'''),
(1463328,51,1,21,30,'아브라함이 가로되 `너는 내 손에서 이 암양 새끼 일곱을 받아 내가 이 우물 판 증거를 삼으라'' 하고'),
(1463329,51,1,21,31,'두 사람이 거기서 서로 맹세하였으므로 그 곳을 브엘세바라 이름하였더라'),
(1463330,51,1,21,32,'그들이 브엘세바에서 언약을 세우매 아비멜렉과 그 군대 장관 비골은 떠나 블레셋 족속의 땅으로 돌아갔고'),
(1463331,51,1,21,33,'아브라함은 브엘세바에 에셀나무를 심고 거기서 영생하시는 하나님 여호와의 이름을 불렀으며'),
(1463332,51,1,21,34,'그가 블레셋 족속의 땅에서 여러 날을 지내었더라'),
(1463333,51,1,22,1,'그 일 후에 하나님이 아브라함을 시험하시려고 그를 부르시되 아브라함아 하시니 그가 가로되 `내가 여기 있나이다'''),
(1463334,51,1,22,2,'여호와께서 가라사대 네 아들 네 사랑하는 독자 이삭을 데리고 모리아 땅으로 가서 내가 네게 지시하는 한 산 거기서 그를 번제로 드리라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463335,51,1,22,3,'아브라함이 아침에 일찌기 일어나 나귀에 안장을 지우고 두 사환과 그 아들 이삭을 데리고 번제에 쓸 나무를 쪼개어 가지고 떠나 하나님의 자기에게 지시하시는 곳으로 가더니'),
(1463336,51,1,22,4,'제 삼일에 아브라함이 눈을 들어 그곳을 멀리 바라본지라'),
(1463337,51,1,22,5,'이에 아브라함이 사환에게 이르되 `너희는 나귀와 함께 여기서 기다리라 내가 아이와 함께 저기 가서 경배하고 너희에게로 돌아오리라'' 하고'),
(1463338,51,1,22,6,'아브라함이 이에 번제 나무를 취하여 그 아들 이삭에게 지우고 자기는 불과 칼을 손에 들고 두 사람이 동행하더니'),
(1463339,51,1,22,7,'이삭이 그 아비 아브라함에게 말하여 가로되 `내 아버지여'' 하니 그가 가로되 `내 아들아 내가 여기 있노라'' 이삭이 가로되 `불과 나무는 있거니와 번제할 어린 양은 어디 있나이까 ?'''),
(1463340,51,1,22,8,'아브라함이 가로되 `아들아, 번제할 어린 양은 하나님이 자기를 위하여 친히 준비하시리라'' 하고 두 사람이 함께 나아가서'),
(1463341,51,1,22,9,'하나님이 그에게 지시하신 곳에 이른지라 이에 아브라함이 그곳에 단을 쌓고 나무를 벌여놓고 그 아들 이삭을 결박하여 단 나무위에 놓고'),
(1463342,51,1,22,10,'손을 내밀어 칼을 잡고 그 아들을 잡으려 하더니'),
(1463343,51,1,22,11,'여호와의 사자가 하늘에서부터 그를 불러 가라사대 `아브라함아, 아브라함아'' 하시는지라 아브라함이 가로되 `내가 여기 있나이다'' 하매'),
(1463344,51,1,22,12,'사자가 가라사대 `그 아이에게 네 손을 대지 말라 아무 일도 그에게 하지 말라 네가 네 아들 네 독자라도 내게 아끼지 아니하였으니 내가 이제야 네가 하나님을 경외하는 줄을 아노라'''),
(1463345,51,1,22,13,'아브라함이 눈을 들어 살펴본즉 한 수양이 뒤에 있는데 뿔이 수풀에 걸렸는지라 아브라함이 가서 그 수양을 가져다가 아들을 대신하여 번제로 드렸더라'),
(1463346,51,1,22,14,'아브라함이 그 땅 이름을 `여호와 이레'' 라 하였으므로 오늘까지 사람들이 이르기를 `여호와의 산에서 준비되리라'' 하더라'),
(1463347,51,1,22,15,'여호와의 사자가 하늘에서부터 두번째 아브라함을 불러'),
(1463348,51,1,22,16,'가라사대 여호와께서 이르시기를 내가 나를 가리켜 맹세하노니 네가 이같이 행하여 네 아들 네 독자를 아끼지 아니하였은즉'),
(1463349,51,1,22,17,'내가 네게 큰 복을 주고 네 씨로 크게 성하여 하늘의 별과 같고 바닷가의 모래와 같게 하리니 네 씨가 그 대적의 문을 얻으리라'),
(1463350,51,1,22,18,'또 네 씨로 말미암아 천하 만민이 복을 얻으리니 이는 네가 나의 말을 준행하였음이니라 ! 하셨다 하니라'),
(1463351,51,1,22,19,'이에 아브라함이 그 사환에게로 돌아와서 함께 떠나 브엘세바에 이르러 거기 거하였더라'),
(1463352,51,1,22,20,'이일 후에 혹이 아브라함에게 고하여 이르기를 `밀가가 그대의 동생 나홀에게 자녀를 낳았다'' 하였더라'),
(1463353,51,1,22,21,'그 맏아들은 우스요 우스의 동생은 부스와, 아람의 아비 그므엘과'),
(1463354,51,1,22,22,'게셋과, 하소와, 빌다스와, 이들랍과, 브두엘이라'),
(1463355,51,1,22,23,'이 여덟 사람은 아브라함의 동생 나홀의 처 밀가의 소생이며 브두엘은 리브가를 낳았고'),
(1463356,51,1,22,24,'나홀의 첩 르우마라 하는 자도 데바와, 가함과, 다하스와, 마아가를 낳았더라'),
(1463357,51,1,23,1,'사라가 일백 이십 칠세를 살았으니 이것이 곧 사라의 향년이라'),
(1463358,51,1,23,2,'사라가 가나안 땅 헤브론 곧 기럇아르바에서 죽으매 아브라함이 들어가서 사라를 위하여 슬퍼하며 애통하다가'),
(1463359,51,1,23,3,'그 시체 앞에서 일어나 나가서 헷 족속에게 말하여 가로되'),
(1463360,51,1,23,4,'`나는 당신들 중에 나그네요, 우거한 자니 청컨대 당신들 중에서 내게 매장지를 주어 소유를 삼아 나로 내 죽은 자를 내어 장사하게 하시오'''),
(1463361,51,1,23,5,'헷 족속이 아브라함에게 대답하여 가로되'),
(1463362,51,1,23,6,'`내 주여, 들으소서 당신은 우리 중 하나님의 방백이시니 우리 묘실 중에서 좋은 것을 택하여 당신의 죽은 자를 장사하소서 우리 중에서 자기 묘실에 당신의 죽은 자 장사함을 금할 자가 없으리이다'''),
(1463363,51,1,23,7,'아브라함이 일어나 그 땅 거민 헷 족속을 향하여 몸을 굽히고'),
(1463364,51,1,23,8,'그들에게 말하여 가로되 `나로 나의 죽은 자를 내어 장사하게 하는 일이 당신들의 뜻일진대 내 말을 듣고 나를 위하여 소할의 아들 에브론에게 구하여'),
(1463365,51,1,23,9,'그로 그 밭머리에 있는 막벨라 굴을 내게 주게 하되 준가를 받고 그 굴을 내게 주어서 당신들 중에 내 소유 매장지가 되게 하기를 원하노라'),
(1463366,51,1,23,10,'때에 에브론이 헷 족속 중에 앉았더니 그가 헷 족속 곧 성문에 들어온 모든 자의 듣는데 아브라함에게 대답하여 가로되'),
(1463367,51,1,23,11,'`내 주여, 그리 마시고 내 말을 들으소서 내가 그 밭을 당신께 드리되 내가 내 동족 앞에서 당신께 드리고 그 속의 굴도 내가 당신께 드리되 내가 내 동족 앞에서 당신께 드리오니 당신의 죽은 자를 장사하소서'''),
(1463368,51,1,23,12,'아브라함이 이에 그 땅 백성을 대하여 몸을 굽히고'),
(1463369,51,1,23,13,'그 땅 백성의 듣는데 에브론에게 말하여 가로되 `당신이 합당히 여기면 청컨대 내 말을 들으시오 내가 그 밭값을 당신에게 주리니 당신은 내게서 받으시오 내가 나의 죽은 자를 거기 장사하겠노라'''),
(1463370,51,1,23,14,'에브론이 아브라함에게 대답하여 가로되'),
(1463371,51,1,23,15,'`내 주여, 내게 들으소서 땅값은 은 사백 세겔이나 나와 당신 사이에 어찌 교계하리이까 ? 당신의 죽은 자를 장사하소서'''),
(1463372,51,1,23,16,'아브라함이 에브론의 말을 좇아 에브론이 헷 족속의 듣는데서 말한 대로 상고의 통용하는 은 사백 세겔을 달아 에브론에게 주었더니'),
(1463373,51,1,23,17,'마므레 앞 막벨라에 있는 에브론의 밭을 바꾸어 그 속의 굴과 그 사방에 둘린 수목을 다'),
(1463374,51,1,23,18,'성문에 들어온 헷 족속 앞에서 아브라함의 소유로 정한지라'),
(1463375,51,1,23,19,'그 후에 아브라함이 그 아내 사라를 가나안 땅 마므레 앞 막벨라밭 굴에 장사하였더라 (마므레는 곧 헤브론이라)'),
(1463376,51,1,23,20,'이와 같이 그 밭과 그 속의 굴을 헷 족속이 아브라함 소유 매장지로 정하였더라'),
(1463377,51,1,24,1,'아브라함이 나이 많아 늙었고 여호와께서 그의 범사에 복을 주셨더라'),
(1463378,51,1,24,2,'아브라함이 자기 집 모든 소유를 맡은 늙은 종에게 이르되 `청컨대 네 손을 내 환도뼈 밑에 넣으라'),
(1463379,51,1,24,3,'내가 너로 하늘의 하나님, 땅의 하나님이신 여호와를 가리켜 맹세하게 하노니 너는 나의 거하는 이 지방 가나안 족속의 딸 중에서 내 아들을 위하여 아내를 택하지 말고'),
(1463380,51,1,24,4,'내 고향 내 족속에게로 가서 내 아들 이삭을 위하여 아내를 택하라'''),
(1463381,51,1,24,5,'종이 가로되 `여자가 나를 좇아 이 땅으로 오고자 아니하거든 내가 주인의 아들을 주인의 나오신 땅으로 인도하여 돌아가리이까 ?'''),
(1463382,51,1,24,6,'아브라함이 그에게 이르되 `삼가 내 아들을 그리로 데리고 돌아가지 말라'),
(1463383,51,1,24,7,'하늘의 하나님 여호와께서 나를 내 아버지의 집과 내 본토에서 떠나게 하시고 내게 말씀하시며 내게 맹세하여 이르시기를 이 땅을 네 씨에게 주리라 하셨으니 그가 그 사자를 네 앞서 보내실지라 네가 거기서 내 아들을 위하여 아내를 택할지니라'),
(1463384,51,1,24,8,'만일 여자가 너를 좇아 오고자 아니하면 나의 이 맹세가 너와 상관이 없나니 오직 내 아들을 데리고 그리로 가지 말지니라''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463385,51,1,24,9,'종이 이에 주인 아브라함의 환도뼈 아래 손을 넣고 이 일에 대하여 그에게 맹세하였더라'),
(1463386,51,1,24,10,'이에 종이 그 주인의 약대 중 열 필을 취하고 떠났는데 곧 그 주인의 모든 좋은 것을 가지고 떠나 메소보다미아로 가서 나홀의 성에 이르러'),
(1463387,51,1,24,11,'그 약대를 성 밖 우물 곁에 꿇렸으니 저녁 때라 여인들이 물을 길러 나올 때이었더라'),
(1463388,51,1,24,12,'그가 가로되 `우리 주인 아브라함의 하나님 여호와여 ! 원컨대 오늘날 나로 순적히 만나게 하사 나의 주인 아브라함에게 은혜를 베푸시옵소서 !'),
(1463389,51,1,24,13,'성 중 사람의 딸들이 물 길러 나오겠사오니 내가 우물 곁에 섰다가'),
(1463390,51,1,24,14,'한 소녀에게 이르기를 청컨대 너는 물 항아리를 기울여 나로 마시게 하라 하리니 그의 대답이 마시라 내가 당신의 약대에게도 마시우리라 하면 그는 주께서 주의 종 이삭을 위하여 정하신 자라 이로 인하여 주께서 나의 주인에게 은혜 베푸심을 내가 알겠나이다'''),
(1463391,51,1,24,15,'말을 마치지 못하여서 리브가가 물 항아리를 어깨에 메고 나오니 그는 아브라함의 동생 나홀의 아내 밀가의 아들 브두엘의 소생이라'),
(1463392,51,1,24,16,'그 소녀는 보기에 심히 아리땁고 지금까지 남자가 가까이 하지 아니한 처녀더라 그가 우물에 내려가서 물을 그 물 항아리에 채워 가지고 올라오는지라'),
(1463393,51,1,24,17,'종이 마주 달려가서 가로되 `청컨대 네 물 항아리의 물을 내게 조금 마시우라'''),
(1463394,51,1,24,18,'그가 가로되 `주여, 마시소서'' 하며 급히 그 물 항아리를 손에 내려 마시게 하고'),
(1463395,51,1,24,19,'마시우기를 다하고 가로되 `당신의 약대도 위하여 물을 길어 그것들로 배불리 마시게 하리이다'' 하고'),
(1463396,51,1,24,20,'급히 물 항아리의 물을 구유에 붓고 다시 길으려고 우물로 달려가서 모든 약대를 위하여 긷는지라'),
(1463397,51,1,24,21,'그 사람이 그를 묵묵히 주목하며 여호와께서 과연 평탄한 길을 주신 여부를 알고자 하더니'),
(1463398,51,1,24,22,'약대가 마시기를 다하매 그가 반 세겔중 금고리 한개와, 열 세겔중 금 손목고리 한 쌍을 그에게 주며'),
(1463399,51,1,24,23,'가로되 `네가 뉘 딸이냐 ? 청컨대 내게 고하라 네 부친의 집에 우리 유숙할 곳이 있느냐 ?'''),
(1463400,51,1,24,24,'그 여자가 그에게 이르되 `나는 밀가가 나홀에게 낳은 아들 브두엘의 딸이니이다'''),
(1463401,51,1,24,25,'또 가로되 `우리에게 짚과 보리가 족하며 유숙할 곳도 있나이다'''),
(1463402,51,1,24,26,'이에 그 사람이 머리를 숙여 여호와께 경배하고'),
(1463403,51,1,24,27,'가로되 `나의 주인 아브라함의 하나님 여호와를 찬송하나이다 ! 나의 주인에게 주의 인자와 성실을 끊이지 아니하셨사오며 여호와께서 길에서 나를 인도하사 내 주인의 동생집에 이르게 하셨나이다'' 하니라'),
(1463404,51,1,24,28,'소녀가 달려가서 이 일을 어미 집에 고하였더니'),
(1463405,51,1,24,29,'리브가에게 오라비가 있어 이름은 라반이라 그가 우물로 달려가 그 사람에게 이르니'),
(1463406,51,1,24,30,'그가 그 누이의 고리와 그 손의 손목고리를 보고 또 그 누이 리브가가 그 사람이 자기에게 이같이 말하더라 함을 듣고 그 사람에게로 나아감이라 때에 그가 우물가 약대 곁에 섰더라'),
(1463407,51,1,24,31,'라반이 가로되 `여호와께 복을 받은 자여 ! 들어오소서 어찌 밖에 섰나이까 ? 내가 방과 약대의 처소를 예비하였나이다'''),
(1463408,51,1,24,32,'그 사람이 집으로 들어가매 라반이 약대의 짐을 부리고 짚과 보리를 약대에게 주고 그 사람의 발과 그 종자의 발 씻을 물을 주고'),
(1463409,51,1,24,33,'그 앞에 식물을 베푸니 그 사람이 가로되 `내가 내 일을 진술하기 전에는 먹지 아니하겠나이다'' 라반이 가로되 `말하소서'''),
(1463410,51,1,24,34,'그가 가로되 `나는 아브라함의 종이니이다'),
(1463411,51,1,24,35,'여호와께서 나의 주인에게 크게 복을 주어 창성케 하시되 우양과, 은,금과, 노비와, 약대와, 나귀를 그에게 주셨고'),
(1463412,51,1,24,36,'나의 주인의 부인 사라가 노년에 나의 주인에게 아들을 낳으매 주인이 그 모든 소유를 그 아들에게 주었나이다'),
(1463413,51,1,24,37,'나의 주인이 나로 맹세하게 하여 가로되 너는 내 아들을 위하여 나 사는 땅 가나안 족속의 딸 중에서 아내를 택하지 말고'),
(1463414,51,1,24,38,'내 아비 집 내 족속에게로 가서 내 아들을 위하여 아내를 택하라 하시기로'),
(1463415,51,1,24,39,'내가 내 주인에게 말씀하되 혹 여자가 나를 좇지 아니하면 어찌 하리이까 ? 한즉'),
(1463416,51,1,24,40,'주인이 내게 이르되 나의 섬기는 여호와께서 그 사자를 너와 함께 보내어 네게 평탄한 길을 주시리니 너는 내 족속 중 내 아비 집에서 내 아들을 위하여 아내를 택할 것이니라'),
(1463417,51,1,24,41,'네가 내 족속에게 이를 때에는 네가 내 맹세와 상관이 없으리라 설혹 그들이 네게 주지 아니할지라도 네가 내 맹세와 상관이 없으리라 하시기로'),
(1463418,51,1,24,42,'내가 오늘 우물에 이르러 말씀하기를 나의 주인 아브라함의 하나님 여호와여, 만일 나의 행하는 길에 형통함을 주실진대'),
(1463419,51,1,24,43,'내가 이 우물 곁에 섰다가 청년 여자가 물을 길러 오거든 내가 그에게 청하기를 너는 물 항아리의 물을 내게 조금 마시우라 하여'),
(1463420,51,1,24,44,'그의 대답이 당신은 마시라 내가 또 당신의 약대를 위하여도 길으리라 하면 그 여자는 여호와께서 나의 주인의 아들을 위하여 정하여 주신 자가 되리이다 하며'),
(1463421,51,1,24,45,'내가 묵도하기를 마치지 못하여 리브가가 물 항아리를 어깨에 메고 나와서 우물로 내려와 긷기로 내가 그에게 이르기를 청컨대 내게 마시우라 한즉'),
(1463422,51,1,24,46,'그가 급히 물 항아리를 어깨에서 내리며 가로되 마시라 내가 당신의 약대에게도 마시우리라 하기로 내가 마시매 그가 또 약대에게도 마시운지라'),
(1463423,51,1,24,47,'내가 그에게 묻기를 네가 뉘 딸이뇨? 한즉 가로되 밀가가 나홀에게 낳은 브두엘의 딸이라 하기로 내가 고리를 그 코에 꿰고 손목고리를 그 손에 끼우고'),
(1463424,51,1,24,48,'나의 주인 아브라함의 하나님 여호와께서 나를 바른 길로 인도하사 나의 주인의 동생의 딸을 그 아들을 위하여 택하게 하셨으므로 내가 머리를 숙여 그에게 경배하고 찬송하였나이다 !'),
(1463425,51,1,24,49,'이제 당신들이 인자와 진실로 나의 주인을 대접하려거든 내게 고하시고 그렇지 않을지라도 내게 고하여 나로 좌우간 행하게 하소서'''),
(1463426,51,1,24,50,'라반과 브두엘이 대답하여 가로되 `이 일이 여호와께로 말미암았으니 우리는 가부를 말할 수 없노라'),
(1463427,51,1,24,51,'리브가가 그대 앞에 있으니 데리고 가서 여호와의 명대로 그로 그대의 주인의 아들의 아내가 되게 하라'''),
(1463428,51,1,24,52,'아브라함의 종이 그들의 말을 듣고 땅에 엎드리어 여호와께 절하고'),
(1463429,51,1,24,53,'은,금 패물과 의복을 꺼내어 리브가에게 주고 그 오라비와 어미에게도 보물을 주니라'),
(1463430,51,1,24,54,'이에 그들 곧 종과 종자들이 먹고 마시고 유숙하고 아침에 일어나서 그가 가로되 `나를 보내어 내 주인에게로 돌아가게 하소서'''),
(1463431,51,1,24,55,'리브가의 오라비와 그 어미가 가로되 `소녀로 며칠을 적어도 열흘을 우리와 함께 있게 하라 그 후에 그가 갈 것이니라'''),
(1463432,51,1,24,56,'그 사람이 그들에게 이르되 `나를 만류치 마소서 여호와께서 내게 형통한 길을 주셨으니 나를 보내어 내 주인에게로 돌아가게 하소서'''),
(1463433,51,1,24,57,'그들이 가로되 `우리가 소녀를 불러 그에게 물으리라` 하고'),
(1463434,51,1,24,58,'리브가를 불러 그에게 이르되 `네가 이 사람과 함께 가려느냐 ?` 그가 대답하되 `가겠나이다''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463435,51,1,24,59,'그들이 그 누이 리브가와 그의 유모와 아브라함의 종과 종자들을 보내며'),
(1463436,51,1,24,60,'리브가에게 축복하여 가로되 `우리 누이여, 너는 천만인의 어미가 될지어다 ! 네 씨로 그 원수의 성문을 얻게 할지어다'''),
(1463437,51,1,24,61,'리브가가 일어나 비자와 함께 약대를 타고 그 사람을 따라가니 종이 리브가를 데리고 가니라'),
(1463438,51,1,24,62,'때에 이삭이 브엘 라해로이에서 왔으니 그가 남방에 거하였었음이라'),
(1463439,51,1,24,63,'이삭이 저물 때에 들에 나가 묵상하다가 눈을 들어 보매 약대들이 오더라'),
(1463440,51,1,24,64,'리브가가 눈을 들어 이삭을 바라보고 약대에서 내려'),
(1463441,51,1,24,65,'종에게 말하되 `들에서 배회하다가 우리에게로 마주 오는 자가 누구뇨 ?'' 종이 가로되 `이는 내 주인이니이다'' 리브가가 면박을 취하여 스스로 가리우더라'),
(1463442,51,1,24,66,'종이 그 행한 일을 다 이삭에게 고하매'),
(1463443,51,1,24,67,'이삭이 리브가를 인도하여 모친 사라의 장막으로 들이고 그를 취하여 아내를 삼고 사랑하였으니 이삭이 모친 상사 후에 위로를 얻었더라'),
(1463444,51,1,25,1,'아브라함이 후처를 취하였으니 그 이름은 그두라라'),
(1463445,51,1,25,2,'그가 시므란과, 욕산과, 므단과, 미디안과, 이스박과, 수아을 낳았고'),
(1463446,51,1,25,3,'욕산과, 스바와, 드단을 낳았으며 드단의 자손은 앗수르 족속과, 르두시 족속과, 르움미 족속이며'),
(1463447,51,1,25,4,'미디안의 아들은 에바와, 에벨과, 하녹과, 아비다와, 엘다아니 다 그두라의 자손이었더라'),
(1463448,51,1,25,5,'아브라함이 이삭에게 자기 모든 소유를 주었고'),
(1463449,51,1,25,6,'자기 서자들에게도 재물을 주어 자기 생전에 그들로 자기 아들 이삭을 떠나 동방 곧 동국으로 가게 하였더라'),
(1463450,51,1,25,7,'아브라함의 향년이 일백 칠십 오세라'),
(1463451,51,1,25,8,'그가 수가 높고 나이 많아 기운이 진하여 죽어 자기 열조에게로 돌아가매'),
(1463452,51,1,25,9,'그 아들 이삭과 이스마엘이 그를 마므레 앞 헷 족속 소할의 아들 에브론의 밭에 있는 막벨라 굴에 장사하였으니'),
(1463453,51,1,25,10,'이것은 아브라함이 헷 족속에게서 산 밭이라 아브라함과 그 아내 사라가 거기 장사되니라'),
(1463454,51,1,25,11,'아브라함이 죽은 후에 하나님이 그 아들 이삭에게 복을 주셨고 이삭을 브엘 라해로이 근처에 거하였더라'),
(1463455,51,1,25,12,'사라의 여종 애굽인 하갈이 아브라함에게 낳은 아들 이스마엘의 후예는 이러하고'),
(1463456,51,1,25,13,'이스마엘의 아들들의 이름은 그 이름과 그 세대 대로 이와 같으니라 이스마엘의 장자는 느바욧이요, 그 다음은 게달과, 앗브엘과, 밉삼과,'),
(1463457,51,1,25,14,'미스마와, 두마와, 맛사와,'),
(1463458,51,1,25,15,'하닷과, 데마와, 여둘과, 나비스와, 게드마니'),
(1463459,51,1,25,16,'이들은 이스마엘의 아들들이요 그 촌과 부락대로 된 이름이며 그 족속대로는 십 이방백이었더라'),
(1463460,51,1,25,17,'이스마엘은 향년이 일백 삼십 칠세에 기운이 진하여 죽어 자기 열조에게로 돌아갔고'),
(1463461,51,1,25,18,'그 자손들은 하윌라에서부터 앗수르로 통하는 애굽 앞 술까지 이르러 그 모든 형제의 맞은편에 거하였더라'),
(1463462,51,1,25,19,'아브라함의 아들 이삭의 후예는 이러하니라 아브라함이 이삭을 낳았고'),
(1463463,51,1,25,20,'이삭은 사십세에 리브가를 취하여 아내를 삼았으니 리브가는 밧단 아람의 아람 족속 중 브두엘의 딸이요 아람 족속 중 라반의 누이였더라'),
(1463464,51,1,25,21,'이삭이 그 아내가 잉태하지 못하므로 그를 위하여 여호와께 간구하매 여호와께서 그 간구를 들으셨으므로 그 아내 리브가가 잉태하였더니'),
(1463465,51,1,25,22,'아이들이 그의 태 속에서 서로 싸우는지라 그가 가로되 `이같으면 내가 어찌할꼬 ?'' 하고 가서 여호와께 묻자온대'),
(1463466,51,1,25,23,'여호와께서 그에게 이르시되 두 국민이 네 태 중에 있구나 두 민족이 네 복 중에서부터 나누이리라 이 족속이, 저 족속보다 강하겠고 큰 자는 어린 자를 섬기리라 하셨더라'),
(1463467,51,1,25,24,'그 해산 기한이 찬즉 태에 쌍동이가 있었는데'),
(1463468,51,1,25,25,'먼저 나온 자는 붉고 전신이 갖옷 같아서 이름을 에서라 하였고'),
(1463469,51,1,25,26,'후에 나온 아우는 손으로 에서의 발꿈치를 잡았으므로 그 이름을 야곱이라 하였으며 리브가가 그들을 낳을 때에 이삭이 육십세이었더라'),
(1463470,51,1,25,27,'그 아이들이 장성하매 에서는 익숙한 사냥군인고로 들 사람이 되고 야곱은 종용한 사람인고로 장막에 거하니'),
(1463471,51,1,25,28,'이삭은 에서의 사냥한 고기를 좋아하므로 그를 사랑하고 리브가는 야곱을 사랑하였더라'),
(1463472,51,1,25,29,'야곱이 죽을 쑤었더니 에서가 들에서부터 돌아와서 심히 곤비하여'),
(1463473,51,1,25,30,'야곱에게 이르되 `내가 곤비하니 그 붉은 것을 나로 먹게 하라'' 한지라 그러므로 에서의 별명은 에돔이더라'),
(1463474,51,1,25,31,'야곱이 가로되 `형의 장자의 명분을 오늘날 내게 팔라'''),
(1463475,51,1,25,32,'에서가 가로되 `내가 죽게 되었으니 이 장자의 명분이 내게 무엇이 유익하리요'''),
(1463476,51,1,25,33,'야곱이 가로되 `오늘 내게 맹세하라'' 에서가 맹세하고 장자의 명분을 야곱에게 판지라'),
(1463477,51,1,25,34,'야곱이 떡과 팥죽을 에서에게 주매 에서가 먹으며 마시고 일어나서 갔으니 에서가 장자의 명분을 경홀히 여김이었더라'),
(1463478,51,1,26,1,'아브라함 때에 첫 흉년이 들었더니 그 땅에 또 흉년이 들매 이삭이 그랄로 가서 블레셋 왕 아비멜렉에게 이르렀더니'),
(1463479,51,1,26,2,'여호와께서 이삭에게 나타나 가라사대 애굽으로 내려가지 말고 내가 네게 지시하는 땅에 거하라'),
(1463480,51,1,26,3,'이 땅에 유하면 내가 너와 함께 있어 네게 주고 내가 이 모든 땅을 너와 네 자손에게 주리라 내가 네 아비 아브라함에게 맹세한 것을 이루어'),
(1463481,51,1,26,4,'네 자손을 하늘의 별과 같이 번성케 하며 이 모든 땅을 네 자손에게 주리니 네 자손을 인하여 천하 만민이 복을 받으리라'),
(1463482,51,1,26,5,'이는 아브라함이 내 말을 순종하고 내 명령과, 내 계명과, 내 율례와, 내 법도를 지켰음이니라 하시니라'),
(1463483,51,1,26,6,'이삭이 그랄에 거하였더니'),
(1463484,51,1,26,7,'그 곳 사람들이 그 아내를 물으매 그가 말하기를 그는 나의 누이라 하였으니 리브가는 보기에 아리따우므로 그 곳 백성이 리브가로 인하여 자기를 죽일까 하여 그는 나의 아내라 하기를 두려워 함이었더라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463485,51,1,26,8,'이삭이 거기 오래 거하였더니 이삭이 그 아내 리브가를 껴안은 것을 블레셋 왕 아비멜렉이 창으로 내다본지라'),
(1463486,51,1,26,9,'이에 아비멜렉이 이삭을 불러 이르되 `그가 정녕 네 아내여늘 어찌 네 누이라 하였느냐 ?'' 이삭이 그에게 대답하되 `내 생각에 그를 인하여 내가 죽게 될까 두려워하였음이로라'''),
(1463487,51,1,26,10,'아비멜렉이 가로되 `네가 어찌 우리에게 이렇게 행하였느냐 ? 백성 중 하나가 네 아내와 동침하기 쉬웠을뻔 하였은즉 네가 죄를 우리에게 입혔으리라'''),
(1463488,51,1,26,11,'아비멜렉이 이에 모든 백성에게 명하여 가로되 `이 사람이나 그 아내에게 범하는 자는 죽이리라'' 하였더라'),
(1463489,51,1,26,12,'이삭이 그 땅에서 농사하여 그 해에 백배나 얻었고 여호와께서 복을 주시므로'),
(1463490,51,1,26,13,'그 사람이 창대하고 왕성하여 마침내 거부가 되어'),
(1463491,51,1,26,14,'양과 소가 떼를 이루고 노복이 심히 많으므로 블레셋 사람이 그를 시기하여'),
(1463492,51,1,26,15,'그 아비 아브라함 때에 그 아비의 종들이 판 모든 우물을 막고 흙으로 메웠더라'),
(1463493,51,1,26,16,'아비멜렉이 이삭에게 이르되 `네가 우리보다 크게 강성한즉 우리를 떠나가라'''),
(1463494,51,1,26,17,'이삭이 그곳을 떠나 그랄 골짜기에 장막을 치고 거기 우거하며'),
(1463495,51,1,26,18,'그 아비 아브라함 때에 팠던 우물들을 다시 팠으니 이는 아브라함 죽은 후에 블레셋 사람이 그 우물들을 메웠음이라 이삭이 그 우물들의 이름을 그 아비의 부르던 이름으로 불렀더라'),
(1463496,51,1,26,19,'이삭의 종들이 골짜기에 파서 샘 근원을 얻었더니'),
(1463497,51,1,26,20,'그랄 목자들이 이삭의 목자와 다투어 가로되 `이 물은 우리의 것이라'' 하매 이삭이 그 다툼을 인하여 그 우물 이름을 에섹이라 하였으며'),
(1463498,51,1,26,21,'또 다른 우물을 팠더니 그들이 또 다투는고로 그 이름을 싯나라 하였으며'),
(1463499,51,1,26,22,'이삭이 거기서 옮겨 다른 우물을 팠더니 그들이 다투지 아니하였으므로 그 이름을 르호봇이라 하여 가로되 `이제는 여호와께서 우리의 장소를 넓게 하셨으니 이 땅에서 우리가 번성하리로다'' 하였더라'),
(1463500,51,1,26,23,'이삭이 거기서부터 브엘세바로 올라갔더니'),
(1463501,51,1,26,24,'그 밤에 여호와께서 그에게 나타나 가라사대 나는 네 아비 아브라함의 하나님이니 두려워 말라! 내 종 아브라함을 위하여 내가 너와 함께 있어 네게 복을 주어 네 자손으로 번성케 하리라 하신지라'),
(1463502,51,1,26,25,'이삭이 그 곳에 단을 쌓아 여호와의 이름을 부르고 거기 장막을 쳤더니 그 종들이 거기서도 우물을 팠더라'),
(1463503,51,1,26,26,'아비멜렉이 그 친구 아훗삿과 군대장관 비골로 더불어 그랄에서부터 이삭에게로 온지라'),
(1463504,51,1,26,27,'이삭이 그들에게 이르되 `너희가 나를 미워하여 나로 너희를 떠나가게 하였거늘 어찌하여 내게 왔느냐 ?'''),
(1463505,51,1,26,28,'그들이 가로되 `여호와께서 너와 함께 계심을 우리가 분명히 보았으므로 우리의 사이 곧 우리와 너의 사이에 맹세를 세워 너와 계약을 맺으리라 말하였노라'),
(1463506,51,1,26,29,'너는 우리를 해하지 말라 이는 우리가 너를 범하지 아니하고 선한 일만 네게 행하며 너로 평안히 가게 하였음이니라 이제 너는 여호와께 복을 받은 자니라 !'''),
(1463507,51,1,26,30,'이삭이 그들을 위하여 잔치를 베풀매 그들이 먹고 마시고'),
(1463508,51,1,26,31,'아침에 일찌기 일어나 서로 맹세한 후에 이삭이 그들을 보내매 그들이 평안히 갔더라'),
(1463509,51,1,26,32,'그 날에 이삭의 종들이 자기들의 판 우물에 대하여 이삭에게 와서 고하여 가로되 `우리가 물을 얻었나이다'' 하매'),
(1463510,51,1,26,33,'그가 그 이름을 세바라 한지라 그러므로 그 성읍 이름이 오늘까지 브엘세바더라'),
(1463511,51,1,26,34,'에서가 사십세에 헷 족속 브에리의 딸 유딧과, 헷 족속 엘론의 딸 바스맛을 아내로 취하였더니'),
(1463512,51,1,26,35,'그들이 이삭과 리브가의 마음의 근심이 되었더라'),
(1463513,51,1,27,1,'이삭이 나이 많아 눈이 어두워 잘 보지 못하더니 맏아들 에서를 불러 가로되 `내 아들아'' 하매 그가 가로되 `내가 여기 있나이다'' 하니'),
(1463514,51,1,27,2,'이삭이 가로되 `내가 이제 늙어 어느날 죽을는지 알지 못하노니'),
(1463515,51,1,27,3,'그런즉 네 기구 곧 전통과 활을 가지고 들에 가서 나를 위하여 사냥하여'),
(1463516,51,1,27,4,'나의 즐기는 별미를 만들어 내게로 가져다가 먹게 하여 나로 죽기 전에 내 마음껏 네게 축복하게 하라'''),
(1463517,51,1,27,5,'이삭이 그 아들 에서에게 말할때에 리브가가 들었더니 에서가 사냥하여 오려고 들로 나가매'),
(1463518,51,1,27,6,'리브가가 그 아들 야곱에게 일러 가로되 `네 부친이 네 형 에서에게 말씀하시는 것을 내가 들으니 이르시기를'),
(1463519,51,1,27,7,'나를 위하여 사냥하여 가져다가 별미를 만들어 나로 먹게 하여 죽기 전에 여호와 앞에서 네게 축복하게 하라 하셨으니'),
(1463520,51,1,27,8,'그런즉 내 아들아 내 말을 좇아 내가 네게 명하는대로'),
(1463521,51,1,27,9,'염소떼에 가서 거기서 염소의 좋은 새끼를 내게로 가져오면 내가 그것으로 네 부친을 위하여 그 즐기시는 별미를 만들리니'),
(1463522,51,1,27,10,'네가 그것을 가져 네 부친께 드려서 그로 죽으시기 전에 네게 축복하기 위하여 잡수시게 하라'''),
(1463523,51,1,27,11,'야곱이 그 모친 리브가에게 이르되 `내 형 에서는 털사람이요, 나는 매끈매끈한 사람인즉'),
(1463524,51,1,27,12,'아버지께서 나를 만지실진대 내가 아버지께 속이는 자로 뵈일지라 복은 고사하고 저주를 받을까 하나이다'''),
(1463525,51,1,27,13,'어미가 그에게 이르되 `내 아들아, 너의 저주는 내게로 돌리리니 내 말만 좇고 가서 가져오라'''),
(1463526,51,1,27,14,'그가 가서 취하여 어미에게로 가져왔더니 그 어미가 그 아비의 즐기는 별미를 만들었더라'),
(1463527,51,1,27,15,'리브가가 집 안 자기 처소에 있는 맏아들 에서의 좋은 의복을 취하여 작은 아들 야곱에게 입히고'),
(1463528,51,1,27,16,'또 염소 새끼의 가죽으로 그 손과 목의 매끈매끈한 곳에 꾸미고'),
(1463529,51,1,27,17,'그 만든 별미와 떡을 자기 아들 야곱의 손에 주매'),
(1463530,51,1,27,18,'야곱이 아버지에게 나아가서 `내 아버지여'' 하고 부른대 가로되 `내가 여기 있노라 내 아들아 네가 누구냐 ?'''),
(1463531,51,1,27,19,'야곱이 아비에게 대답하되 `나는 아버지의 맏아들 에서로소이다 아버지께서 내게 명하신대로 내가 하였사오니 청컨대 일어나 앉아서 내 사냥한 고기를 잡수시고 아버지의 마음껏 내게 축복하소서 !'''),
(1463532,51,1,27,20,'이삭이 그 아들에게 이르되 `내 아들아, 네가 어떻게 이같이 속히 잡았느냐 ?'' 그가 가로되 `아버지의 하나님 여호와께서 나로 순적히 만나게 하셨음이니이다'''),
(1463533,51,1,27,21,'이삭이 야곱에게 이르되 `내 아들아, 가까이 오라 네가 과연 내 아들 에서인지 아닌지 내가 너를 만지려 하노라'''),
(1463534,51,1,27,22,'야곱이 그 아비 이삭에게 가까이 가니 이삭이 만지며 가로되 `음성은 야곱의 음성이나, 손은 에서의 손이로다'' 하며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463535,51,1,27,23,'그 손이 형 에서의 손과 같이 털이 있으므로 능히 분별치 못하고 축복하였더라'),
(1463536,51,1,27,24,'이삭이 가로되 네가 참 내 아들 에서냐 그가 대답하되 그러하니이다'),
(1463537,51,1,27,25,'이삭이 가로되 `내게로 가져오라 내 아들의 사냥한 고기를 먹고 내 마음껏 네게 축복하리라 !'' 야곱이 그에게로 가져가매 그가 먹고 또 포도주를 가져가매 그가 마시고'),
(1463538,51,1,27,26,'그 아비 이삭이 그에게 이르되 `내 아들아, 가까이 와서 내게 입맞추라`'),
(1463539,51,1,27,27,'그가 가까이 가서 그에게 입맞추니 아비가 그 옷의 향취를 맡고 그에게 축복하여 가로되 `내 아들의 향취는 여호와의 복 주신 밭의 향취로다'),
(1463540,51,1,27,28,'하나님은 하늘의 이슬과 땅의 기름짐이며 풍성한 곡식과 포도주로 네게 주시기를 원하노라'),
(1463541,51,1,27,29,'만민이 너를 섬기고 열국이 네게 굴복하리니 네가 형제들의 주가 되고 네 어미의 아들들이 네게 굴복하며 네게 저주하는 자는 저주를 받고 네게 축복하는 자는 복을 받기를 원하노라'''),
(1463542,51,1,27,30,'이삭이 야곱에게 축복하기를 마치매 야곱이 그 아비 이삭 앞에서 나가자 곧 그 형 에서가 사냥하여 돌아온지라'),
(1463543,51,1,27,31,'그가 별미를 만들어 아비에게로 가지고 가서 가로되 `아버지여, 일어나서 아들의 사냥한 고기를 잡수시고 마음껏 내게 축복하소서'''),
(1463544,51,1,27,32,'그 아비 이삭이 그에게 이르되 `너는 누구냐 ?'' 그가 대답하되 `나는 아버지의 아들 곧 아버지의 맏아들 에서로소이다`'),
(1463545,51,1,27,33,'이삭이 심히 크게 떨며 가로되 `그런즉 사냥한 고기를 내게 가져온 자가 누구냐 ? 너 오기 전에 내가 다 먹고 그를 위하여 축복하였은즉 그가 정녕 복을 받을 것이니라 !'''),
(1463546,51,1,27,34,'에서가 그 아비의 말을 듣고 방성 대곡하며 아비에게 이르되 `내 아버지여, 내게 축복하소서 내게도 그리하소서'''),
(1463547,51,1,27,35,'이삭이 가로되 `네 아우가 간교하게 와서 네 복을 빼앗았도다'''),
(1463548,51,1,27,36,'에서가 가로되 `그의 이름을 야곱이라 함이 합당치 아니하니이까 ? 그가 나를 속임이 이것이 두번째니이다 전에는 나의 장자의 명분을 빼앗고 이제는 내 복을 빼앗았나이다'' 또 가로되 `아버지께서 나를 위하여 빌 복을 남기지 아니하셨나이까 ?'''),
(1463549,51,1,27,37,'이삭이 에서에게 대답하여 가로되 `내가 그를 너의 주로 세우고 그 모든 형제를 내가 그에게 종으로 주었으며 곡식과 포도주를 그에게 공급하였으니 내 아들아 ! 내가 네게 무엇을 할 수 있으랴 ?'''),
(1463550,51,1,27,38,'에서가 아비에게 이르되 `내 아버지여, 아버지의 빌 복이 이 하나뿐이리이까 ? 내 아버지여, 내게 축복하소서 내게도 그리 하소서'' 하고 소리를 높여 우니'),
(1463551,51,1,27,39,'그 아비 이삭이 그에게 대답하여 가로되 `너의 주소는 땅의 기름짐에서 뜨고 내리는 하늘 이슬에서 뜰 것이며'),
(1463552,51,1,27,40,'너는 칼을 믿고 생활하겠고 네 아우를 섬길 것이며 네가 매임을 벗을 때에는 그 멍에를 네 목에서 떨쳐버리리라'' 하였더라'),
(1463553,51,1,27,41,'그 아비가 야곱에게 축복한 그 축복을 인하여 에서가 야곱을 미워하여 심중에 이르기를 `아버지를 곡할 때가 가까왔은즉 내가 내 아우 야곱을 죽이리라'' 하였더니'),
(1463554,51,1,27,42,'맏아들 에서의 이 말이 리브가에게 들리매 이에 보내어 작은 아들 야곱을 불러 그에게 이르되 `네 형 에서가 너를 죽여 그 한을 풀려하나니'),
(1463555,51,1,27,43,'내 아들아, 내 말을 좇아 일어나 하란으로 가서 내 오라버니 라반에게 피하여'),
(1463556,51,1,27,44,'네 형의 노가 풀리기 까지 몇날 동안 그와 함께 거하라'),
(1463557,51,1,27,45,'네 형의 분노가 풀려 네가 자기에게 행한 것을 잊어버리거든 내가 곧 보내어 너를 거기서 불러오리라 어찌 하루에 너희 둘을 잃으랴'''),
(1463558,51,1,27,46,'리브가가 이삭에게 이르되 `내가 헷 사람의 딸들을 인하여 나의 생명을 싫어하거늘 야곱이 만일 이 땅의 딸들 곧 그들과 같은 헷 사람의 딸들 중에서 아내를 취하면 나의 생명이 내게 무슨 재미가 있으리이까 ?'''),
(1463559,51,1,28,1,'이삭이 야곱을 불러 그에게 축복하고 또 부탁하여 가로되 `너는 가나안 사람의 딸들 중에서 아내를 취하지 말고'),
(1463560,51,1,28,2,'일어나 밧단아람으로 가서 너의 외조부 브두엘 집에 이르러 거기서 너의 외삼촌 라반의 딸 중에서 아내를 취하라'),
(1463561,51,1,28,3,'전능하신 하나님이 네게 복을 주어 너로 생육하고 번성케하사 너로 여러 족속을 이루게 하시고'),
(1463562,51,1,28,4,'아브라함에게 허락하신 복을 네게 주시되 너와 너와 함께 네 자손에게 주사 너로 하나님이 아브라함에게 주신 땅 곧 너의 우거하는 땅을 유업으로 받게 하시기를 원하노라'''),
(1463563,51,1,28,5,'이에 이삭이 야곱을 보내었더니 밧단아람으로 가서 라반에게 이르렀으니 라반은 아람 사람 브두엘의 아들이요 야곱과 에서의 어미 리브가의 오라비더라'),
(1463564,51,1,28,6,'에서가 본즉 이삭이 야곱에게 축복하고 그를 밧단아람으로 보내어 거기서 아내를 취하게 하였고 또 그에게 축복하고 명하기를 `너는 가나안 사람의 딸들 중에서 아내를 취하지 말라'' 하였고'),
(1463565,51,1,28,7,'또 야곱이 부모의 명을 좇아 밧단아람으로 갔으며'),
(1463566,51,1,28,8,'에서가 또 본즉 가나안 사람의 딸들이 그 아비 이삭을 기쁘게 못하는지라'),
(1463567,51,1,28,9,'이에 에서가 이스마엘에게 가서 그 본처들 외에 아브라함의 아들 이스마엘의 딸이요 느바욧의 누이인 마할랏을 아내로 취하였더라'),
(1463568,51,1,28,10,'야곱이 브엘세바에서 떠나 하란으로 향하여 가더니'),
(1463569,51,1,28,11,'한 곳에 이르러는 해가 진지라 거기서 유숙하려고 그 곳의 한 돌을 취하여 베개하고 거기 누워 자더니'),
(1463570,51,1,28,12,'꿈에 본즉 사닥다리가 땅 위에 섰는데 그 꼭대기가 하늘에 닿았고 또 본즉 하나님의 사자가 그 위에서 오르락 내리락하고'),
(1463571,51,1,28,13,'또 본즉 여호와께서 그 위에 서서 가라사대 나는 여호와니 너의 조부 아브라함의 하나님이요 이삭의 하나님이라 ! 너 누운 땅을 내가 너와 네 자손에게 주리니'),
(1463572,51,1,28,14,'네 자손이 땅의 티끌같이 되어서 동서남북에 편만할지며 땅의 모든 족속이 너와 네 자손을 인하여 복을 얻으리라 !'),
(1463573,51,1,28,15,'내가 너와 함께 있어 네가 어디로 가든지 너를 지키며 너를 이끌어 이 땅으로 돌아오게 할지라 내가 네게 허락한 것을 다 이루기까지 너를 떠나지 아니하리라 ! 하신지라'),
(1463574,51,1,28,16,'야곱이 잠이 깨어 가로되 `여호와께서 과연 여기 계시거늘 내가 알지 못하였도다'''),
(1463575,51,1,28,17,'이에 두려워하여 가로되 `두렵도다, 이 곳이여 ! 다른 것이 아니라 이는 하나님의 전이요, 이는 하늘의 문이로다'' 하고'),
(1463576,51,1,28,18,'야곱이 아침에 일찌기 일어나 베개하였던 돌을 가져 기둥으로 세우고 그 위에 기름을 붓고'),
(1463577,51,1,28,19,'그곳 이름을 벧엘이라 하였더라 이 성의 본 이름은 루스더라'),
(1463578,51,1,28,20,'야곱이 서원하여 가로되 `하나님이 나와 함께 계시사 내가 가는 이 길에서 나를 지키시고 먹을 양식과 입을 옷을 주사'),
(1463579,51,1,28,21,'나로 평안히 아비 집으로 돌아가게 하시오면 여호와께서 나의 하나님이 되실 것이요'),
(1463580,51,1,28,22,'내가 기둥으로 세운 이 돌이 하나님의 전이 될 것이요 하나님께서 내게 주신 모든 것에서 십분 일을 내가 반드시 하나님께 드리겠나이다` 하였더라'),
(1463581,51,1,29,1,'야곱이 발행하여 동방 사람의 땅에 이르러'),
(1463582,51,1,29,2,'본즉 들에 우물이 있고 그 곁에 양 세 떼가 누웠으니 이는 목자들이 그 우물에서 물을 양떼에게 먹임이라 큰 돌로 우물 아구를 덮었다가'),
(1463583,51,1,29,3,'모든 떼가 모이면 그들이 우물 아구에서 돌을 옮기고 양에게 물을 먹이고는 여전히 우물 아구 그 자리에 돌을 덮더라'),
(1463584,51,1,29,4,'야곱이 그들에게 이르되 `나의 형제여 어디로서뇨 ?'' 그들이 가로되 `하란에서로라''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463585,51,1,29,5,'야곱이 그들에게 이르되 `너희가 나홀의 손자 라반을 아느냐 ?'' 그들이 가로되 `아노라'''),
(1463586,51,1,29,6,'야곱이 그들에게 이르되 `그가 평안하냐 ?'' 가로되 `평안하니라 딸 라헬이 지금 양을 몰고 오느니라'''),
(1463587,51,1,29,7,'야곱이 가로되 `해가 아직 높은즉 짐승 모일 때가 아니니 양에게 물을 먹이고 가서 뜯기라'''),
(1463588,51,1,29,8,'그들이 가로되 `우리가 그리하지 못하겠노라 떼가 다 모이고 목자들이 우물 아구에서 돌을 옮겨야 우리가 양에게 물을 먹이느리라'''),
(1463589,51,1,29,9,'야곱이 그들과 말하는 중에 라헬이 그 아비의 양과 함께 오니 그가 그의 양들을 침이었더라'),
(1463590,51,1,29,10,'야곱이 그 외삼촌 라반의 딸 라헬과 그 외삼촌의 양을 보고 나아가서 우물 아구에서 돌을 옮기고 외삼촌 라반의 양떼에게 물을 먹이고'),
(1463591,51,1,29,11,'그가 라헬에게 입맞추고 소리내어 울며'),
(1463592,51,1,29,12,'그에게 자기가 그의 아비의 생질이요 리브가의 아들됨을 고하였더니 라헬이 달려가서 그 아비에게 고하매'),
(1463593,51,1,29,13,'라반이 그 생질 야곱의 소식을 듣고 달려와서 그를 영접하여 안고 입맞추고 자기 집으로 인도하여 들이니 야곱이 자기의 모든 일을 라반에게 고하매'),
(1463594,51,1,29,14,'라반이 가로되 `너는 참으로 나의 골육이로다'' 하였더라 야곱이 한달을 그와 함께 거하더니'),
(1463595,51,1,29,15,'라반이 야곱에게 이르되 `네가 비록 나의 생질이나 어찌 공으로 내 일만 하겠느냐 ? 무엇이 네 보수겠느냐 ? 내게 고하라'''),
(1463596,51,1,29,16,'라반이 두 딸이 있으니 형의 이름은 레아요 아우의 이름은 라헬이라'),
(1463597,51,1,29,17,'레아는 안력이 부족하고 라헬은 곱고 아리따우니'),
(1463598,51,1,29,18,'야곱이 라헬을 연애하므로 대답하되 `내가 외삼촌의 작은 딸 라헬을 위하여 외삼촌에게 칠년을 봉사하리이다'''),
(1463599,51,1,29,19,'라반이 가로되 `그를 네게 주는 것이 타인에게 주는 것보다 나으니 나와 함께 있으라'''),
(1463600,51,1,29,20,'야곱이 라헬을 위하여 칠년 동안 라반을 봉사하였으나 그를 연애하는 까닭에 칠년을 수일 같이 여겼더라'),
(1463601,51,1,29,21,'야곱이 라반에게 이르되 `내 기한이 찼으니 내 아내를 내게 주소서 내가 그에게 들어가겠나이다'''),
(1463602,51,1,29,22,'라반이 그 곳 사람을 다 모아 잔치하고'),
(1463603,51,1,29,23,'저녁에 그 딸 레아를 야곱에게로 데려가매 야곱이 그에게로 들어가니라'),
(1463604,51,1,29,24,'라반이 또 그 여종 실바를 그 딸 레아에게 시녀로 주었더라'),
(1463605,51,1,29,25,'야곱이 아침에 보니 레아라 라반에게 이르되 `외삼촌이 어찌하여 내게 이같이 행하셨나이까 ? 내가 라헬을 위하여 외삼촌께 봉사하지 아니하였나이까 ? 외삼촌이 나를 속이심은 어찜이니이까 ?'''),
(1463606,51,1,29,26,'라반이 가로되 `형보다 아우를 먼저 주는 것은 우리 지방에서 하지 아니하는 바이라'),
(1463607,51,1,29,27,'이를 위하여 칠일을 채우라 우리가 그도 네게 주리니 네가 그를 위하여 또 칠년을 내게 봉사할지니라'''),
(1463608,51,1,29,28,'야곱이 그대로 하여 그 칠일을 채우매 라반이 딸 라헬도 그에게 아내로 주고'),
(1463609,51,1,29,29,'라반이 또 그 여종 빌하를 그 딸 라헬에게 주어 시녀가 되게 하매'),
(1463610,51,1,29,30,'야곱이 또한 라헬에게로 들어갔고 그가 레아보다 라헬을 더 사랑하고 다시 칠년을 라반에게 봉사하였더라'),
(1463611,51,1,29,31,'여호와께서 레아에게 총이 없음을 보시고 그의 태를 여셨으나 라헬은 무자하였더라'),
(1463612,51,1,29,32,'레아가 잉태하여 아들을 낳고 그 이름을 르우벤이라 하여 가로되 `여호와께서 나의 괴로움을 권고하셨으니 이제는 내 남편이 나를 사랑하리로다'' 하였더라'),
(1463613,51,1,29,33,'그가 다시 잉태하여 아들을 낳고 가로되 `여호와께서 나의 총이 없음을 들으셨으므로 내게 이도 주셨도다'' 하고 그 이름을 시므온이라 하였으며'),
(1463614,51,1,29,34,'그가 또 잉태하여 아들을 낳고 가로되 `내가 그에게 세 아들을 낳았으니 내 남편이 지금부터 나와 연합하리로다'' 하고 그 이름을 레위라 하였으며'),
(1463615,51,1,29,35,'그가 또 잉태하여 아들을 낳고 가로되 `내가 이제는 여호와를 찬송하리로다 !'' 하고 이로 인하여 그가 그 이름을 유다라 하였고 그의 생산이 멈추었더라'),
(1463616,51,1,30,1,'라헬이 자기가 야곱에게 아들을 낳지 못함을 보고 그 형을 투기하여 야곱에게 이르되 `나로 자식을 낳게 하라 그렇지 아니하면 내가 죽겠노라'''),
(1463617,51,1,30,2,'야곱이 라헬에게 노를 발하여 가로되 `그대로 성태치 못하게 하시는 이는 하나님이시니 내가 하나님을 대신하겠느냐 ?'''),
(1463618,51,1,30,3,'라헬이 가로되 `나의 여종 빌하에게로 들어가라 그가 아들을 낳아 내 무릎에 두리니 그러면 나도 그를 인하여 자식을 얻겠노라'' 하고'),
(1463619,51,1,30,4,'그 시녀 빌하를 남편에게 첩으로 주매 야곱이 그에게로 들어갔더니'),
(1463620,51,1,30,5,'빌하가 잉태하여 야곱에게 아들을 낳은지라'),
(1463621,51,1,30,6,'라헬이 가로되 `하나님이 내 억울함을 푸시려고 내 소리를 들으사 내게 아들을 주셨다'' 하고 이로 인하여 그 이름을 단이라 하였으며'),
(1463622,51,1,30,7,'라헬의 시녀 빌하가 다시 잉태하여 둘째 아들을 야곱에게 낳으매'),
(1463623,51,1,30,8,'라헬이 가로되 `내가 형과 크게 경쟁하여 이기었다'' 하고 그 이름을 납달리라 하였더라'),
(1463624,51,1,30,9,'레아가 자기의 생산이 멈춤을 보고 그 시녀 실바를 취하여 야곱에게 주어 첩을 삼게 하였더니'),
(1463625,51,1,30,10,'레아의 시녀 실바가 야곱에게 아들을 낳으매'),
(1463626,51,1,30,11,'레아가 가로되 `복되도다'' 하고 그 이름을 갓이라 하였으며'),
(1463627,51,1,30,12,'레아의 시녀 실바가 둘째 아들을 야곱에게 낳으매'),
(1463628,51,1,30,13,'레아가 가로되 `기쁘도다 모든 딸들이 나를 기쁜 자라 하리로다'' 하고 그 이름을 아셀이라 하였더라'),
(1463629,51,1,30,14,'맥추 때에 르우벤이 나가서 들에서 합환채를 얻어 어미 레아에게 드렸더니 라헬이 레아에게 이르되 `형의 아들의 합환채를 청구하노라'''),
(1463630,51,1,30,15,'레아가 그에게 이르되 `네가 내 남편을 빼앗은 것이 작은 일이냐 ? 네가 내 아들의 합환채도 빼앗고자 하느냐 ?'' 라헬이 가로되 `그러면 형의 아들의 합환채 대신에 오늘밤에 내 남편이 형과 동침하리라'' 하리라'),
(1463631,51,1,30,16,'저물 때에 야곱이 들에서 돌아오매 레아가 나와서 그를 영접하며 이르되 `내게로 들어오라 내가 내 아들의 합환채로 당신을 샀노라'' 그 밤에 야곱이 그와 동침하였더라'),
(1463632,51,1,30,17,'하나님이 레아를 들으셨으므로 그가 잉태하여 다섯째 아들을 야곱에게 낳은지라'),
(1463633,51,1,30,18,'레아가 가로되 `내가 내 시녀를 남편에게 주었으므로 하나님이 내게 그 값을 주셨다'' 하고 그 이름을 잇사갈이라 하였으며'),
(1463634,51,1,30,19,'레아가 다시 잉태하여 여섯째 아들을 야곱에게 낳은지라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463635,51,1,30,20,'레아가 가로되 `하나님이 네게 후한 선물을 주시도다 내가 남편에게 여섯 아들을 낳았으니 이제는 그가 나와 함께 거하리라'' 하고 그 이름을 스불론이라 하였으며'),
(1463636,51,1,30,21,'그 후에 그가 딸을 낳고 그 이름을 디나라 하였더라'),
(1463637,51,1,30,22,'하나님이 라헬을 생각하신지라 하나님이 그를 들으시고 그 태를 여신고로'),
(1463638,51,1,30,23,'그가 잉태하여 아들을 낳고 가로되 `하나님이 나의 부끄러움을 씻으셨다'' 하고'),
(1463639,51,1,30,24,'그 이름을 요셉이라 하니 여호와는 다시 다른 아들을 내게 더하시기를 원하노라 함이었더라'),
(1463640,51,1,30,25,'라헬이 요셉을 낳은 때에 야곱이 라반에게 이르되 `나를 보내어 내 고향 내 본토로 가게 하시되'),
(1463641,51,1,30,26,'내가 외삼촌에게서 일하고 얻은 처자를 내게 주어 나로 가게 하소서 내가 외삼촌께 한 일은 외삼촌이 아시나이다'''),
(1463642,51,1,30,27,'라반이 그에게 이르되 `여호와께서 너로 인하여 내게 복 주신줄을 내가 깨달았노니 네가 나를 사랑스럽게 여기거든 유하라'''),
(1463643,51,1,30,28,'또 가로되 `네 품삯을 정하라 내가 그것을 주리라'''),
(1463644,51,1,30,29,'야곱이 그에게 이르되 `내가 어떻게 외삼촌을 섬겼는지, 어떻게 외삼촌의 짐승을 쳤는지 외삼촌이 아시나이다'),
(1463645,51,1,30,30,'내가 오기 전에는 외삼촌의 소유가 적더니 번성하여 떼를 이루었나이다 나의 공력을 따라 여호와께서 외삼촌에게 복을 주셨나이다 그러나 나는 어느 때에나 내 집을 세우리이까 ?'''),
(1463646,51,1,30,31,'라반이 가로되 내가 무엇으로 네게 주랴 야곱이 가로되 외삼촌께서 아무 것도 내게 주실 것이 아니라 나를 위하여 이 일을 행하시면 내가 다시 외삼촌의 양떼를 먹이고 지키리이다'),
(1463647,51,1,31,1,'야곱이 들은즉 라반의 아들들의 말이 `야곱이 우리 아버지의 소유를 다 빼앗고 우리 아버지의 소유로 인하여 이같이 거부가 되었다'' 하는지라'),
(1463648,51,1,31,2,'야곱이 라반의 안색을 본즉 자기에게 대하여 전과 같지 아니하더라'),
(1463649,51,1,31,3,'여호와께서 야곱에게 이르시되 네 조상의 땅, 네 족속에게로 돌아가라 내가 너와 함께 있으리라 하신지라'),
(1463650,51,1,31,4,'야곱이 보내어 라헬과 레아를 자기 양떼 있는 들로 불러다가'),
(1463651,51,1,31,5,'그들에게 이르되 `내가 그대들의 아버지의 안색을 본즉 내게 대하여 전과 같지 아니하도다 그러할지라도 내 아버지의 하나님은 나와 함께 계셨느니라'),
(1463652,51,1,31,6,'그대들도 알거니와 내가 힘을 다하여 그대들의 아버지를 섬겼거늘'),
(1463653,51,1,31,7,'그대들의 아버지가 나를 속여 품삯을 열번이나 변역하였느니라 그러나 하나님이 그를 금하사 나를 해치 못하게 하셨으며'),
(1463654,51,1,31,8,'그가 이르기를 점 있는 것이 네 삯이 되리라 하면 온 양떼의 낳은 것이 점 있는 것이요 또 얼룩무늬 있는 것이 네 삯이 되리라 하면 온 양떼의 낳은 것이 얼룩무늬 있는 것이니'),
(1463655,51,1,31,9,'하나님이 이같이 그대들의 아버지의 짐승을 빼앗아 내게 주셨으니라'),
(1463656,51,1,31,10,'그 양떼가 새끼 밸 때에 내가 꿈에 눈을 들어 보니 양떼를 탄 수양은 다 얼룩무늬 있는것, 점 있는 것, 아롱진 것이었더라'),
(1463657,51,1,31,11,'꿈에 하나님의 사자가 내게 말씀하시기를 야곱아 ! 하기로 내가 대답하기를 여기 있나이다 ! 하매'),
(1463658,51,1,31,12,'가라사대 네 눈을 들어 보라 ! 양떼를 탄 수양은 다 얼룩무늬 있는것, 점 있는 것, 아롱진 것이니라 라반이 네게 행한 모든 것을 내가 보았노라'),
(1463659,51,1,31,13,'나는 벧엘 하나님이라 ! 네가 거기서 기둥에 기름을 붓고 거기서 내게 서원하였으니 지금 일어나 이곳을 떠나서 네 출생지로 돌아가라 하셨느니라'''),
(1463660,51,1,31,14,'라헬과 레아가 그에게 대답하여 가로되 `우리가 우리 아버지 집에서 무슨 분깃이나 유업이나 있으리요'),
(1463661,51,1,31,15,'아버지가 우리를 팔고 우리의 돈을 다 먹었으니 아버지가 우리를 외인으로 여기는 것이 아닌가'),
(1463662,51,1,31,16,'하나님이 우리 아버지에게서 취하신 재물은 우리와 우리 자식의 것이니 이제 하나님이 당신에게 이르신 일을 다 준행하라'''),
(1463663,51,1,31,17,'야곱이 일어나 자식들과 아내들을 약대들에게 태우고'),
(1463664,51,1,31,18,'그 얻은 바 모든 짐승과 모든 소유물 곧 그가 밧단아람에서 얻은 짐승을 이끌고 가나안 땅에 있는 그 아비 이삭에게로 가려할새'),
(1463665,51,1,31,19,'때에 라반이 양털을 깎으러 갔으므로 라헬은 그 아비의 드라빔을 도적질하고'),
(1463666,51,1,31,20,'야곱은 그 거취를 아람 사람 라반에게 고하지 않고 가만히 떠났더라'),
(1463667,51,1,31,21,'그가 그 모든 소유를 이끌고 강을 건너 길르앗 산을 향하여 도망한지'),
(1463668,51,1,31,22,'삼일만에 야곱의 도망한 것이 라반에게 들린지라'),
(1463669,51,1,31,23,'라반이 그 형제를 거느리고 칠일 길을 쫓아가 길르앗산에서 그에게 미쳤더니'),
(1463670,51,1,31,24,'밤에 하나님이 아람 사람 라반에게 현몽하여 가라사대 너는 삼가 야곱에게 선악간 말하지 말라 하셨더라'),
(1463671,51,1,31,25,'라반이 야곱을 쫓아 미치니 야곱이 산에 장막을 쳤는지라 라반이 그 형제로 더불어 길르앗산에 장막을 치고'),
(1463672,51,1,31,26,'라반이 야곱에게 이르되 `네가 내게 알리지 아니하고 가만히 내 딸들을 칼로 잡은 자 같이 끌고 갔으니 어찌 이같이 하였느냐 ?'),
(1463673,51,1,31,27,'내가 즐거움과, 노래와, 북과, 수금으로 너를 보내겠거늘 어찌하여 네가 나를 속이고 가만히 도망하고 내게 고하지 아니하였으며'),
(1463674,51,1,31,28,'나로 내 손자들과 딸들에게 입맞추지 못하게 하였느냐 ? 네 소위가 실로 어리석도다'),
(1463675,51,1,31,29,'너를 해할만한 능력이 내 손에 있으나 너희 아버지의 하나님이 어제밤에 내게 말씀하시기를 너는 삼가 야곱에게 선악간 말하지 말라 하셨느니라'),
(1463676,51,1,31,30,'이제 네가 네 아비 집을 사모하여 돌아가려는 것은 가하거니와 어찌 내 신(神)을 도적질하였느냐 ?'''),
(1463677,51,1,31,31,'야곱이 라반에게 대답하여 가로되 `내가 말하기를 외삼촌이 외삼촌의 딸들을 내게서 억지로 빼앗으리라 하여 두려워하였음이니이다'),
(1463678,51,1,31,32,'외삼촌의 신은 뉘게서 찾든지 그는 살지 못할 것이요 우리 형제들 앞에서 무엇이든지 외삼촌의 것이 발견되거든 외삼촌에게로 하소서'' 하니 야곱은 라헬이 그것을 도적질한 줄을 알지 못함이었더라'),
(1463679,51,1,31,33,'라반이 야곱의 장막에 들어가고 레아의 장막에 들어가고 두 여종의 장막에 들어갔으나 찾지 못하고 레아의 장막에서 나와 라헬의 장막에 들어가매'),
(1463680,51,1,31,34,'라헬이 그 드라빔을 가져 약대 안장 아래 넣고 그 위에 앉은지라 라반이 그 장막에서 찾다가 얻지 못하매'),
(1463681,51,1,31,35,'라헬이 그 아비에게 이르되 `마침 경수가 나므로 일어나서 영접할수 없사오니 내 주는 노하지 마소서'' 하니라 라반이 그 드라빔을 두루 찾다가 얻지 못한지라'),
(1463682,51,1,31,36,'야곱이 노하여 라반을 책망할새 야곱이 라반에게 대척하여 가로되 나의 허물이 무엇이니이까 ? 무슨 죄가 있기에 외삼촌께서 나를 불같이 급히 쫓나이까 ?'),
(1463683,51,1,31,37,'외삼촌께서 내 물건을 다 뒤져 보셨으니 외삼촌의 가장집물 중에 무엇을 찾았나이까 ? 여기 나의 형제와 외삼촌의 형제 앞에 그것을 두고 우리 두 사이에 판단하게 하소서'),
(1463684,51,1,31,38,'내가 이 이십년에 외삼촌과 함께 하였거니와 외삼촌의 암양들이나 암염소들이 낙태하지 아니하였고 또 외삼촌의 양떼의 수양을 내가 먹지 아니하였으며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463685,51,1,31,39,'물려 찢긴 것은 내가 외삼촌에게로 가져가지 아니하고 스스로 그것을 보충하였으며 낮에 도적을 맞았든지, 밤에 도적을 맞았든지, 내가 외삼촌에게 물어 내었으며'),
(1463686,51,1,31,40,'내가 이와 같이 낮에는 더위를 무릅쓰고, 밤에는 추위를 당하며, 눈붙일 겨를도 없이 지내었나이다'),
(1463687,51,1,31,41,'내가 외삼촌의 집에 거한 이 이십년에 외삼촌의 두 딸을 위하여 십 사년, 외삼촌의 양떼를 위하여 육년을 외삼촌을 봉사하였거니와 외삼촌께서 내 품값을 열번이나 변역하셨으니'),
(1463688,51,1,31,42,'우리 아버지의 하나님, 아브라함의 하나님, 곧 이삭의 경외하는 이가 나와 함께 계시지 아니하셨더면 외삼촌께서 이제 나를 공수로 돌려 보내셨으리이다마는 하나님이 나의 고난과 내 손의 수고를 감찰하시고 어제밤에 외삼촌을 책망하셨나이다'),
(1463689,51,1,31,43,'라반이 야곱에게 대답하여 가로되 `딸들은 내 딸이요, 자식들은 내 자식이요, 양떼는 나의 양떼요, 네가 보는 것은 다 내 것이라 내가 오늘날 내 딸들과 그 낳은 자식들에게 어찌할 수 있으랴 ?'),
(1463690,51,1,31,44,'이제 오라 너와 내가 언약을 세워 그것으로 너와 나 사이에 증거를 삼을 것이니라'''),
(1463691,51,1,31,45,'이에 야곱이 돌을 가져 기둥으로 세우고'),
(1463692,51,1,31,46,'또 `그 형제들에게 돌을 모으라` 하니 그들이 돌을 취하여 무더기를 이루매 무리가 거기 무더기 곁에서 먹고'),
(1463693,51,1,31,47,'라반은 그것을 여갈사하두다라 칭하였고 야곱은 그것을 갈르엣이라 칭하였으니'),
(1463694,51,1,31,48,'라반의 말에 `오늘날 이 무더기가 너와 나 사이에 증거가 된다'' 하였으므로 그 이름을 갈르엣이라 칭하였으며'),
(1463695,51,1,31,49,'또 미스바라 하였으니 이는 그의 말에 `우리 피차 떠나 있을 때에 여호와께서 너와 나 사이에 감찰하옵소서'' 함이라'),
(1463696,51,1,31,50,'`네가 내 딸을 박대하거나 내 딸들 외에 다른 아내들을 취하면 사람은 우리와 함께 할 자가 없어도 보라, 하나님이 너와 나 사이에 증거하시느니라'' 하였더라'),
(1463697,51,1,31,51,'라반이 또 야곱에게 이르되 `내가 너와 나 사이에 둔 이 무더기를 보라 또 이 기둥을 보라'),
(1463698,51,1,31,52,'이 무더기가 증거가 되고 이 기둥이 증거가 되나니 내가 이 무더기를 넘어 네게로 가서 해하지 않을 것이요, 네가 이 무더기, 이 기둥을 넘어 내게로 와서 해하지 않을 것이라'),
(1463699,51,1,31,53,'아브라함의 하나님, 나홀의 하나님, 그들의 조상의 하나님은 우리 사이에 판단하옵소서'' 하매 야곱이 그 아비 이삭의 경외하는 이를 가리켜 맹세하고'),
(1463700,51,1,31,54,'야곱이 또 산에서 제사를 드리고 형제들을 불러 떡을 먹이니 그들이 떡을 먹고 산에서 경야하고'),
(1463701,51,1,31,55,'라반이 아침에 일찌기 일어나 손자들과 딸들에게 입맞추며 그들에게 축복하고 떠나 고향으로 돌아갔더라'),
(1463702,51,1,32,1,'야곱이 그 길을 진행하더니 하나님의 사자들이 그를 만난지라'),
(1463703,51,1,32,2,'야곱이 그들을 볼 때에 이르기를 `이는 하나님의 군대라'' 하고 그 땅 이름을 마하나임이라 하였더라'),
(1463704,51,1,32,3,'야곱이 세일 땅 에돔 들에 있는 형 에서에게로 사자들을 자기보다 앞서 보내며'),
(1463705,51,1,32,4,'그들에게 부탁하여 가로되 `너희는 이같이 내 주 에서에게 고하라 주의 종 야곱이 말하기를 내가 라반에게 붙여서 지금까지 있었사오며'),
(1463706,51,1,32,5,'내게 소와, 나귀와, 양떼와, 노비가 있사오므로 사람을 보내어 내 주께 고하고 내 주께 은혜 받기를 원하나이다 하더라 하라'' 하였더니'),
(1463707,51,1,32,6,'사자들이 야곱에게 돌아와 가로되 `우리가 주인의 형 에서에게 이른즉 그가 사백인을 거느리고 주인을 만나려고 오더이다'''),
(1463708,51,1,32,7,'야곱이 심히 두렵고 답답하여 자기와 함께 한 종자와 양과, 소와, 약대를 두 떼로 나누고'),
(1463709,51,1,32,8,'가로되 `에서가 와서 한 떼를 치면, 남은 한 떼는 피하리라'' 하고'),
(1463710,51,1,32,9,'야곱이 또 가로되 `나의 조부 아브라함의 하나님, 나의 아버지 이삭의 하나님, 여호와여 ! 주께서 전에 내게 명하시기를 네 고향 네 족속에게로 돌아가라 내가 네게 은혜를 베풀리라 하셨나이다'),
(1463711,51,1,32,10,'나는 주께서 주의 종에게 베푸신 모든 은총과 모든 진리를 조금이라도 감당할 수 없사오나 내가 내 지팡이만 가지고 이 요단을 건넜더니 지금은 두 떼나 이루었나이다'),
(1463712,51,1,32,11,'내가 주께 간구하오니 내 형의 손에서 에서의 손에서 나를 건져내시옵소서 내가 그를 두려워하옴은 그가 와서 나와 내 처자들을 칠까 겁냄이니이다'),
(1463713,51,1,32,12,'주께서 말씀하시기를 내가 정녕 네게 은혜를 베풀어 네 씨로 바다의 셀 수 없는 모래와 같이 많게 하리라 하셨나이다'''),
(1463714,51,1,32,13,'야곱이 거기서 경야하고 그 소유 중에서 형 에서를 위하여 예물을 택하니'),
(1463715,51,1,32,14,'암염소가 이백이요, 수염소가 이십이요, 암양이 이백이요, 수양이 이십이요,'),
(1463716,51,1,32,15,'젖나는 약대 삼십과 그 새끼요, 암소가 사십이요, 황소가 열이요, 암나귀가 이십이요, 그 새끼나귀가 열이라,'),
(1463717,51,1,32,16,'그것을 각각 떼로 나눠 종들의 손에 맡기고 그 종들에게 이르되 나보다 앞서 건너가서 각 떼로 상거가 뜨게 하라 하고'),
(1463718,51,1,32,17,'그가 또 앞선 자에게 부탁하여 가로되 `내 형 에서가 너를 만나 묻기를 네가 뉘 사람이며 어디로 가느냐 ? 네 앞엣 것은 뉘 것이냐 ? 하거든'),
(1463719,51,1,32,18,'대답하기를 주의 종 야곱의 것이요, 자기 주 에서에게로 보내는 예물이오며 야곱도 우리 뒤에 있나이다 하라'' 하고'),
(1463720,51,1,32,19,'그 둘째와 세째와 각 떼를 따라가는 자에게 부탁하여 가로되 `너희도 에서를 만나거든 곧 이같이 그에게 고하고'),
(1463721,51,1,32,20,'또 너희는 말하기를 주의 종 야곱이 우리 뒤에 있다 하라'' 하니 이는 야곱의 생각에 `내가 내 앞에 보내는 예물로 형의 감정을 푼 후에 대면하면 형이 혹시 나를 받으리라'' 함이었더라'),
(1463722,51,1,32,21,'그 예물은 그의 앞서 행하고 그는 무리 가운데서 경야하다가'),
(1463723,51,1,32,22,'밤에 일어나 두 아내와 두 여종과 열 한 아들을 인도하여 얍복 나루를 건널새'),
(1463724,51,1,32,23,'그들을 인도하여 시내를 건네며 그 소유도 건네고'),
(1463725,51,1,32,24,'야곱은 홀로 남았더니 어떤 사람이 날이 새도록 야곱과 씨름하다가'),
(1463726,51,1,32,25,'그 사람이 자기가 야곱을 이기지 못함을 보고 야곱의 환도뼈를 치매 야곱의 환도뼈가 그 사람과 씨름할 때에 위골되었더라'),
(1463727,51,1,32,26,'그 사람이 가로되 `날이 새려 하니 나로 가게 하라'' 야곱이 가로되 `당신이 내게 축복하지 아니하면 가게 하지 아니하겠나이다 !'''),
(1463728,51,1,32,27,'그 사람이 그에게 이르되 `네 이름이 무엇이냐 ?'' 그가 가로되 `야곱이니이다'''),
(1463729,51,1,32,28,'그 사람이 가로되 `네 이름을 다시는 야곱이라 부를 것이 아니요 이스라엘이라 부를 것이니 이는 네가 하나님과 사람으로 더불어 겨루어 이기었음이니라'''),
(1463730,51,1,32,29,'야곱이 청하여 가로되 `당신의 이름을 고하소서'' 그 사람이 가로되 `어찌 내 이름을 묻느냐 ?'' 하고 거기서 야곱에게 축복한지라'),
(1463731,51,1,32,30,'그러므로 야곱이 그곳 이름을 브니엘이라 하였으니 그가 이르기를 내가 하나님과 대면하여 보았으나 내 생명이 보전되었다'' 함이더라'),
(1463732,51,1,32,31,'그가 브니엘을 지날 때에 해가 돋았고 그 환도뼈로 인하여 절었더라'),
(1463733,51,1,32,32,'그 사람이 야곱의 환도뼈 큰 힘줄을 친고로 이스라엘 사람들이 지금까지 환도뼈 큰 힘줄을 먹지 아니하더라'),
(1463734,51,1,33,1,'야곱이 눈을 들어 보니 에서가 사백인을 거느리고 오는지라 그 자식들을 나누어 레아와 라헬과 두 여종에게 맡기고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463735,51,1,33,2,'여종과 그 자식들은 앞에 두고 레아와 그 자식들은 다음에 두고 라헬과 요셉은 뒤에 두고'),
(1463736,51,1,33,3,'자기는 그들 앞에서 나아가되 몸을 일곱번 땅에 굽히며 그 형 에서에게 가까이 하니'),
(1463737,51,1,33,4,'에서가 달려와서 그를 맞아서 안고 목을 어긋맞기고 그와 입맞추고 피차 우니라'),
(1463738,51,1,33,5,'에서가 눈을 들어 여인과 자식들을 보고 묻되 `너와 함께한 이들은 누구냐 ?'' 야곱이 가로되 `하나님이 주의 종에게 은혜로 주신 자식이니이다'''),
(1463739,51,1,33,6,'때에 여종들이 그 자식으로 더불어 나아와 절하고'),
(1463740,51,1,33,7,'레아도 그 자식으로 더불어 나아와 절하고 그 후에 요셉이 라헬로 더불어 나아와 절하니'),
(1463741,51,1,33,8,'에서가 또 가로되 `나의 만난 바 이 모든 떼는 무슨 까닭이냐 ?'' 야곱이 가로되 `내 주께 은혜를 입으려 함이니이다'''),
(1463742,51,1,33,9,'에서가 가로되 `내 동생아, 내게 있는 것이 족하니 네 소유는 네게 두라'''),
(1463743,51,1,33,10,'야곱이 가로되 `그렇지 아니하니이다 형님께 은혜를 얻었사오면 청컨대 내 손에서 이 예물을 받으소서 내가 형님의 얼굴을 뵈온즉 하나님의 얼굴을 본 것 같사오며 형님도 나를 기뻐하심이니이이다'),
(1463744,51,1,33,11,'하나님이 내게 은혜를 베푸셨고 나의 소유도 족하오니 청컨대 내가 형님께 드리는 예물을 받으소서'' 하고 그에게 강권하매 받으니라'),
(1463745,51,1,33,12,'에서가 가로되 `우리가 떠나가자 내가 너의 앞잡이가 되리라'''),
(1463746,51,1,33,13,'야곱이 그에게 이르되 `내 주도 아시거니와 자식들은 유약하고 내게 있는 양떼와 소가 새끼를 데렸은즉 하루만 과히 몰면 모든 떼가 죽으리니'),
(1463747,51,1,33,14,'청컨대 내 주는 종보다 앞서 가소서 나는 앞에 가는 짐승과 자식의 행보대로 천천히 인도하여 세일로 가서 내 주께 나아가리이다'''),
(1463748,51,1,33,15,'에서가 가로되 `내가 내 종자 수인을 네게 머물리라'' 야곱이 가로되 `어찌하여 그리하리이까 ? 나로 내 주께 은혜를 얻게 하소서'' 하매'),
(1463749,51,1,33,16,'이 날에 에서는 세일로 회정하고'),
(1463750,51,1,33,17,'야곱은 숙곳에 이르러 자기를 위하여 집을 짓고 짐승을 위하여 우릿간을 지은고로 그 땅 이름을 숙곳이라 부르더라'),
(1463751,51,1,33,18,'야곱이 밧단아람에서부터 평안히 가나안 땅 세겜 성에 이르러 성 앞에 그 장막을 치고'),
(1463752,51,1,33,19,'그 장막 친 밭을 세겜의 아비 하몰의 아들들의 손에서 은 일백개로 사고'),
(1463753,51,1,34,1,'레아가 야곱에게 낳은 딸 디나가 그 땅 여자를 보러 나갔더니'),
(1463754,51,1,34,2,'히위 족속 중 하몰의 아들 그 땅 추장 세겜이 그를 보고 끌어들여 강간하여 욕되게 하고'),
(1463755,51,1,34,3,'그 마음이 깊이 야곱의 딸 디나에게 연련하며 그 소녀를 사랑하여 그의 마음을 말로 위로하고'),
(1463756,51,1,34,4,'그 아비 하몰에게 청하여 가로되 `이 소녀를 내 아내로 얻게 하여 주소서'' 하였더라'),
(1463757,51,1,34,5,'야곱이 그 딸 디나를 그가 더럽혔다 함을 들었으나 자기 아들들이 들에서 목축하므로 그들의 돌아오기까지 잠잠하였고'),
(1463758,51,1,34,6,'세겜의 아비 하몰은 야곱에게 말하러 왔으며'),
(1463759,51,1,34,7,'야곱의 아들들은 들에서 이를 듣고 돌아와서 사람 사람이 근심하고 심히 노하였으니 이는 세겜이 야곱의 딸을 강간하여 이스라엘에게 부끄러운 일 곧 행치 못할 일을 행하였음이더라'),
(1463760,51,1,34,8,'하몰이 그들에게 이르되 `내 아들 세겜이 마음으로 너희 딸을 연련하여 하니 원컨대 그를 세겜에게 주어 아내를 삼게 하라'),
(1463761,51,1,34,9,'너희가 우리와 통혼하여 너희 딸을 우리에게 주며 우리 딸을 너희가 취하고'),
(1463762,51,1,34,10,'너희가 우리와 함께 거하되 땅이 너희 앞에 있으니 여기 머물러 매매하며 여기서 기업을 얻으라'' 하고'),
(1463763,51,1,34,11,'세겜도 디나의 아비와 남형들에게 이르되 `나로 너희에게 은혜를 입게 하라 너희가 내게 청구하는 것은 내가 수응하리니'),
(1463764,51,1,34,12,'이 소녀만 내게 주어 아내가 되게 하라 아무리 큰 빙물과 예물을 청구할지라도 너희가 내게 말한대로 수응하리라'''),
(1463765,51,1,34,13,'야곱의 아들들이 세겜과 그 아비 하몰에게 속여 대답하였으니 이는 세겜이 그 누이 디나를 더럽혔음이라'),
(1463766,51,1,34,14,'야곱의 아들들이 그들에게 말하되 `우리는 그리하지 못하겠노라 할례 받지 아니한 사람에게 우리 누이를 줄 수 없노니 이는 우리의 수욕이 됨이니라'),
(1463767,51,1,34,15,'그런즉 이같이 하면 너희에게 허락하리라 만일 너희 중 남자가 다 할례를 받고 우리 같이 되면'),
(1463768,51,1,34,16,'우리 딸을 너희에게 주며 너희 딸을 우리가 취하며 너희가 함께 거하여 한 민족이 되려니와'),
(1463769,51,1,34,17,'너희가 만일 우리를 듣지 아니하고 할례를 받지 아니하면 우리는 곧 우리 딸을 데리고 가리라'''),
(1463770,51,1,34,18,'그들의 말을 하몰과 그 아들 세겜이 좋게 여기므로'),
(1463771,51,1,34,19,'이 소년이 그 일 행하기를 지체치 아니하였으니 그가 야곱의 딸을 사랑함이며 그는 그 아비 집에 가장 존귀함일러라'),
(1463772,51,1,34,20,'하몰과 그 아들 세겜이 성문에 이르러 그 고을 사람에게 말하여 가로되'),
(1463773,51,1,34,21,'`이 사람들은 우리와 친목하고 이 땅은 넓어 그들을 용납할 만하니 그들로 여기서 거주하며 매매하게 하고 우리가 그들의 딸들을 아내로 취하고 우리 딸들도 그들에게 주자'),
(1463774,51,1,34,22,'그러나 우리 중에 모든 남자가 그들의 할례를 받음 같이 할례를 받아야 그 사람들이 우리와 함께 거하여 한 민족 되기를 허락할 것이라'),
(1463775,51,1,34,23,'그리하면 그들의 생축과 재산과 그 모든 짐승이 우리의 소유가 되지 않겠느냐 ? 다만 그 말대로 하자 그리하면 그들이 우리와 함께 거하리라'''),
(1463776,51,1,34,24,'성문으로 출입하는 모든 자가 하몰과 그 아들 세겜의 말을 듣고 성문으로 출입하는 그 모든 남자가 할례를 받으니라'),
(1463777,51,1,34,25,'제 삼일에 미쳐 그들이 고통할 때에 야곱의 두 아들 디나의 오라비 시므온과 레위가 각기 칼을 가지고 가서 부지중에 성을 엄습하여 그 모든 남자를 죽이고'),
(1463778,51,1,34,26,'칼로 하몰과 그 아들 세겜을 죽이고 디나를 세겜의 집에서 데려오고'),
(1463779,51,1,34,27,'야곱의 여러 아들이 그 시체있는 성으로 가서 노략하였으니 이는 그들이 그 누이를 더럽힌 연고라'),
(1463780,51,1,34,28,'그들이 양과, 소와, 나귀와, 그 성에 있는 것과, 들에 있는 것과,'),
(1463781,51,1,34,29,'그 모든 재물을 빼앗으며 그 자녀와 아내들을 사로잡고 집 속의 물건을 다 노략한지라'),
(1463782,51,1,34,30,'야곱이 시므온과 레위에게 이르되 너희가 내게 화를 끼쳐 나로 이 땅 사람 곧 가나안 족속과 브리스 족속에게 냄새를 내게 하였도다 나는 수가 적은즉 그들이 모여 나를 치고 나를 죽이리니 그리하면 나와 내 집이 멸망하리라'),
(1463783,51,1,34,31,'그들이 가로되 `그가 우리 누이를 창녀같이 대우함이 가하니이까 ?'''),
(1463784,51,1,35,1,'하나님이 야곱에게 이르시되 일어나 벧엘로 올라가서 거기 거하며 네가 네 형 에서의 낯을 피하여 도망하던 때에 네게 나타났던 하나님께 거기서 단을 쌓으라 ! 하신지라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463785,51,1,35,2,'야곱이 이에 자기 집 사람과 자기와 함께 한 모든 자에게 이르되 `너희 중의 이방 신상을 버리고 자신을 정결케 하고 의복을 바꾸라'),
(1463786,51,1,35,3,'우리가 일어나 벧엘로 올라가자 나의 환난날에 내게 응답하시며 나의 가는 길에서 나와 함께 하신 하나님께 내가 거기서 단을 쌓으려 하노라'' 하매'),
(1463787,51,1,35,4,'그들이 자기 손에 있는 모든 이방 신상과 자기 귀에 있는 고리를 야곱에게 주는지라 야곱이 그것들을 세겜 근처 상수리나무 아래 묻고'),
(1463788,51,1,35,5,'그들이 발행하였으나 하나님이 그 사면 고을들로 크게 두려워하게 하신 고로 야곱의 아들들을 추격하는 자가 없었더라'),
(1463789,51,1,35,6,'야곱과 그와 함께한 모든 사람이 가나안 땅 루스 곧 벧엘에 이르고'),
(1463790,51,1,35,7,'그가 거기서 단을 쌓고 그곳을 엘벧엘이라 불렀으니 이는 그 형의 낯을 피할 때에 하나님이 그에게 거기서 나타나셨음이더라'),
(1463791,51,1,35,8,'리브가의 유모 드보라가 죽으매 그를 벧엘 아래 상수리나무 밑에 장사하고 그 나무 이름을 알론바굿이라 불렀더라'),
(1463792,51,1,35,9,'야곱이 밧단아람에서 돌아오매 하나님이 다시 야곱에게 나타나서 그에게 복을 주시고'),
(1463793,51,1,35,10,'그에게 이르시되 네 이름이 야곱이다마는 네 이름을 다시는 야곱이라 부르지 않겠고 이스라엘이 네 이름이 되리라 하시고 그가 그의 이름을 이스라엘이라 부르시고'),
(1463794,51,1,35,11,'그에게 이르시되 나는 전능한 하나님이니라 ! 생육하며 번성하라 ! 국민과 많은 국민이 네게서 나고 왕들이 네 허리에서 나오리라'),
(1463795,51,1,35,12,'내가 아브라함과 이삭에게 준 땅을 네게 주고 내가 네 후손에게도 그 땅을 주리라 ! 하시고'),
(1463796,51,1,35,13,'하나님이 그와 말씀하시던 곳에서 그를 떠나 올라가시는지라'),
(1463797,51,1,35,14,'야곱이 하나님의 자기와 말씀하시던 곳에 기둥 곧 돌 기둥을 세우고 그 위에 전제물을 붓고 또 그 위에 기름을 붓고'),
(1463798,51,1,35,15,'하나님이 자기와 말씀하시던 곳의 이름을 벧엘이라 불렀더라'),
(1463799,51,1,35,16,'그들이 벧엘에서 발행하여 에브랏에 이르기까지 얼마 길을 격한 곳에서 라헬이 임산하여 심히 신고하더니'),
(1463800,51,1,35,17,'그가 난산할 즈음에 산파가 그에게 이르되 `두려워말라 지금 그대가 또 득남하느니라'' 하매'),
(1463801,51,1,35,18,'그가 죽기에 임하여 그 혼이 떠나려할 때에 아들의 이름은 베노니라 불렀으나 그 아비가 그를 베냐민이라 불렀더라'),
(1463802,51,1,35,19,'라헬이 죽으매 에브랏 곧 베들레헴 길에 장사되었고'),
(1463803,51,1,35,20,'야곱이 라헬의 묘에 비를 세웠더니 지금까지 라헬의 묘비라 일컫더라'),
(1463804,51,1,35,21,'이스라엘이 다시 발행하여 에델 망대를 지나 장막을 쳤더라'),
(1463805,51,1,35,22,'이스라엘이 그 땅에 유할 때에 르우벤이 가서 그 서모 빌하와 통간하매 이스라엘이 이를 들었더라 야곱의 아들은 열 둘이라'),
(1463806,51,1,35,23,'레아의 소생은 야곱의 장자 르우벤과, 그 다음 시므온과, 레위와, 유다와, 잇사갈과, 스불론이요,'),
(1463807,51,1,35,24,'라헬의 소생은 요셉과, 베냐민이며,'),
(1463808,51,1,35,25,'라헬의 여종 빌하의 소생은 단과, 납달리요,'),
(1463809,51,1,35,26,'레아의 여종 실바의 소생은 갓과, 아셀이니, 이들은 야곱의 아들들이요 밧단아람에서 그에게 낳은 자더라'),
(1463810,51,1,35,27,'야곱이 기럇아르바의 마므레로 가서 그 아비 이삭에게 이르렀으니 기럇아르바는 곧 아브라함과 이삭의 우거하던 헤브론이더라'),
(1463811,51,1,35,28,'이삭의 나이 일백 팔십세라'),
(1463812,51,1,35,29,'이삭이 나이 많고 늙어 기운이 진하매 죽어 자기 열조에게로 돌아가니 그 아들 에서와 야곱이 그를 장사하였더라'),
(1463813,51,1,36,1,'에서 곧 에돔의 대략이 이러하니라'),
(1463814,51,1,36,2,'에서가 가나안 여인 중 헷 족속 중 엘론의 딸 아다와, 히위 족속중 시브온의 딸 아나의 소생 오홀리바마를 자기 아내로 취하고'),
(1463815,51,1,36,3,'또 이스마엘의 딸 느바욧의 누이 바스맛을 취하였더니'),
(1463816,51,1,36,4,'아다는 엘리바스를 에서에게 낳았고, 바스맛은 르우엘을 낳았고'),
(1463817,51,1,36,5,'오홀리바마는 여우스와, 얄람과, 고라를 낳았으니 이들은 에서의 아들이요 가나안 땅에서 그에게 낳은 자더라'),
(1463818,51,1,36,6,'에서가 자기 아내들과, 자기 자녀들과, 자기 집의 모든 사람과, 자기의 가축과, 자기 모든 짐승과, 자기가 가나안 땅에서 얻은 모든 재물을 이끌고 그 동생 야곱을 떠나 타처로 갔으니'),
(1463819,51,1,36,7,'두 사람의 소유가 풍부하여 함께 거할 수 없음이러라 그들의 우거한 땅이 그들의 가축으로 인하여 그들을 용납할 수 없었더라'),
(1463820,51,1,36,8,'이에 에서 곧 에돔이 세일산에 거하니라'),
(1463821,51,1,36,9,'세일산에 거한 에돔 족속의 조상 에서의 대략이 이러하고'),
(1463822,51,1,36,10,'그 자손의 이름은 이러하니라 에서의 아내 아다의 아들은 엘리바스요, 에서의 아내 바스맛의 아들은 르우엘이며'),
(1463823,51,1,36,11,'엘리바스의 아들들은 데만과, 오말과, 스보와, 가담과, 그나스요,'),
(1463824,51,1,36,12,'에서의 아들 엘리바스의 첩 딤나는 아말렉을 엘리바스에게 낳았으니 이들은 에서의 아내 아다의 자손이며'),
(1463825,51,1,36,13,'르우엘의 아들들은 나핫과, 세라와, 삼마와, 미사니 이들은 에서의 아내 바스맛의 자손이며'),
(1463826,51,1,36,14,'시브온의 손녀 아나의 딸 에서의 아내 오홀리바마의 아들들은 이러하니 그가 여우스와, 얄람과, 고라를 에서에게 낳았더라'),
(1463827,51,1,36,15,'에서 자손 중 족장은 이러하니라 에서의 장자 엘리바스의 자손에는 데만 족장, 오말 족장, 스보 족장, 그나스 족장과'),
(1463828,51,1,36,16,'고라 족장, 가담 족장, 아말렉 족장이니 이들은 에돔 땅에 있는 엘리바스로 말미암아 나온 족장들이요 이들은 아다의 자손이며'),
(1463829,51,1,36,17,'에서의 아들 르우엘의 자손에는 나핫 족장, 세라 족장, 삼마 족장, 미사 족장이니 이들은 에돔 땅에 있는 르우엘로 말미암아 나온 족장들이요 이들은 에서의 아내 바스맛의 자손이며'),
(1463830,51,1,36,18,'에서의 아내 오홀리바마의 아들들은 여우스 족장, 얄람 족장, 고라 족장이니 이들은 아나의 딸이요 에서의 아내인 오홀리바마로 말미암아 나온 족장들이라'),
(1463831,51,1,36,19,'에서 곧 에돔의 자손으로서 족장 된 자들이 이러하였더라'),
(1463832,51,1,36,20,'그 땅의 원거인 호리 족속 세일의 자손은 로단과, 소발과, 시브온과, 아나와,'),
(1463833,51,1,36,21,'디손과, 에셀과, 디산이니 이들은 에돔 땅에 있는 세일의 자손중 호리 족속으로 말미암아 나온 족장들이요'),
(1463834,51,1,36,22,'로단의 자녀는 호리와, 헤맘과, 로단의 누이 딤나요');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463835,51,1,36,23,'소발의 자녀는 알완과, 마나핫과, 에발과, 스보와, 오남이요'),
(1463836,51,1,36,24,'시브온의 자녀는 아야와, 아나며 이 아나는 그 아비 시브온의 나귀를 칠 때에 광야에서 온천을 발견하였고'),
(1463837,51,1,36,25,'아나의 자녀는 디손과, 오홀리바마니 오홀리바마는 아나의 딸이며'),
(1463838,51,1,36,26,'디손의 자녀는 헴단과, 에스반과, 이드란과, 그란이요'),
(1463839,51,1,36,27,'에셀의 자녀는 빌한과, 사아완과, 아간이요'),
(1463840,51,1,36,28,'디산의 자녀는 우스와, 아란이니'),
(1463841,51,1,36,29,'호리 족속의 족장들은 곧 로단 족장, 소발 족장, 시브온 족장, 아나 족장'),
(1463842,51,1,36,30,'디손 족장, 에셀 족장, 디산 족장이라 이들은 그 구역을 따라 세일 땅에 있는 호리 족속으로 말미암아 나온 족장들이었더라'),
(1463843,51,1,36,31,'이스라엘 자손을 다스리는 왕이 있기 전에 에돔 땅을 다스리는 왕이 이러하니라'),
(1463844,51,1,36,32,'브올의 아들 벨라가 에돔의 왕이 되었으니 그 도성의 이름은 딘하바며'),
(1463845,51,1,36,33,'벨라가 죽고 보스라 사람 세라의 아들 요밥이 그를 대신하여 왕이 되고'),
(1463846,51,1,36,34,'요밥이 죽고 데만 족속의 땅의 후삼이 그를 대신하여 왕이 되고'),
(1463847,51,1,36,35,'후삼이 죽고 브닷의 아들 곧 모압 들에서 미디안 족속을 친 하닷이 그를 대신하여 왕이 되니 그 도성 이름은 아윗이며'),
(1463848,51,1,36,36,'하닷이 죽고 마스레가의 삼라가 그를 대신하여 왕이 되고'),
(1463849,51,1,36,37,'삼라가 죽고 유브라데 하숫가 르호봇의 사울이 그를 대신하여 왕이 되고'),
(1463850,51,1,36,38,'사울이 죽고 악볼의 아들 바알하난이 그를 대신하여 왕이 되고'),
(1463851,51,1,36,39,'악볼의 아들 바알하난이 죽고 하달이 그를 대신하여 왕이 되니 그 도성 이름은 바우며 그 처의 이름은 므헤다벨이니 마드렛의 딸이요 메사합의 손녀더라'),
(1463852,51,1,36,40,'에서에게서 나온 족장들의 이름은 그 종족과 거처와 이름대로 이러하니 딤나 족장, 알와 족장, 여뎃 족장'),
(1463853,51,1,36,41,'오홀리바마 족장, 엘라 족장, 비논 족장'),
(1463854,51,1,36,42,'그나스 족장, 데만 족장, 밉살 족장'),
(1463855,51,1,36,43,'막디엘 족장, 이람 족장이라 이들은 그 구역과 거처를 따른 에돔 족장들이며 에돔 족속의 조상은 에서더라'),
(1463856,51,1,37,1,'야곱이 가나안 땅 곧 그 아비의 우거하던 땅에 거하였으니'),
(1463857,51,1,37,2,'야곱의 약전이 이러하니라 요셉이 십 칠세의 소년으로서 그 형제와 함께 양을 칠 때에 그 아비의 첩 빌하와 실바의 아들들로 더불어 함께 하였더니 그가 그들의 과실을 아비에게 고하더라'),
(1463858,51,1,37,3,'요셉은 노년에 얻은 아들이므로 이스라엘이 여러 아들보다 그를 깊이 사랑하여 위하여 채색옷을 지었더니'),
(1463859,51,1,37,4,'그 형들이 아비가 형제들보다 그를 사랑함을 보고 그를 미워하여 그에게 언사가 불평하였더라'),
(1463860,51,1,37,5,'요셉이 꿈을 꾸고 자기 형들에게 고하매 그들이 그를 더욱 미워하였더라'),
(1463861,51,1,37,6,'요셉이 그들에게 이르되 `청컨대 나의 꾼 꿈을 들으시오'),
(1463862,51,1,37,7,'우리가 밭에서 곡식을 묶더니 내 단은 일어서고 당신들의 단은 내 단을 둘러서서 절하더이다'''),
(1463863,51,1,37,8,'그 형들이 그에게 이르되 `네가 참으로 우리의 왕이 되겠느냐 ? 참으로 우리를 다스리게 되겠느냐 ?'' 하고 그 꿈과 그 말을 인하여 그를 더욱 미워하더니'),
(1463864,51,1,37,9,'요셉이 다시 꿈을 꾸고 그 형들에게 고하여 가로되 `내가 또 꿈을 꾼즉 해와 달과 열한 별이 내게 절하더이다'' 하니라'),
(1463865,51,1,37,10,'그가 그 꿈으로 부형에게 고하매 아비가 그를 꾸짖고 그에게 이르되 `너의 꾼 꿈이 무엇이냐 나와 네 모와 네 형제들이 참으로 가서 땅에 엎드려 네게 절하겠느냐 ?'''),
(1463866,51,1,37,11,'그 형들은 시기하되 그 아비는 그 말을 마음에 두었더라'),
(1463867,51,1,37,12,'그 형들이 세겜에 가서 아비의 양떼를 칠 때에'),
(1463868,51,1,37,13,'이스라엘이 요셉에게 이르되 `네 형들이 세겜에서 양을 치지 아니하느냐 ? 너를 그들에게로 보내리라'' 요셉이 아비에게 대답하되 `내가 그리하겠나이다'''),
(1463869,51,1,37,14,'이스라엘이 그에게 이르되 `가서 네 형들과 양떼가 다 잘 있는 여부를 보고 돌아와 내게 고하라'' 하고 그를 헤브론 골짜기에서 보내매 이에 세겜으로 가니라'),
(1463870,51,1,37,15,'어떤 사람이 그를 만난즉 그가 들에서 방황하는지라 그 사람이 그에게 물어 가로되 `네가 무엇을 찾느냐 ?'''),
(1463871,51,1,37,16,'그가 가로되 `내가 나의 형들을 찾으오니 청컨대 그들의 양치는 곳을 내게 가르치소서'''),
(1463872,51,1,37,17,'그 사람이 가로되 `그들이 여기서 떠났느니라 내가 그들의 말을 들으니 도단으로 가자 하더라'' 요셉이 그 형들의 뒤를 따라 가서 도단에서 그들을 만나니라'),
(1463873,51,1,37,18,'요셉이 그들에게 가까이 오기 전에 그들이 요셉을 멀리서 보고 죽이기를 꾀하여'),
(1463874,51,1,37,19,'서로 이르되 `꿈 꾸는 자가 오는도다'),
(1463875,51,1,37,20,'자, 그를 죽여 한 구덩이에 던지고 우리가 말하기를 악한 짐승이 그를 잡아먹었다 하자 그 꿈이 어떻게 되는 것을 우리가 볼 것이니라'' 하는지라'),
(1463876,51,1,37,21,'르우벤이 듣고 요셉을 그들의 손에서 구원하려 하여 가로되 `우리가 그 생명은 상하지 말자'''),
(1463877,51,1,37,22,'르우벤이 또 그들에게 이르되 `피를 흘리지 말라 그를 광야 그 구덩이에 던지고 손을 그에게 대지 말라'' 하니 이는 그가 요셉을 그들의 손에서 구원하여 그 아비에게로 돌리려 함이었더라'),
(1463878,51,1,37,23,'요셉이 형들에게 이르매 그 형들이 요셉의 옷 곧 그 입은 채색옷을 벗기고'),
(1463879,51,1,37,24,'그를 잡아 구덩이에 던지니 그 구덩이는 빈 것이라 그 속에 물이 없었더라'),
(1463880,51,1,37,25,'그들이 앉아 음식을 먹다가 눈을 들어 본즉 한떼 이스마엘 족속이 길르앗에서 오는데 그 약대들에 향품과, 유향과, 몰약을 싣고 애굽으로 내려가는지라'),
(1463881,51,1,37,26,'유다가 자기 형제에게 이르되 `우리가 우리 동생을 죽이고 그의 피를 은익한들 무엇이 유익할까 ?'),
(1463882,51,1,37,27,'자, 그를 이스마엘 사람에게 팔고 우리 손을 그에게 대지 말자 그는 우리의 동생이요 우리의 골육이니라'' 하매 형제들이 청종하였더라'),
(1463883,51,1,37,28,'때에 미디안 사람 상고들이 지나는지라 그들이 요셉을 구덩이에서 끌어 올리고 은 이십개에 그를 이스마엘 사람들에게 팔매 그 상고들이 요셉을 데리고 애굽으로 갔더라'),
(1463884,51,1,37,29,'르우벤이 돌아와서 구덩이에 이르러 본즉 거기 요셉이 없는지라 옷을 찢고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463885,51,1,37,30,'아우들에게로 와서 가로되 `아이가 없도다 나는 나는 어디로 갈까 ?'''),
(1463886,51,1,37,31,'그들이 요셉의 옷을 취하고 수염소를 죽여 그 옷을 피에 적시고'),
(1463887,51,1,37,32,'그 채색옷을 보내어 그 아비에게로 가져다가 이르기를 `우리가 이것을 얻었으니 아버지의 아들의 옷인가 아닌가 보소서'' 하매'),
(1463888,51,1,37,33,'아비가 그것을 알아보고 가로되 `내 아들의 옷이라 악한 짐승이 그를 먹었도다 요셉이 정녕 찢겼도다'' 하고'),
(1463889,51,1,37,34,'자기 옷을 찢고 굵은 베로 허리를 묶고 오래도록 그 아들을 위하여 애통하니'),
(1463890,51,1,37,35,'그 모든 자녀가 위로하되 그가 그 위로를 받지 아니하여 가로되 `내가 슬퍼하며 음부에 내려 아들에게로 가리라'' 하고 그 아비가 그를 위하여 울었더라'),
(1463891,51,1,37,36,'미디안 사람이 애굽에서 바로의 신하 시위대장 보디발에게 요셉을 팔았더라'),
(1463892,51,1,38,1,'그 후에 유다가 자기 형제에게서 내려가서 아둘람 사람 히라에게로 나아가니라'),
(1463893,51,1,38,2,'유다가 거기서 가나안 사람 수아라 하는 자의 딸을 보고 그를 취하여 동침하니'),
(1463894,51,1,38,3,'그가 잉태하여 아들을 낳으매 유다가 그 이름을 엘이라 하니라'),
(1463895,51,1,38,4,'그가 다시 잉태하여 아들을 낳고 그 이름을 오난이라 하고'),
(1463896,51,1,38,5,'그가 또 다시 아들을 낳고 그 이름을 셀라라 하니라 그가 셀라를 낳을 때에 유다는 거십에 있었더라'),
(1463897,51,1,38,6,'유다가 장자 엘을 위하여 아내를 취하니 그 이름은 다말이더라'),
(1463898,51,1,38,7,'유다의 장자 엘이 여호와 목전에 악하므로 여호와께서 그를 죽이신지라'),
(1463899,51,1,38,8,'유다가 오난에게 이르되 `네 형수에게로 들어가서 남편의 아우의 본분을 행하여 네 형을 취하여 씨가 있게 하라'''),
(1463900,51,1,38,9,'오난이 그 씨가 자기 것이 되지 않을 줄 알므로 형수에게 들어갔을 때에 형에게 아들을 얻게 아니하려고 땅에 설정하매'),
(1463901,51,1,38,10,'그 일이 여호와 목전에 악하므로 여호와께서 그도 죽이시니'),
(1463902,51,1,38,11,'유다가 그 며느리 다말에게 이르되 `수절하고 네 아비 집에 있어서 내 아들 셀라가 장성하기를 기다리라'' 하니 셀라도 그 형들 같이 죽을까 염려함이라 다말이 가서 그 아비 집에 있으니라'),
(1463903,51,1,38,12,'얼마 후에 유다의 아내 수아의 딸이 죽은지라 유다가 위로를 받은 후에 그 친구 아둘람 사람 히라와 함께 딤나로 올라가서 자기 양털 깍는 자에게 이르렀더니'),
(1463904,51,1,38,13,'혹이 다말에게 고하되 `네 시부가 자기 양털을 깎으려고 딤나에 올라왔다'' 한지라'),
(1463905,51,1,38,14,'그가 그 과부의 의복을 벗고 면박으로 얼굴을 가리고 몸을 휩싸고 딤나 길 곁 에나임 문에 앉으니 이는 셀라가 장성함을 보았어도 자기를 그의 아내로 주지 않음을 인함이라'),
(1463906,51,1,38,15,'그가 얼굴을 가리웠으므로 유다가 그를 보고 창녀로 여겨'),
(1463907,51,1,38,16,'길곁으로 그에게 나아가 가로되 `청컨대 나로 네게 들어가게 하라'' 하니 그 자부인줄 알지 못하였음이라 그가 가로되 `당신이 무엇을 주고 내게 들어 오려느냐 ?'''),
(1463908,51,1,38,17,'유다가 가로되 내가 내 떼에서 염소 새끼를 주리라 그가 가로되 당신이 그것을 줄 때까지 약조물을 주겠느냐 ?'),
(1463909,51,1,38,18,'유다가 가로되 `무슨 약조물을 네게 주랴 ?'' 그가 가로되 `당신의 도장과 그 끈과 당신의 손에 있는 지팡이로 하라'' 유다가 그것들을 그에게 주고 그에게로 들어갔더니 그가 유다로 말미암아 잉태하였더라'),
(1463910,51,1,38,19,'그가 일어나 떠나가서 그 면박을 벗고 과부의 의복을 도로 입으니라'),
(1463911,51,1,38,20,'유다가 그 친구 아둘람 사람의 손에 부탁하여 염소 새끼를 보내고 그 여인의 손에서 약조물을 찾으려 하였으나 그가 그 여인을 찾지 못한지라'),
(1463912,51,1,38,21,'그가 그 곳 사람에게 물어 가로되 `길 곁 에나임에 있던 창녀가 어디 있느냐 ?` 그들이 가로되 `여기는 창녀가 없느니라'''),
(1463913,51,1,38,22,'그가 유다에게로 돌아와 가로되 `내가 그를 찾지 못하고 그 곳 사람도 이르기를 여기는 창녀가 없다 하더라`'),
(1463914,51,1,38,23,'유다가 가로되 `그로 그것을 가지게 두라 우리가 부끄러움을 당할까 하노라 내가 이 염소 새끼를 보내었으나 그대가 그를 찾지 못하였느니라'''),
(1463915,51,1,38,24,'석달쯤 후에 혹이 유다에게 고하여 가로되 `네 며느리 다말이 행음하였고 그 행음함을 인하여 잉태하였느니라'' 유다가 가로되 `그를 끌어 내어 불사르라'''),
(1463916,51,1,38,25,'여인이 끌려 나갈 때에 보내어 시부에게 이르되 `이 물건 임자로 말미암아 잉태하였나이다 청컨대 보소서, 이 도장과 그 끈과 지팡이가 뉘 것이니이까 ?'' 한지라'),
(1463917,51,1,38,26,'유다가 그것들을 알아보고 가로되 `그는 나보다 옳도다 내가 그를 내 아들 셀라에게 주지 아니하였음이로다'' 하고 다시는 그를 가까이 하지 아니하였더라'),
(1463918,51,1,38,27,'임산하여 보니 쌍태라'),
(1463919,51,1,38,28,'해산할 때에 손이 나오는지라 산파가 가로되 `이는 먼저 나온자라'' 하고 홍사를 가져 그 손에 매었더니'),
(1463920,51,1,38,29,'그 손을 도로 들이며 그 형제가 나오는지라 산파가 가로되 `네가 어찌하여 터치고 나오느냐 ?'' 한고로 그 이름을 베레스라 불렀고'),
(1463921,51,1,38,30,'그 형제 곧 손에 홍사 있는 자가 뒤에 나오니 그 이름을 세라라 불렀더라'),
(1463922,51,1,39,1,'요셉이 이끌려 애굽에 내려가매 바로의 신하 시위대장 애굽사람 보디발이 그를 그리로 데려간 이스마엘 사람의 손에서 그를 사니라'),
(1463923,51,1,39,2,'여호와께서 요셉과 함께 하시므로 그가 형통한 자가 되어 그 주인 애굽 사람의 집에 있으니'),
(1463924,51,1,39,3,'그 주인이 여호와께서 그와 함께하심을 보며 또 여호와께서 그의 범사에 형통케 하심을 보았더라'),
(1463925,51,1,39,4,'요셉이 그 주인에게 은혜를 입어 섬기매 그가 요셉으로 가정 총무를 삼고 자기 소유를 다 그 손에 위임하니'),
(1463926,51,1,39,5,'그가 요셉에게 자기 집과 그 모든 소유물을 주관하게 한 때부터 여호와께서 요셉을 위하여 그 애굽 사람의 집에 복을 내리시므로 여호와의 복이 그의 집과 밭에 있는 모든 소유에 미친지라'),
(1463927,51,1,39,6,'주인이 그 소유를 다 요셉의 손에 위임하고 자기 식료 외에는 간섭하지 아니하였더라 요셉은 용모가 준수하고 아담하였더라'),
(1463928,51,1,39,7,'그 후에 그 주인의 처가 요셉에게 눈짓하다가 동침하기를 청하니'),
(1463929,51,1,39,8,'요셉이 거절하며 자기 주인의 처에게 이르되 `나의 주인이 가중 제반 소유를 간섭지 아니하고 다 내 손에 위임하였으니'),
(1463930,51,1,39,9,'이 집에는 나보다 큰 이가 없으며 주인이 아무 것도 내게 금하지 아니하였어도 금한 것은 당신뿐이니 당신은 자기 아내임이라 그런즉 내가 어찌 이 큰 악을 행하여 하나님께 득죄하리이까 ?'''),
(1463931,51,1,39,10,'여인이 날마다 요셉에게 청하였으나 요셉이 듣지 아니하여 동침하지 아니할 뿐더러 함께 있지도 아니하니라'),
(1463932,51,1,39,11,'그러할 때에 요셉이 시무하러 그 집에 들어갔더니 그 집 사람은 하나도 거기 없었더라'),
(1463933,51,1,39,12,'그 여인이 그 옷을 잡고 가로되 `나와 동침하자'' 요셉이 자기 옷을 그 손에 버리고 도망하여 나가매'),
(1463934,51,1,39,13,'그가 요셉이 그 옷을 자기 손에 버려두고 도망하여 나감을 보고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463935,51,1,39,14,'집 사람들을 불러서 그들에게 이르되 `보라, 주인이 히브리 사람을 우리에게 데려다가 우리를 희롱하게 하도다 그가 나를 겁간코자 내게로 들어오기로 내가 크게 소리 질렀더니'),
(1463936,51,1,39,15,'그가 나의 소리질러 부름을 듣고 그 옷을 내게 버려두고 도망하여 나갔느니라'' 하고'),
(1463937,51,1,39,16,'그 옷을 곁에 두고 자기 주인이 집으로 돌아오기를 기다려'),
(1463938,51,1,39,17,'이 말로 그에게 고하여 가로되 `당신이 우리에게 데려온 히브리 종이 나를 희롱코자 내게로 들어 왔기로'),
(1463939,51,1,39,18,'내가 소리질러 불렀더니 그가 그 옷을 내게 버려두고 도망하여 나갔나이다'''),
(1463940,51,1,39,19,'주인이 그 아내가 자기에게 고하기를 `당신의 종이 내게 이같이 행하였다'' 하는 말을 듣고 심히 노한지라'),
(1463941,51,1,39,20,'이에 요셉의 주인이 그를 잡아 옥에 넣으니 그 옥은 왕의 죄수를 가두는 곳이었더라 요셉이 옥에 갇혔으나'),
(1463942,51,1,39,21,'여호와께서 요셉과 함께 하시고 그에게 인자를 더하사 전옥에게 은혜를 받게 하시매'),
(1463943,51,1,39,22,'전옥이 옥중 죄수를 다 요셉의 손에 맡기므로 그 제반 사무를 요셉이 처리하고'),
(1463944,51,1,39,23,'전옥은 그의 손에 맡긴 것을 무엇이든지 돌아보지 아니하였으니 이는 여호와께서 요셉과 함께 하심이라 여호와께서 그의 범사에 형통케 하셨더라'),
(1463945,51,1,40,1,'그 후에 애굽 왕의 술 맡은 자와 떡굽는 자가 그 주 애굽 왕에게 범죄한지라'),
(1463946,51,1,40,2,'바로가 그 두 관원장 곧 술 맡은 관원장과 떡 굽는 관원장에게 노하여'),
(1463947,51,1,40,3,'그들을 시위대장의 집 안에 있는 옥에 가두니 곧 요셉의 갇힌 곳이라'),
(1463948,51,1,40,4,'시위대장이 요셉으로 그들에게 수종하게 하매 요셉이 그들을 섬겼더라 그들이 갇힌지 수일이라'),
(1463949,51,1,40,5,'옥에 갇힌 애굽 왕의 술 맡은 자와 떡 굽는 자 두 사람이 하룻밤에 꿈을 꾸니 각기 몽조가 다르더라'),
(1463950,51,1,40,6,'아침에 요셉이 들어가 보니 그들에게 근심 빛이 있는지라'),
(1463951,51,1,40,7,'요셉이 그 주인의 집에 자기와 함께 갇힌 바로의 관원장에게 묻되 당신들이 오늘 어찌하여 근심 빛이 있나이까 ?'),
(1463952,51,1,40,8,'그들이 그에게 이르되 `우리가 꿈을 꾸었으나 이를 해석할 자가 없도다'' 요셉이 그들에게 이르되 `해석은 하나님께 있지 아니하나이까 ? 청컨대 내게 고하소서'''),
(1463953,51,1,40,9,'술 맡은 관원장이 그 꿈을 요셉에게 말하여 가로되 `내가 꿈에 보니 내 앞에 포도나무가 있는데'),
(1463954,51,1,40,10,'그 나무에 세 가지가 있고 싹이 나서 꽃이 피고 포도송이가 익었고'),
(1463955,51,1,40,11,'내 손에 바로의 잔이 있기로 내가 포도를 따서 그 즙을 바로의 잔에 짜서 그 잔을 바로의 손에 드렸노라'''),
(1463956,51,1,40,12,'요셉이 그에게 이르되 `그 해석이 이러하니 세 가지는 사흘이라'),
(1463957,51,1,40,13,'지금부터 사흘 안에 바로가 당신의 머리를 들고 당신의 전직을 회복하리니 당신이 이왕에 술 맡은 자가 되었을 때에 하던것 같이 바로의 잔을 그 손에 받들게 되리이다'),
(1463958,51,1,40,14,'당신이 득의하거든 나를 생각하고 내게 은혜를 베풀어서 내 사정을 바로에게 고하여 이 집에서 나를 건져내소서'),
(1463959,51,1,40,15,'나는 히브리 땅에서 끌려온 자요 여기서도 옥에 갇힐 일은 행치 아니하였나이다'''),
(1463960,51,1,40,16,'떡 굽는 관원장이 그 해석이 길함을 보고 요셉에게 이르되 `나도 꿈에 보니 흰 떡 세 광주리가 내 머리에 있고'),
(1463961,51,1,40,17,'그 윗광주리에 바로를 위하여 만든 각종 구운 식물이 있는데 새들이 내 머리의 광주리에서 그것을 먹더라'''),
(1463962,51,1,40,18,'요셉이 대답하여 가로되 `그 해석은 이러하니 세 광주리는 사흘이라'),
(1463963,51,1,40,19,'지금부터 사흘 안에 바로가 당신의 머리를 끊고 당신을 나무에 달리니 새들이 당신의 고기를 뜯어 먹으리이다'' 하더니'),
(1463964,51,1,40,20,'제 삼일은 바로의 탄일이라 바로가 모든 신하를 위하여 잔치할때에 술 맡은 관원장과 떡 굽는 관원장으로 머리를 그 신하 중에 들게 하니라'),
(1463965,51,1,40,21,'바로의 술 맡은 관원장은 전직을 회복하매 그가 잔을 바로의 손에 받들어 드렸고'),
(1463966,51,1,40,22,'떡 굽는 관원장은 매여 달리니 요셉이 그들에게 해석함과 같이 되었으나'),
(1463967,51,1,40,23,'술 맡은 관원장이 요셉을 기억지 않고 잊었더라'),
(1463968,51,1,41,1,'만 이년 후에 바로가 꿈을 꾼즉 자기가 하숫가에 섰는데'),
(1463969,51,1,41,2,'보니 아름답고 살진 일곱 암소가 하수에서 올라와 갈밭에서 뜯어먹고'),
(1463970,51,1,41,3,'그 뒤에 또 흉악하고 파리한 다른 일곱 암소가 하수에서 올라와 그 소와 함께 하숫가에 섰더니'),
(1463971,51,1,41,4,'그 흉악하고 파리한 소가 그 아름답고 살진 일곱 소를 먹은지라 바로가 곧 깨었다가'),
(1463972,51,1,41,5,'다시 잠이 들어 꿈을 꾸니 한 줄기에 무성하고 충실한 일곱 이삭이 나오고'),
(1463973,51,1,41,6,'그 후에 또 세약하고 동풍에 마른 일곱 이삭이 나오더니'),
(1463974,51,1,41,7,'그 세약한 일곱 이삭이 무성하고 충실한 일곱 이삭을 삼킨지라 바로가 깬즉 꿈이라'),
(1463975,51,1,41,8,'아침에 그 마음이 번민하여 보내어 애굽의 술객과 박사를 모두 불러 그들에게 그 꿈을 고하였으나 그것을 바로에게 해석하는 자가 없었더라'),
(1463976,51,1,41,9,'술 맡은 관원장이 바로에게 고하여 가로되 `내가 오늘날 나의 허물을 추억하나이다'),
(1463977,51,1,41,10,'바로께서 종들에게 노하사 나와 떡 굽는 관원장을 시위대장의 집에 가두셨을 때에'),
(1463978,51,1,41,11,'나와 그가 하룻밤에 꿈을 꾼즉 각기 징조가 있는 꿈이라'),
(1463979,51,1,41,12,'그 곳에 시위대장의 종된 히브리 소년이 우리와 함께 있기로 우리가 그에게 고하매 그가 우리의 꿈을 풀되 그 꿈대로 각인에게 해석하더니'),
(1463980,51,1,41,13,'그 해석 한대로 되어 나는 복직하고 그는 매여 달렸나이다'''),
(1463981,51,1,41,14,'이에 바로가 보내어 요셉을 부르매 그들이 급히 그를 옥에서 낸지라 요셉이 곧 수염을 깎고 그 옷을 갈아 입고 바로에게 들어오니'),
(1463982,51,1,41,15,'바로가 요셉에게 이르되 `내가 한 꿈을 꾸었으나 그것을 해석하는 자가 없더니 들은즉 너는 꿈을 들으면 능히 푼다더라`'),
(1463983,51,1,41,16,'요셉이 바로에게 대답하여 가로되 `이는 내게 있는 것이 아니라 하나님이 바로에게 평안한 대답을 하시리이다'''),
(1463984,51,1,41,17,'바로가 요셉에게 이르되 `내가 꿈에 하숫가에 서서');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1463985,51,1,41,18,'보니 살지고 아름다운 일곱 암소가 하숫가에 올라와 갈밭에서 뜯어 먹고'),
(1463986,51,1,41,19,'그 뒤에 또 약하고 심히 흉악하고 파리한 일곱 암소가 올라오니 그같이 흉악한 것들은 애굽 땅에서 내가 아직 보지 못한 것이라'),
(1463987,51,1,41,20,'그 파리하고 흉악한 소가 처음의 일곱 살진 소를 먹었으며'),
(1463988,51,1,41,21,'먹었으나 먹은듯하지 아니하여 여전히 흉악하더라 내가 곧 깨었다가'),
(1463989,51,1,41,22,'다시 꿈에 보니 한 줄기에 무성하고 충실한 일곱 이삭이 나오고'),
(1463990,51,1,41,23,'그 후에 또 세약하고 동풍에 마른 일곱 이삭이 나더니'),
(1463991,51,1,41,24,'그 세약한 이삭이 좋은 일곱 이삭을 삼키더라 내가 그 꿈을 술객에게 말하였으나 그것을 내게 보이는 자가 없느니라'''),
(1463992,51,1,41,25,'요셉이 바로에게 고하되 `바로의 꿈은 하나이라 하나님이 그 하실 일을 바로에게 보이심이니이다'),
(1463993,51,1,41,26,'일곱 좋은 암소는 일곱해요, 일곱 좋은 이삭도 일곱해니, 그 꿈은 하나이라'),
(1463994,51,1,41,27,'그 후에 올라온 파리하고 흉악한 일곱 소는 칠년이요, 동풍에 말라 속이 빈 일곱 이삭도 일곱해 흉년이니'),
(1463995,51,1,41,28,'내가 바로에게 고하기를 하나님이 그 하실 일로 바로에게 보이신다 함이 이것이라'),
(1463996,51,1,41,29,'온 애굽 땅에 일곱해 큰 풍년이 있겠고'),
(1463997,51,1,41,30,'후에 일곱해 흉년이 들므로 애굽 땅에 있던 풍년을 다 잊어버리게 되고 이 땅이 기근으로 멸망되리니'),
(1463998,51,1,41,31,'후에 든 그 흉년이 너무 심하므로 이전 풍년을 이 땅에서 기억하지 못하게 되리이다'),
(1463999,51,1,41,32,'바로께서 꿈을 두번 겹쳐 꾸신 것은 하나님이 이 일을 정하셨음이라 속히 행하시리니'),
(1464000,51,1,41,33,'이제 바로께서는 명철하고 지혜있는 사람을 택하여 애굽 땅을 치리하게 하시고'),
(1464001,51,1,41,34,'바로께서는 또 이같이 행하사 국중에 여러 관리를 두어 그 일곱해 풍년에 애굽 땅의 오분의 일을 거두되'),
(1464002,51,1,41,35,'그 관리로 장차 올 풍년의 모든 곡물을 거두고 그 곡물을 바로의 손에 돌려 양식을 위하여 각 성에 적치하게 하소서'),
(1464003,51,1,41,36,'이와 같이 그 곡물을 이 땅에 저장하여 애굽 땅에 임할 일곱해 흉년을 예비하시면 땅이 이 흉년을 인하여 멸망치 아니하리이다'''),
(1464004,51,1,41,37,'바로와 그 모든 신하가 이 일을 좋게 여긴지라'),
(1464005,51,1,41,38,'바로가 그 신하들에게 이르되 `이와 같이 하나님의 신이 감동한 사람을 우리가 어찌 얻을 수 있으리요'' 하고'),
(1464006,51,1,41,39,'요셉에게 이르되 `하나님이 이 모든 것을 네게 보이셨으니 너와 같이 명철하고 지혜있는 자가 없도다'),
(1464007,51,1,41,40,'너는 내 집을 치리하라 내 백성이 다 네 명을 복종하리니 나는 너보다 높음이 보좌 뿐이니라'''),
(1464008,51,1,41,41,'바로가 또 요셉에게 이르되 `내가 너로 애굽 온 땅을 총리하게 하노라'' 하고'),
(1464009,51,1,41,42,'자기의 인장 반지를 빼어 요셉의 손에 끼우고 그에게 세마포 옷을 입히고 금사슬을 목에 걸고'),
(1464010,51,1,41,43,'자기에게 있는 버금 수레에 그를 태우매 무리가 그 앞에서 소리 지르기를 `엎드리라'' 하더라 바로가 그로 애굽 전국을 총리하게 하였더라'),
(1464011,51,1,41,44,'바로가 요셉에게 이르되 `나는 바로라 애굽 온 땅에서 네 허락없이는 수족을 놀릴 자가 없으리라'' 하고'),
(1464012,51,1,41,45,'그가 요셉의 이름을 사브낫바네아라 하고 또 온 제사장 보디베라의 딸 아스낫을 그에게 주어 아내를 삼게 하니라 요셉이 나가 애굽 온 땅을 순찰하니라'),
(1464013,51,1,41,46,'요셉이 애굽 왕 바로 앞에 설 때에 삼십세라 그가 바로 앞을 떠나 애굽 온 땅을 순찰하니'),
(1464014,51,1,41,47,'일곱해 풍년에 토지 소출이 심히 많은지라'),
(1464015,51,1,41,48,'요셉이 애굽 땅에 있는 그 칠년 곡물을 거두어 각 성에 저축하되 각 성주위의 밭의 곡물을 그 성중에 저장하매'),
(1464016,51,1,41,49,'저장한 곡식이 바다 모래같이 심히 많아 세기를 그쳤으니 그 수가 한이 없음이었더라'),
(1464017,51,1,41,50,'흉년이 들기 전에 요셉에게 두 아들을 낳되 곧 온 제사장 보디베라의 딸 아스낫이 그에게 낳은지라'),
(1464018,51,1,41,51,'요셉이 그 장자의 이름을 므낫세라 하였으니 `하나님이 나로 나의 모든 고난과 나의 아비의 온 집 일을 잊어버리게 하셨다'' 함이요'),
(1464019,51,1,41,52,'차자의 이름을 에브라임이라 하였으니 `하나님이 나로 나의 수고한 땅에서 창성하게 하셨다'' 함이었더라'),
(1464020,51,1,41,53,'애굽 땅에 일곱해 풍년이 그치고'),
(1464021,51,1,41,54,'요셉의 말과 같이 일곱해 흉년이 들기 시작하매 각국에는 기근이 있으나 애굽 온 땅에는 식물이 있더니'),
(1464022,51,1,41,55,'애굽 온 땅이 주리매 백성이 바로에게 부르짖어 양식을 구하는지라 바로가 애굽 모든 백성에게 이르되 `요셉에게 가서 그가 너희에게 이르는 대로 하라'' 하니라'),
(1464023,51,1,41,56,'온 지면에 기근이 있으매 요셉이 모든 창고를 열고 애굽 백성에게 팔새 애굽 땅에 기근이 심하며'),
(1464024,51,1,41,57,'각국 백성도 양식을 사려고 애굽으로 들어와 요셉에게 이르렀으니 기근이 온 세상에 심함이었더라'),
(1464025,51,1,42,1,'때에 야곱이 애굽에 곡식이 있음을 보고 아들들에게 이르되 `너희는 어찌하여 서로 관망만 하느냐 ?'''),
(1464026,51,1,42,2,'야곱이 또 이르되 `내가 들은즉 저 애굽에 곡식이 있다 하니 너희는 그리로 가서 거기서 우리를 위하여 사오라 그리하면 우리가 살고 죽지 아니하리라 !'' 하매'),
(1464027,51,1,42,3,'요셉의 형 십인이 애굽에서 곡식을 사려고 내려 갔으나'),
(1464028,51,1,42,4,'야곱이 요셉의 아우 베냐민을 그 형들과 함께 보내지 아니하였으니 이는 그의 말이 `재난이 그에게 미칠까 두렵다'' 함이었더라'),
(1464029,51,1,42,5,'이스라엘의 아들들이 양식 사러간 자 중에 있으니 가나안 땅에 기근이 있음이라'),
(1464030,51,1,42,6,'때에 요셉이 나라의 총리로서 그 땅 모든 백성에게 팔더니 요셉의 형들이 와서 그 앞에서 땅에 엎드려 절하매'),
(1464031,51,1,42,7,'요셉이 보고 형들인 줄 아나 모르는 체 하고 엄한 소리로 그들에 말하여 가로되 `너희가 어디서 왔느냐 ?'' 그들이 가로되 `곡물을 사려고 가나안에서 왔나이다'''),
(1464032,51,1,42,8,'요셉은 그 형들을 아나 그들은 요셉을 알지 못하더라'),
(1464033,51,1,42,9,'요셉이 그들에게 대하여 꾼 꿈을 생각하고 그들에게 이르되 `너희는 정탐들이라 이 나라의 틈을 엿보려고 왔느니라'''),
(1464034,51,1,42,10,'그들이 그에게 이르되 `내 주여, 아니니이다 종들은 곡물을 사러 왔나이다');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464035,51,1,42,11,'우리는 다 한 사람의 아들로서 독실한 자니 종들은 정탐이 아니니이다'''),
(1464036,51,1,42,12,'요셉이 그들에게 이르되 `아니라 너희가 이 나라의 틈을 엿보러 왔느니라'''),
(1464037,51,1,42,13,'그들이 가로되 `주의 종 우리들은 십 이형제로서 가나안 땅 한 사람의 아들들이라 말째 아들은 오늘 아버지와 함께 있고 또 하나는 없어졌나이다'''),
(1464038,51,1,42,14,'요셉이 그들에게 이르되 `내가 너희에게 이르기를 너희는 정탐들이라 한 말이 이것이니라'),
(1464039,51,1,42,15,'너희는 이같이 하여 너희 진실함을 증명할 것이라 바로의 생명으로 맹세하노니 너희 말째 아우가 여기 오지 아니하면 너희가 여기서 나가지 못하리라'),
(1464040,51,1,42,16,'너희 중 하나를 보내어 너희 아우를 데려오게 하고 너희는 갇히어 있으라 내가 너희의 말을 시험하여 너희 중에 진실이 있는지 보리라 바로의 생명으로 맹세하노니 그리하지 아니하면 너희는 과연 정탐이니라'' 하고'),
(1464041,51,1,42,17,'그들을 다 함께 삼일을 가두었더라'),
(1464042,51,1,42,18,'삼일만에 요셉이 그들에게 이르되 `나는 하나님을 경외하노니 너희는 이같이 하여 생명을 보전하라'),
(1464043,51,1,42,19,'너희가 독실한 자이면 너희 형제 중 한 사람만 그 옥에 갇히게 하고 너희는 곡식을 가지고 가서 너희 집들의 주림을 구하고'),
(1464044,51,1,42,20,'너희 말째 아우를 내게로 데리고 오라 그리하면 너희 말이 진실함이 되고 너희가 죽지 아니하리라'' 그들이 그대로 하니라'),
(1464045,51,1,42,21,'그들이 서로 말하되 `우리가 아우의 일로 인하여 범죄하였도다 그가 우리에게 애걸할때에 그 마음의 괴로움을 보고도 듣지 아니하였으므로 이 괴로움이 우리에게 임하도다'''),
(1464046,51,1,42,22,'르우벤이 그들에게 대답하여 가로되 `내가 너희더러 그 아이에게 득죄하지 말라고 하지 아니하였느냐 ? 그래도 너희가 듣지 아니하였느니라 그러므로 그의 피 값을 내게 되었도다'' 하니'),
(1464047,51,1,42,23,'피차간에 통변을 세웠으므로 그들은 요셉이 그 말을 알아 들은 줄을 알지 못하였더라'),
(1464048,51,1,42,24,'요셉이 그들을 떠나 가서 울고 다시 돌아와서 그들과 말하다가 그들 중에서 시므온을 취하여 그들의 목전에서 결박하고'),
(1464049,51,1,42,25,'명하여 곡물을 그 그릇에 채우게 하고 각인의 돈은 그 자루에 도로 넣게 하고 또 길 양식을 그들에게 주게 하니 그대로 행하였더라'),
(1464050,51,1,42,26,'그들이 곡식을 나귀에 싣고 그 곳을 떠났더니'),
(1464051,51,1,42,27,'한 사람이 객점에서 나귀에게 먹이를 주려고 자루를 풀고 본즉 그 돈이 자루 아구에 있는지라'),
(1464052,51,1,42,28,'그가 그 형제에게 고하되 `내 돈을 도로 넣었도다 보라, 자루 속에 있도다'' 이에 그들이 혼이 나서 떨며 서로 돌아보며 말하되 `하나님이 어찌하여 우리에게 이 일을 행하셨는고'' 하고'),
(1464053,51,1,42,29,'그들이 가나안 땅에 돌아와 그 아비 야곱에게 이르러 그 만난 일을 자세히 고하여 가로되'),
(1464054,51,1,42,30,'`그 땅의 주, 그 사람이 엄히 우리에게 말씀하고 우리를 그 나라 정탐자로 여기기로'),
(1464055,51,1,42,31,'우리가 그에게 이르되 우리는 독실한 자요 정탐이 아니니이다'),
(1464056,51,1,42,32,'우리는 한 아비의 아들 십 이 형제로서 하나는 없어지고 말째는 오늘 우리 아버지와 함께 가나안 땅에 있나이다 하였더니'),
(1464057,51,1,42,33,'그 땅의 주 그 사람이 우리에게 이르되 내가 이같이 하여 너희가 독실한 자임을 알리니 너희 형제 중 하나를 내게 두고 양식을 가지고 가서 너희 집들의 주림을 구하고'),
(1464058,51,1,42,34,'너희 말째 아우를 내게로 데려오라 그리하면 너희가 정탐이 아니요 독실한 자임을 내가 알고 너희 형제를 너희에게 돌리리니 너희가 이 나라에서 무역하리라 하더이다'' 하고'),
(1464059,51,1,42,35,'각기 자루를 쏟고 본즉 각인의 돈뭉치가 그 자루 속에 있는지라 그들과 그 아비가 돈 뭉치를 보고 다 두려워하더니'),
(1464060,51,1,42,36,'그 아비 야곱이 그들에게 이르되 `너희가 나로 나의 자식들을 잃게 하도다 요셉도 없어졌고 시므온도 없어졌거늘 베냐민을 또 빼앗아 가고자 하니 이는 다 나를 해롭게 함이로다'''),
(1464061,51,1,42,37,'르우벤이 아비에게 고하여 가로되 `내가 그를 아버지께로 데리고 오지 아니하거든 나의 두 아들을 죽이소서 그를 내 손에 맡기소서 내가 그를 아버지께로 데리고 돌아오리이다'''),
(1464062,51,1,42,38,'야곱이 가로되 `내 아들은 너희와 함께 내려가지 못하리니 그의 형은 죽고 그만 남았음이라 만일 너희 행하는 길에서 재난이 그 몸에 미치면 너희가 나의 흰 머리로 슬피 음부로 내려가게 함이 되리라'''),
(1464063,51,1,43,1,'그 땅에 기근이 심하고'),
(1464064,51,1,43,2,'그들이 애굽에서 가져온 곡식을 다 먹으매 그 아비가 그들에게 이르되 `다시 가서 우리를 위하여 양식을 조금 사라'''),
(1464065,51,1,43,3,'유다가 아비에게 말하여 가로되 `그 사람이 엄히 우리에게 경계하여 가로되 너희 아우가 너희와 함께 하지 아니하면 너희가 내 얼굴을 보지 못하리라 하였으니'),
(1464066,51,1,43,4,'아버지께서 우리 아우를 우리와 함께 보내시면 우리가 내려가서 아버지를 위하여 양식을 사려니와'),
(1464067,51,1,43,5,'아버지께서 만일 그를 보내지 않으시면 우리는 내려가지 아니하리니 그 사람이 우리에게 말하기를 너희 아우가 너희와 함께하지 아니하면 너희가 내 얼굴을 보지 못하리라 하였음이니이다'''),
(1464068,51,1,43,6,'이스라엘이 가로되 `너희가 어찌하여 너희에게 오히려 아우가 있다고 그 사람에게 고하여 나를 해롭게 하였느냐 ?'''),
(1464069,51,1,43,7,'그들이 가로되 `그 사람이 우리와 우리의 친족에 대하여 자세히 힐문하여 이르기를 너희 아버지가 그저 살았느냐 ? 너희에게 아우가 있느냐 ? 하기로 그 말을 조조이 그에게 대답한 것이라 그가 너희 아우를 데리고 내려오라 할 줄을 우리가 어찌 알았으리이까 ?'''),
(1464070,51,1,43,8,'유다가 아비 이스라엘에게 이르되 `저 아이를 나와 함께 보내시면 우리가 곧 가리니 그러면 우리와 아버지와 우리 어린 것들이 다 살고 죽지 아니하리이다'),
(1464071,51,1,43,9,'내가 그의 몸을 담보하오리니 아버지께서 내 손에 그를 물으소서 내가 만일 그를 아버지께 데려다가 아버지 앞에 두지 아니하면 내가 영원히 죄를 지리이다'),
(1464072,51,1,43,10,'우리가 지체하지 아니하였더면 벌써 두번 갔다 왔으리이다`'),
(1464073,51,1,43,11,'그들의 아비 이스라엘이 그들에게 이르되 `그러할진대 이렇게 하라 너희는 이 땅의 아름다운 소산을 그릇에 담아가지고 내려가서그 사람에게 예물을 삼을지니 곧 유향 조금과, 꿀 조금과, 향품과, 몰약과, 비자와, 파단행이니라'),
(1464074,51,1,43,12,'너희 손에 돈을 배나 가지고 너희 자루 아구에 도로 넣여 온 그 돈을 다시 가지고 가라 혹 차착이 있었을까 두렵도다'),
(1464075,51,1,43,13,'네 아우도 데리고 떠나 다시 그 사람에게로 가라'),
(1464076,51,1,43,14,'전능하신 하나님께서 그 사람 앞에서 너희에게 은혜를 베푸사 그 사람으로 너희 다른 형제와 베냐민을 돌려보내게 하시기를 원하노라 내가 자식을 잃게 되면 잃으리로다 !'''),
(1464077,51,1,43,15,'그 사람들이 그 예물을 취하고 갑절 돈을 자기들의 손에 가지고 베냐민을 데리고 애굽에 내려가서 요셉의 앞에 서니라'),
(1464078,51,1,43,16,'요셉이 베냐민이 그들과 함께 있음을 보고 청지기에게 이르되 `이 사람들을 집으로 인도해 들이고 짐승을 잡고 준비하라 이 사람들이 오정에 나와 함께 먹을 것이니라'''),
(1464079,51,1,43,17,'그 사람이 요셉의 명대로 하여 그 사람들을 요셉의 집으로 인도하니'),
(1464080,51,1,43,18,'그 사람들이 요셉의 집으로 인도되매 두려워하여 이르되 `전일 우리 자루에 넣여 있던 돈의 일로 우리가 끌려드도다 이는 우리를 잡아 노예를 삼고 우리의 나귀를 빼앗으려 함이로다'' 하고'),
(1464081,51,1,43,19,'그들이 요셉의 청지기에게 가까이 나아가 그 집 문앞에서 그에게 고하여'),
(1464082,51,1,43,20,'가로되 `내 주여, 우리가 전일에 내려와서 양식을 사가지고'),
(1464083,51,1,43,21,'객점에 이르러 자루를 풀어본즉 각인의 돈이 본수대로 자루 아구에 있기로 우리가 도로 가져 왔고'),
(1464084,51,1,43,22,'양식 살 다른 돈도 우리가 가지고 내려왔나이다 우리의 돈을 우리 자루에 넣은 자는 누구인지 우리가 알지 못하나이다''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464085,51,1,43,23,'그가 이르되 `너희는 안심하라 두려워 말라 ! 너희 하나님 너희 아버지의 하나님이 재물을 너희 자루에 넣어 너희에게 주신 것이니라 너희 돈은 내가 이미 받았느니라'' 하고 시므온을 그들에게로 이끌어 내고'),
(1464086,51,1,43,24,'그들을 요셉의 집으로 인도하고 물을 주어 발을 씻게 하며 그 나귀에게 먹이를 주더라'),
(1464087,51,1,43,25,'그들이 여기서 먹겠다 함을 들으므로 예물을 정돈하고 요셉이 오정에 오기를 기다리더니'),
(1464088,51,1,43,26,'요셉이 집으로 오매 그들이 그 집으로 들어가서 그 예물을 그에게 드리고 땅에 엎드리어 절하니'),
(1464089,51,1,43,27,'요셉이 그들의 안부를 물으며 가로되 `너희 아버지 너희가 말하던 그 노인이 안녕하시냐 ? 지금까지 생존하셨느냐 ?'''),
(1464090,51,1,43,28,'그들이 대답하되 `주의 종 우리 아비가 평안하고 지금까지 생존하였나이다'' 하고 머리 숙여 절하더라'),
(1464091,51,1,43,29,'요셉이 눈을 들어 자기 어머니의 아들 자기 동생 베냐민을 보고 가로되 너희가 내게 말하던 너희 작은 동생이 이냐 ? 그가 또 가로되 소자여 하나님이 네게 은혜 베푸시기를 원하노라'),
(1464092,51,1,43,30,'요셉이 아우를 인하여 마음이 타는듯 하므로 급히 울곳을 찾아 안방으로 들어가서 울고'),
(1464093,51,1,43,31,'얼굴을 씻고 나와서 그 정을 억제하고 `음식을 차리라'' 하매'),
(1464094,51,1,43,32,'그들이 요셉에게 따로 하고 그 형제들에게 따로 하고 배식하는 애굽 사람에게도 따로 하니 애굽 사람은 히브리 사람과 같이 먹으면 부정을 입음이었더라'),
(1464095,51,1,43,33,'그들이 요셉의 앞에 앉되 그 장유의 차서대로 앉히운바 되니 그들이 서로 이상히 여겼더라'),
(1464096,51,1,43,34,'요셉이 자기 식물로 그들에게 주되 베냐민에게는 다른 사람보다 오배나 주매 그들이 마시며 요셉과 함께 즐거워하였더라'),
(1464097,51,1,44,1,'요셉이 그 청지기에 명하여 가로되 `양식을 각인의 자루에 실을 수 있을 만큼 채우고 각인의 돈을 그 자루에 넣고'),
(1464098,51,1,44,2,'또 잔 내 곧 은잔을 그 소년의 자루 아구에 넣고 그 양식값 돈도 함께 넣으라'' 하매 그가 요셉의 명령대로 하고'),
(1464099,51,1,44,3,'개동시에 사람들과 그 나귀를 보내니라'),
(1464100,51,1,44,4,'그들이 성에서 나가 멀리 가기 전에 요셉이 청지기에게 이르되 `일어나 그 사람들의 뒤를 따라 미칠 때에 그들에게 이르기를 너희가 어찌하여 악으로 선을 갚느냐 ?'),
(1464101,51,1,44,5,'이것은 내 주인이 가지고 마시며 늘 점치는데 쓰는것이 아니냐 ? 너희가 이같이 하니 악하도다 하라'''),
(1464102,51,1,44,6,'청지기가 그들에게 따라 미쳐 그대로 말하니'),
(1464103,51,1,44,7,'그들이 그에게 대답하되 `우리 주여, 어찌 이렇게 말씀하시나이까 ? 이런 일은 종들이 결단코 아니하나이다'),
(1464104,51,1,44,8,'우리 자루에 있던 돈도 우리가 가나안 땅에서부터 당신에게로 가져왔거늘 우리가 어찌 당신 주인의 집에서 은,금을 도적질 하리이까 ?'),
(1464105,51,1,44,9,'종들 중 뉘게서 발견되든지 그는 죽을 것이요 우리는 우리 주의 종이 되리이다'''),
(1464106,51,1,44,10,'그가 가로되 `그러면 너희 말과 같이 하리라 그것이 뉘게서든지 발견되면 그는 우리 종이 될 것이요 너희에게는 책망이 없으리라'''),
(1464107,51,1,44,11,'그들이 각각 급히 자루를 땅에 내려 놓고 각기 푸니'),
(1464108,51,1,44,12,'그가 나이 많은 자에게서부터 시작하여 나이 적은 자에게까지 수탐하매 잔이 베냐민의 자루에서 발견된지라'),
(1464109,51,1,44,13,'그들이 옷을 찢고 각기 짐을 나귀에 싣고 성으로 돌아오니라'),
(1464110,51,1,44,14,'유다와 그 형제들이 요셉의 집에 이르니 요셉이 오히려 그 곳에 있는지라 그 앞 땅에 엎드리니'),
(1464111,51,1,44,15,'요셉이 그들에게 이르되 `너희가 어찌하여 이런 일을 행하였느냐 ? 나 같은 사람이 점 잘 칠 줄을 너희가 알지 못하느냐 ?'''),
(1464112,51,1,44,16,'유다가 가로되 `우리가 내 주께 무슨 말을 하오리이까 ? 무슨 설명을 하오리이까 ? 어떻게 우리의 정직을 나타내리이까 ? 하나님이 종들의 죄악을 적발하셨으니 우리와 이 잔이 발견된 자가 다 내 주의 종이 되겠나이다'''),
(1464113,51,1,44,17,'요셉이 가로되 `내가 결코 그리하지 아니하리라 잔이 그 손에서 발견된 자만 나의 종이 되고 너희는 평안히 너희 아버지께로 도로 올라갈 것이니라'''),
(1464114,51,1,44,18,'유다가 그에게 가까이 가서 가로되 `내 주여, 청컨대 종으로 내 주의 귀에 한 말씀을 고하게 하소서 주의 종에게 노하지 마옵소서 주는 바로와 같으심이니이다'),
(1464115,51,1,44,19,'이전에 내 주께서 종들에게 물으시되 너희는 아비가 있느냐 ? 아우가 있느냐 ? 하시기에'),
(1464116,51,1,44,20,'우리가 내 주께 고하되 우리에게 아비가 있으니 노인이요 또 그 노년에 얻은 아들 소년이 있으니 그의 형은 죽고 그 어미의 끼친것은 그 뿐이므로 그 아비가 그를 사랑하나이다 하였더니'),
(1464117,51,1,44,21,'주께서 또 종들에게 이르시되 그를 내게로 데리고 내려와서 나로 그를 목도하게 하라 하시기로'),
(1464118,51,1,44,22,'우리가 내 주께 말씀하기를 그 아이는 아비를 떠나지 못할지니 떠나면 아비가 죽겠나이다'),
(1464119,51,1,44,23,'주께서 또 주의 종들에게 말씀하시되 너희 말째 아우가 너희와 함께 내려오지 아니하면 너희가 다시 내 얼굴을 보지 못하리라 하시기로'),
(1464120,51,1,44,24,'우리가 주의 종 우리 아비에게로 도로 올라가서 내 주의 말씀을 그에게 고하였나이다'),
(1464121,51,1,44,25,'그 후에 우리 아비가 다시 가서 곡물을 조금 사오라 하시기로'),
(1464122,51,1,44,26,'우리가 이르되 우리가 내려갈 수 없나이다 우리 말째 아우가 함께 하면 내려가려니와 말째 아우가 우리와 함께함이 아니면 그 사람의 얼굴을 볼 수 없음이니이다'),
(1464123,51,1,44,27,'주의 종 우리 아비가 우리에게 이르되 너희도 알거니와 내 아내가 내게 두 아들을 낳았으나'),
(1464124,51,1,44,28,'하나는 내게서 나간고로 내가 말하기를 정녕 찢겨 죽었다하고 내가 지금까지 그를 보지 못하거늘'),
(1464125,51,1,44,29,'너희가 이도 내게서 취하여 가려한즉 만일 재해가 그 몸에 미치면 나의 흰 머리로 슬피 음부로 내려가게 하리라 하니'),
(1464126,51,1,44,30,'아비의 생명과 아이의 생명이 서로 결탁되었거늘 이제 내가 주의 종 우리 아비에게 돌아갈 때에 아이가 우리와 함께 하지 아니하면'),
(1464127,51,1,44,31,'아비가 아이의 없음을 보고 죽으리니 이같이 되면 종들이 주의 종 우리 아비의 흰 머리로 슬피 음부로 내려가게 함이니이다'),
(1464128,51,1,44,32,'주의 종이 내 아비에게 아이를 담보하기를 내가 이를 아버지께로 데리고 돌아오지 아니하면 영영히 아버지께 죄를 지리이다 하였사오니'),
(1464129,51,1,44,33,'청컨대 주의 종으로 아이를 대신하여 있어서 주의 종이 되게 하시고 아이는 형제와 함께 도로 올려 보내소서'),
(1464130,51,1,44,34,'내가 어찌 아이와 함께 하지 아니하고 내 아비에게로 올라 갈 수 있으리이까 ? 두렵건대 재해가 내 아비에게 미침을 보리이다'''),
(1464131,51,1,45,1,'요셉이 시종하는 자들 앞에서 그 정을 억제하지 못하여 소리질러 모든 사람을 자기에게서 물러가라 하고 그 형제에게 자기를 알리니 때에 그와 함께 한 자가 없었더라'),
(1464132,51,1,45,2,'요셉이 방성대곡하니 애굽 사람에게 들리며 바로의 궁중에 들리더라'),
(1464133,51,1,45,3,'요셉이 그 형들에게 이르되 `나는 요셉이라 내 아버지께서 아직 살아 계시니이까 ?'' 형들이 그 앞에서 놀라서 능히 대답하지 못하는지라'),
(1464134,51,1,45,4,'요셉이 형들에게 이르되 `내게로 가까이 오소서` 그들이 가까이 가니 가로되 `나는 당신들의 아우 요셉이니 당신들이 애굽에 판 자라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464135,51,1,45,5,'당신들이 나를 이곳에 팔았으므로 근심하지 마소서 한탄하지 마소서 ! 하나님이 생명을 구원하시려고 나를 당신들 앞서 보내셨나이다'),
(1464136,51,1,45,6,'이 땅에 이년 동안 흉년이 들었으나 아직 오년은 기경도 못하고 추수도 못할지라'),
(1464137,51,1,45,7,'하나님이 큰 구원으로 당신들의 생명을 보존하고 당신들의 후손을 세상에 두시려고 나를 당신들 앞서 보내셨나니'),
(1464138,51,1,45,8,'그런즉 나를 이리로 보낸 자는 당신들이 아니요 하나님이시라 하나님이 나로 바로의 아비를 삼으시며 그 온 집의 주를 삼으시며 애굽 온 땅의 치리자를 삼으셨나이다'),
(1464139,51,1,45,9,'당신들은 속히 아버지께로 올라가서 고하기를 아버지의 아들 요셉의 말에 하나님이 나를 애굽 전국의 주로 세우셨으니 내게로 지체말고 내려오사'),
(1464140,51,1,45,10,'아버지의 아들들과 아버지의 손자들과 아버지의 양과 소와 모든 소유가 고센 땅에 있어서 나와 가깝게 하소서'),
(1464141,51,1,45,11,'흉년이 아직 다섯해가 있으니 내가 거기서 아버지를 봉양하리이다 아버지와 아버지의 가속과 아버지의 모든 소속이 결핍할까 하나이다 하더라 하소서'),
(1464142,51,1,45,12,'당신들의 눈과 내 아우 베냐민의 눈이 보는바 당신들에게 이 말을 하는 것은 내 입이라'),
(1464143,51,1,45,13,'당신들은 나의 애굽에서의 영화와 당신들의 본 모든 것을 다 내 아버지께 고하고 속히 모시고 내려오소서'' 하며'),
(1464144,51,1,45,14,'자기 아우 베냐민의 목을 안고 우니 베냐민도 요셉의 목을 안고 우니라'),
(1464145,51,1,45,15,'요셉이 또 형들과 입맞추며 안고 우니 형들이 그제야 요셉과 말하니라'),
(1464146,51,1,45,16,'요셉의 형들이 왔다는 소문이 바로의 궁에 들리매 바로와 그 신복이 기뻐하고'),
(1464147,51,1,45,17,'바로는 요셉에게 이르되 `네 형들에게 명하기를 너희는 이렇게 하여 너희 양식을 싣고 가서 가나안 땅에 이르거든'),
(1464148,51,1,45,18,'너희 아비와 너희 가속을 이끌고 내게로 오라 내가 너희에게 애굽 땅 아름다운 것을 주리니 너희가 나라의 기름진 것을 먹으리라'),
(1464149,51,1,45,19,'이제 명을 받았으니 이렇게 하라 너희는 애굽 땅에서 수레를 가져다가 너희 자녀와 아내를 태우고 너희 아비를 데려오라'),
(1464150,51,1,45,20,'또 너희의 기구를 아끼지 말라 온 애굽 땅의 좋은 것이 너희 것임이니라 하라`'),
(1464151,51,1,45,21,'이스라엘의 아들들이 그대로 할새 요셉이 바로의 명대로 그들에게로 수레를 주고 길 양식을 주며'),
(1464152,51,1,45,22,'또 그들에게 다 각기 옷 한벌씩 주되 베냐민에게는 은 삼백과 옷 다섯벌을 주고'),
(1464153,51,1,45,23,'그가 또 이와 같이 그 아비에게 보내되 수나귀 열 필에 애굽의 아름다운 물품을 실리고 암나귀 열필에는 아비에게 길에서 공궤할 곡식과 떡과 양식을 실리고'),
(1464154,51,1,45,24,'이에 형들을 돌려 보내며 그들에게 이르되 `당신들은 노중에서 다투지 말라'' 하였더라'),
(1464155,51,1,45,25,'그들이 애굽에서 올라와 가나안 땅으로 들어가서 아비 야곱에게 이르러'),
(1464156,51,1,45,26,'고하여 가로되 `요셉이 지금까지 살아 있어 애굽 땅 총리가 되었더이다'' 야곱이 그들을 믿지 아니하므로 기색하더니'),
(1464157,51,1,45,27,'그들이 또 요셉이 자기들에게 부탁한 모든 말로 그 아비에게 고하매 그 아비 야곱이 요셉의 자기를 태우려고 보낸 수레를 보고야 기운이 소생한지라'),
(1464158,51,1,45,28,'이스라엘이 가로되 `족하도다 내 아들 요셉이 지금까지 살았으니 내가 죽기 전에 가서 그를 보리라'''),
(1464159,51,1,46,1,'이스라엘이 모든 소유를 이끌고 발행하여 브엘세바에 이르러 그 아비 이삭의 하나님께 희생을 드리니'),
(1464160,51,1,46,2,'밤에 하나님이 이상중에 이스라엘에게 나타나시고 불러 가라사대 야곱아 ! 야곱아 ! 하시는지라 야곱이 가로되 `내가 여기 있나이다` 하매'),
(1464161,51,1,46,3,'하나님이 가라사대 나는 하나님이라 네 아비의 하나님이니 애굽으로 내려가기를 두려워 말라 내가 거기서 너로 큰 민족을 이루게 하리라'),
(1464162,51,1,46,4,'내가 너와 함께 애굽으로 내려가겠고 정녕 너를 인도하여 다시 올라올 것이며 요셉이 그 손으로 네 눈을 감기리라 하셨더라'),
(1464163,51,1,46,5,'야곱이 브엘세바에서 발행할새 이스라엘의 아들들이 바로의 태우려고 보낸 수레에 자기들의 아비 야곱과 자기들의 처자들을 태웠고'),
(1464164,51,1,46,6,'그 생축과 가나안 땅에서 얻은 재물을 이끌었으며 야곱과 그 자손들이 다 함께 애굽으로 갔더라'),
(1464165,51,1,46,7,'이와 같이 야곱이 그 아들들과 손자들과, 딸들과, 손녀들 곧 그 모든 자손을 데리고 애굽으로 갔더라'),
(1464166,51,1,46,8,'애굽으로 내려간 이스라엘 가족의 이름이 이러하니 야곱과 그 아들들 곧 야곱의 맏아들 르우벤과'),
(1464167,51,1,46,9,'르우벤의 아들 하녹과, 발루와, 헤스론과, 갈미요'),
(1464168,51,1,46,10,'시므온의 아들 곧 여무엘과, 야민과, 오핫과, 야긴과, 스할과, 가나안 여인의 소생 사울이요'),
(1464169,51,1,46,11,'레위의 아들 곧 게르손과, 그핫과, 므라리요'),
(1464170,51,1,46,12,'유다의 아들 곧 엘과, 오난과, 셀라와, 베레스와, 세라니, 엘과 오난은 가나안 땅에서 죽었고 또 베레스의 아들 곧 헤스론과, 하물이요'),
(1464171,51,1,46,13,'잇사갈의 아들 곧 돌라와, 부와와, 욥과, 시므론이요'),
(1464172,51,1,46,14,'스불론의 아들 곧 세렛과, 엘론과, 얄르엘이니'),
(1464173,51,1,46,15,'이들은 레아가 밧단아람에서 야곱에게 낳은 자손들이라 그 딸 디나를 합하여 남자와 여자가 삼십 삼명이며'),
(1464174,51,1,46,16,'갓의 아들 곧 시뵨과, 학기와, 수니와, 에스본과, 에리와, 아로디와, 아렐리요'),
(1464175,51,1,46,17,'아셀의 아들 곧 임나와, 이스와와, 이스위와, 브리아와 그들의 누이 세라며 또 브리아의 아들 곧 헤벨과, 말기엘이니'),
(1464176,51,1,46,18,'이들은 라반이 그 딸 레아에게 준 실바가 야곱에게 낳은 자손들이라 합 십 륙명이요'),
(1464177,51,1,46,19,'야곱의 아내 라헬의 아들 곧 요셉과, 베냐민이요'),
(1464178,51,1,46,20,'애굽 땅에서 온 제사장 보디베라의 딸 아스낫이 요셉에게 낳은 므낫세와 에브라임이요'),
(1464179,51,1,46,21,'베냐민의 아들 곧 벨라와, 베겔과, 아스벨과, 게라와, 나아만과, 에히와, 로스와, 뭅빔과, 훔빔과, 아릇이니'),
(1464180,51,1,46,22,'이들은 라헬이 야곱에게 낳은 자손이라 합 십 사명이요'),
(1464181,51,1,46,23,'단의 아들 후심이요'),
(1464182,51,1,46,24,'납달리의 아들 곧 야스엘과, 구니와, 예셀과, 실렘이라'),
(1464183,51,1,46,25,'이들은 라반이 그 딸 라헬에게 준 빌하가 야곱에게 낳은 자손이니 합이 칠명이라'),
(1464184,51,1,46,26,'야곱과 함께 애굽에 이른 자는 야곱의 자부 외에 육십 륙명이니 이는 다 야곱의 몸에서 나온 자며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464185,51,1,46,27,'애굽에서 요셉에게 낳은 아들이 두명이니 야곱의 집 사람으로 애굽에 이른 자의 도합이 칠십명이었더라'),
(1464186,51,1,46,28,'야곱이 유다를 요셉에게 미리 보내어 자기를 고센으로 인도하게 하고 다 고센 땅에 이르니'),
(1464187,51,1,46,29,'요셉이 수레를 갖추고 고센으로 올라가서 아비 이스라엘을 맞으며 그에게 보이고 그 목을 어긋맞겨 안고 얼마동안 울매'),
(1464188,51,1,46,30,'이스라엘이 요셉에게 이르되 `네가 지금까지 살아 있고 내가 네 얼굴을 보았으니 지금 죽어도 가하도다'''),
(1464189,51,1,46,31,'요셉이 그 형들과 아비의 권속에게 이르되 내가 올라가서 바로에게 고하여 이르기를 `가나안 땅에 있던 내 형들과 내 아비의 권속이 내게로 왔는데'),
(1464190,51,1,46,32,'그들은 목자라 목축으로 업을 삼으므로 그 양과 소와 모든 소유를 이끌고 왔나이다 하리니'),
(1464191,51,1,46,33,'바로가 당신들을 불러서 너희의 업이 무엇이냐 ? 묻거든'),
(1464192,51,1,46,34,'당신들은 고하기를 주의 종들은 어렸을 때부터 지금까지 목축하는 자이온데 우리와 우리 선조가 다 그러하니이다 하소서 애굽 사람은 다 목축을 가증히 여기나니 당신들이 고센 땅에 거하게 되리이다`'),
(1464193,51,1,47,1,'요셉이 바로에게 가서 고하여 가로되 `나의 아비와 형들과 그들의 양과 소와 모든 소유가 가나안 땅에서 와서 고센 땅에 있나이다'' 하고'),
(1464194,51,1,47,2,'형들 중 오인을 택하여 바로에게 보이니'),
(1464195,51,1,47,3,'바로가 요셉의 형들에게 묻되 `너희 생업이 무엇이냐 ? 그들이 바로에게 대답하되 `종들은 목자이온데 우리와 선조가 다 그러하니이다'' 하고'),
(1464196,51,1,47,4,'그들이 또 바로에게 고하되 `가나안 땅에 기근이 심하여 종들의 떼를 칠 곳이 없기로 종들이 이곳에 우거하러 왔사오니 청컨대 종들로 고센 땅에 거하게 하소서'''),
(1464197,51,1,47,5,'바로가 요셉에게 일러 가로되 `네 아비와 형들이 네게 왔은즉'),
(1464198,51,1,47,6,'애굽 땅이 네 앞에 있으니 땅의 좋은 곳에 네 아비와 형들로 거하게 하되 고센 땅에 그들로 거하게 하고 그들 중에 능한 자가 있는줄 알거든 그들로 나의 짐승을 주관하게 하라'''),
(1464199,51,1,47,7,'요셉이 자기 아비 야곱을 인도하여 바로 앞에 서게 하니 야곱이 바로에게 축복하매'),
(1464200,51,1,47,8,'바로가 야곱에게 묻되 `네 연세가 얼마뇨 ?'''),
(1464201,51,1,47,9,'야곱이 바로에게 고하되 `내 나그네 길의 세월이 일백 삼십년이니이다 나의 연세가 얼마 못되니 우리 조상의 나그네 길의 세월에 미치지 못하나 험악한 세월을 보내었나이다'' 하고'),
(1464202,51,1,47,10,'야곱이 바로에게 축복하고 그 앞에서 나오니라'),
(1464203,51,1,47,11,'요셉이 바로의 명대로 그 아비와 형들에게 거할 곳을 주되 애굽의 좋은 땅 라암세스를 그들에게 주어 기업을 삼게 하고'),
(1464204,51,1,47,12,'또 그 아비와 형들과 아비의 온 집에 그 식구를 따라 식물을 주어 공궤하였더라'),
(1464205,51,1,47,13,'기근이 더욱 심하여 사방에 식물이 없고 애굽 땅과 가나안 땅이 기근으로 쇠약하니'),
(1464206,51,1,47,14,'요셉이 곡식을 팔아 애굽 땅과 가나안 땅에 있는 돈을 몰수히 거두고 그 돈을 바로의 궁으로 가져오니'),
(1464207,51,1,47,15,'애굽 땅과 가나안 땅에 돈이 진한지라 애굽 백성이 다 요셉에게 와서 가로되 `돈이 진하였사오니 우리에게 식물을 주소서 어찌 주 앞에서 죽으리이까 ?'''),
(1464208,51,1,47,16,'요셉이 가로되 `너희의 짐승을 내라 돈이 진하였은즉 내가 너희의 짐승과 바꾸어 주리라'''),
(1464209,51,1,47,17,'그들이 그 짐승을 요셉에게 끌어 오는지라 요셉이 그 말과 양떼와 소떼와 나귀를 받고 그들에게 식물을 주되 곧 그 모든 짐승과 바꾸어서 그 해 동안에 식물로 그들을 기르니라'),
(1464210,51,1,47,18,'그 해가 다하고 새 해가 되매 무리가 요셉에게 와서 그에게 고하되 우리가 주께 숨기지 아니하나이다 우리의 돈이 다하였고 우리의 짐승떼가 주께로 돌아갔사오니 주께 낼 것이 아무 것도 남지 아니하고 우리의 몸과 전지뿐이라'),
(1464211,51,1,47,19,'우리가 어찌 우리의 전지와 함께 주의 목전에 죽으리이까 ? 우리 몸과 우리 토지를 식물로 사소서 우리가 토지와 함께 바로의 종이 되리니 우리에게 종자를 주시면 우리가 살고 죽지 아니하고 전지도 황폐치 아니하리이다'''),
(1464212,51,1,47,20,'그러므로 요셉이 애굽 전지를 다 사서 바로에게 드리니 애굽 사람이 기근에 몰려서 각기 전지를 팖이라 땅이 바로의 소유가 되니라'),
(1464213,51,1,47,21,'요셉이 애굽 이 끝에서 저 끝까지의 백성을 성읍들에 옮겼으나'),
(1464214,51,1,47,22,'제사장의 전지는 사지 아니하였으니 제사장은 바로에게서 녹을 받음이라 바로의 주는 녹을 먹으므로 그 전지를 팔지 않음이었더라'),
(1464215,51,1,47,23,'요셉이 백성에게 이르되 `오늘날 내가 바로를 위하여 너희 몸과 너희 전지를 샀노라 여기 종자가 있으니 너희는 그 땅에 뿌리라'),
(1464216,51,1,47,24,'추수의 오분 일을 바로에게 상납하고 사분은 너희가 취하여 전지의 종자도 삼고 너희의 양식도 삼고 너희 집 사람과 어린 아이의 양식도 삼으라'''),
(1464217,51,1,47,25,'그들이 가로되 `주께서 우리를 살리셨사오니 우리가 주께 은혜를 입고 바로의 종이 되겠나이다'''),
(1464218,51,1,47,26,'요셉이 애굽 토지법을 세우매 그 오분 일이 바로에게 상납되나 제사장의 토지는 바로의 소유가 되지 아니하여 오늘까지 이르니라'),
(1464219,51,1,47,27,'이스라엘 족속이 애굽 고센 땅에 거하며 거기서 산업을 얻고 생육하며 번성하였더라'),
(1464220,51,1,47,28,'야곱이 애굽 땅에 십 칠년을 거하였으니 그의 수가 일백 사십 칠세라'),
(1464221,51,1,47,29,'이스라엘의 죽을 기한이 가까우매 그가 그 아들 요셉을 불러 그에게 이르되 `이제 내가 네게 은혜를 입었거든 청하노니 네 손을 내 환도뼈 아래 넣어서 나를 인애와 성심으로 대접하여 애굽에 장사하지 않기를 맹세하고'),
(1464222,51,1,47,30,'내가 조상들과 함께 눕거든 너는 나를 애굽에서 메어다가 선영에 장사하라'' 요셉이 가로되 `내가 아버지의 말씀대로 행하리이다 !'''),
(1464223,51,1,47,31,'야곱이 또 가로되 `내게 맹세하라'' 맹세하니 이스라엘이 침상 머리에서 경배하니라'),
(1464224,51,1,48,1,'이 일 후에 혹이 요셉에게 고하기를 `네 부친이 병들었다'' 하므로 그가 곧 두아들 므낫세와 에브라임과 함께 이르니'),
(1464225,51,1,48,2,'혹이 야곱에게 고하되 `네 아들 요셉이 네게 왔다'' 하매 이스라엘이 힘을 내어 침상에 앉아'),
(1464226,51,1,48,3,'요셉에게 이르되 `이전에 가나안 땅 루스에서 전능한 하나님이 내게 나타나 복을 허락하여'),
(1464227,51,1,48,4,'내게 이르시되 내가 너로 생육하게 하며 번성하게 하여 네게서 많은 백성이 나게 하고 내가 이 땅을 네 후손에게 주어 영원한 기업이 되게 하리라 하셨느니라'),
(1464228,51,1,48,5,'내가 애굽으로 와서 네게 이르기 전에 애굽에서 네게 낳은 두 아들 에브라임과 므낫세는 내 것이라 르우벤과 시므온처럼 내 것이 될 것이요'),
(1464229,51,1,48,6,'이들 후의 네 소생이 네 것이 될 것이며 그 산업은 그 형의 명의하에서 함께 하리라'),
(1464230,51,1,48,7,'내게 관하여는 내가 이전에 내가 밧단에서 올 때에 라헬이 나를 따르는 노중 가나안 땅에서 죽었는데 그곳은 에브랏까지 길이 오히려 격한 곳이라 내가 거기서 그를 에브랏 길에 장사 하였느니라'' (에브랏은 곧 베들레헴이라)'),
(1464231,51,1,48,8,'이스라엘이 요셉의 아들들을 보고 가로되 `이들은 누구냐 ?`'),
(1464232,51,1,48,9,'요셉이 그 아비에게 고하되 `이는 하나님이 여기서 내게 주신 아들들이니이다` 아비가 가로되 `그들을 이끌어 내 앞으로 나아오라 내가 그들에게 축복하리라'''),
(1464233,51,1,48,10,'이스라엘의 눈이 나이로 인하여 어두워서 보지 못하더라 요셉이 두 아들을 이끌어 아비 앞으로 나아가니 이스라엘이 그들에게 입맞추고 그들을 안고'),
(1464234,51,1,48,11,'요셉에게 이르되 `내가 네 얼굴을 보리라고는 뜻하지 못하였더니 하나님이 내게 네 소생까지 보이셨도다''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464235,51,1,48,12,'요셉이 아비 무릎 사이에서 두 아들을 물리고 땅에 엎드려 절하고'),
(1464236,51,1,48,13,'우수로는 에브라임을 이스라엘의 좌수를 향하게 하고 좌수로는 므낫세를 이스라엘의 우수를 향하게 하고 이끌어 그에게 가까이 나아가매'),
(1464237,51,1,48,14,'이스라엘이 우수를 차자 에브라임의 머리에 얹고 좌수를 펴서 므낫세의 머리에 얹으니 므낫세는 장자라도 팔을 어긋맞겨 얹었더라'),
(1464238,51,1,48,15,'그가 요셉을 위하여 축복하여 가로되 `내 조부 아브라함과 아버지 이삭의 섬기던 하나님, 나의 남으로부터 지금까지 나를 기르신 하나님,'),
(1464239,51,1,48,16,'나를 모든 환난에서 건지신 사자께서 이 아이에게 복을 주시오며 이들로 내 이름과 내 조부 아브라함과 아버지 이삭의 이름으로 칭하게 하시오며 이들로 세상에서 번식되게 하시기를 원하나이다'''),
(1464240,51,1,48,17,'요셉이 그 아비가 우수를 에브라임의 머리에 얹은 것을 보고 기뻐 아니하여 아비의 손을 들어 에브라임의 머리에서 므낫세의 머리로 옮기고자 하여'),
(1464241,51,1,48,18,'그 아비에게 이르되 `아버지여, 그리 마옵소서 이는 장자니 우수를 그 머리에 얹으소서'''),
(1464242,51,1,48,19,'아비가 허락지 아니하여 가로되 `나도 안다 내 아들아 ! 나도 안다 그도 한 족속이 되며 그도 크게 되려니와 그 아우가 그보다 큰 자가 되고 그 자손이 여러 민족을 이루리라` 하고'),
(1464243,51,1,48,20,'그 날에 그들에게 축복하여 가로되 `이스라엘 족속이 너로 축복하기를 하나님이 너로 에브라임 같고 므낫세같게 하시리라 하리라'' 하여 에브라임을 므낫세보다 앞세웠더라'),
(1464244,51,1,48,21,'이스라엘이 요셉에게 또 이르되 `나는 죽으나 하나님이 너희와 함께 계시사 너희를 인도하여 너희 조상의 땅으로 돌아가게 하시려니와'),
(1464245,51,1,48,22,'내가 네게 네 형제보다 일부분을 더 주었나니 이는 내가 내 칼과 활로 아모리 족속의 손에서 빼앗은 것이니라'''),
(1464246,51,1,49,1,'야곱이 그 아들들을 불러 이르되 너희는 모이라 너희의 후일에 당할 일을 내가 너희에게 이르리라'),
(1464247,51,1,49,2,'너희는 모여 들으라 야곱의 아들들아 너희 아비 이스라엘에게 들을지어다 !'),
(1464248,51,1,49,3,'르우벤아 너는 내 장자요 나의 능력이요 나의 기력의 시작이라 위광이 초등하고 권능이 탁월하도다마는'),
(1464249,51,1,49,4,'물의 끓음 같았은즉 너는 탁월치 못하리니 네가 아비의 침상에 올라 더럽혔음이로다 그가 내 침상에 올랐었도다'),
(1464250,51,1,49,5,'시므온과 레위는 형제요 그들의 칼은 잔해하는 기계로다'),
(1464251,51,1,49,6,'내 혼아, 그들의 모의에 상관하지 말지어다 내 영광아 그들의 집회에 참여하지 말지어다 그들이 그 분노대로 사람을 죽이고 그 혈기대로 소의 발목 힘줄을 끊었음이로다'),
(1464252,51,1,49,7,'그 노염이 혹독하니 저주를 받을 것이요 분기가 맹렬하니 저주를 받을 것이라 내가 그들을 야곱중에서 나누며 이스라엘 중에서 흩으리로다'),
(1464253,51,1,49,8,'유다야, 너는 네 형제의 찬송이 될지라 ! 네 손이 네 원수의 목을 잡을 것이요 네 아비의 아들들이 네 앞에 절하리로다'),
(1464254,51,1,49,9,'유다는 사자 새끼로다 내 아들아 ! 너는 움킨 것을 찢고 올라 갔도다 그의 엎드리고 웅크림이 수사자 같고 암사자 같으니 누가 그를 범할 수 있으랴'),
(1464255,51,1,49,10,'홀이 유다를 떠나지 아니하며 치리자의 지팡이가 그 발 사이에서 떠나지 아니하시기를 실로가 오시기까지 미치리니 그에게 모든 백성이 복종하리로다'),
(1464256,51,1,49,11,'그의 나귀를 포도나무에 매며 그 암나귀 새끼를 아름다운 포도나무에 맬 것이며 또 그 옷을 포도주에 빨며 그 복장을 포도즙에 빨리로다'),
(1464257,51,1,49,12,'그 눈은 포도주로 인하여 붉겠고 그 이는 우유로 인하여 희리로다'),
(1464258,51,1,49,13,'스불론은 해변에 거하리니 그곳은 배 매는 해변이라 그 지경이 시돈까지리로다'),
(1464259,51,1,49,14,'잇사갈은 양의 우리 사이에 꿇어 앉은 건장한 나귀로다'),
(1464260,51,1,49,15,'그는 쉴 곳을 보고 좋게 여기며 토지를 보고 아름답게 여기고 어깨를 내려 짐을 메고 압제 아래서 섬기리로다'),
(1464261,51,1,49,16,'단은 이스라엘의 한 지파같이 그 백성을 심판하리로다'),
(1464262,51,1,49,17,'단은 길의 뱀이요 첩경의 독사리로다 말굽을 물어서 그 탄 자로 뒤로 떨어지게 하리로다'),
(1464263,51,1,49,18,'여호와여 ! 나는 주의 구원을 기다리나이다'),
(1464264,51,1,49,19,'갓은 군대의 박격을 받으나 도리어 그 뒤를 추격하리로다'),
(1464265,51,1,49,20,'아셀에게서 나는 식물은 기름진 것이라 그가 왕의 진수를 공궤하리로다'),
(1464266,51,1,49,21,'납달리는 놓인 암사슴이라 아름다운 소리를 발하는도다'),
(1464267,51,1,49,22,'요셉은 무성한 가지 곧 샘 곁의 무성한 가지라 그 가지가 담을 넘었도다'),
(1464268,51,1,49,23,'활쏘는 자가 그를 학대하며 그를 쏘며 그를 군박하였으나'),
(1464269,51,1,49,24,'요셉의 활이 도리어 견강하며 그의 팔이 힘이 있으니 야곱의 전능자의 손을 힘입음이라 그로부터 이스라엘의 반석인 목자가 나도다'),
(1464270,51,1,49,25,'네 아비의 하나님께로 말미암나니 그가 너를 도우실 것이요 전능자로 말미암나니 그가 네게 복을 주실 것이라 위로 하늘의 복과 아래로 원천의 복과 젖먹이는 복과 태의 복이리로다'),
(1464271,51,1,49,26,'네 아비의 축복이 내 부여조의 축복보다 나아서 영원한 산이 한 없음같이 이 축복이 요셉의 머리로 돌아오며 그 형제중 뛰어난 자의 정수리로 돌아오리로다'),
(1464272,51,1,49,27,'베냐민은 물어 뜯는 이리라 아침에는 빼앗은 것을 먹고 저녁에는 움킨 것을 나누리로다'),
(1464273,51,1,49,28,'이들은 이스라엘의 십 이 지파라 이와 같이 그 아비가 그들에게 말하고 그들에게 축복하였으되 곧 그들 각인의 분량대로 축복하였더라'),
(1464274,51,1,49,29,'그가 그들에게 명하여 가로되 `내가 내 열조에게로 돌아가리니 나를 헷 사람 에브론 밭에 있는 굴에 우리 부여조와 함께 장사하라'),
(1464275,51,1,49,30,'이 굴은 가나안 땅 마므레 앞 막벨라 밭에 있는 것이라 아브라함이 헷 사람 에브론에게서 밭과 함께 사서 그 소유 매장지를 삼았으므로'),
(1464276,51,1,49,31,'아브라함과 그 아내 사라가 거기 장사되었고 이삭과 그 아내 리브가도 거기 장사되었으며 나도 레아를 그 곳에 장사하였노라'),
(1464277,51,1,49,32,'이 밭과 거기 있는 굴은 헷 사람에게서 산 것이니라'''),
(1464278,51,1,49,33,'야곱이 아들에게 명하기를 마치고 그 발을 침상에 거두고 기운이 진하여 그 열조에게로 돌아갔더라'),
(1464279,51,1,50,1,'요셉이 아비 얼굴에 구푸려 울며 입맞추고'),
(1464280,51,1,50,2,'그 수종 의사에게 명하여 향 재료로 아비의 몸에 넣게 하매 의사가 이스라엘에게 그대로 하되'),
(1464281,51,1,50,3,'사십일이 걸렸으니 향 재료를 넣는 데는 이 날수가 걸림이며 애굽 사람들은 칠십일 동안 그를 위하여 곡하였더라'),
(1464282,51,1,50,4,'곡하는 기한이 지나매 요셉이 바로의 궁에 말하여 가로되 `내가 너희에게 은혜를 입었으면 청컨대 바로의 귀에 고하기를'),
(1464283,51,1,50,5,'우리 아버지가 나로 맹세하게 하여 이르되 내가 죽거든 가나안 땅에 내가 파서 둔 묘실에 나를 장사하라 하였나니 나로 올라가서 내가 다시 오리이다 하라'' 하였더니'),
(1464284,51,1,50,6,'바로가 가로되 `그가 네게 시킨 맹세대로 올라가서 네 아비를 장사하라''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464285,51,1,50,7,'요셉이 자기 아비를 장사하러 올라가니 바로의 모든 신하와 바로 궁의 장로들과 애굽 땅의 모든 장로와'),
(1464286,51,1,50,8,'요셉의 온 집과 그 형제들과 그 아비의 집이 그와 함께 올라가고 그들의 어린 아이들과 양떼와 소떼만 고센 땅에 남겼으며'),
(1464287,51,1,50,9,'병거와 기병이 요셉을 따라 올라가니 그 떼가 심히 컸더라'),
(1464288,51,1,50,10,'그들이 요단강 건너편 아닷 타작마당에 이르러 거기서 크게 호곡하고 애통하며 요셉이 아비를 위하여 칠일 동안 애곡하였더니'),
(1464289,51,1,50,11,'그 땅 거민 가나안 백성들이 아닷 마당의 애통을 보고 가로되 `이는 애굽 사람의 큰 애통이라'' 하였으므로 그 땅 이름을 아벨미스라임이라 하였으니 곧 요단강 건너편이더라'),
(1464290,51,1,50,12,'야곱의 아들들이 부명을 좇아 행하여'),
(1464291,51,1,50,13,'그를 가나안 땅으로 메어다가 마므레 앞 막벨라 밭 굴에 장사하였으니 이는 아브라함이 헷 족속 에브론에게 밭과 함께 사서 소유 매장지를 삼은 곳이더라'),
(1464292,51,1,50,14,'요셉이 아비를 장사한 후에 자기 형제와 호상군과 함께 애굽으로 돌아왔더라'),
(1464293,51,1,50,15,'요셉의 형제들이 그 아비가 죽었음을 보고 말하되 `요셉이 혹시 우리를 미워하여 우리가 그에게 행한 모든 악을 다 갚지나 아니할까 ?'' 하고'),
(1464294,51,1,50,16,'요셉에게 말을 전하여 가로되 `당신의 아버지가 돌아가시기 전에 명하여 이르시기를'),
(1464295,51,1,50,17,'너희는 이같이 요셉에게 이르라 네 형들이 네게 악을 행하였을지라도 이제 바라건대 그 허물과 죄를 용서하라 하셨다 하라 하셨나니 당신의 아버지의 하나님의 종들의 죄를 이제 용서하소서` 하매 요셉의 그 말을 들을 때에 울었더라'),
(1464296,51,1,50,18,'그 형들이 또 친히 와서 요셉의 앞에 엎드려 가로되 `우리는 당신의 종이니이다'''),
(1464297,51,1,50,19,'요셉이 그들에게 이르되 `두려워 마소서 내가 하나님을 대신하리이까 ?'),
(1464298,51,1,50,20,'당신들은 나를 해하려 하였으나 하나님은 그것을 선으로 바꾸사 오늘과 같이 만민의 생명을 구원하게 하시려 하셨나니'),
(1464299,51,1,50,21,'당신들은 두려워 마소서 내가 당신들과 당신들의 자녀를 기르리이다'' 하고 그들을 간곡한 말로 위로하였더라'),
(1464300,51,1,50,22,'요셉이 그 아비의 가족과 함께 애굽에 거하여 일백 십세를 살며'),
(1464301,51,1,50,23,'에브라임의 자손 삼대를 보았으며 므낫세의 아들 마길의 아들들도 요셉의 슬하에서 양육되었더라'),
(1464302,51,1,50,24,'요셉이 그 형제에게 이르되 `나는 죽으나 하나님이 너희를 권고하시고 너희를 이 땅에서 인도하여 내사 아브라함과 이삭과 야곱에게 맹세하신 땅에 이르게 하시리라` 하고'),
(1464303,51,1,50,25,'요셉이 또 이스라엘 자손에게 맹세시켜 이르기를 `하나님이 정녕 너희를 권고하시리니 너희는 여기서 내 해골을 메고 올라가겠다 하라'' 하였더라'),
(1464304,51,1,50,26,'요셉이 일백십세에 죽으매 그들이 그의 몸에 향 재료를 넣고 애굽에서 입관하였더라'),
(1464305,51,2,1,1,'야곱과 함께 각기 권속을 데리고 애굽에 이른 이스라엘 아들들의 이름은 이러하니'),
(1464306,51,2,1,2,'르우벤과, 시므온과, 레위와, 유다와'),
(1464307,51,2,1,3,'잇사갈과, 스불론과, 베냐민과'),
(1464308,51,2,1,4,'단과, 납달리와, 갓과, 아셀이요'),
(1464309,51,2,1,5,'이미 애굽에 있는 요셉까지 야곱의 혈속이 모두 칠십인이었더라'),
(1464310,51,2,1,6,'요셉과 그의 모든 형제와 그 시대 사람은 다 죽었고'),
(1464311,51,2,1,7,'이스라엘 자손은 생육이 중다하고 번식하고 창성하고 심히 강대하여 온 땅에 가득하게 되었더라'),
(1464312,51,2,1,8,'그가 그 신민에게 이르되 `이 백성 이스라엘 자손이 우리보다 많고 강하도다'),
(1464313,51,2,1,9,'자, 우리가 그들에게 대하여 지혜롭게 하자 두렵건대 그들이 더 많게 되면 전쟁이 일어날 때에 우리 대적과 합하여 우리와 싸우고 이 땅에서 갈까 하노라'' 하고'),
(1464314,51,2,1,10,'감독들을 그들 위에 세우고 그들에게 무거운 짐을 지워 괴롭게 하여 그들로 바로를 위하여 국고성 비돔과 라암셋을 건축하게 하니라'),
(1464315,51,2,1,11,'그러나 학대를 받을수록 더욱 번식하고 창성하니 애굽 사람이 이스라엘 자손을 인하여 근심하여'),
(1464316,51,2,1,12,'이스라엘 자손의 역사를 엄하게 하여'),
(1464317,51,2,1,13,'고역으로 그들의 생활을 괴롭게 하니 곧 흙 이기기와 벽돌 굽기와 농사의 여러가지 일이라 그 시키는 역사가 다 엄하였더라'),
(1464318,51,2,1,14,'애굽 왕이 히브리 산파 십브라라 하는 자와 부아라 하는 자에게 일러'),
(1464319,51,2,1,15,'가로되 `너희는 히브리 여인을 위하여 조산할 때에 살펴서 남자여든 죽이고 여자여든 그는 살게 두라'''),
(1464320,51,2,1,16,'그러나 산파들이 하나님을 두려워하여 애굽 왕의 명을 어기고 남자를 살린지라'),
(1464321,51,2,1,17,'애굽 왕이 산파를 불러서 그들에게 이르되 `너희가 어찌 이같이 하여 남자를 살렸느냐 ?'''),
(1464322,51,2,1,18,'산파가 바로에게 대답하되 `히브리 여인은 애굽 여인과 같지 아니하고 건장하여 산파가 그들에게 이르기 전에 해산하였더이다'' 하매'),
(1464323,51,2,1,19,'하나님이 그 산파들에게 은혜를 베푸시니라 백성은 생육이 번성하고 심히 강대하며'),
(1464324,51,2,1,20,'산파는 하나님을 경외하였으므로 하나님이 그들의 집을 왕성케 하신지라'),
(1464325,51,2,1,21,'그러므로 바로가 그 모든 신민에게 명하여 가로되 `남자가 나거든 너희는 그를 하수에 던지고 여자여든 살리라'' 하였더라'),
(1464326,51,2,2,1,'레위 족속 중 한 사람이 가서 레위 여자에게 장가 들었더니'),
(1464327,51,2,2,2,'그 여자가 잉태하여 아들을 낳아 그 준수함을 보고 그를 석달을 숨겼더니'),
(1464328,51,2,2,3,'더 숨길 수 없이 되매 그를 위하여 갈 상자를 가져다가 역청과 나무 진을 칠하고 아이를 거기 담아 하숫가 갈대 사이에 두고'),
(1464329,51,2,2,4,'그 누이가 어떻게 되는 것을 알려고 멀리 섰더니'),
(1464330,51,2,2,5,'바로의 딸이 목욕하러 하수로 내려오고 시녀들은 하숫가에 거닐 때에 그가 갈대 사이에 상자를 보고 시녀를 보내어 가져다가'),
(1464331,51,2,2,6,'열고 그 아이를 보니 아이가 우는지라 그가 불쌍히 여겨 가로되 `이는 히브리 사람의 아이로다'''),
(1464332,51,2,2,7,'그 누이가 바로의 딸에게 이르되 `내가 가서 히브리 여인 중에서 유모를 불러다가 당신을 위하여 이 아이를 젖 먹이게 하리이까 ?'''),
(1464333,51,2,2,8,'바로의 딸이 그에게 이르되 `가라'' 그 소녀가 가서 아이의 어미를 불러오니'),
(1464334,51,2,2,9,'바로의 딸이 그에게 이르되 `이 아이를 데려다가 나를 위하여 젖을 먹이라 내가 그 삯을 주리라'' 여인이 아이를 데려다가 젖을 먹이더니');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464335,51,2,2,10,'그 아이가 자라매 바로의 딸에게로 데려가니 그의 아들이 되니라 그가 그 이름을 모세라 하여 가로되 `이는 내가 그를 물에서 건져내었음이라'' 하였더라'),
(1464336,51,2,2,11,'모세가 장성한 후에 한번은 자기 형제들에게 나가서 그 고역함을 보더니 어떤 애굽 사람이 어떤 히브리 사람 곧 자기 형제를 치는 것을 본지라'),
(1464337,51,2,2,12,'좌우로 살펴 사람이 없음을 보고 그 애굽 사람을 쳐죽여 모래에 감추니라'),
(1464338,51,2,2,13,'이튿날 다시 나가니 두 히브리 사람이 서로 싸우는지라 그 그른 자에게 이르되 `네가 어찌하여 동포를 치느냐 ?'' 하매'),
(1464339,51,2,2,14,'그가 가로되 `누가 너로 우리의 주재와 법관을 삼았느냐 ? 네가 애굽 사람을 죽임같이 나도 죽이려느냐 ?'' 모세가 두려워하여 가로되 `일이 탄로되었도다'''),
(1464340,51,2,2,15,'바로가 이 일을 듣고 모세를 죽이고자 하여 찾은지라 모세가 바로의 낯을 피하여 미디안 땅에 머물며 하루는 우물 곁에 앉았더라'),
(1464341,51,2,2,16,'미디안 제사장에게 일곱 딸이 있더니 그들이 와서 물을 길어 구유에 채우고 그 아비의 양무리에게 먹이려 하는데'),
(1464342,51,2,2,17,'목자들이 와서 그들을 쫓는지라 모세가 일어나 그들을 도와 그 양무리에게 먹이니라'),
(1464343,51,2,2,18,'그들이 그 아비 르우엘에게 이를 때에 아비가 가로되 `너희가 오늘은 어찌하여 이같이 속히 돌아오느냐 ?'''),
(1464344,51,2,2,19,'그들이 가로되 `한 애굽 사람이 우리를 목자들의 손에서 건져내고 우리를 위하여 물을 길어 양무리에게 먹였나이다'''),
(1464345,51,2,2,20,'아비가 딸들에게 이르되 `그 사람이 어디 있느냐 ? 너희가 어찌하여 그 사람을 버리고 왔느냐 ? 그를 청하여 음식으로 대접하라'' 하였더라'),
(1464346,51,2,2,21,'모세가 그와 동거하기를 기뻐하매 그가 그 딸 십보라를 모세에게 주었더니'),
(1464347,51,2,2,22,'그가 아들을 낳으매 모세가 그 이름을 게르솜이라 하여 가로되 `내가 타국에서 객이 되었음이라'' 하였더라'),
(1464348,51,2,2,23,'여러 해 후에 애굽 왕은 죽었고 이스라엘 자손은 고역으로 인하여 탄식하며 부르짖으니 그 고역으로 인하여 부르짖는 소리가 하나님께 상달한지라'),
(1464349,51,2,2,24,'하나님이 그 고통 소리를 들으시고 아브라함과 이삭과 야곱에게 세운 그 언약을 기억하사'),
(1464350,51,2,2,25,'이스라엘 자손을 권념하셨더라'),
(1464351,51,2,3,1,'모세가 그 장인 미디안 제사장 이드로의 양무리를 치더니 그 무리를 광야 서편으로 인도하여 하나님의 산 호렙에 이르매'),
(1464352,51,2,3,2,'여호와의 사자가 떨기나무 불꽃 가운데서 그에게 나타나시니라 그가 보니 떨기나무에 불이 붙었으나 사라지지 아니하는지라'),
(1464353,51,2,3,3,'이에 가로되 `내가 돌이켜 가서 이 큰 광경을 보리라 떨기나무가 어찌하여 타지 아니하는고 ?'' 하는 동시에'),
(1464354,51,2,3,4,'여호와께서 그가 보려고 돌이켜 오는 것을 보신지라 하나님이 떨기나무 가운데서 그를 불러 가라사대 모세야, 모세야 ! 하시매 그가 가로되 ''내가 여기 있나이다'''),
(1464355,51,2,3,5,'하나님이 가라사대 이리로 가까이 하지 말라 너의 선 곳은 거룩한 땅이니 네 발에서 신을 벗으라 !'),
(1464356,51,2,3,6,'또 이르시되 나는 네 조상의 하나님이니 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님이니라 모세가 하나님 뵈옵기를 두려워하여 얼굴을 가리우매'),
(1464357,51,2,3,7,'여호와께서 가라사대 내가 애굽에 있는 내 백성의 고통을 정녕히 보고 그들이 그 간역자로 인하여 부르짖음을 듣고 그 우고를 알고'),
(1464358,51,2,3,8,'내가 내려와서 그들을 애굽인의 손에서 건져내고 그들을 그 땅에서 인도하여 아름답고 광대한 땅 젖과 꿀이 흐르는 땅 곧 가나안 족속, 헷 족속, 아모리 족속, 브리스 족속, 히위 족속, 여부스 족속의 지방에 이르려 하노라'),
(1464359,51,2,3,9,'이제 이스라엘 자손의 부르짖음이 내게 달하고 애굽 사람이 그들을 괴롭게 하는 학대도 내가 보았으니'),
(1464360,51,2,3,10,'이제 내가 너를 바로에게 보내어 너로 내 백성 이스라엘 자손을 애굽에서 인도하여 내게 하리라'),
(1464361,51,2,3,11,'모세가 하나님께 고하되 `내가 누구관대 바로에게 가며 이스라엘 자손을 애굽에서 인도하여 내리이까 ?'''),
(1464362,51,2,3,12,'하나님이 가라사대 내가 정녕 너와 함께 있으리라 ! 네가 백성을 애굽에서 인도하여 낸 후에 너희가 이 산에서 하나님을 섬기리니 이것이 내가 너를 보낸 증거니라'),
(1464363,51,2,3,13,'모세가 하나님께 고하되 `내가 이스라엘 자손에게 가서 이르기를 너희 조상의 하나님이 나를 너희에게 보내셨다 하면 그들이 내게 묻기를 그의 이름이 무엇이냐 ? 하리니 내가 무엇이라고 그들에게 말하리이까 ?'''),
(1464364,51,2,3,14,'하나님이 모세에게 이르시되 나는 스스로 있는 자니라 ! 또 이르시되 너는 이스라엘 자손에게 이같이 이르기를 스스로 있는 자가 나를 너희에게 보내셨다 하라'),
(1464365,51,2,3,15,'하나님이 또 모세에게 이르시되 너는 이스라엘 자손에게 이같이 이르기를 나를 너희에게 보내신 이는 너희 조상의 하나님 곧 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님 여호와라 하라 이는 나의 영원한 이름이요 대대로 기억할 나의 표호니라 !'),
(1464366,51,2,3,16,'너는 가서 이스라엘 장로들을 모으고 그들에게 이르기를 여호와 너희 조상의 하나님 곧 아브라함과 이삭과 야곱의 하나님이 내게 나타나 이르시되 내가 실로 너희를 권고하여 너희가 애굽에서 당한 일을 보았노라'),
(1464367,51,2,3,17,'내가 말하였거니와 내가 너희를 애굽의 고난 중에서 인도하여 내어 젖과 꿀이 흐르는 땅 곧 가나안 족속, 헷 족속, 아모리 족속, 브리스 족속, 히위 족속, 여부스 족속의 땅으로 올라가게 하리라 하셨다 하면'),
(1464368,51,2,3,18,'그들이 네 말을 들으리니 너는 그들의 장로들과 함께 애굽 왕에게 이르기를 히브리 사람의 하나님 여호와께서 우리에게 임하셨은즉 우리가 우리 하나님 여호와께 희생을 드리려 하오니 사흘길쯤 광야로 가기를 허락하소서 하라'),
(1464369,51,2,3,19,'내가 아노니 강한 손으로 치기 전에는 애굽 왕이 너희의 가기를 허락지 아니하다가'),
(1464370,51,2,3,20,'내가 내 손을 들어 애굽 중에 여러가지 이적으로 그 나라를 친 후에야 그가 너희를 보내리라'),
(1464371,51,2,3,21,'내가 애굽 사람으로 이 백성에게 은혜를 입히게 할지라 너희가 갈 때에 빈 손으로 가지 아니하리니'),
(1464372,51,2,3,22,'여인마다 그 이웃 사람과 및 자기 집에 우거하는 자에게 은 패물과 금 패물과 의복을 구하여 너희 자녀를 꾸미라 너희가 애굽 사람의 물품을 취하리라'),
(1464373,51,2,4,1,'모세가 대답하여 가로되 `그러나 그들이 나를 믿지 아니하며 내 말을 듣지 아니하고 이르기를 여호와께서 네게 나타나지 아니하셨다 하리이다'''),
(1464374,51,2,4,2,'여호와께서 그에게 이르시되 네 손에 있는 것이 무엇이냐 ? 그가 가로되 `지팡이니이다'''),
(1464375,51,2,4,3,'여호와께서 가라사대 그것을 땅에 던지라 ! 곧 땅에 던지니 그것이 뱀이 된지라 모세가 뱀 앞에서 피하매'),
(1464376,51,2,4,4,'여호와께서 모세에게 이르시되 네 손을 내밀어 그 꼬리를 잡으라 ! 그가 손을 내밀어 잡으니 그 손에서 지팡이가 된지라'),
(1464377,51,2,4,5,'또 가라사대 이는 그들로 그 조상의 하나님 곧 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님 여호와가 네게 나타난 줄을 믿게 함이니라 하시고'),
(1464378,51,2,4,6,'여호와께서 또 가라사대 네 손을 품에 넣으라 ! 하시매 손을 품에 넣었다가 내어보니 그 손에 문둥병이 발하여 눈 같이 흰지라'),
(1464379,51,2,4,7,'가라사대 네 손을 다시 품에 넣으라 ! 하시매 그가 다시 손을 품에 넣었다가 내어보니 손이 여상하더라'),
(1464380,51,2,4,8,'여호와께서 가라사대 그들이 너를 믿지 아니하며 그 처음 이적의 표징을 받지 아니하여도 둘째 이적의 표징은 믿으리라'),
(1464381,51,2,4,9,'그들이 이 두 이적을 믿지 아니하며 네 말을 듣지 아니하거든 너는 하수를 조금 취하여다가 육지에 부으라 ! 네가 취한 하수가 육지에서 피가 되리라'),
(1464382,51,2,4,10,'모세가 여호와께 고하되 `주여, 나는 본래 말에 능치 못한 자라 주께서 주의 종에게 명하신 후에도 그러하니 나는 입이 뻣뻣하고 혀가 둔한 자니이다'''),
(1464383,51,2,4,11,'여호와께서 그에게 이르시되 누가 사람의 입을 지었느뇨 ! 누가 벙어리나 귀머거리나 눈 밝은 자나 소경이 되게 하였느뇨 ! 나 여호와가 아니뇨 ?'),
(1464384,51,2,4,12,'이제 가라 내가 네 입과 함께 있어서 할 말을 가르치리라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464385,51,2,4,13,'모세가 가로되 `주여, 보낼만한 자를 보내소서'''),
(1464386,51,2,4,14,'여호와께서 모세를 향하여 노를 발하시고 가라사대 레위 사람 네 형 아론이 있지 아니하뇨 ? 그의 말 잘함을 내가 아노라 그가 너를 만나러 나오나니 그가 너를 볼 때에 마음에 기뻐할 것이라'),
(1464387,51,2,4,15,'너는 그에게 말하고 그 입에 말을 주라 내가 네 입과 그의 입에 함께 있어서 너의 행할 일을 가르치리라'),
(1464388,51,2,4,16,'그가 너를 대신하여 백성에게 말할 것이니 그는 네 입을 대신할 것이요 너는 그에게 하나님 같이 되리라'),
(1464389,51,2,4,17,'너는 이 지팡이를 손에 잡고 이것으로 이적을 행할지니라'),
(1464390,51,2,4,18,'모세가 장인 이드로에게로 돌아가서 그에게 이르되 `내가 애굽에 있는 내 형제들에게로 돌아가서 그들이 생존하였는지 보려하오니 나로 가게 하소서'' 이드로가 그에게 ''평안히 가라'' 하니라'),
(1464391,51,2,4,19,'여호와께서 미디안에서 모세에게 이르시되 애굽으로 돌아가라 네 생명을 찾던 자가 다 죽었느니라'),
(1464392,51,2,4,20,'모세가 그 아내와 아들들을 나귀에 태우고 애굽으로 돌아가는데 하나님의 지팡이를 손에 잡았더라'),
(1464393,51,2,4,21,'여호와께서 모세에게 이르시되 네가 애굽으로 돌아가거든 내가 네 손에 준 이적을 바로 앞에서 다 행하라 그러나 내가 그의 마음을 강퍅케 한즉 그가 백성을 놓지 아니하리니'),
(1464394,51,2,4,22,'너는 바로에게 이르기를 여호와의 말씀에 이스라엘은 내 아들, 내 장자라 !'),
(1464395,51,2,4,23,'내가 네게 이르기를 내 아들을 놓아서 나를 섬기게 하라 하여도 네가 놓기를 거절하니 내가 네 아들 네 장자를 죽이리라 하셨다 하라 하시니라'),
(1464396,51,2,4,24,'여호와께서 길의 숙소에서 모세를 만나사 그를 죽이려 하시는지라'),
(1464397,51,2,4,25,'십보라가 차돌을 취하여 그 아들의 양피를 베어 모세의 발 앞에 던지며 가로되 `당신은 참으로 내게 피 남편이로다'' 하니'),
(1464398,51,2,4,26,'여호와께서 모세를 놓으시니라 그 때에 십보라가 피 남편이라 함은 할례를 인함이었더라'),
(1464399,51,2,4,27,'여호와께서 아론에게 이르시되 광야에 가서 모세를 맞으라 하시매 그가 가서 하나님의 산에서 모세를 만나 그에게 입맞추니'),
(1464400,51,2,4,28,'모세가 여호와께서 자기에게 부탁하여 보내신 모든 말씀과 여호와께서 자기에게 명하신 모든 이적을 아론에게 고하니라'),
(1464401,51,2,4,29,'모세와 아론이 가서 이스라엘 자손의 모든 장로를 모으고'),
(1464402,51,2,4,30,'아론이 여호와께서 모세에게 명하신 모든 말씀을 전하고 백성 앞에서 이적을 행하니'),
(1464403,51,2,4,31,'백성이 믿으며 여호와께서 이스라엘 자손을 돌아보시고 그 고난을 감찰하셨다 함을 듣고 머리 숙여 경배하였더라'),
(1464404,51,2,5,1,'그 후에 모세와 아론이 가서 바로에게 이르되 `이스라엘 하나님 여호와의 말씀에 내 백성을 보내라 그들이 광야에서 내 앞에 절기를 지킬 것이니라 하셨나이다'''),
(1464405,51,2,5,2,'바로가 가로되 `여호와가 누구관대 내가 그 말을 듣고 이스라엘을 보내겠느냐 ? 나는 여호와를 알지 못하니 이스라엘도 보내지 아니하리라'''),
(1464406,51,2,5,3,'그들이 가로되 `히브리인의 하나님이 우리에게 나타나셨은즉 우리가 사흘길쯤 광야에 가서 우리 하나님 여호와께 희생을 드리려 하오니 가기를 허락하소서 여호와께서 온역이나 칼로 우리를 치실까 두려워하나이다'''),
(1464407,51,2,5,4,'애굽왕이 그들에게 이르되 `모세와 아론아 ! 너희가 어찌하여 백성으로 역사를 쉬게 하느냐 ? 가서 너희의 역사나 하라'''),
(1464408,51,2,5,5,'또 가로되 `이제 나라에 이 백성이 많거늘 너희가 그들로 역사를 쉬게 하는도다'' 하고'),
(1464409,51,2,5,6,'바로가 당일에 백성의 간역자들과 패장들에게 명하여 가로되'),
(1464410,51,2,5,7,'`너희는 백성에게 다시는 벽돌 소용의 짚을 전과 같이 주지 말고 그들로 가서 스스로 줍게 하라'),
(1464411,51,2,5,8,'또 그들의 전에 만든 벽돌 수효대로 그들로 만들게 하고 감하지 말라 그들이 게으르므로 소리질러 이르기를 우리가 가서 우리 하나님께 희생을 드리자 하나니'),
(1464412,51,2,5,9,'그 사람들의 고역을 무겁게 함으로 수고롭게 하여 그들로 거짓말을 듣지 않게 하라'''),
(1464413,51,2,5,10,'간역자들과 패장들이 나아가 백성에게 일러 가로되 `바로의 말씀에 내가 너희에게 짚을 주지 아니하리니'),
(1464414,51,2,5,11,'너희는 짚을 얻을 곳으로 가서 주우라 너희 일은 조금도 감하지 아니하리라'' 하셨느니라'),
(1464415,51,2,5,12,'백성이 애굽 온 땅에 흩어져 곡초 그루터기를 거두어다가 짚을 대신하니'),
(1464416,51,2,5,13,'간역자들이 그들을 독촉하여 가로되 `너희는 짚이 있을 때와 같이 당일 일을 당일에 마치라'' 하며'),
(1464417,51,2,5,14,'바로의 간역자들이 자기들의 세운바 이스라엘 자손의 패장들을 때리며 가로되 ''너희가 어찌하여 어제와 오늘에 만드는 벽돌의 수효를 전과 같이 채우지 아니하였느냐 ?'' 하니라'),
(1464418,51,2,5,15,'이스라엘 자손의 패장들이 가서 바로에게 호소하여 가로되 `왕은 어찌하여 종들에게 이같이 하시나이까 ?'),
(1464419,51,2,5,16,'종들에게 짚을 주지 아니하고 그들이 우리더러 벽돌을 만들라 하나이다 종들이 매를 맞으오니 이는 왕의 백성의 허물이니이다'''),
(1464420,51,2,5,17,'바로가 가로되 `너희가 게으르다, 게으르다 그러므로 너희가 이르기를 우리가 가서 여호와께 희생을 드리자 하는도다'),
(1464421,51,2,5,18,'이제 가서 일하라 짚은 너희에게 주지 않을지라도 너희가 벽돌을 여수히 바칠지니라'''),
(1464422,51,2,5,19,'이스라엘 자손의 패장들이 너희의 매일 만드는 벽돌을 조금도 감하지 못하리라 함을 듣고 화가 몸에 미친 줄 알고'),
(1464423,51,2,5,20,'그들이 바로를 떠나 나올 때에 모세와 아론이 길에 선 것을 만나'),
(1464424,51,2,5,21,'그들에게 이르되 `너희가 우리로 바로의 눈과 그 신하의 눈에 미운 물건이 되게 하고 그들의 손에 칼을 주어 우리를 죽이게 하는도다 여호와는 너희를 감찰하시고 판단하시기를 원하노라'''),
(1464425,51,2,5,22,'모세가 여호와께 돌아와서 고하되 `주여, 어찌하여 이 백성으로 학대를 당케 하셨나이까 ? 어찌하여 나를 보내셨나이까 ?'),
(1464426,51,2,5,23,'내가 바로에게 와서 주의 이름으로 말함으로부터 그가 이 백성을 더 학대하며 주께서도 주의 백성을 구원치 아니하시나이다'''),
(1464427,51,2,6,1,'여호와께서 모세에게 이르시되 이제 내가 바로에게 하는 일을 네가 보리라 강한 손을 더하므로 바로가 그들을 보내리라 강한 손을 더하므로 바로가 그들을 그 땅에서 쫓아내리라'),
(1464428,51,2,6,2,'하나님이 모세에게 말씀하여 가라사대 나는 여호와로라 !'),
(1464429,51,2,6,3,'내가 아브라함과 이삭과 야곱에게 전능의 하나님으로 나타났으나 나의 이름을 여호와로는 그들에게 알리지 아니하였고'),
(1464430,51,2,6,4,'가나안 땅 곧 그들의 우거하는 땅을 주기로 그들과 언약하였더니'),
(1464431,51,2,6,5,'이제 애굽 사람이 종을 삼은 이스라엘 자손의 신음을 듣고 나의 언약을 기억하노라'),
(1464432,51,2,6,6,'그러므로 이스라엘 자손에게 말하기를 나는 여호와라 내가 애굽 사람의 무거운 짐 밑에서 너희를 빼어 내며 그 고역에서 너희를 건지며 편 팔과 큰 재앙으로 너희를 구속하여'),
(1464433,51,2,6,7,'너희로 내 백성을 삼고 나는 너희 하나님이 되리니 나는 애굽 사람의 무거운 짐 밑에서 너희를 빼어낸 너희 하나님 여호와인줄 너희가 알지라'),
(1464434,51,2,6,8,'내가 아브라함과 이삭과 야곱에게 주기로 맹세한 땅으로 너희를 인도하고 그 땅을 너희에게 주어 기업을 삼게 하리라 나는 여호와로라 하셨다 하라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464435,51,2,6,9,'모세가 이와 같이 이스라엘 자손에게 전하나 그들이 마음의 상함과 역사의 혹독함을 인하여 모세를 듣지 아니하였더라'),
(1464436,51,2,6,10,'여호와께서 모세에게 일러 가라사대'),
(1464437,51,2,6,11,'들어가서 애굽왕 바로에게 말하여 이스라엘 자손을 그 땅에서 내어 보내게 하라'),
(1464438,51,2,6,12,'모세가 여호와 앞에 고하여 가로되 `이스라엘 자손도 나를 듣지 아니하였거든 바로가 어찌 들으리이까 ? 나는 입이 둔한 자니이다'''),
(1464439,51,2,6,13,'여호와께서 모세와 아론에게 말씀하사 그들로 이스라엘 자손과 애굽 왕 바로에게 명을 전하고 이스라엘 자손을 애굽 땅에서 인도하여 내게 하시니라'),
(1464440,51,2,6,14,'그 조상을 따라 집의 어른은 이러하니라 이스라엘의 장자 르우벤의 아들 하녹과, 발루와, 헤스론과, 갈미니 이들은 르우벤의 족장이요'),
(1464441,51,2,6,15,'시므온의 아들 여무엘과, 야민과, 오핫과, 야긴과, 소할과, 가나안 여인의 소생 사울이니 이들은 시므온의 족장이요'),
(1464442,51,2,6,16,'레위의 아들들의 이름은 그 연치대로 이러하니 게르손과, 고핫과, 므라리요 레위의 수는 일백 삼십 칠세이었으며'),
(1464443,51,2,6,17,'게르손의 아들들은 그 가족대로 립니와, 시므이요'),
(1464444,51,2,6,18,'고핫의 아들들은 아므람과, 이스할과, 헤브론과, 웃시엘이요, 고핫의 수는 일백 삼십 삼세이었으며'),
(1464445,51,2,6,19,'므라리의 아들은 마흘리와, 무시니 이들은 그 연치대로 레위의 족장이요'),
(1464446,51,2,6,20,'아므람이 그 아비의 누이 요게벳을 아내로 취하였고 그가 아론과 모세를 낳았으며 아므람의 수는 일백 삼십 칠세이었으며'),
(1464447,51,2,6,21,'이스할의 아들은 고라와, 네벡과, 시그리요'),
(1464448,51,2,6,22,'웃시엘의 아들은 미사엘과, 엘사반과, 시드리요'),
(1464449,51,2,6,23,'아론이 암미나답의 딸 나손의 누이 엘리세바를 아내로 취하였고 그가 나답과, 아비후와, 엘르아살과, 이다말을 낳았으며'),
(1464450,51,2,6,24,'고라의 아들은 앗실과, 엘가나와, 아비아삽이니 이들은 고라 사람의 족장이요'),
(1464451,51,2,6,25,'아론의 아들 엘르아살이 부디엘의 딸 중에서 아내를 취하였고 그가 비느하스를 낳았으니 이들은 레위 사람의 조상을 따라 가족의 어른들이라'),
(1464452,51,2,6,26,'이스라엘 자손을 그 군대대로 애굽 땅에서 인도하라 하신 여호와의 명을 받은 자는 이 아론과 모세요'),
(1464453,51,2,6,27,'애굽 왕 바로에게 이스라엘 자손을 애굽에서 내어 보내라 말한 자도 이 모세와 아론이었더라'),
(1464454,51,2,6,28,'여호와께서 애굽 땅에서 모세에게 말씀하시던 날에'),
(1464455,51,2,6,29,'여호와께서 모세에게 일러 가라사대 나는 여호와라 내가 네게 이르는 바를 너는 애굽 왕 바로에게 다 고하라'),
(1464456,51,2,6,30,'모세가 여호와 앞에서 고하되 `나는 입이 둔한 자이오니 바로가 어찌 나를 들으리이까 ?'''),
(1464457,51,2,7,1,'여호와께서 모세에게 이르시되 볼지어다 ! 내가 너로 바로에게 신이 되게 하였은즉 네 형 아론은 네 대언자가 되리니'),
(1464458,51,2,7,2,'내가 네게 명한 바를 너는 네 형 아론에게 말하고 그는 바로에게 말하여 그로 이스라엘 자손을 그 땅에서 보내게 할지니라'),
(1464459,51,2,7,3,'내가 바로의 마음을 강퍅케 하고 나의 표징과 나의 이적을 애굽땅에 많이 행하리라마는'),
(1464460,51,2,7,4,'바로가 너희를 듣지 아니할터인즉 내가 내 손을 애굽에 더하여 여러 큰 재앙을 내리고 내 군대 내 백성 이스라엘 자손을 그 땅에서 인도하여 낼지라'),
(1464461,51,2,7,5,'내가 내 손을 애굽 위에 펴서 이스라엘 자손을 그 땅에서 인도하여 낼 때에야 애굽 사람이 나를 여호와인 줄 알리라 하시매'),
(1464462,51,2,7,6,'모세와 아론이 여호와께서 자기들에게 명하신대로 곧 그대로 행하였더라'),
(1464463,51,2,7,7,'그들이 바로에게 말할 때에 모세는 팔십세이었고 아론은 팔십 삼세이었더라'),
(1464464,51,2,7,8,'여호와께서 모세와 아론에게 일러 가라사대'),
(1464465,51,2,7,9,'바로가 너희에게 이르기를 너희는 이적을 보이라 하거든 너는 아론에게 명하기를 너의 지팡이를 가져 바로 앞에 던지라 하라 그것이 뱀이 되리라'),
(1464466,51,2,7,10,'모세와 아론이 바로에게 가서 여호와의 명하신대로 행하여 아론이 바로와 그 신하 앞에 지팡이를 던졌더니 뱀이 된지라'),
(1464467,51,2,7,11,'바로도 박사와 박수를 부르매 그 애굽 술객들도 그 술법으로 그와 같이 행하되'),
(1464468,51,2,7,12,'각 사람이 지팡이를 던지매 뱀이 되었으나 아론의 지팡이가 그들의 지팡이를 삼키니라'),
(1464469,51,2,7,13,'그러나 바로의 마음이 강퍅하여 그들을 듣지 아니하니 여호와의 말씀과 같더라'),
(1464470,51,2,7,14,'여호와께서 모세에게 이르시되 바로의 마음이 완강하여 백성 보내기를 거절하는도다'),
(1464471,51,2,7,15,'아침에 너는 바로에게로 가라 그가 물로 나오리니 너는 하숫가에 서서 그를 맞으며 그 뱀 되었던 지팡이를 손에 잡고'),
(1464472,51,2,7,16,'그에게 이르기를 히브리 사람의 하나님 여호와께서 나를 왕에게 보내어 이르시되 내 백성을 보내라 그들이 광야에서 나를 섬길 것이니라 하였으나 이제까지 네가 듣지 아니하도다'),
(1464473,51,2,7,17,'여호와가 이같이 이르노니 네가 이로 인하여 나를 여호와인줄 알리라 하셨느니라 볼지어다 ! 내가 내 손의 지팡이로 하수를 치면 그것이 피로 변하고'),
(1464474,51,2,7,18,'하수의 고기가 죽고 그 물에서는 악취가 나리니 애굽 사람들이 그 물 마시기를 싫어하리라 하라'),
(1464475,51,2,7,19,'여호와께서 또 모세에게 이르시되 아론에게 명하기를 네 지팡이를 잡고 네 팔을 애굽의 물들과 하수들과 운하와 못과 모든 호수위에 펴라 하라 그것들이 피가 되리니 애굽 온 땅에와, 나무 그릇에와, 돌 그릇에 모두 피가 있으리라'),
(1464476,51,2,7,20,'모세와 아론이 여호와의 명하신대로 행하여 바로와 그 신하의 목전에서 지팡이를 들어 하수를 치니 그 물이 다 피로 변하고'),
(1464477,51,2,7,21,'하수의 고기가 죽고 그 물에서는 악취가 나니 애굽 사람들이 하수물을 마시지 못하며 애굽 온 땅에는 피가 있으나'),
(1464478,51,2,7,22,'애굽 술객들도 자기 술법으로 그와 같이 행하므로 바로의 마음이 강퍅하여 그들을 듣지 아니하니 여호와의 말씀과 같더라'),
(1464479,51,2,7,23,'바로가 돌이켜 궁으로 들어가고 그 일에도 관념하지 아니하였고'),
(1464480,51,2,7,24,'애굽 사람들은 하수 물을 마실 수 없으므로 하숫가를 두루 파서 마실 물을 구하였더라'),
(1464481,51,2,7,25,'여호와께서 하수를 치신 후 칠일이 지나니라'),
(1464482,51,2,8,1,'여호와께서 모세에게 이르시되 너는 바로에게 가서 그에게 이르기를 여호와의 말씀에 내 백성을 보내라 그들이 나를 섬길 것이니라'),
(1464483,51,2,8,2,'네가 만일 보내기를 거절하면 내가 개구리로 너의 온 지경을 칠지라'),
(1464484,51,2,8,3,'개구리가 하수에서 무수히 생기고 올라와서 네 궁에와, 네 침실에와, 네 침상 위에와, 네 신하의 집에와, 네 백성에게와, 네 화덕에와, 네 떡반죽 그릇에 들어갈지며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464485,51,2,8,4,'개구리가 네게와, 네 백성에게와, 네 모든 신하에게 오르리라 하셨다 하라'),
(1464486,51,2,8,5,'여호와께서 모세에게 이르시되 아론에게 명하기를 네 지팡이를 잡고 네 팔을 강들과 운하들과 못 위에 펴서 개구리로 애굽 땅에올라오게 하라 할지니라'),
(1464487,51,2,8,6,'아론이 팔을 애굽 물들 위에 펴매 개구리가 올라와서 애굽 땅에 덮이니'),
(1464488,51,2,8,7,'술객들도 자기 술법대로 이와 같이 하여 개구리로 애굽 땅에 올라오게 하였더라'),
(1464489,51,2,8,8,'바로가 모세와 아론을 불러 이르되 `여호와께 구하여 개구리를 나와 내 백성에게서 떠나게 하라 내가 이 백성을 보내리니 그들이 여호와께 희생을 드릴 것이니라'''),
(1464490,51,2,8,9,'모세가 바로에게 이르되 `내가 왕과 왕의 신하와 왕의 백성을 위하여 어느 때에 구하여 이 개구리를 왕과 왕궁에서 끊어서 하수에만 있게 하오리이까 ? 내게 보이소서'''),
(1464491,51,2,8,10,'그가 가로되 `내일이니라'' 모세가 가로되 `왕의 말씀대로 하여 왕으로 우리 하나님 여호와와 같은 이가 없는 줄을 알게 하리니'),
(1464492,51,2,8,11,'개구리가 왕과, 왕궁과, 왕의 신하와, 왕의 백성을 떠나서 하수에만 있으리이다'' 하고'),
(1464493,51,2,8,12,'모세와 아론이 바로를 떠나 나가서 바로에게 내리신 개구리에 대하여 모세가 여호와께 간구하매'),
(1464494,51,2,8,13,'여호와께서 모세의 말대로 하시니 개구리가 집에서,마당에서,밭에서 나와서 죽은지라'),
(1464495,51,2,8,14,'사람들이 모아 무더기로 쌓으니 땅에서 악취가 나더라'),
(1464496,51,2,8,15,'그러나 바로가 숨을 통할 수 있음을 볼 때에 그 마음을 완강케 하여 그들을 듣지 아니하였으니 여호와의 말씀과 같더라'),
(1464497,51,2,8,16,'여호와께서 모세에게 이르시되 아론에게 명하기를 네 지팡이를 들어 땅의 티끌을 치라 하라 그것이 애굽 온 땅에서 이가 되리라'),
(1464498,51,2,8,17,'그들이 그대로 행할쌔 아론이 지팡이를 잡고 손을 들어 땅의 티끌을 치매 애굽 온 땅의 티끌이 다 이가 되어 사람과 생축에게 오르니'),
(1464499,51,2,8,18,'술객들이 자기 술법으로 이같이 행하여 이를 내려 하였으나 못하였고 이는 사람과 생축에게 있은지라'),
(1464500,51,2,8,19,'술객이 바로에게 고하되 `이는 하나님의 권능이니이다 !'' 하나 바로의 마음이 강퍅케 되어 그들을 듣지 아니하였으니 여호와의 말씀과 같더라'),
(1464501,51,2,8,20,'여호와께서 모세에게 이르시되 아침에 일찌기 일어나 바로 앞에 서라 그가 물로 나오리니 그에게 이르기를 여호와의 말씀에 내 백성을 보내라 그들이 나를 섬길 것이니라'),
(1464502,51,2,8,21,'네가 만일 내 백성을 보내지 아니하면 내가 너와 네 신하와 네 백성을 보내지 아니하면 내가 너와 네 신하와 네 백성과 네 집들에 파리떼를 보내리니 애굽 사람의 집집에 파리 떼가 가득할 것이며 그들의 거하는 땅에도 그러하리라'),
(1464503,51,2,8,22,'그 날에 내가 내 백성의 거하는 고센 땅을 구별하여 그 곳에는 파리떼가 없게 하리니 이로 말미암아 나는 세상 중의 여호와인 줄을 네가 알게 될 것이라'),
(1464504,51,2,8,23,'내가 내 백성과 네 백성 사이에 구별을 두리니 내일 이 표징이 있으리라 하셨다 하라 하시고'),
(1464505,51,2,8,24,'여호와께서 그와 같이 하시니 무수한 파리떼가 바로의 궁에와, 그 신하의 집에와, 애굽 전국에 이르니 파리떼로 인하여 땅이 해를 받더라'),
(1464506,51,2,8,25,'바로가 모세와 아론을 불러 이르되 `너희는 가서 이 땅에서 너희 하나님께 희생을 드리라'''),
(1464507,51,2,8,26,'모세가 가로되 `그리함은 불가하니이다 우리가 우리 하나님 여호와께 희생을 드리는 것은 애굽 사람의 미워하는 바이온즉 우리가 만일 애굽 사람의 목전에서 희생을 드리면 그들이 그것을 미워하여 우리를 돌로 치지 아니하리이까 ?'),
(1464508,51,2,8,27,'우리가 사흘길쯤 광야로 들어가서 우리 하나님 여호와께 희생을 드리되 우리에게 명하시는대로 하려하나이다'''),
(1464509,51,2,8,28,'바로가 가로되 `내가 너희를 보내리니 너희가 너희 하나님 여호와께 광야에서 희생을 드릴 것이나 너무 멀리는 가지 말라 그런즉 너희는 나를 위하여 기도하라'''),
(1464510,51,2,8,29,'모세가 가로되 `내가 왕을 떠나 가서 여호와께 기도하리니 내일이면 파리떼가 바로와 바로의 신하와 바로의 백성을 떠나려니와 바로는 이 백성을 보내어 여호와께 희생을 드리는 일에 다시 거짓을 행치 마소서'' 하고'),
(1464511,51,2,8,30,'모세가 바로를 떠나 나와서 여호와께 기도하니'),
(1464512,51,2,8,31,'여호와께서 모세의 말대로 하사 파리를 바로와 그 신하와 그 백성에게 몰수히 떠나게 하시니라'),
(1464513,51,2,8,32,'그러나 바로가 이 때에도 마음을 완강케 하여 백성을 보내지 아니하였더라'),
(1464514,51,2,9,1,'여호와께서 모세에게 이르시되 바로에게 들어가서 그에게 이르라 히브리 사람의 하나님 여호와께서 말씀하시기를 내 백성을 보내라 그들이 나를 섬길 것이니라'),
(1464515,51,2,9,2,'네가 만일 그들 보내기를 거절하고 억지로 잡아 두면'),
(1464516,51,2,9,3,'여호와의 손이 들에 있는 네 생축 곧 말과 나귀와 약대와 우양에게 더하리니 심한 악질이 있을 것이며'),
(1464517,51,2,9,4,'여호와가 이스라엘의 생축과 애굽의 생축을 구별하리니 이스라엘 자손에 속한 것은 하나도 죽지 아니하리라 하셨다 하라 하시고'),
(1464518,51,2,9,5,'여호와께서 기한을 정하여 가라사대 여호와가 내일 이 땅에서 이 일을 행하리라 하시더니'),
(1464519,51,2,9,6,'이튿날에 여호와께서 이 일을 행하시니 애굽의 모든 생축은 죽었으나 이스라엘 자손의 생축은 하나도 죽지 아니한지라'),
(1464520,51,2,9,7,'바로가 보내어 본즉 이스라엘의 생축은 하나도 죽지 아니하였더라 그러나 바로의 마음이 완강하여 백성을 보내지 아니하니라'),
(1464521,51,2,9,8,'여호와께서 모세와 아론에게 이르시되 너희는 풀무의 재 두 움큼을 가지고 모세가 바로의 목전에서 하늘을 향하여 날리라'),
(1464522,51,2,9,9,'그 재가 애굽 온 땅의 티끌이 되어 애굽 온 땅의 사람과 짐승에게 붙어서 독종이 발하리라'),
(1464523,51,2,9,10,'그들이 풀무의 재를 가지고 바로 앞에 서서 모세가 하늘을 향하여 날리니 사람과 짐승에게 붙어 독종이 발하고'),
(1464524,51,2,9,11,'술객도 독종으로 인하여 모세 앞에 서지 못하니 독종이 술객들로 부터 애굽 모든 사람에게 발하였음이라'),
(1464525,51,2,9,12,'그러나 여호와께서 바로의 마음을 강퍅케 하셨으므로 그들을 듣지 아니하였으니 여호와께서 모세에게 말씀하심과 같더라'),
(1464526,51,2,9,13,'여호와께서 모세에게 이르시되 아침에 일찌기 일어나 바로 앞에 서서 그에게 이르기를 히브리 사람의 하나님 여호와의 말씀에 내 백성을 보내라 그들이 나를 섬길 것이니라'),
(1464527,51,2,9,14,'내가 이번에는 모든 재앙을 네 마음과 네 신하와 네 백성에게 내려 너로 온 천하에 나와 같은 자가 없음을 알게 하리라'),
(1464528,51,2,9,15,'내가 손을 펴서 온역으로 너와 네 백성을 쳤더면 네가 세상에서 끊어졌을 것이나'),
(1464529,51,2,9,16,'네가 너를 세웠음은 나의 능력을 네게 보이고 내 이름이 온 천하에 전파되게 하려 하였음이니라'),
(1464530,51,2,9,17,'네가 여전히 내 백성 앞에 자고하고 그들을 보내지 아니하느냐 ?'),
(1464531,51,2,9,18,'내일 이맘때면 내가 중한 우박을 내리리니 애굽 개국 이래로 그 같은 것이 있지 않던 것이리라'),
(1464532,51,2,9,19,'이제 보내어 네 생축과 네 들에 있는 것을 다 모으라 사람이나 짐승이나 무릇 들에 있어서 집에 돌아오지 않은 자에게는 우박이그 위에 내리리니 그것들이 죽으리라 하셨다 하라 하시니라'),
(1464533,51,2,9,20,'바로의 신하 중에 여호와의 말씀을 두려워하는 자들은 그 종들과 생축을 집으로 피하여 들였으나'),
(1464534,51,2,9,21,'여호와의 말씀을 마음에 두지 아니하는 자는 그 종들과 생축을 들에 그대로 두었더라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464535,51,2,9,22,'여호와께서 모세에게 이르시되 너는 하늘을 향하여 손을 들어 애굽 전국에 우박이 애굽땅의 사람과 짐승과 밭의 모든 채소에 내리게 하라'),
(1464536,51,2,9,23,'모세가 하늘을 향하여 지팡이를 들매 여호와께서 뇌성과 우박을 보내시고 불을 내려 땅에 달리게 하시니라 여호와께서 우박을 애굽 땅에 내리시매'),
(1464537,51,2,9,24,'우박의 내림과 불덩이가 우박에 섞여 내림이 심히 맹렬하니 애굽 전국에 그 개국 이래로 그 같은 것이 없던 것이라'),
(1464538,51,2,9,25,'우박이 애굽 온 땅에서 사람과 짐승을 무론하고 무릇 밭에 있는 것을 쳤으며 우박이 또 밭의 모든 채소를 치고 들의 모든 나무를 꺽었으되'),
(1464539,51,2,9,26,'이스라엘 자손의 거한 고센 땅에는 우박이 없었더라'),
(1464540,51,2,9,27,'바로가 사람을 보내어 모세와 아론을 불러 그들에게 이르되 `이번은 내가 범죄하였노라 여호와는 의로우시고 나와 나의 백성은 악하도다'),
(1464541,51,2,9,28,'여호와께 구하여 이 뇌성과 우박을 그만 그치게 하라 내가 너희를 보내리니 너희가 다시는 머물지 아니하리라'''),
(1464542,51,2,9,29,'모세가 그에게 이르되 `내가 성에서 나가자 곧 내 손을 여호와를 향하여 펴리니 그리하면 뇌성이 그치고 우박이 다시 있지 않을지라 세상이 여호와께 속한 줄을 왕이 알리이다'),
(1464543,51,2,9,30,'그러나 왕과 왕의 신하들이 여호와 하나님을 아직도 두려워 아니할 줄을 내가 아나이다'''),
(1464544,51,2,9,31,'때에 보리는 이삭이 나왔고 삼은 꽃이 피었으므로 삼과 보리가 상하였으나'),
(1464545,51,2,9,32,'그러나 밀과 나맥은 자라지 아니한고로 상하지 아니하였더라'),
(1464546,51,2,9,33,'모세가 바로를 떠나 성에서 나가서 여호와를 향하여 손을 펴매 뇌성과 우박이 그치고 비가 땅에 내리지 아니하니라'),
(1464547,51,2,9,34,'바로가 비와 우박과 뇌성의 그친 것을 볼 때에 다시 범죄하여 마음을 완강케 하니 그와 그 신하가 일반이라'),
(1464548,51,2,9,35,'바로의 마음이 강퍅하여 이스라엘 자손을 보내지 아니하였으니 여호와께서 모세에게 말씀하심과 같더라'),
(1464549,51,2,10,1,'여호와께서 모세에게 이르시되 바로에게로 들어가라 내가 그의 마음과 그 신하들의 마음을 완강케 함은 나의 표징을 그들 중에 보이기 위함이며'),
(1464550,51,2,10,2,'너로 내가 애굽에서 행한 일들 곧 내가 그 가운데서 행한 표징을 네 아들과 네 자손의 귀에 전하게 하려 함이라 너희가 나를 여호와인줄 알리라'),
(1464551,51,2,10,3,'모세와 아론이 바로에게 들어가서 그에게 이르되 `히브리 사람의 하나님 여호와께서 말씀하시기를 네가 어느 때까지 내 앞에 겸비치 아니하겠느냐 ? 내 백성을 보내라 ! 그들이 나를 섬길 것이라'),
(1464552,51,2,10,4,'네가 만일 내 백성 보내기를 거절하면 내일 내가 메뚜기로 네 경내에 들어가게 하리니'),
(1464553,51,2,10,5,'메뚜기가 지면을 덮어서 사람이 땅을 볼 수 없을 것이라 메뚜기가 네게 남은 그것 곧 우박을 면하고 남은 것을 먹으며 들에 너를 위하여 자라는 모든 나무를 먹을 것이며'),
(1464554,51,2,10,6,'또 네 집들과 네 모든 신하의 집들과 모든 애굽 사람의 집들에 가득하리니 이는 네 아비와 네 조상이 세상에 있어 옴으로 오늘까지 보지 못하였던 것이리라 하셨다'' 하고 돌이켜 바로에게서 나오니'),
(1464555,51,2,10,7,'바로의 신하들이 그에게 고하되 `어느 때까지 이 사람이 우리의 함정이 되리이까 ? 그 사람들을 보내어 그 하나님 여호와를 섬기게 하소서 ! 왕은 아직도 애굽이 망한 줄을 알지 못하시나이까 ?'' 하고'),
(1464556,51,2,10,8,'모세와 아론을 바로에게로 다시 데려오니 바로가 그들에게 이르되 가서 너희 하나님 여호와를 섬기라 ! 갈 자는 누구 누구뇨 ?'),
(1464557,51,2,10,9,'모세가 가로되 `우리가 여호와 앞에 절기를 지킬 것인즉 우리가 남녀 노소와 우양을 데리고 가겠나이다'''),
(1464558,51,2,10,10,'바로가 그들에게 이르되 `내가 너희와 너희 어린 것들을 보내면 여호와를 너희와 함께하게 함과 일반이니라 삼갈지어다 너희 경영이 악하니라'),
(1464559,51,2,10,11,'그는 불가하니 너희 남정만 가서 여호와를 섬기라 이것이 너희의 구하는 바니라'' 이에 그들이 바로 앞에서 쫓겨나니라'),
(1464560,51,2,10,12,'여호와께서 모세에게 이르시되 네 손을 애굽 땅 위에 들어 메뚜기로 애굽 땅에 올라와서 우박에 상하지 아니한 밭의 모든 채소를 먹게 하라'),
(1464561,51,2,10,13,'모세가 애굽 땅 위에 그 지팡이를 들매 여호와께서 동풍을 일으켜 온 낮과 온 밤에 불게 하시니 아침에 미쳐 동풍이 메뚜기를 불어 들인지라'),
(1464562,51,2,10,14,'메뚜기가 애굽 온 땅에 이르러 그 사방에 내리매 그 해가 심하니 이런 메뚜기는 전에도 없었고 후에도 없을러라'),
(1464563,51,2,10,15,'메뚜기가 온 지면에 덮여 날으매 땅이 어둡게 되었고 메뚜기가 우박에 상하지 아니한 밭의 채소와 나무 열매를 다 먹었으므로 애굽 전경에 나무나 밭의 채소나 푸른 것은 남지 아니하였더라'),
(1464564,51,2,10,16,'바로가 모세와 아론을 급히 불러서 이르되 `내가 너희 하나님 여호와와 너희에게 득죄하였으니'),
(1464565,51,2,10,17,'청컨대 나의 죄를 이번만 용서하고 너희 하나님 여호와께 구하여 이 죽음만을 내게서 떠나게 하라'''),
(1464566,51,2,10,18,'그가 바로에게서 나가서 여호와께 구하매'),
(1464567,51,2,10,19,'여호와께서 돌이켜 강렬한 서풍이 불게 하사 메뚜기를 홍해에 몰아 넣으시니 애굽 온 지경에 메뚜기가 하나도 남지 아니하니라'),
(1464568,51,2,10,20,'그러나 여호와께서 바로의 마음을 강퍅케 하셨으므로 이스라엘 자손을 보내지 아니하였더라'),
(1464569,51,2,10,21,'여호와께서 모세에게 이르시되 하늘을 향하여 네 손을 들어서 애굽 땅위에 흑암이 있게 하라 곧 더듬을 만한 흑암이리라'),
(1464570,51,2,10,22,'모세가 하늘을 향하여 손을 들매 캄캄한 흑암이 삼일 동안 애굽온 땅에 있어서'),
(1464571,51,2,10,23,'그 동안은 사람 사람이 서로 볼 수 없으며 자기 처소에서 일어나는 자가 없으되 이스라엘 자손의 거하는 곳에는 광명이 있었더라'),
(1464572,51,2,10,24,'바로가 모세를 불러서 이르되 `너희는 가서 여호와를 섬기되 너희 양과 소는 머물러두고 너희 어린 것은 너희와 함께 갈지니라'''),
(1464573,51,2,10,25,'모세가 가로되 `왕이라도 우리 하나님 여호와께 드릴 희생과 번제물을 우리에게 주어야 하겠고'),
(1464574,51,2,10,26,'우리의 생축도 우리와 함께 가고 한 마리도 남길 수 없으니 이는 우리가 그 중에서 취하여 우리 하나님 여호와를 섬길 것임이며 또 우리가 거기 이르기까지는 어떤 것으로 여호와를 섬기는지 알지 못함이니이다'' 하나'),
(1464575,51,2,10,27,'여호와께서 바로의 마음을 강퍅케 하셨으므로 그들을 보내기를 즐겨 아니하고'),
(1464576,51,2,10,28,'모세에게 이르되 `너는 나를 떠나가고 스스로 삼가 다시 내 얼굴을 보지 말라 내 얼굴을 보는 날에는 죽으리라'''),
(1464577,51,2,10,29,'모세가 가로되 `왕의 말씀이 옳으니이다 ! 내가 다시는 왕의 얼굴을 보지 아니하리이다 !'''),
(1464578,51,2,11,1,'여호와께서 모세에게 이르시기를 내가 이제 한 가지 재앙을 바로와 애굽에 내린 후에야 그가 너희를 여기서 보낼지라 그가 너희를 보낼 때에는 여기서 정녕 다 쫓아 내리니'),
(1464579,51,2,11,2,'백성에게 말하여 남녀로 각기 이웃들에게 은금 패물을 구하게 하라 하시더니'),
(1464580,51,2,11,3,'여호와께서 그 백성으로 애굽 사람의 은혜를 받게 하셨고 또 그 사람 모세는 애굽국에서 바로의 신하와 백성에게 심히 크게 뵈었더라'),
(1464581,51,2,11,4,'모세가 바로에게 이르되 `여호와께서 이같이 말씀하시기를 밤중에 내가 애굽 가운데로 들어가리니'),
(1464582,51,2,11,5,'애굽 가운데 처음 난 것은 위에 앉은 바로의 장자로부터 맷돌 뒤에 있는 여종의 장자까지와 모든 생축의 처음 난 것이 죽을지라'),
(1464583,51,2,11,6,'애굽 전국에 전무후무한 큰 곡성이 있으리라'),
(1464584,51,2,11,7,'그러나 이스라엘 자손에게는 사람에게나 짐승에게나 개도 그 혀를 움직이지 않으리니 여호와가 애굽 사람과 이스라엘 사이에 구별하는 줄을 너희가 알리라'' 하셨나니');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464585,51,2,11,8,'왕이 이 모든 신하가 내게 내려와서 내게 절하며 이르기를 `너와 너를 좇는 온 백성은 나가라 한 후에야 내가 나가리라'' 하고 심히 노하여 바로에게서 나오니라'),
(1464586,51,2,11,9,'여호와께서 모세에게 이르시기를 바로가 너희를 듣지 아니할찌라 그러므로 내가 애굽 땅에서 나의 기사를 더하리라 하셨고'),
(1464587,51,2,11,10,'모세와 아론이 이 모든 기사를 바로 앞에서 행하였으나 여호와께서 바로의 마음을 강퍅케 하셨으므로 그가 이스라엘 자손을 그 나라에서 보내지 아니하였더라'),
(1464588,51,2,12,1,'여호와께서 애굽 땅에서 모세와 아론에게 일러 가라사대'),
(1464589,51,2,12,2,'이 달로 너희에게 달의 시작 곧 해의 첫 달이 되게 하고'),
(1464590,51,2,12,3,'너희는 이스라엘 회중에게 고하여 이르라 이 달 열흘에 너희 매인이 어린 양을 취할지니 각 가족대로 그 식구를 위하여 어린 양을 취하되'),
(1464591,51,2,12,4,'그 어린 양에 대하여 식구가 너무 적으면 그 집의 이웃과 함께 수를 따라서 하나를 취하며 각 사람의 식량을 따라서 너희 어린 양을 계산할 것이며'),
(1464592,51,2,12,5,'너희 어린 양은 흠 없고 일년 된 수컷으로 하되 양이나 염소 중에서 취하고'),
(1464593,51,2,12,6,'이달 십사일까지 간직하였다가 해질 때에 이스라엘 회중이 그 양을 잡고'),
(1464594,51,2,12,7,'양을 먹을 집 문 좌우 설주와 인방에 바르고'),
(1464595,51,2,12,8,'그 밤에 그 고기를 불에 구워 무교병과 쓴 나물과 아울러 먹되'),
(1464596,51,2,12,9,'날로나 물에 삶아서나 먹지 말고 그 머리와 정강이와 내장을 다 불에 구워 먹고'),
(1464597,51,2,12,10,'아침까지 남겨 두지 말며 아침까지 남은 것은 곧 소화하라'),
(1464598,51,2,12,11,'너희는 그것을 이렇게 먹을지니 허리에 띠를 띠고 발에 신을 신고 손에 지팡이를 잡고 급히 먹으라 ! 이것이 여호와의 유월절이니라 !'),
(1464599,51,2,12,12,'내가 그 밤에 애굽 땅에 두루 다니며 사람과 짐승을 무론하고 애굽 나라 가운데 처음 난 것을 다 치고 애굽의 모든 신에게 벌을 내리리라 나는 여호와로라 !'),
(1464600,51,2,12,13,'내가 애굽 땅을 칠 때에 그 피가 너희의 거하는 집에 있어서 너희를 위하여 표적이 될지라 내가 피를 볼때에 너희를 넘어가리니재앙이 너희에게 내려 멸하지 아니하리라'),
(1464601,51,2,12,14,'너희는 이 날을 기념하여 여호와의 절기를 삼아 영원한 규례로 대대에 지킬지니라 !'),
(1464602,51,2,12,15,'너희는 칠일동안 무교병을 먹을지니 그 첫날에 누룩을 너희 집에서 제하라 ! 무릇 첫날부터 칠일까지 유교병을 먹는 자는 이스라엘에서 끊쳐지리라'),
(1464603,51,2,12,16,'너희에게 첫날에도 성회요 제 칠일에도 성회가 되리니 이 두 날에는 아무 일도 하지 말고 각인의 식물만 너희가 갖출 것이니라'),
(1464604,51,2,12,17,'너희는 무교절을 지키라 ! 이 날에 내가 너희 군대를 애굽 땅에서 인도하여 내었음이니라 그러므로 너희가 영원한 규례를 삼아 이 날을 대대로 지킬지라 !'),
(1464605,51,2,12,18,'정월에 그 달 십사일 저녁부터 이십 일일 저녁까지 너희는 무교병을 먹을 것이요'),
(1464606,51,2,12,19,'칠일 동안은 누룩을 너희 집에 있지 않게 하라 무릇 유교물을 먹는 타국인이든지 본국에서 난 자든지 무론하고 이스라엘 회중에서 끊쳐지리니'),
(1464607,51,2,12,20,'너희는 아무 유교물이든지 먹지 말고 너희 모든 유하는 곳에서 무교병을 먹을지니라'),
(1464608,51,2,12,21,'모세가 이스라엘 모든 장로를 불러서 그들에게 이르되 `너희는 나가서 너희 가족대로 어린 양을 택하여 유월절 양으로 잡고'),
(1464609,51,2,12,22,'너희는 우슬초 묶음을 취하여 그릇에 담은 피에 적시어서 그 피를 문 인방과 좌우 설주에 뿌리고 아침까지 한 사람도 자기 집 문밖에 나가지 말라'),
(1464610,51,2,12,23,'여호와께서 애굽 사람을 치러 두루 다니실 때에 문 인방과 좌우설주의 피를 보시면 그 문을 넘으시고 멸하는 자로 너희 집에 들어가서 너희를 치지 못하게 하실 것임이니라'),
(1464611,51,2,12,24,'너희는 이 일을 규례로 삼아 너희와 너희 자손이 영원히 지킬 것이니'),
(1464612,51,2,12,25,'너희는 여호와께서 허락하신대로 너희에게 주시는 땅에 이를 때에 이 예식을 지킬 것이라'),
(1464613,51,2,12,26,'이 후에 너희 자녀가 묻기를 이 예식이 무슨 뜻이냐 ? 하거든'),
(1464614,51,2,12,27,'너희는 이르기를 이는 여호와의 유월절 제사라 여호와께서 애굽 사람을 치실 때에 애굽에 있는 이스라엘 자손의 집을 넘으사 우리의 집을 구원하셨느니라 하라'' 하매 백성이 머리 숙여 경배하니라'),
(1464615,51,2,12,28,'이스라엘 자손이 물러가서 그대로 행하되 여호와께서 모세와 아론에게 명하신 대로 행하니라'),
(1464616,51,2,12,29,'밤중에 여호와께서 애굽 땅에서 모든 처음 난 것 곧 위에 앉은 바로의 장자로부터 옥에 갇힌 사람의 장자까지와 생축의 처음난 것을 다 치시매'),
(1464617,51,2,12,30,'그 밤에 바로와 그 모든 신하와 모든 애굽 사람이 일어나고 애굽에 큰 호곡이 있었으니 이는 그 나라에 사망치 아니한 집이 하나도 없었음이었더라'),
(1464618,51,2,12,31,'밤에 바로가 모세와 아론을 불러서 이르되 `너희와 이스라엘 자손은 일어나 내 백성 가운데서 떠나서 너희의 말대로 가서 여호와를 섬기며'),
(1464619,51,2,12,32,'너희의 말대로 너희의 양도 소도 몰아가고 나를 위하여 축복하라'' 하며'),
(1464620,51,2,12,33,'애굽 사람들은 말하기를 `우리가 다 죽은 자가 되도다'' 하고 백성을 재촉하여 그 지경에서 속히 보내려 하므로'),
(1464621,51,2,12,34,'백성이 발교되지 못한 반죽 담은 그릇을 옷에 싸서 어깨에 메니라'),
(1464622,51,2,12,35,'이스라엘 자손이 모세의 말대로 하여 애굽 사람에게 은금 패물과 의복을 구하매'),
(1464623,51,2,12,36,'여호와께서 애굽 사람으로 백성에게 은혜를 입히게 하사 그들의 구하는대로 주게 하시므로 그들이 애굽 사람의 물품을 취하였더라'),
(1464624,51,2,12,37,'이스라엘 자손이 라암셋에서 발행하여 숙곳에 이르니 유아 외에 보행하는 장정이 육십만 가량이요'),
(1464625,51,2,12,38,'중다한 잡족과 양과 소와 심히 많은 생축이 그들과 함께 하였으며'),
(1464626,51,2,12,39,'그들이 가지고 나온 발교되지 못한 반죽으로 무교병을 구웠으니 이는 그들이 애굽에서 쫓겨 남으로 지체할 수 없었음이며 아무 양식도 준비하지 못하였음이었더라'),
(1464627,51,2,12,40,'이스라엘 자손이 애굽에 거주한지 사백 삼십년이라'),
(1464628,51,2,12,41,'사백 삼십년이 마치는 그 날에 여호와의 군대가 다 애굽 땅에서 나왔은즉'),
(1464629,51,2,12,42,'이 밤은 그들을 애굽 땅에서 인도하여 내심을 인하여 여호와 앞에 지킬 것이니 이는 여호와의 밤이라 이스라엘 자손이 다 대대로 지킬 것이니라'),
(1464630,51,2,12,43,'여호와께서 모세와 아론에게 이르시되 유월절 규례가 이러하니라 이방 사람은 먹지 못할 것이나'),
(1464631,51,2,12,44,'각 사람이 돈으로 산 종은 할례를 받은 후에 먹을 것이며'),
(1464632,51,2,12,45,'거류인과 타국 품군은 먹지 못하리라'),
(1464633,51,2,12,46,'한 집에서 먹되 그 고기를 조금도 집 밖으로 내지 말고 뼈도 꺾지 말지며'),
(1464634,51,2,12,47,'이스라엘 회중이 다 이것을 지킬지니라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464635,51,2,12,48,'너희와 함께 거하는 타국인이 여호와의 유월절을 지키고자 하거든 그 모든 남자는 할례를 받은 후에야 가까이하여 지킬지니 곧 그는 본토인과 같이 될 것이나 할례 받지 못한 자는 먹지 못할 것이니라'),
(1464636,51,2,12,49,'본토인에게나 너희 중에 우거한 이방인에게나 이 법이 동일하니라 하셨으므로'),
(1464637,51,2,12,50,'온 이스라엘 자손이 이와 같이 행하되 여호와께서 모세와 아론에게 명하신대로 행하였으며'),
(1464638,51,2,12,51,'그 같은 날에 여호와께서 이스라엘 자손을 그 군대대로 애굽 땅에서 인도하여 내셨더라'),
(1464639,51,2,13,1,'여호와께서 모세에게 일러 가라사대'),
(1464640,51,2,13,2,'이스라엘 자손 중에 사람이나 짐승이나 무론하고 초태생은 다 거룩히 구별하여 내게 돌리라 이는 내 것이니라 ! 하시니라'),
(1464641,51,2,13,3,'모세가 백성에게 이르되 `너희는 애굽에서 곧 종 되었던 집에서 나온 그 날을 기념하여 유교병을 먹지 말라 여호와께서 그 손의 권능으로 너희를 그 곳에서 인도하여 내셨음이니라'),
(1464642,51,2,13,4,'아빕월 이 날에 너희가 나왔으니'),
(1464643,51,2,13,5,'여호와께서 너를 인도하여 가나안 사람과, 헷 사람과, 아모리 사람과, 히위 사람과, 여부스 사람의 땅 곧 네게 주시려고 네 조상들에게 맹세하신바 젖과 꿀이 흐르는 땅에 이르게 하시거든 너는 이 달에 이 예식을 지켜'),
(1464644,51,2,13,6,'칠일 동안 무교병을 먹고 제 칠일에는 여호와께 절기를 지키라'),
(1464645,51,2,13,7,'칠일 동안에는 무교병을 먹고 유교병을 너희 곳에 있게 하지 말며 네 지경 안에서 누룩을 네게 보이지도 말게 하며'),
(1464646,51,2,13,8,'너는 그 날에 네 아들에게 뵈어 이르기를 이 예식은 내가 애굽에서 나올 때에 여호와께서 나를 위하여 행하신 일을 인함이라 하고'),
(1464647,51,2,13,9,'이것으로 네 손의 기호와 네 미간의 표를 삼고 여호와의 율법으로 네 입에 있게 하라 이는 여호와께서 능하신 손으로 너를 애굽에서 인도하여 내셨음이니'),
(1464648,51,2,13,10,'연년이 기한에 이르러 이 규례를 지킬지니라'),
(1464649,51,2,13,11,'여호와께서 너와 네 조상에게 맹세하신대로 너를 가나안 사람의 땅에 인도하시고 그 땅을 네게 주시거든'),
(1464650,51,2,13,12,'너는 무릇 초태생과 네게 있는 생축의 초태생을 다 구별하여 여호와께 돌리라 수컷은 여호와의 것이니라'),
(1464651,51,2,13,13,'나귀의 첫새끼는 다 어린 양으로 대속할 것이요 그렇게 아니하려면 그 목을 꺽을 것이며 너의 아들중 모든 장자 된 자는 다 대속할지니라'),
(1464652,51,2,13,14,'장래에 네 아들이 네게 묻기를 이것이 어찜이냐 ? 하거든 너는 그에게 이르기를 여호와께서 그 손의 권능으로 우리를 애굽에서 곧 종이 되었던 집에서 인도하여 내실쌔'),
(1464653,51,2,13,15,'그 때에 바로가 강퍅하여 우리를 보내지 아니하매 여호와께서 애굽 나라 가운데 처음 낳은 것까지 다 죽이신고로 초태생의 수컷은 다 여호와께 희생으로 드리고 우리 장자는 다 대속하나니'),
(1464654,51,2,13,16,'이것으로 네 손의 기호와 네 미간의 표를 삼으라 여호와께서 그 손의 권능으로 우리를 애굽에서 인도하여 내셨음이니라 할지니라'''),
(1464655,51,2,13,17,'바로가 백성을 보낸 후에 블레셋 사람의 땅의 길은 가까울지라도 하나님이 그들을 그 길로 인도하지 아니하셨으니 이는 하나님이 말씀하시기를 이 백성이 전쟁을 보면 뉘우쳐 애굽으로 돌아갈까 하셨음이라'),
(1464656,51,2,13,18,'그러므로 하나님이 홍해의 광야 길로 돌려 백성을 인도하시매 이스라엘 자손이 애굽 땅에서 항오를 지어 나올 때에'),
(1464657,51,2,13,19,'모세가 요셉의 해골을 취하였으니 이는 요셉이 이스라엘 자손으로 단단히 맹세케 하여 이르기를 ''하나님이 필연 너희를 권고하시리니 너희는 나의 해골을 여기서 가지고 나가라'' 하였음이었더라'),
(1464658,51,2,13,20,'그들이 숙곳에서 발행하여 광야 끝에 담에 장막을 치니'),
(1464659,51,2,13,21,'여호와께서 그들 앞에 행하사 낮에는 구름 기둥으로 그들의 길을 인도하시고 밤에는 불기둥으로 그들에게 비취사 주야로 진행하게 하시니'),
(1464660,51,2,13,22,'낮에는 구름 기둥,밤에는 불기둥이 백성 앞에서 떠나지 아니하니라'),
(1464661,51,2,14,1,'여호와께서 모세에게 일러 가라사대'),
(1464662,51,2,14,2,'이스라엘 자손을 명하여 돌쳐서 바다와 믹돌 사이의 비하히롯 앞 곧 바알스본 맞은편 바닷가에 장막을 치게 하라'),
(1464663,51,2,14,3,'바로가 이스라엘 자손에 대하여 말하기를 `그들이 그 땅에서 아득하여 광야에 갇힌바 되었다 할지라'''),
(1464664,51,2,14,4,'내가 바로의 마음을 강퍅케 한즉 바로가 그들의 뒤를 따르리니 내가 그와 그 온 군대를 인하여 영광을 얻어 애굽 사람으로 나를 여호와인 줄 알게 하리라 하시매 무리가 그대로 행하니라'),
(1464665,51,2,14,5,'혹이 백성의 도망한 것을 애굽 왕에게 고하매 바로와 그 신하들이 백성에 대하여 마음이 변하여 가로되 ''우리가 어찌 이같이 하여 이스라엘을 우리를 섬김에서 놓아 보내었는고 ?'' 하고'),
(1464666,51,2,14,6,'바로가 곧 그 병거를 갖추고 그 백성을 데리고 갈새'),
(1464667,51,2,14,7,'특별 병거 육백승과 애굽의 모든 병거를 발하니 장관들이 다 거느렸더라'),
(1464668,51,2,14,8,'여호와께서 애굽 왕 바로의 마음을 강퍅케 하셨으므로 그가 이스라엘 자손의 뒤를 따르니 이스라엘 자손이 담대히 나갔음이라'),
(1464669,51,2,14,9,'애굽 사람들과 바로의 말들 병거들과 그 마병과 그 군대가 그들의 뒤를 따라 바알스본 맞은편 비하히롯 곁 해변 그 장막 친 데 미치니라'),
(1464670,51,2,14,10,'바로가 가까와 올 때에 이스라엘 자손이 눈을 들어 본즉 애굽 사람들이 자기 뒤에 미친지라 이스라엘 자손이 심히 두려워하여 여호와께 부르짖고'),
(1464671,51,2,14,11,'그들이 또 모세에게 이르되 `애굽에 매장지가 없으므로 당신이 우리를 이끌어 내어 이 광야에서 죽게 하느뇨 ? 어찌하여 당신이 우리를 애굽에서 이끌어 내어 이같이 우리에게 하느뇨 ?'),
(1464672,51,2,14,12,'우리가 애굽에서 당신에게 고한 말이 이것이 아니뇨 ? 이르기를 우리를 버려 두라 우리가 애굽 사람을 섬길 것이라 하지 아니하더뇨 ? 애굽 사람을 섬기는 것이 광야에서 죽는 것보다 낫겠노라'''),
(1464673,51,2,14,13,'모세가 백성에게 이르되 `너희는 두려워 말고 가만히 서서 여호와께서 오늘날 너희를 위하여 행하시는 구원을 보라 ! 너희가 오늘 본 애굽 사람을 또 다시는 영원히 보지 못하리라'),
(1464674,51,2,14,14,'여호와께서 너희를 위하여 싸우시리니 너희는 가만히 있을지니라 !'''),
(1464675,51,2,14,15,'여호와께서 모세에게 이르시되 너는 어찌하여 내게 부르짖느뇨 이스라엘 자손을 명하여 앞으로 나가게 하고'),
(1464676,51,2,14,16,'지팡이를 들고 손을 바다 위로 내밀어 그것으로 갈라지게 하라 이스라엘 자손이 바다 가운데 육지로 행하리라'),
(1464677,51,2,14,17,'내가 애굽 사람들의 마음을 강퍅케 할 것인즉 그들이 그 뒤를 따라 들어갈 것이라 내가 바로와 그 모든 군대와 그 병거와 마병을 인하여 영광을 얻으리니'),
(1464678,51,2,14,18,'내가 바로와 그 병거와 마병으로 인하여 영광을 얻을 때에야 애굽 사람들이 나를 여호와인 줄 알리라 하시더니'),
(1464679,51,2,14,19,'이스라엘 진 앞에 행하던 하나님의 사자가 옮겨 그 뒤로 행하매 구름 기둥도 앞에서 그 뒤로 옮겨'),
(1464680,51,2,14,20,'애굽 진과 이스라엘 진 사이에 이르러 서니 저 편은 구름과 흑암이 있고 이 편은 밤이 광명하므로 밤새도록 저 편이 이 편에 가까이 못하였더라'),
(1464681,51,2,14,21,'모세가 바다 위로 손을 내어민대 여호와께서 큰 동풍으로 밤새도록 바닷물을 물러가게 하시니 물이 갈라져 바다가 마른 땅이 된지라'),
(1464682,51,2,14,22,'이스라엘 자손이 바다 가운데 육지로 행하고 물은 그들의 좌우에 벽이 되니'),
(1464683,51,2,14,23,'애굽 사람들과 바로의 말들, 병거들과 그 마병들이 다 그 뒤를 쫓아 바다 가운데로 들어 오는지라'),
(1464684,51,2,14,24,'새벽에 여호와께서 불 구름기둥 가운데서 애굽 군대를 보시고 그 군대를 어지럽게 하시며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464685,51,2,14,25,'그 병거 바퀴를 벗겨서 달리기에 극난하게 하시니 애굽 사람들이 가로되 ''이스라엘 앞에서 우리가 도망하자 ! 여호와가 그들을 위하여 싸워 애굽 사람들을 치는도다'''),
(1464686,51,2,14,26,'여호와께서 모세에게 이르시되 네 손을 바다 위로 내어밀어 물이 애굽 사람들과 그 병거들과 마병들 위에 다시 흐르게 하라 하시니'),
(1464687,51,2,14,27,'모세가 곧 손을 바다 위로 내어밀매 새벽에 미쳐 바다의 그 세력이 회복된지라 애굽 사람들이 물을 거스려 도망하나 여호와께서 애굽 사람들을 바다 가운데 엎으시니'),
(1464688,51,2,14,28,'물이 다시 흘러 병거들과 기병들을 덮되 그들의 뒤를 쫓아 바다에 들어간 바로의 군대를 다 덮고 하나도 남기지 아니하였더라'),
(1464689,51,2,14,29,'그러나 이스라엘 자손은 바다 가운데 육지로 행하였고 물이 좌우에 벽이 되었었더라'),
(1464690,51,2,14,30,'그 날에 여호와께서 이같이 이스라엘을 애굽 사람의 손에서 구원하시매 이스라엘이 바닷가의 애굽 사람의 시체를 보았더라'),
(1464691,51,2,14,31,'이스라엘이 여호와께서 애굽 사람들에게 베푸신 큰 일을 보았으므로 백성이 여호와를 경외하며 여호와와 그 종 모세를 믿었더라'),
(1464692,51,2,15,1,'이 때에 모세와 이스라엘 자손이 이 노래로 여호와께 노래하니 일렀으되 내가 여호와를 찬송하리니 그는 높고 영화로우심이요 말과 그 탄 자를 바다에 던지셨음이로다'),
(1464693,51,2,15,2,'여호와는 나의 힘이요, 노래시며, 나의 구원이시로다 그는 나의 하나님이시니 내가 그를 찬송할 것이요 내 아비의 하나님이시니 내가 그를 높이리로다'),
(1464694,51,2,15,3,'여호와는 용사시니 여호와는 그의 이름이시로다'),
(1464695,51,2,15,4,'그가 바로의 병거와 그 군대를 바다에 던지시니 그 택한 장관이 홍해에 잠겼고'),
(1464696,51,2,15,5,'큰 물이 그들을 덮으니 그들이 돌처럼 깊음에 내렸도다'),
(1464697,51,2,15,6,'여호와여 주의 오른손이 권능으로 영광을 나타내시니이다 여호와여 ! 주의 오른 손이 원수를 부수시니이다'),
(1464698,51,2,15,7,'주께서 주의 큰 위엄으로 주를 거스리는 자를 엎으시나이다 주께서 진노를 발하시니 그 진노가 그들을 초개같이 사르니이다'),
(1464699,51,2,15,8,'주의 콧김에 물이 쌓이되 파도가 언덕 같이 일어서고 큰 물이 바다 가운데 엉기니이다'),
(1464700,51,2,15,9,'대적의 말이 내가 쫓아 미쳐 탈취물을 나누리라 내가 그들로 인하여 내 마음을 채우리라 내가 내 칼을 빼리니 내 손이 그들을 멸하리라 하였으나'),
(1464701,51,2,15,10,'주께서 주의 바람을 일으키시매 바다가 그들을 덮으니 그들이 흉용한 물에 납 같이 잠겼나이다'),
(1464702,51,2,15,11,'여호와여 ! 신 중에 주와 같은 자 누구니이까 ? 주와 같이 거룩함에 영광스러우며 찬송할만한 위엄이 있으며 기이한 일을 행하는 자 누구니이까 ?'),
(1464703,51,2,15,12,'주께서 오른손을 드신즉 땅이 그들을 삼켰나이다'),
(1464704,51,2,15,13,'주께서 그 구속하신 백성을 은혜로 인도하시되 주의 힘으로 그들을 주의 성결한 처소에 들어가게 하시나이다'),
(1464705,51,2,15,14,'열방이 듣고 떨며 블레셋 거민이 두려움에 잡히며'),
(1464706,51,2,15,15,'에돔 방백이 놀라고 모압 영웅이 떨림에 잡히며 가나안 거민이 다 낙담하나이다'),
(1464707,51,2,15,16,'놀람과 두려움이 그들에게 미치매 주의 팔이 큼을 인하여 그들이 돌같이 고요하였사오되 여호와여 ! 주의 백성이 통과하기까지 곧 주의 사신 백성이 통과하기까지였나이다'),
(1464708,51,2,15,17,'주께서 백성을 인도하사 그들을 주의 기업의 산에 심으시리이다 여호와여 ! 이는 주의 처소를 삼으시려고 예비하신 것이라 주여 ! 이것이 주의 손으로 세우신 성소로소이다'),
(1464709,51,2,15,18,'여호와의 다스리심이 영원무궁하시도다 하였더라'),
(1464710,51,2,15,19,'바로의 말과 병거와 마병이 함께 바다에 들어가매 여호와께서 바닷물로 그들 위에 돌이켜 흐르게 하셨으나 이스라엘 자손은 바다가운데서 육지로 행한지라'),
(1464711,51,2,15,20,'아론의 누이 선지자 미리암이 손에 소고를 잡으매 모든 여인도 그를 따라 나오며 소고를 잡고 춤추니'),
(1464712,51,2,15,21,'미리암이 그들에게 화답하여 가로되 `너희는 여호와를 찬송하라 ! 그는 높고 영화로우심이요 말과 그 탄 자를 바다에 던지셨음이로다'' 하였더라'),
(1464713,51,2,15,22,'모세가 홍해에서 이스라엘을 인도하매 그들이 나와서 수르 광야로 들어가서 거기서 사흘길을 행하였으나 물을 얻지 못하고'),
(1464714,51,2,15,23,'마라에 이르렀더니 그 곳 물이 써서 마시지 못하겠으므로 그 이름을 마라라 하였더라'),
(1464715,51,2,15,24,'백성이 모세를 대하여 원망하여 가로되 `우리가 무엇을 마실까 ?'' 하매'),
(1464716,51,2,15,25,'모세가 여호와께 부르짖었더니 여호와께서 그에게 한 나무를 지시하시니 그가 물에 던지매 물이 달아졌더라 거기서 여호와께서 그들을 위하여 법도와 율례를 정하시고 그들을 시험하실쌔'),
(1464717,51,2,15,26,'가라사대 너희가 너희 하나님 나 여호와의 말을 청종하고 나의 보기에 의를 행하며 내 계명에 귀를 기울이며 내 모든 규례를 지키면 내가 애굽 사람에게 내린 모든 질병의 하나도 너희에게 내리지 아니하리니 나는 너희를 치료하는 여호와임이니라 !'),
(1464718,51,2,15,27,'그들이 엘림에 이르니 거기 물샘 열 둘과 종려 칠십주가 있는지라 거기서 그들이 그 물 곁에 장막을 치니라'),
(1464719,51,2,16,1,'이스라엘 자손의 온 회중이 엘림에서 떠나 엘림과 시내산 사이 신 광야에 이르니 애굽에서 나온 후 제 이월 십오일이라'),
(1464720,51,2,16,2,'이스라엘 온 회중이 그 광야에서 모세와 아론을 원망하여'),
(1464721,51,2,16,3,'그들에게 이르되 `우리가 애굽 땅에서 고기 가마 곁에 앉았던 때와 떡을 배불리 먹던 때에 여호와의 손에 죽었더면 좋았을 것을 너희가 이 광야로 우리를 인도하여 내어 이 온 회중으로 주려 죽게 하는도다'''),
(1464722,51,2,16,4,'때에 여호와께서 모세에게 이르시되 `보라 ! 내가 너희를 위하여 하늘에서 양식을 비 같이 내리리니 백성이 나가서 일용할 것을 날마다 거둘 것이라 이같이 하여 그들이 나의 율법을 준행하나 아니하나 내가 시험하리라'),
(1464723,51,2,16,5,'제 육일에는 그들이 그 거둔 것을 예비할지니 날마다 거두던 것의 갑절이 되리라'''),
(1464724,51,2,16,6,'모세와 아론이 온 이스라엘 자손에게 이르되 `저녁이 되면 너희가 여호와께서 너희를 애굽 땅에서 인도하여 내셨음을 알 것이요'),
(1464725,51,2,16,7,'아침에는 너희가 여호와의 영광을 보리니 이는 여호와께서 너희가 자기를 향하여 원망함을 들으셨음이라 우리가 누구관대 너희가 우리를 대하여 원망하느냐 ?'''),
(1464726,51,2,16,8,'모세가 또 가로되 `여호와께서 저녁에는 너희에게 고기를 주어 먹이시고 아침에는 떡으로 배불리시리니 이는 여호와께서 자기를 향하여 너희의 원망하는 그 말을 들으셨음이니라 우리가 누구냐 ? 너희의 원망은 우리를 향하여 함이 아니요 여호와를 향하여 함이로다'''),
(1464727,51,2,16,9,'모세가 또 아론에게 이르되 `이스라엘 자손의 온 회중에게 명하기를 여호와께 가까이 나아오라 ! 여호와께서 너희의 원망함을 들으셨느니라 하라'''),
(1464728,51,2,16,10,'아론이 이스라엘 자손의 온 회중에게 말하매 그들이 광야를 바라보니 여호와의 영광이 구름 속에 나타나더라'),
(1464729,51,2,16,11,'여호와께서 모세에게 일러 가라사대'),
(1464730,51,2,16,12,'내가 이스라엘 자손의 원망함을 들었노라 그들에게 고하여 이르기를 너희가 해 질 때에는 고기를 먹고 아침에는 떡으로 배부르리니 나는 여호와 너희의 하나님인 줄 알리라 하라 하시니라'),
(1464731,51,2,16,13,'저녁에는 메추라기가 와서 진에 덮이고 아침에는 이슬이 진 사면에 있더니'),
(1464732,51,2,16,14,'그 이슬이 마른 후에 광야 지면에 작고 둥글며 서리 같이 세미한 것이 있는지라'),
(1464733,51,2,16,15,'이스라엘 자손이 보고 그것이 무엇인지 알지 못하여 서로 이르되 이것이 무엇이냐 ? 하니 모세가 그들에게 이르되 이는 여호와께서 너희에게 주어 먹게 하신 양식이라'),
(1464734,51,2,16,16,'여호와께서 이같이 명하시기를 너희 각 사람의 식량대로 이것을 거둘지니 곧 너희 인수대로 매명에 한 오멜씩 취하되 각 사람이 그 장막에 있는 자들을 위하여 취할지니라 하셨느니라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464735,51,2,16,17,'이스라엘 자손이 그같이 하였더니 그 거둔 것이 많기도 하고 적기도 하나'),
(1464736,51,2,16,18,'오멜로 되어 본즉 많이 거둔 자도 남음이 없고 적게 거둔 자도 부족함이 없이 각기 식량대로 거두었더라'),
(1464737,51,2,16,19,'모세가 그들에게 이르기를 `아무든지 아침까지 그것을 남겨 두지말라'' 하였으나'),
(1464738,51,2,16,20,'그들이 모세의 말을 청종치 아니하고 더러는 아침까지 두었더니 벌레가 생기고 냄새가 난지라 모세가 그들에게 노하니라'),
(1464739,51,2,16,21,'무리가 아침마다 각기 식량대로 거두었고 해가 뜨겁게 쪼이면 그것이 스러졌더라'),
(1464740,51,2,16,22,'제육일에는 각 사람이 갑절의 식물 곧 하나에 두 오멜씩 거둔지라 회중의 모든 두목이 와서 모세에게 고하매'),
(1464741,51,2,16,23,'모세가 그들에게 이르되 `여호와께서 이같이 말씀하셨느니라 내일은 휴식이니 여호와께 거룩한 안식일이라 너희가 구울 것은 굽고 삶을 것은 삶고, 그 나머지는 다 너희를 위하여 아침까지 간수하라'''),
(1464742,51,2,16,24,'그들이 모세의 명대로 아침까지 간수하였으나 냄새도 나지 아니하고 벌레도 생기지 아니한지라'),
(1464743,51,2,16,25,'모세가 가로되 `오늘은 그것을 먹으라 오늘은 여호와께 안식일인즉 오늘은 너희가 그것을 들에서 얻지 못하리라'),
(1464744,51,2,16,26,'육일 동안은 너희가 그것을 거두되 제 칠일은 안식일인즉 그날에는 없으리라 !'' 하였으나'),
(1464745,51,2,16,27,'제 칠일에 백성 중 더러가 거두러 나갔다가 얻지 못하니라'),
(1464746,51,2,16,28,'여호와께서 모세에게 이르시되 어느 때까지 너희가 내 계명과 내 율법을 지키지 아니하려느냐 ?'),
(1464747,51,2,16,29,'볼지어다 ! 여호와가 너희에게 안식일을 줌으로 제 육일에는 이들 양식을 너희에게 주는 것이니 너희는 각기 처소에 있고 제 칠일에는 아무도 그 처소에서 나오지 말지니라'),
(1464748,51,2,16,30,'그러므로 백성이 제 칠일에 안식하니라'),
(1464749,51,2,16,31,'이스라엘 족속이 그 이름을 만나라 하였으며 깟씨 같고도 희고 맛은 꿀 섞은 과자 같았더라'),
(1464750,51,2,16,32,'모세가 가로되 `여호와께서 이같이 명하시기를 이것을 오멜에 채워서 너의 대대 후손을 위하여 간수하라 이는 내가 너희를 애굽 땅에서 인도하여 낼 때에 광야에서 너희에게 먹인 양식을 그들에게 보이기 위함이니라 하셨다'' 하고'),
(1464751,51,2,16,33,'또 아론에게 이르되 `항아리를 가져다가 그 속에 만나 한 오멜을 담아 여호와 앞에 두어 너희 대대로 간수하라'''),
(1464752,51,2,16,34,'아론이 여호와께서 모세에게 명하신대로 그것을 증거판 앞에 두어 간수하게 하였고'),
(1464753,51,2,16,35,'이스라엘 자손이 사람 사는 땅에 이르기까지 사십년 동안 만나를 먹되 곧 가나안 지경에 이르기까지 그들이 만나를 먹었더라'),
(1464754,51,2,16,36,'오멜은 에바 십분의 일이더라'),
(1464755,51,2,17,1,'이스라엘 자손의 온 회중이 여호와의 명령대로 신 광야에서 떠나 그 노정대로 행하여 르비딤에 장막을 쳤으나 백성이 마실 물이 없는지라'),
(1464756,51,2,17,2,'백성이 모세와 다투어 가로되 `우리에게 물을 주어 마시게 하라'' 모세가 그들에게 이르되 ''너희가 어찌하여 나와 다투느냐 ? 너희가 어찌하여 여호와를 시험하느냐 ?'''),
(1464757,51,2,17,3,'거기서 백성이 물에 갈하매 그들이 모세를 대하여 원망하여 가로되 당신이 어찌하여 우리를 애굽에서 인도하여 내어서 우리와 우리 자녀와 우리 생축으로 목말라 죽게 하느냐 ?'),
(1464758,51,2,17,4,'모세가 여호와께 부르짖어 가로되 `내가 이 백성에게 어떻게 하리이까 ? 그들이 얼마 아니면 내게 돌질하겠나이다'''),
(1464759,51,2,17,5,'여호와께서 모세에게 이르시되 백성 앞을 지나가서 이스라엘 장로들을 데리고 하수를 치던 네 지팡이를 손에 잡고 가라'),
(1464760,51,2,17,6,'내가 거기서 호렙산 반석 위에 너를 대하여 서리니 너는 반석을 치라 ! 그것에서 물이 나리니 백성이 마시리라 모세가 이스라엘 장로들의 목전에서 그대로 행하니라'),
(1464761,51,2,17,7,'그가 그곳 이름을 맛사라 또는 므리바라 불렀으니 이는 이스라엘 자손이 다투었음이요 또는 그들이 여호와를 시험하여 이르기를 ''여호와께서 우리 중에 계신가 아닌가'' 하였음이더라'),
(1464762,51,2,17,8,'때에 아말렉이 이르러 이스라엘과 르비딤에서 싸우니라'),
(1464763,51,2,17,9,'모세가 여호수아에게 이르되 `우리를 위하여 사람들을 택하여 나가서 아말렉과 싸우라 내일 내가 하나님의 지팡이를 손에 잡고 산꼭대기에 서리라'''),
(1464764,51,2,17,10,'여호수아가 모세의 말대로 행하여 아말렉과 싸우고 모세와 아론과 훌은 산꼭대기에 올라가서'),
(1464765,51,2,17,11,'모세가 손을 들면 이스라엘이 이기고 손을 내리면 아말렉이 이기더니'),
(1464766,51,2,17,12,'모세의 팔이 피곤하매 그들이 돌을 가져다가 모세의 아래에 놓아 그로 그 위에 앉게 하고 아론과 훌이 하나는 이편에서 하나는 저편에서 모세의 손을 붙들어 올렸더니 그 손이 해가 지도록 내려 오지 아니한지라'),
(1464767,51,2,17,13,'여호수아가 칼날로 아말렉과 그 백성을 쳐서 파하니라'),
(1464768,51,2,17,14,'여호와께서 모세에게 이르시되 이것을 책에 기록하여 기념하게 하고 여호수아의 귀에 외워 들리라 내가 아말렉을 도말하여 천하에서 기억함이 없게 하리라'),
(1464769,51,2,17,15,'모세가 단을 쌓고 그 이름을 `여호와 닛시''라 하고'),
(1464770,51,2,17,16,'가로되 여호와께서 맹세하시기를 여호와가 아말렉으로 더불어 대대로 싸우리라 하셨다 하였더라'),
(1464771,51,2,18,1,'모세의 장인 미디안 제사장 이드로가 하나님이 모세에게와 자기 백성 이스라엘에게 하신 일 곧 여호와께서 이스라엘을 애굽에서 인도하여 내신 모든 일을 들으니라'),
(1464772,51,2,18,2,'모세의 장인 이드로가 모세가 돌려 보내었던 그의 아내 십보라와'),
(1464773,51,2,18,3,'그 두 아들을 데렸으니 그 하나의 이름은 게르솜이라 이는 모세가 이르기를 ''내가 이방에서 객이 되었다'' 함이요'),
(1464774,51,2,18,4,'하나의 이름은 엘리에셀이라 이는 `내 아버지의 하나님이 나를 도우사 바로의 칼에서 구원하셨다'' 함이더라'),
(1464775,51,2,18,5,'모세의 장인 이드로가 모세의 아들들과 그 아내로 더불어 광야에 들어와 모세에게 이르니 곧 모세가 하나님의 산에 진 친 곳이라'),
(1464776,51,2,18,6,'그가 모세에게 전언하되 `그대의 장인 나 이드로가 그대의 아내와 그와 함께한 그 두 아들로 더불어 그대에게 왔노라'''),
(1464777,51,2,18,7,'모세가 나가서 그 장인을 맞아 절하고 그에게 입맞추고 그들이 서로 문안하고 함께 장막에 들어가서'),
(1464778,51,2,18,8,'모세가 여호와께서 이스라엘을 위하여 바로와 애굽 사람에게 행하신 모든 일과 길에서 그들의 당한 모든 고난과 여호와께서 그 들을 구원하신 일을 다 그 장인에게 고하매'),
(1464779,51,2,18,9,'이드로가 여호와께서 이스라엘에게 모든 은혜를 베푸사 애굽 사람의 손에서 구원하심을 기뻐하여'),
(1464780,51,2,18,10,'가로되 `여호와를 찬송하리로다 ! 너희를 애굽 사람의 손에서와 바로의 손에서 건져내시고 백성을 애굽 사람의 손 밑에서 건지셨도다'),
(1464781,51,2,18,11,'이제 내가 알았도다 ! 여호와는 모든 신보다 크시므로 이스라엘에게 교만히 행하는 그들을 이기셨도다'' 하고'),
(1464782,51,2,18,12,'모세의 장인 이드로가 번제물과 희생을 하나님께 가져오매 아론과 이스라엘 모든 장로가 와서 모세의 장인과 함께 하나님 앞에서 떡을 먹으니라'),
(1464783,51,2,18,13,'이튿날에 모세가 백성을 재판하느라고 앉았고 백성은 아침부터 저녁까지 모세의 곁에 섰는지라'),
(1464784,51,2,18,14,'모세의 장인이 모세가 백성에게 행하는 모든 일을 보고 가로되 `그대가 이 백성에게 행하는 이 일이 어찜이뇨 ? 어찌하여 그대는 홀로 앉았고 백성은 아침부터 저녁까지 그대의 곁에 섰느뇨 ?''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464785,51,2,18,15,'모세가 그 장인에게 대답하되 `백성이 하나님께 물으려고 내게로 옴이라'),
(1464786,51,2,18,16,'그들이 일이 있으면 내게로 오나니 내가 그 양편을 판단하여 하나님의 율례와 법도를 알게 하나이다'''),
(1464787,51,2,18,17,'모세의 장인이 그에게 이르되 `그대의 하는 것이 선하지 못하도다'),
(1464788,51,2,18,18,'그대와 그대와 함께한 이 백성이 필연 기력이 쇠하리니 이 일이 그대에게 너무 중함이라 그대가 혼자 할 수 없으리라'),
(1464789,51,2,18,19,'이제 내 말을 들으라 ! 내가 그대에게 방침을 가르치리니 하나님이 그대와 함께 계실지로다 ! 그대는 백성을 위하여 하나님 앞에 있어서 소송을 하나님께 베풀며'),
(1464790,51,2,18,20,'그들에게 율례와 법도를 가르쳐서 마땅히 갈 길과 할 일을 그들에게 보이고'),
(1464791,51,2,18,21,'그대는 또 온 백성 가운데서 재덕이 겸전한 자 곧 하나님을 두려워하며 진실무망하며 불의한 이를 미워하는 자를 빼서 백성 위에 세워 천부장과 백부장과 오십부장과 십부장을 삼아'),
(1464792,51,2,18,22,'그들로 때를 따라 백성을 재판하게 하라 무릇 큰 일이면 그대에게 베풀 것이고 무릇 작은 일이면 그들이 스스로 재판할 것이니 그리하면 그들이 그대와 함께 담당할 것인즉 일이 그대에게 쉬우리라'),
(1464793,51,2,18,23,'그대가 만일 이 일을 하고 하나님께서도 그대에게 인가하시면 그대가 이 일을 감당하고 이 모든 백성도 자기 곳으로 평안히 가리라'''),
(1464794,51,2,18,24,'이에 모세가 자기 장인의 말을 듣고 그 모든 말대로 하여'),
(1464795,51,2,18,25,'이스라엘 무리 중에서 재덕이 겸전한 자를 빼서 그들로 백성의 두목 곧 천부장과 백부장과 오십부장과 십부장을 삼으매'),
(1464796,51,2,18,26,'그들이 때를 따라 백성을 재판하되 어려운 일은 모세에게 베풀고 쉬운 일은 자단하더라'),
(1464797,51,2,18,27,'모세가 그 장인을 보내니 그가 자기 고향으로 돌아가니라'),
(1464798,51,2,19,1,'이스라엘 자손이 애굽 땅에서 나올 때부터 제 삼월 곧 그 때에 그들이 시내 광야에 이르니라'),
(1464799,51,2,19,2,'그들이 르비딤을 떠나 시내 광야에 이르러 그 광야에 장막을 치되 산 앞에 장막을 치니라'),
(1464800,51,2,19,3,'모세가 하나님 앞에 올라가니 여호와께서 산에서 그를 불러 가라사대 너는 이같이 야곱 족속에게 이르고 이스라엘 자손에게 고하라'),
(1464801,51,2,19,4,'나의 애굽 사람에게 어떻게 행하였음과 내가 어떻게 독수리 날개로 너희를 업어 내게로 인도하였음을 너희가 보았느니라'),
(1464802,51,2,19,5,'세계가 다 내게 속하였나니 너희가 내 말을 잘 듣고 내 언약을 지키면 너희는 열국 중에서 내 소유가 되겠고'),
(1464803,51,2,19,6,'너희가 내게 대하여 제사장 나라가 되며 거룩한 백성이 되리라 너는 이 말을 이스라엘 자손에게 고할지니라 !'),
(1464804,51,2,19,7,'모세가 와서 백성의 장로들을 불러 여호와께서 자기에게 명하신 그 모든 말씀을 그 앞에 진술하니'),
(1464805,51,2,19,8,'백성이 일제히 응답하여 가로되 `여호와의 명하신대로 우리가 다 행하리이다 !'' 모세가 백성의 말로 여호와께 회보하매'),
(1464806,51,2,19,9,'여호와께서 모세에게 이르시되 내가 빽빽한 구름 가운데서 네게 일함은 내가 너와 말하는 것을 백성으로 듣게하며 또한 너를 영원히 믿게 하려함이니라 모세가 백성의 말로 여호와께 고하였으므로'),
(1464807,51,2,19,10,'여호와께서 모세에게 이르시되 너는 백성에게로 가서 오늘과 내일 그들을 성결케 하며 그들로 옷을 빨고'),
(1464808,51,2,19,11,'예비하여 제 삼일을 기다리게 하라 이는 제 삼일에 나 여호와가 온 백성의 목전에 시내산에 강림할 것임이니'),
(1464809,51,2,19,12,'너는 백성을 위하여 사면으로 지경을 정하고 이르기를 너희는 삼가 산에 오르거나 그 지경을 범하지 말지니 산을 범하는 자는 정녕 죽임을 당할 것이라'),
(1464810,51,2,19,13,'손을 그에게 댐이 없이 그런 자는 돌에 맞아 죽임을 당하거나 살에 쐬어 죽임을 당하리니 짐승이나 사람을 무론하고 살지 못하리라 나팔을 길게 불거든 산 앞에 이를 것이니라 하라'),
(1464811,51,2,19,14,'모세가 산에서 내려 백성에게 이르러 백성으로 성결케 하니 그들이 자기 옷을 빨더라'),
(1464812,51,2,19,15,'모세가 백성에게 이르되 `예비하여 제 삼일을 기다리고 여인을 가까이 말라'' 하니라'),
(1464813,51,2,19,16,'제 삼일 아침에 우뢰와 번개와 빽빽한 구름이 산 위에 있고 나팔소리가 심히 크니 진중 모든 백성이 다 떨더라'),
(1464814,51,2,19,17,'모세가 하나님을 맞으려고 백성을 거느리고 진에서 나오매 그들이 산 기슭에 섰더니'),
(1464815,51,2,19,18,'시내산에 연기가 자욱하니 여호와께서 불 가운데서 거기 강림하심이라 그 연기가 옹기점 연기 같이 떠오르고 온 산이 크게 진동하며'),
(1464816,51,2,19,19,'나팔 소리가 점점 커질 때에 모세가 말한즉 하나님이 음성으로 대답하시더라'),
(1464817,51,2,19,20,'여호와께서 시내산 곧 그 산꼭대기에 강림하시고 그리로 모세를 부르시니 모세가 올라 가매'),
(1464818,51,2,19,21,'여호와께서 모세에게 이르시되 내려가서 백성을 신칙하라 백성이 돌파하고 나 여호와께로 와서 보려고 하다가 많이 죽을까 하노라'),
(1464819,51,2,19,22,'또 여호와께 가까이 하는 제사장들로 그 몸을 성결히 하게 하라 나 여호와가 그들을 돌격할까 하노라'),
(1464820,51,2,19,23,'모세가 여호와께 고하되 `주께서 우리에게 명하여 이르시기를 산사면에 지경을 세워 산을 거룩하게 하라 하셨사온즉 백성이 시내산에 오르지 못하리이다'''),
(1464821,51,2,19,24,'여호와께서 그에게 이르시되 가라 너는 내려가서 아론과 함께 올라오고 제사장들과 백성에게는 돌파하고 나 여호와에게로 올라오지 못하게 하라 내가 그들을 돌격할까 하노라'),
(1464822,51,2,19,25,'모세가 백성에게 내려가서 그들에게 고하니라'),
(1464823,51,2,20,1,'하나님이 이 모든 말씀으로 일러 가라사대'),
(1464824,51,2,20,2,'나는 너를 애굽 땅 종 되었던 집에서 인도하여 낸 너의 하나님 여호와로라'),
(1464825,51,2,20,3,'너는 나 외에는 다른 신들을 네게 있게 말지니라 !'),
(1464826,51,2,20,4,'너를 위하여 새긴 우상을 만들지 말고 또 위로 하늘에 있는 것이나 아래로 땅에 있는 것이나 땅 아래 물 속에 있는 것의 아무 형상이든지 만들지 말며'),
(1464827,51,2,20,5,'그것들에게 절하지 말며 그것들을 섬기지 말라 ! 나 여호와 너의 하나님은 질투하는 하나님인즉 나를 미워하는 자의 죄를 갚되 아비로부터 아들에게로 삼 사대까지 이르게 하거니와'),
(1464828,51,2,20,6,'나를 사랑하고 내 계명을 지키는 자에게는 천대까지 은혜를 베푸느니라'),
(1464829,51,2,20,7,'너는 너의 하나님 여호와의 이름을 망령되이 일컫지 말라 ! 나 여호와의 이름을 망령되이 일컫는 자를 죄 없다 하지 아니하리라'),
(1464830,51,2,20,8,'안식일을 기억하여 거룩히 지키라 !'),
(1464831,51,2,20,9,'엿새 동안은 힘써 네 모든 일을 행할 것이나'),
(1464832,51,2,20,10,'제 칠일은 너의 하나님 여호와의 안식일인즉 너나 네 아들이나 네 육축이나 네 문안에 유하는 객이라도 아무 일도 하지 말라'),
(1464833,51,2,20,11,'이는 엿새 동안에 나 여호와가 하늘과 땅과 바다와 그 가운데 모든 것을 만들고 제 칠일에 쉬었음이라 그러므로 나 여호와가 안식일을 복되게 하여 그 날을 거룩하게 하였느니라'),
(1464834,51,2,20,12,'네 부모를 공경하라 ! 그리하면 너의 하나님 나 여호와가 네게 준 땅에서 네 생명이 길리라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464835,51,2,20,13,'살인하지 말지니라 !'),
(1464836,51,2,20,14,'간음하지 말지니라 !'),
(1464837,51,2,20,15,'도적질하지 말지니라 !'),
(1464838,51,2,20,16,'네 이웃에 대하여 거짓 증거하지 말지니라 !'),
(1464839,51,2,20,17,'네 이웃의 집을 탐내지 말지니라 ! 네 이웃의 아내나, 그의 남종이나, 그의 여종이나, 그의 소나, 그의 나귀나, 무릇 네 이웃의 소유를 탐내지 말지니라 !'),
(1464840,51,2,20,18,'뭇 백성이 우뢰와 번개와 나팔소리와 산의 연기를 본지라 그들이 볼 때에 떨며 멀리 서서'),
(1464841,51,2,20,19,'모세에게 이르되 `당신이 우리에게 말씀하소서 우리가 들으리이다 하나님이 우리에게 말씀하시지 말게 하소서 우리가 죽을까 하나이다'''),
(1464842,51,2,20,20,'모세가 백성에게 이르되 `두려워 말라 ! 하나님이 강림하심은 너희를 시험하고 너희로 경외하여 범죄치 않게 하려 하심이니라'''),
(1464843,51,2,20,21,'백성은 멀리 섰고 모세는 하나님의 계신 암흑으로 가까이 가니라'),
(1464844,51,2,20,22,'여호와께서 모세에게 이르시되 너는 이스라엘 자손에게 이같이 이르라 내가 하늘에서부터 너희에게 말하는 것을 너희가 친히 보았으니'),
(1464845,51,2,20,23,'너희는 나를 비겨서 은으로 신상이나 금으로 신상을 너희를 위하여 만들지 말고'),
(1464846,51,2,20,24,'내게 토단을 쌓고 그 위에 너의 양과 소로 너의 번제와 화목제를 드리라 내가 무릇 내 이름을 기념하게 하는 곳에서 네게 강림하여 복을 주리라'),
(1464847,51,2,20,25,'네가 내게 돌로 단을 쌓거든 다듬은 돌로 쌓지 말라 네가 정으로 그것을 쪼면 부정하게 함이니라'),
(1464848,51,2,20,26,'너는 층계로 내 단에 오르지 말라 네 하체가 그 위에서 드러날까 함이니라'),
(1464849,51,2,21,1,'네가 백성 앞에 세울 율례는 이러하니라'),
(1464850,51,2,21,2,'네가 히브리 종을 사면 그가 육년 동안 섬길 것이요 제 칠년에는 값 없이 나가 자유할 것이요'),
(1464851,51,2,21,3,'그가 단신으로 왔으면 단신으로 나갈 것이요, 장가 들었으면 그 아내도 그와 함께 나가려니와'),
(1464852,51,2,21,4,'상전이 그에게 아내를 줌으로 그 아내가 자녀간 낳았으면 그 아내와 그 자식들은 상전에게 속할 것이요 그는 단신으로 나갈 것이로되'),
(1464853,51,2,21,5,'종이 진정으로 말하기를 `내가 상전과 내 처자를 사랑하니 나가서 자유하지 않겠노라'' 하면'),
(1464854,51,2,21,6,'상전이 그를 데리고 재판장에게로 갈 것이요 또 그를 문이나 문설주 앞으로 데리고 가서 그것에다가 송곳으로 그 귀를 뚫을 것이라 그가 영영히 그 상전을 섬기리라'),
(1464855,51,2,21,7,'사람이 그 딸을 여종으로 팔았으면 그는 남종 같이 나오지 못할지며'),
(1464856,51,2,21,8,'만일 상전이 그를 기뻐 아니하여 상관치 아니하면 그를 속신케 할것이나 그 여자를 속임이 되었으니 타국인에게 팔지 못할 것이요'),
(1464857,51,2,21,9,'만일 그를 자기 아들에게 주기로 하였으면 그를 딸 같이 대접 할것이요'),
(1464858,51,2,21,10,'만일 상전이 달리 장가를 들지라도 그의 의복과 음식과 동침하는 것은 끊지 못할 것이요'),
(1464859,51,2,21,11,'이 세가지를 시행하지 아니하면 그는 속전을 내지 않고 거저 나가게 할 것이니라'),
(1464860,51,2,21,12,'사람을 쳐 죽인 자는 반드시 죽일 것이나'),
(1464861,51,2,21,13,'만일 사람이 계획한 일이 아니라 나 하나님이 사람을 그 손에 붙임이면 내가 위하여 한 곳을 정하리니 그 사람이 그리로 도망할 것이며'),
(1464862,51,2,21,14,'사람이 그 이웃을 짐짓 모살하였으면 너는 그를 내 단에서라도 잡아내어 죽일지니라 !'),
(1464863,51,2,21,15,'자기 아비나 어미를 치는 자는 반드시 죽일지니라 !'),
(1464864,51,2,21,16,'사람을 후린 자가 그 사람을 팔았든지 자기 수하에 두었든지 그를 반드시 죽일지니라 !'),
(1464865,51,2,21,17,'그 아비나 어미를 저주하는 자는 반드시 죽일지니라 !'),
(1464866,51,2,21,18,'사람이 서로 싸우다가 하나가 돌이나 주먹으로 그 적수를 쳤으나 그가 죽지 않고 자리에 누었다가'),
(1464867,51,2,21,19,'지팡이를 짚고 기동하면 그를 친 자가 형벌은 면하되 기간 손해를 배상하고 그로 전치되게 할지니라'),
(1464868,51,2,21,20,'사람이 매로 그 남종이나 여종을 쳐서 당장에 죽으면 반드시 형벌을 받으려니와'),
(1464869,51,2,21,21,'그가 일일이나 이일을 연명하면 형벌을 면하리니 그는 상전의 금전임이니라'),
(1464870,51,2,21,22,'사람이 서로 싸우다가 아이 밴 여인을 다쳐 낙태케 하였으나 다른 해가 없으면 그 남편의 청구대로 반드시 벌금을 내되 재판장의 판결을 좇아 낼 것이니라'),
(1464871,51,2,21,23,'그러나 다른 해가 있으면 갚되 생명은 생명으로,'),
(1464872,51,2,21,24,'눈은 눈으로, 이는 이로, 손은 손으로, 발은 발로'),
(1464873,51,2,21,25,'데운 것은 데움으로, 상하게 한것은 상함으로, 때린 것은 때림으로 갚을지니라 !'),
(1464874,51,2,21,26,'사람이 그 남종의 한 눈이나 여종의 한 눈을 쳐서 상하게 하면 그 눈 대신에 그를 놓을 것이며'),
(1464875,51,2,21,27,'그 남종의 한 이나 여종의 한 이를 쳐서 빠뜨리면 그 이 대신에 그를 놓을지니라'),
(1464876,51,2,21,28,'소가 남자나 여자를 받아서 죽이면 그 소는 반드시 돌에 맞아 죽을 것이요 그 고기는 먹지 말 것이며 임자는 형벌을 면하려니와'),
(1464877,51,2,21,29,'소는 본래 받는 버릇이 있고 그 임자는 그로 인하여 경고를 받았으되 단속하지 아니하므로 남녀 간에 받아 죽이면 그 소는 돌로 쳐 죽일 것이고 임자도 죽일 것이며'),
(1464878,51,2,21,30,'만일 그에게 속죄금을 명하면 무릇 그 명한 것을 생명의 속으로 낼 것이요'),
(1464879,51,2,21,31,'아들을 받든지 딸을 받든지 이 율례대로 그 임자에게 행할 것이며'),
(1464880,51,2,21,32,'소가 만일 남종이나 여종을 받으면 소 임자가 은 삼십 세겔을 그 상전에게 줄 것이요 소는 돌에 맞아 죽을지니라 !'),
(1464881,51,2,21,33,'사람이 구덩이를 열어 두거나 구덩이를 파고 덮지 아니함으로 소나 나귀가 거기에 빠지면'),
(1464882,51,2,21,34,'그 구덩이 주인이 잘 조처하여 짐승의 임자에게 돈을 줄 것이요 죽은 것은 그의 차지가 될지니라 !'),
(1464883,51,2,21,35,'이 사람의 소가 저 사람의 소를 받아 죽이면 산 소를 팔아 그 값을 반분하고 죽은 것도 반분하려니와'),
(1464884,51,2,21,36,'그 소가 본래 받는 버릇이 있는 줄을 알고도 그 임자가 단속하지 아니하였으면 그는 소로 소를 갚을 것이요 죽은 것은 그의 차지가 될지니라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464885,51,2,22,1,'사람이 소나 양을 도적질하여 잡거나 팔면 그는 소 하나에 소 다섯으로 갚고 양 하나에 양 넷으로 갚을지니라 !'),
(1464886,51,2,22,2,'도적이 뚫고 들어옴을 보고 그를 쳐 죽이면 피 흘린 죄가 없으나'),
(1464887,51,2,22,3,'해 돋은 후이면 피 흘린 죄가 있으리라 도적은 반드시 배상할 것이나 배상할 것이 없으면 그 몸을 팔아 그 도적질한 것을 배상할 것이요'),
(1464888,51,2,22,4,'도적질한 것이 살아 그 손에 있으면 소나 나귀나 양을 무론하고 갑절을 배상할지니라 !'),
(1464889,51,2,22,5,'사람이 밭에서나 포도원에서 먹이다가 그 짐승을 놓아서 남의 밭에서 먹게 하면 자기 밭의 제일 좋은 것과 자기 포도원의 제일 좋은 것으로 배상할지니라 !'),
(1464890,51,2,22,6,'불이 나서 가시나무에 미쳐 낟가리나 거두지 못한 곡식이나 전원을 태우면 불 놓은 자가 반드시 배상할지니라 !'),
(1464891,51,2,22,7,'사람이 돈이나 물품을 이웃에게 맡겨 지키게 하였다가 그 이웃의 집에서 봉적하였는데 그 도적이 잡히면 갑절을 배상할 것이요'),
(1464892,51,2,22,8,'도적이 잡히지 아니하면 그 집 주인이 재판장 앞에 가서 자기가 그 이웃의 물품에 손 댄 여부의 조사를 받을 것이며'),
(1464893,51,2,22,9,'어떠한 과실에든지, 소에든지, 나귀에든지, 양에든지, 의복에든지, 또는 아무 잃은 물건에든지, 그것에 대하여 혹이 이르기를 이것이 그것이라 하면 두 편이 재판장 앞에 나아갈 것이요 재판장이 죄 있다고 하는 자가 그 상대편에게 갑절을 배상할지니라 !'),
(1464894,51,2,22,10,'사람이 나귀나 소나 양이나 다른 짐승을 이웃에게 맡겨 지키게 하였다가 죽거나 상하거나 몰려가도 본 사람이 없으면'),
(1464895,51,2,22,11,'두 사람 사이에 맡은 자가 이웃의 것에 손을 대지 아니하였다고 여호와로 맹세할 것이요 그 임자는 그대로 믿을 것이며 그 사람은 배상하지 아니하려니와'),
(1464896,51,2,22,12,'만일 자기에게서 봉적하였으면 그 임자에게 배상할 것이며'),
(1464897,51,2,22,13,'만일 찢겼으면 그것을 가져다가 증거할 것이요 그 찢긴 것에 대하여 배상하지 않을지니라 !'),
(1464898,51,2,22,14,'만일 이웃에게 빌어온 것이 그 임자가 함께 있지 아니할 때에 상하거나 죽으면 반드시 배상하려니와'),
(1464899,51,2,22,15,'그 임자가 그것과 함께 하였으면 배상하지 않을지며 세 낸것도 세를 위하여 왔은즉 배상하지 않을지니라 !'),
(1464900,51,2,22,16,'사람이 정혼하지 아니한 처녀를 꾀어 동침하였으면 빙폐를 드려 아내로 삼을 것이요'),
(1464901,51,2,22,17,'만일 그 아비가 그로 그에게 주기를 거절하면 그는 처녀에게 빙폐하는 일례로 돈을 낼지니라 !'),
(1464902,51,2,22,18,'너는 무당을 살려 두지 말지니라 !'),
(1464903,51,2,22,19,'짐승과 행음하는 자는 반드시 죽일지니라 !'),
(1464904,51,2,22,20,'여호와 외에 다른 신에게 희생을 드리는 자는 멸할지니라 !'),
(1464905,51,2,22,21,'너는 이방 나그네를 압제하지 말며 그들을 학대하지 말라 너희도 애굽 땅에서 나그네이었었음이니라'),
(1464906,51,2,22,22,'너는 과부나 고아를 해롭게 하지 말라 !'),
(1464907,51,2,22,23,'네가 만일 그들을 해롭게 하므로 그들이 내게 부르짖으면 내가 반드시 그 부르짖음을 들을지라'),
(1464908,51,2,22,24,'나의 노가 맹렬하므로 내가 칼로 너희를 죽이리니 너희 아내는 과부가 되고 너희 자녀는 고아가 되리라'),
(1464909,51,2,22,25,'네가 만일 너와 함께한 나의 백성 중 가난한 자에게 돈을 꾸이거든 너는 그에게 채주같이 하지 말며 변리를 받지 말 것이며'),
(1464910,51,2,22,26,'네가 만일 이웃의 옷을 전당잡거든 해가 지기 전에 그에게 돌려보내라'),
(1464911,51,2,22,27,'그 몸을 가릴 것이 이뿐이라 이는 그 살의 옷인즉 그가 무엇을 입고 자겠느냐 ? 그가 내게 부르짖으면 내가 들으리니 나는 자비한자임이니라'),
(1464912,51,2,22,28,'너는 재판장을 욕하지 말며 백성의 유사를 저주하지 말지니라 !'),
(1464913,51,2,22,29,'너는 너의 추수한 것과 너의 짜낸 즙을 드리기에 더디게 말지며 너의 처음 난 아들들을 내게 줄지며'),
(1464914,51,2,22,30,'너의 소와 양도 그 일례로 하되 칠일 동안 어미와 함께 있게 하다가 팔일만에 내게 줄지니라 !'),
(1464915,51,2,22,31,'너희는 내게 거룩한 사람이 될지니 들에서 짐승에게 찢긴 것의 고기를 먹지 말고 개에게 던질지니라 !'),
(1464916,51,2,23,1,'너는 허망한 풍설을 전파하지 말며 악인과 연합하여 무함하는 증인이 되지 말며'),
(1464917,51,2,23,2,'다수를 따라 악을 행하지 말며 송사에 다수를 따라 부정당한 증거를 하지 말며'),
(1464918,51,2,23,3,'가난한 자의 송사라고 편벽되이 두호하지 말지니라 !'),
(1464919,51,2,23,4,'네가 만일 네 원수의 길 잃은 소나 나귀를 만나 거든 반드시 그 사람에게로 돌릴지며'),
(1464920,51,2,23,5,'네가 만일 너를 미워하는 자의 나귀가 짐을 싣고 엎드러짐을 보거든 삼가 버려두지 말고 그를 도와 그 짐을 부리울지니라 !'),
(1464921,51,2,23,6,'너는 가난한 자의 송사라고 공평치 않게 하지 말며'),
(1464922,51,2,23,7,'거짓 일을 멀리하며 무죄한 자와 의로운 자를 죽이지 말라 ! 나는 악인을 의롭다 하지 아니하겠노라'),
(1464923,51,2,23,8,'너는 뇌물을 받지 말라 ! 뇌물은 밝은 자의 눈을 어둡게 하고 의로운 자의 말을 굽게 하느니라'),
(1464924,51,2,23,9,'너는 이방 나그네를 압제하지 말라 ! 너희가 애굽 땅에서 나그네 되었었은즉 나그네의 정경을 아느니라'),
(1464925,51,2,23,10,'너는 육년 동안은 너의 땅에 파종하여 그 소산을 거두고'),
(1464926,51,2,23,11,'제 칠년에는 갈지말고 묵여 두어서 네 백성의 가난한 자로 먹게하라 그 남은 것은 들짐승이 먹으리라 너의 포도원과 감람원도 그리할지니라'),
(1464927,51,2,23,12,'너는 육일 동안에 네 일을 하고 제 칠일에는 쉬라 네 소와 나귀가 쉴 것이며 네 계집 종의 자식과 나그네가 숨을 돌리리라'),
(1464928,51,2,23,13,'내가 네게 이른 모든 일을 삼가 지키고 다른 신들의 이름은 부르지도 말며 네 입에서 들리게도 말지니라'),
(1464929,51,2,23,14,'너는 매년 삼차 내게 절기를 지킬지니라 !'),
(1464930,51,2,23,15,'너는 무교병의 절기를 지키라 ! 내가 네게 명한대로 아빕월의 정한때에 칠일동안 무교병을 먹을지니 이는 그 달에 네가 애굽에서 나왔음이라 빈 손으로 내게 보이지 말지니라 !'),
(1464931,51,2,23,16,'맥추절을 지키라 ! 이는 네가 수고하여 밭에 뿌린 것의 첫 열매를 거둠이니라 수장절을 지키라 ! 이는 네가 수고하여 이룬 것을 연종에 밭에서부터 거두어 저장함이니라'),
(1464932,51,2,23,17,'너의 모든 남자는 매년 세번씩 주 여호와께 보일지니라 !'),
(1464933,51,2,23,18,'너는 내 희생의 피를 유교병과 함께 드리지 말며 내 절기 희생의 기름을 아침까지 남겨 두지 말지니라'),
(1464934,51,2,23,19,'너의 토지에서 처음 익은 열매의 첫것을 가져다가 너의 하나님 여호와의 전에 드릴지니라 너는 염소 새끼를 그 어미의 젖으로 삶지 말지니라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464935,51,2,23,20,'내가 사자를 네 앞서 보내어 길에서 너를 보호하여 너로 내가 예비한 곳에 이르게 하리니'),
(1464936,51,2,23,21,'너희는 삼가 그 목소리를 청종하고 그를 노엽게 하지 말라 ! 그가 너희 허물을 사하지 아니할 것은 내 이름이 그에게 있음이니라'),
(1464937,51,2,23,22,'네가 그 목소리를 잘 청종하고 나의 모든 말대로 행하면 내가 네 원수에게 원수가 되고 네 대적에게 대적이 될지라'),
(1464938,51,2,23,23,'나의 사자가 네 앞서가서 너를 아모리 사람과, 헷 사람과, 브리스 사람과, 가나안 사람과, 히위 사람과, 여부스 사람에게로 인도하고 나는 그들을 끊으리니'),
(1464939,51,2,23,24,'너는 그들의 신을 숭배하지 말며 섬기지 말며 그들의 소위를 본받지 말며 그것들을 다 훼파하며 그 주상을 타파하고'),
(1464940,51,2,23,25,'너의 하나님 여호와를 섬기라 ! 그리하면 여호와가 너희의 양식과 물에 복을 내리고 너희 중에 병을 제하리니'),
(1464941,51,2,23,26,'네 나라에 낙태하는 자가 없고 잉태치 못하는 자가 없을 것이라 내가 너의 날 수를 채우리라'),
(1464942,51,2,23,27,'내가 내 위엄을 네 앞서 보내어 너의 이를 곳의 모든 백성을 파하고 너의 모든 원수로 너를 등지게 할 것이며'),
(1464943,51,2,23,28,'내가 왕벌을 네 앞에 보내리니 그 벌이 히위 족속과, 가나안 족속과, 헷 족속을 네 앞에서 쫓아내리라'),
(1464944,51,2,23,29,'그러나 그 땅이 황무하게 되어 들짐승이 번성하여 너희를 해할까 하여 일년 안에는 그들을 네 앞에서 쫓아내지 아니하고'),
(1464945,51,2,23,30,'네가 번성하여 그 땅을 기업으로 얻을 때까지 내가 그들을 네 앞에서 조금씩 쫓아내리라'),
(1464946,51,2,23,31,'너의 지경을 홍해에서부터 블레셋 바다까지 광야에서부터 하수까지 정하고 그 땅의 거민을 네 앞에서 쫓아낼지라'),
(1464947,51,2,23,32,'너는 그들과 그들의 신과 언약하지 말라 !'),
(1464948,51,2,23,33,'그들이 네 땅에 머무르지 못할것은 그들이 너로 내게 범죄케 할까 두려움이라 네가 그 신을 섬기면 그것이 너의 올무가 되리라'),
(1464949,51,2,24,1,'또 모세에게 이르시되 너는 아론과 나답과 아비후와 이스라엘 장로 칠십인과 함께 여호와에게로 올라와 멀리서 경배하고'),
(1464950,51,2,24,2,'너 모세만 여호와에게 가까이 나아오고 그들은 가까이 나아오지 말며 백성은 너와 함께 올라오지 말지니라 !'),
(1464951,51,2,24,3,'모세가 와서 여호와의 모든 말씀과 그 모든 율례를 백성에게 고하매 그들이 한 소리로 응답하여 가로되 ''여호와의 명하신 모든 말씀을 우리가 준행하리이다 !'''),
(1464952,51,2,24,4,'모세가 여호와의 모든 말씀을 기록하고 이른 아침에 일어나 산 아래 단을 쌓고 이스라엘 십 이 지파대로 열 두 기둥을 세우고'),
(1464953,51,2,24,5,'이스라엘 자손의 청년들을 보내어 번제와 소로 화목제를 여호와께 드리게 하고'),
(1464954,51,2,24,6,'모세가 피를 취하여 반은 양푼에 담고, 반은 단에 뿌리고'),
(1464955,51,2,24,7,'언약서를 가져 백성에게 낭독하여 들리매 그들이 가로되 `여호와의 모든 말씀을 우리가 준행하리이다'''),
(1464956,51,2,24,8,'모세가 그 피를 취하여 백성에게 뿌려 가로되 `이는 여호와께서 이 모든 말씀에 대하여 너희와 세우신 언약의 피니라'''),
(1464957,51,2,24,9,'모세와 아론과, 나답과, 아비후와 이스라엘 장로 칠십인이 올라가서'),
(1464958,51,2,24,10,'이스라엘 하나님을 보니 그 발 아래에는 청옥을 편듯하고 하늘 같이 청명하더라'),
(1464959,51,2,24,11,'하나님이 이스라엘의 존귀한 자들에게 손을 대지 아니하셨고 그들은 하나님을 보고 먹고 마셨더라'),
(1464960,51,2,24,12,'여호와께서 모세에게 이르시되 너는 산에 올라 내게로 와서 거기 있으라 너로 그들을 가르치려고 내가 율법과 계명을 친히 기록한 돌판을 네게 주리라'),
(1464961,51,2,24,13,'모세가 그 종자 여호수아와 함께 일어나 하나님의 산으로 올라가며'),
(1464962,51,2,24,14,'장로들에게 이르되 `너희는 여기서 우리가 너희에게로 돌아오기까지 기다리라 아론과 훌이 너희와 함께하리니 무릇 일이 있는 자는 그들에게로 나아갈지니라'' 하고'),
(1464963,51,2,24,15,'모세가 산에 오르매 구름이 산을 가리며'),
(1464964,51,2,24,16,'여호와의 영광이 시내산 위에 머무르고 구름이 육일 동안 산을 가리더니 제 칠일에 여호와께서 구름 가운데 모세를 부르시니라'),
(1464965,51,2,24,17,'산 위의 여호와의 영광이 이스라엘 자손의 눈에 맹렬한 불 같이 보였고'),
(1464966,51,2,24,18,'모세는 구름 속으로 들어가서 산 위에 올랐으며 사십일 사십야를 산에 있으니라'),
(1464967,51,2,25,1,'여호와께서 모세에게 일러 가라사대'),
(1464968,51,2,25,2,'이스라엘 자손에게 명하여 내게 예물을 가져오라 하고 무릇 즐거운 마음으로 내는 자에게서 내게 드리는 것을 너희는 받을지니라'),
(1464969,51,2,25,3,'너희가 그들에게서 받을 예물은 이러하니 금과 은과 놋과'),
(1464970,51,2,25,4,'청색, 자색, 홍색실과, 가는 베실과, 염소털과,'),
(1464971,51,2,25,5,'붉은 물 들인 수양의 가죽과, 해달의 가죽과, 조각목과,'),
(1464972,51,2,25,6,'등유와 관유에 드는 향품과 분향할 향을 만들 향품과'),
(1464973,51,2,25,7,'호마노며 에봇과 흉패에 물릴 보석이니라'),
(1464974,51,2,25,8,'내가 그들 중에 거할 성소를 그들을 시켜 나를 위하여 짓되'),
(1464975,51,2,25,9,'무릇 내가 네게 보이는대로 장막의 식양과 그 기구의 식양을 따라 지을지니라'),
(1464976,51,2,25,10,'그들은 조각목으로 궤를 짓되 장이 이 규빗 반, 광이 일 규빗 반, 고가 일 규빗 반이 되게 하고'),
(1464977,51,2,25,11,'너는 정금으로 그것을 싸되 그 안팎을 싸고 윗가로 돌아가며 금테를 두르고'),
(1464978,51,2,25,12,'금고리 넷을 부어 만들어 그 네 발에 달되 이편에 두 고리요, 저편에 두 고리며'),
(1464979,51,2,25,13,'조각목으로 채를 만들고 금으로 싸고'),
(1464980,51,2,25,14,'그 채를 궤 양편 고리에 꿰어서 궤를 메게 하며'),
(1464981,51,2,25,15,'채를 궤의 고리에 꿴대로 두고 빼어내지 말지며'),
(1464982,51,2,25,16,'내가 네게 줄 증거판을 궤 속에 둘지며'),
(1464983,51,2,25,17,'정금으로 속죄소를 만들되 장이 이 규빗 반,광이 일 규빗 반이 되게 하고'),
(1464984,51,2,25,18,'금으로 그룹 둘을 속죄소 두 끝에 쳐서 만들되');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1464985,51,2,25,19,'한 그룹은 이 끝에,한 그룹은 저 끝에 곧 속죄소 두 끝에 속죄소와 한 덩이로 연하게 할지며'),
(1464986,51,2,25,20,'그룹들은 그 날개를 높이 펴서 그 날개로 속죄소를 덮으며 그 얼굴을 서로 대하여 속죄소를 향하게 하고'),
(1464987,51,2,25,21,'속죄소를 궤 위에 얹고 내가 네게 줄 증거판을 궤 속에 넣으라'),
(1464988,51,2,25,22,'거기서 내가 너와 만나고 속죄소 위 곧 증거궤 위에 있는 두 그룹 사이에서 내가 이스라엘 자손을 위하여 네게 명할 모든 일을 네게 이르리라'),
(1464989,51,2,25,23,'너는 조각목으로 상을 만들되 장이 이 규빗, 광이 일 규빗, 고가 일 규빗 반이 되게 하고'),
(1464990,51,2,25,24,'정금으로 싸고 주위에 금테를 두르고'),
(1464991,51,2,25,25,'그 사면에 손바닥 넓이만한 턱을 만들고 그 턱 주위에 금으로 테를 만들고'),
(1464992,51,2,25,26,'그것을 위하여 금고리 넷을 만들어 네 발위 네 모퉁이에 달되'),
(1464993,51,2,25,27,'턱 곁에 달라 이는 상 멜 채를 꿸 곳이며'),
(1464994,51,2,25,28,'또 조각목으로 그 채를 만들고 금으로 싸라 상을 이것으로 멜 것이니라'),
(1464995,51,2,25,29,'너는 대접과, 숟가락과, 병과 붓는 잔을 만들되 정금으로 만들지며'),
(1464996,51,2,25,30,'상 위에 진설병을 두어 항상 내 앞에 있게 할지니라 !'),
(1464997,51,2,25,31,'너는 정금으로 등대를 쳐서 만들되 그 밑판과, 줄기와, 잔과, 꽃받침과, 꽃을 한 덩이로 연하게 하고'),
(1464998,51,2,25,32,'가지 여섯을 등대 곁에서 나오게 하되 그 세 가지는 이편으로 나오고 그 세 가지는 저편으로 나오게 하며'),
(1464999,51,2,25,33,'이편 가지에 살구 꽃 형상의 잔 셋과 꽃받침과 꽃이 있게 하고 저편 가지에도 살구꽃 형상의 잔 셋과 꽃받침과 꽃이 있게 하여 등대에서 나온 여섯 가지를 같게 할지며'),
(1465000,51,2,25,34,'등대 줄기에는 살구꽃 형상의 잔 넷과 꽃받침과 꽃이 있게 하고'),
(1465001,51,2,25,35,'등대에서 나온 여섯 가지를 위하여 꽃받침이 있게 하되 두 가지 아래 한 꽃받침이 있어 줄기와 연하게 하며 또 두 가지 아래 한 꽃받침이 있어 줄기와 연하게 하고'),
(1465002,51,2,25,36,'그 꽃받침과 가지를 줄기와 연하게 하여 전부를 정금으로 쳐 만들고'),
(1465003,51,2,25,37,'등잔 일곱을 만들어 그 위에 두어 앞을 비추게 하며'),
(1465004,51,2,25,38,'그 불집게와 불똥 그릇도 정금으로 만들지니'),
(1465005,51,2,25,39,'등대와 이 모든 기구를 정금 한 달란트로 만들되'),
(1465006,51,2,25,40,'너는 삼가 이 산에서 네게 보인 식양대로 할지니라 !'),
(1465007,51,2,26,1,'너는 성막을 만들되 앙장 열 폭을 가늘게 꼰 베실과, 청색, 자색, 홍색실로 그룹을 공교히 수 놓아 만들지니'),
(1465008,51,2,26,2,'매 폭의 장은 이십 팔 규빗,광은 사 규빗으로 각 폭의 장단을 같게 하고'),
(1465009,51,2,26,3,'그 앙장 다섯 폭을 서로 연하며, 다른 다섯 폭도 서로 연하고'),
(1465010,51,2,26,4,'그 앙장의 연락할 말폭 가에 청색 고를 만들며, 다른 연락할 말폭가에도 그와 같이 하고'),
(1465011,51,2,26,5,'앙장 말폭 가에 고 오십을 달며, 다른 앙장 말폭 가에도 고 오십을 달고 그 고들을 서로 대하게 하고'),
(1465012,51,2,26,6,'금 갈고리 오십을 만들고, 그 갈고리로 앙장을 연합하여 한 성막을 이룰지며'),
(1465013,51,2,26,7,'그 성막을 덮는 막 곧 앙장을 염소털로 만들되 열 한폭을 만들지며'),
(1465014,51,2,26,8,'각 폭의 장은 삼십 규빗,광은 사 규빗으로 열 한폭의 장단을 같게 하고'),
(1465015,51,2,26,9,'그 앙장 다섯 폭을 서로 연하며, 또 여섯 폭을 서로 연하고, 그 여섯째 폭 절반은 성막 전면에 접어 드리우고'),
(1465016,51,2,26,10,'앙장을 연락할 말폭 가에 고 오십을 달며, 다른 연락할 말폭 가에도 고 오십을 달고'),
(1465017,51,2,26,11,'놋 갈고리 오십을 만들고, 그 갈고리로 그 고를 꿰어 연합하여 한 막이 되게 하고'),
(1465018,51,2,26,12,'그 막 곧 앙장의 나머지 그 반폭은 성막 뒤에 드리우고'),
(1465019,51,2,26,13,'막 곧 앙장의 길이의 남은 것은 이편에 한 규빗,저편에 한 규빗씩 성막 좌우 양편에 덮어 드리우고'),
(1465020,51,2,26,14,'붉은 물 들인 수양의 가죽으로 막의 덮개를 만들고, 해달의 가죽으로 그 웃덮개를 만들지니라 !'),
(1465021,51,2,26,15,'너는 조각목으로 성막을 위하여 널판을 만들어 세우되'),
(1465022,51,2,26,16,'각 판의 장은 십 규빗,광은 일 규빗 반으로 하고'),
(1465023,51,2,26,17,'각 판에 두 촉씩 내어 서로 연하게 하되 너는 성막 널판을 다 그와 같이 하라'),
(1465024,51,2,26,18,'너는 성막을 위하여 널판을 만들되, 남편을 위하여 널판 스물을 만들고'),
(1465025,51,2,26,19,'스무 널판 아래 은받침 마흔을 만들지니 이 널판 아래에도 그 두촉을 위하여 두 받침을 만들고 저 널판 아래에도 그 두 촉을 위하여 두 받침을 만들지라'),
(1465026,51,2,26,20,'성막 다른 편 곧 그 북편을 위하여도 널판 스물로 하고'),
(1465027,51,2,26,21,'은받침 마흔을 이 널판 아래에도 두 받침,저 널판 아래에도 두 받침으로 하며'),
(1465028,51,2,26,22,'성막 뒤 곧 그 서편을 위하여는 널판 여섯을 만들고'),
(1465029,51,2,26,23,'성막 뒤 두 모퉁이 편을 위하여는 널판 둘을 만들되'),
(1465030,51,2,26,24,'아래에서부터 위까지 각기 두겹 두께로 하여 윗고리에 이르게 하고 두 모퉁이 편을 다 그리하며'),
(1465031,51,2,26,25,'그 여덟 널판에는 은받침이 열 여섯이니 이 판 아래에도 두 받침이요, 저 판 아래에도 두 받침이니라'),
(1465032,51,2,26,26,'너는 조각목으로 띠를 만들지니 성막 이편 널판을 위하여 다섯이요'),
(1465033,51,2,26,27,'성막 저편 널판을 위하여 다섯이요, 성막 뒤 곧 서편 널판을 위하여 다섯이요,'),
(1465034,51,2,26,28,'널판 가운데 있는 중간 띠는 이 끝에서 저 끝에 미치게 하고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465035,51,2,26,29,'그 널판들을 금으로 싸고 그 널판들의 띠를 꿸 금고리를 만들고 그 띠를 금으로 싸라'),
(1465036,51,2,26,30,'너는 산에서 보인 식양대로 성막을 세울지니라 !'),
(1465037,51,2,26,31,'너는 청색 자색 홍색실과 가늘게 꼰 베실로 짜서 장을 만들고 그 위에 그룹들을 공교히 수 놓아서'),
(1465038,51,2,26,32,'금 갈고리로 네 기둥 위에 드리우되 그 네 기둥을 조각목으로 만들고 금으로 싸서 네 은받침 위에 둘지며'),
(1465039,51,2,26,33,'그 장을 갈고리 아래 드리운 후에 증거궤를 그 장안에 들여 놓으라 그 장이 너희를 위하여 성소와 지성소를 구별하리라'),
(1465040,51,2,26,34,'너는 지성소에 있는 증거궤 위에 속죄소를 두고'),
(1465041,51,2,26,35,'그 장 바깥 북편에 상을 놓고 남편에 등대를 놓아 상과 대하게 할지며'),
(1465042,51,2,26,36,'청색, 자색, 홍색실과, 가늘게 꼰 베실로 수 놓아 짜서 성막 문을 위하여 장을 만들고'),
(1465043,51,2,26,37,'그 문장을 위하여 기둥 다섯을 조각목으로 만들어 금으로 싸고 그 갈고리도 금으로 만들찌며 또 그 기둥을 위하여 받침 다섯을 놋으로 부어 만들지니라 !'),
(1465044,51,2,27,1,'너는 조각목으로 장이 오 규빗, 광이 오 규빗의 단을 만들되 네모 반듯하게 하며 고는 삼 규빗으로 하고'),
(1465045,51,2,27,2,'그 네 모퉁이 위에 뿔을 만들되 그 뿔이 그것에 연하게 하고 그 단을 놋으로 쌀지며'),
(1465046,51,2,27,3,'재를 담는 통과, 부삽과, 대야와, 고기 갈고리와, 불 옮기는 그릇을 만들되 단의 그릇을 다 놋으로 만들지며'),
(1465047,51,2,27,4,'단을 위하여 놋으로 그물을 만들고 그 위 네 모퉁이에 놋고리 넷을 만들고'),
(1465048,51,2,27,5,'그물은 단 사면 가장자리 아래 곧 단 절반에 오르게 할지며'),
(1465049,51,2,27,6,'또 그 단을 위하여 채를 만들되 조각목으로 만들고 놋으로 쌀지며'),
(1465050,51,2,27,7,'단 양편 고리에 그 채를 꿰어 단을 메게 할지며'),
(1465051,51,2,27,8,'단은 널판으로 비게 만들되 산에서 네게 보인대로 그들이 만들지니라 !'),
(1465052,51,2,27,9,'너는 성막의 뜰을 만들찌니 남을 향하여 뜰 남편에 광이 백 규빗의 세마포장을 쳐서 그 한 편을 당하게 할지니'),
(1465053,51,2,27,10,'그 기둥이 스물이며 그 받침 스물은 놋으로 하고 그 기둥의 갈고리와 가름대는 은으로 할찌며'),
(1465054,51,2,27,11,'그 북편에도 광이 백 규빗의 포장을 치되 그 기둥이 스물이며 그 기둥의 받침 스물은 놋으로 하고 그 기둥의 갈고리와 가름대는 은으로 할지며'),
(1465055,51,2,27,12,'뜰의 옆 곧 서편에 광 오십 규빗의 포장을 치되 그 기둥이 열이요, 받침이 열이며'),
(1465056,51,2,27,13,'동을 향하여 뜰 동편의 광도 오십 규빗이 될지며'),
(1465057,51,2,27,14,'문 이편을 위하여 포장이 십 오 규빗이며, 그 기둥이 셋이요, 받침이 셋이요'),
(1465058,51,2,27,15,'문 저편을 위하여도 포장이 십오 규빗이며, 그 기둥이 셋이요, 받침이 셋이며'),
(1465059,51,2,27,16,'뜰 문을 위하여는 청색, 자색, 홍색실과, 가늘게 꼰 베실로 수 놓아 짠 이십 규빗의 장이 있게 할지니 그 기둥이 넷이요, 받침이 넷이며'),
(1465060,51,2,27,17,'뜰 사면 모든 기둥의 가름대와 갈고리는 은이요, 그 받침은 놋이며'),
(1465061,51,2,27,18,'뜰의 장은 백 규빗이요, 광은 오십 규빗이요, 세마포장의 고는 오규빗이요, 그 받침은 놋이며'),
(1465062,51,2,27,19,'성막에서 쓰는 모든 기구와 그 말뚝과 뜰의 포장 말뚝을 다 놋으로 할지니라 !'),
(1465063,51,2,27,20,'너는 또 이스라엘 자손에게 명하여 감람으로 찧어낸 순결한 기름을 등불을 위하여 네게로 가져오게 하고 끊이지 말고 등불을 켜되'),
(1465064,51,2,27,21,'아론과 그 아들들로 회막한 증거궤 앞 휘장 밖에서 저녁부터 아침까지 항상 여호와 앞에 그 등불을 간검하게 하라 ! 이는 이스라엘 자손의 대대로 영원한 규례니라'),
(1465065,51,2,28,1,'너는 이스라엘 자손 중 네 형 아론과 그 아들들 곧 나답과, 아비후와, 엘르아살과, 이다말을 그와 함께 네게로 나아오게 하여 나를 섬기는 제사장 직분을 행하게 하되'),
(1465066,51,2,28,2,'네 형 아론을 위하여 거룩한 옷을 지어서 영화롭고 아름답게 할지니'),
(1465067,51,2,28,3,'너는 무릇 마음에 지혜 있는자, 곧 내가 지혜로운 영으로 채운 자들에게 말하여 아론의 옷을 지어 그를 거룩하게 하여 내게 제사장 직분을 행하게 하라'),
(1465068,51,2,28,4,'그들의 지을 옷은 이러하니 곧 흉패와, 에봇과, 겉옷과, 반포 속옷과, 관과, 띠라 그들이 네 형 아론과 그 아들들을 위하여 거룩한 옷을 지어 아론으로 내게 제사장 직분을 행하게 할지며'),
(1465069,51,2,28,5,'그들의 쓸것은 금실과, 청색, 자색, 홍색실과, 가늘게 꼰 베실이니라'),
(1465070,51,2,28,6,'그들이 금실과, 청색, 자색, 홍색실과, 가늘게 꼰 베실로 공교히 짜서 에봇을 짓되'),
(1465071,51,2,28,7,'그것에 견대 둘을 달아 그 두 끝을 연하게 하고'),
(1465072,51,2,28,8,'에봇 위에 매는 띠는 에봇 짜는 법으로 금실과, 청색, 자색, 홍색실과, 가늘게 꼰 베실로 에봇에 공교히 붙여 짤지며'),
(1465073,51,2,28,9,'호마노 두개를 취하여 그 위에 이스라엘 아들들의 이름을 새기되'),
(1465074,51,2,28,10,'그들의 연치대로 여섯 이름을 한 보석에 나머지 여섯 이름은 다른 보석에'),
(1465075,51,2,28,11,'보석을 새기는 자가 인에 새김 같이 너는 이스라엘 아들들의 이름을 그 두 보석에 새겨 금테에 물리고'),
(1465076,51,2,28,12,'그 두 보석을 에봇 두 견대에 붙여 이스라엘 아들들의 기념 보석을 삼되 아론이 여호와 앞에서 그들의 이름을 그 두 어깨에 메어서 기념이 되게 할지며'),
(1465077,51,2,28,13,'너는 금으로 테를 만들고'),
(1465078,51,2,28,14,'정금으로 노끈처럼 두 사슬을 땋고 그 땋은 사슬을 그 테에 달지니라'),
(1465079,51,2,28,15,'너는 판결 흉패를 에봇 짜는 법으로 금실과, 청색, 자색, 홍색실과, 가늘게 꼰 베실로 공교히 짜서 만들되'),
(1465080,51,2,28,16,'장광이 한뼘씩 두 겹으로 네모 반듯하게 하고'),
(1465081,51,2,28,17,'그것에 네 줄로 보석을 물리되 첫 줄은 홍보석, 황옥, 녹주옥이요,'),
(1465082,51,2,28,18,'둘째 줄은 석류석, 남보석, 홍마노요,'),
(1465083,51,2,28,19,'세째 줄은 호박, 백마노, 자수정이요,'),
(1465084,51,2,28,20,'네째 줄은 녹보석, 호마노, 벽옥으로 다 금테에 물릴지니');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465085,51,2,28,21,'이 보석들은 이스라엘 아들들의 이름대로 열 둘이라 매 보석에 열두 지파의 한 이름씩 인을 새기는 법으로 새기고'),
(1465086,51,2,28,22,'정금으로 노끈처럼 땋은 사슬을 흉패 위에 붙이고'),
(1465087,51,2,28,23,'또 금고리 둘을 만들어 흉패 위 곧 흉패 두 끝에 그 두 고리를 달고'),
(1465088,51,2,28,24,'땋은 두 금사슬로 흉패 두 끝 두 고리에 꿰어 매고'),
(1465089,51,2,28,25,'두 땋은 사슬의 다른 두 끝을 에봇 앞 두 견대의 금테에 매고'),
(1465090,51,2,28,26,'또 금고리 둘을 만들어 흉패 아래 양편 가 안쪽 곧 에봇에 닿은 곳에 달고'),
(1465091,51,2,28,27,'또 금고리 둘을 만들어 에봇 앞 두 견대 아래 매는 자리 가까운편 곧 공교히 짠 띠 윗편에 달고'),
(1465092,51,2,28,28,'청색 끈으로 흉패 고리와 에봇 고리에 꿰어 흉패로 공교히 짠 에봇 띠 위에 붙여 떠나지 않게 하라'),
(1465093,51,2,28,29,'아론이 성소에 들어갈 때에는 이스라엘 아들들의 이름을 기록한 이 판결흉패를 가슴에 붙여 여호와 앞에 영원한 기념을 삼을 것이니라'),
(1465094,51,2,28,30,'너는 우림과 둠밈을 판결 흉패 안에 넣어 아론으로 여호와 앞에 들어 갈 때에 그 가슴 위에 있게 하라 아론이 여호와 앞에서 이스라엘 자손의 판결을 항상 그 가슴 위에 둘지니라 !'),
(1465095,51,2,28,31,'너는 에봇 받침 겉옷을 전부 청색으로 하되'),
(1465096,51,2,28,32,'두 어깨 사이에 머리 들어갈 구멍을 내고 그 주위에 갑옷 깃 같이 깃을 짜서 찢어지지 않게 하고'),
(1465097,51,2,28,33,'그 옷 가장자리로 돌아가며 청색, 자색, 홍색실로 석류를 수놓고 금방울을 간격하여 달되'),
(1465098,51,2,28,34,'그 옷 가장자리로 돌아가며 한 금방울 한 석류, 한 금방울 한 석류가 있게 하라'),
(1465099,51,2,28,35,'아론이 입고 여호와를 섬기러 성소에 들어갈 때와 성소에서 나갈때에 그 소리가 들릴 것이라 그리하면 그가 죽지 아니하리라 !'),
(1465100,51,2,28,36,'너는 또 정금으로 패를 만들어 인을 새기는 법으로 그 위에 새기되 여호와께 성결이라 하고'),
(1465101,51,2,28,37,'그 패를 청색 끈으로 관 위에 매되 곧 전면에 있게 하라'),
(1465102,51,2,28,38,'이 패가 아론의 이마에 있어서 그로 이스라엘 자손의 거룩하게 드리는 성물의 죄건을 담당하게 하라 그 패가 아론의 이마에 늘 있으므로 그 성물을 여호와께서 받으시게 되리라'),
(1465103,51,2,28,39,'너는 가는 베실로 반포 속옷을 짜고 가는 베실로 관을 만드고 띠를 수 놓아 만들지니라 !'),
(1465104,51,2,28,40,'너는 아론의 아들들을 위하여 속옷을 만들며 그들을 위하여 띠를 만들며 그들을 위하여 관을 만들어서 영화롭고 아름답게 하되'),
(1465105,51,2,28,41,'너는 그것들로 네 형 아론과 그와 함께한 그 아들들에게 입히고 그들에게 기름을 부어 위임하고 거룩하게 하여 그들로 제사장 직분을 내게 행하게 할지며'),
(1465106,51,2,28,42,'또 그들을 위하여 베로 고의를 만들어 허리에서부터 넓적다리까지 이르게 하여 하체를 가리게 하라'),
(1465107,51,2,28,43,'아론과 그 아들들이 회막에 들어갈 때에나 제단에 가까이 하여 거룩한 곳에서 섬길 때에 그것들을 입어야 죄를 지어서 죽지 아니하리니 그와 후손의 영원히 지킬 규례니라'),
(1465108,51,2,29,1,'너는 그들에게 나를 섬길 제사장 직분을 위임하여 그들로 거룩하게 할 일이 이러하니 곧 젊은 수소 하나와, 흠 없는 수양 둘을 취하고'),
(1465109,51,2,29,2,'무교병과, 기름 섞인 무교 과자와, 기름 바른 무교 전병을 모두 고운 밀가루로 만들고'),
(1465110,51,2,29,3,'그것들을 한 광주리에 담고 그것을 광주리에 담은 채 그 송아지와 두 양과 함께 가져 오고'),
(1465111,51,2,29,4,'너는 아론과 그 아들들을 회막 문으로 데려다가 물로 씻기고'),
(1465112,51,2,29,5,'의복을 가져다가 아론에게 속옷과, 에봇 받침 겉옷과, 에봇을 입히고 흉패를 달고 에봇에 공교히 짠 띠를 띠우고'),
(1465113,51,2,29,6,'그 머리에 관을 씌우고 그 위에 성패를 더하고'),
(1465114,51,2,29,7,'관유를 가져다가 그 머리에 부어 바르고'),
(1465115,51,2,29,8,'그 아들들을 데려다가 그들에게 속옷을 입히고'),
(1465116,51,2,29,9,'아론과 그 아들들에게 띠를 띠우며 관을 씌워서 제사장의 직분을 그들에게 맡겨 영원한 규례가 되게 하라 너는 이같이 아론과 그 아들들에게 위임하여 거룩하게 할지니라 !'),
(1465117,51,2,29,10,'너는 수송아지를 회막 앞으로 끌어 오고 아론과 그 아들들은 그 송아지 머리에 안수할지며'),
(1465118,51,2,29,11,'너는 회막문 여호와 앞에서 그 송아지를 잡고'),
(1465119,51,2,29,12,'그 피를 네 손가락으로 단 뿔들에 바르고 그 피 전부를 단 밑에 쏟을지며'),
(1465120,51,2,29,13,'내장에 덮인 모든 기름과 간 위에 있는 꺼풀과, 두 콩팥과, 그 위의 기름을 취하여 단 위에 불사르고'),
(1465121,51,2,29,14,'그 수소의 고기와 가죽과 똥은 진 밖에서 불사르라 ! 이는 속죄제니라'),
(1465122,51,2,29,15,'너는 또 수양 하나를 취하고 아론과 그 아들들은 그 수양의 머리위에 안수할지며'),
(1465123,51,2,29,16,'너는 그 수양을 잡고 그 피를 취하여 단 위의 주위에 뿌리고'),
(1465124,51,2,29,17,'그 수양의 각을 뜨고 그 장부와 다리는 씻어 각 뜬 고기와 그 머리와 함께 두고'),
(1465125,51,2,29,18,'그 수양의 전부를 단 위에 불사르라 ! 이는 여호와께 드리는 번제요 이는 향기로운 냄새니 여호와께 드리는 화제니라'),
(1465126,51,2,29,19,'너는 다른 수양을 취하고 아론과 그 아들들은 그 수양의 머리 위에 안수할지며'),
(1465127,51,2,29,20,'너는 그 수양을 잡고 그 피를 취하여 아론의 오른 귓부리와, 그 아들들의 오른 귓부리에 바르고, 그 오른손 엄지와, 오른발 엄지에 바르고 그 피를 단 주위에 뿌리고'),
(1465128,51,2,29,21,'단 위의 피와 관유를 취하여 아론과, 그 옷과, 그 아들들과, 그 아들들의 옷에 뿌리라 그와, 그 옷과, 그 아들들과, 그 아들들의 옷이 거룩하리라'),
(1465129,51,2,29,22,'또 너는 그 수양의 기름과 기름진 꼬리와 그 내장에 덮인 기름과 간 위의 꺼풀과 두 콩팥과 그것들 위의 기름과 우편 넓적다리를 취하라 ! 이는 위임식의 수양이며'),
(1465130,51,2,29,23,'또 여호와 앞에 있는 무교병 광주리에서 떡 한 덩이와 기름 바른 과자 하나와 전병 하나를 취하고'),
(1465131,51,2,29,24,'그 전부를 아론의 손과 그 아들들의 손에 주고 그것을 흔들어 여호와 앞에 요제를 삼을지며'),
(1465132,51,2,29,25,'너는 그것을 그들의 손에서 취하여 단 위에서 번제물을 더하여 불사르라 ! 이는 여호와 앞에 향기로운 냄새니 곧 여호와께 드리는 화제니라'),
(1465133,51,2,29,26,'너는 위임식 수양의 가슴을 취하여 여호와 앞에 흔들어 요제를 삼으라 ! 이는 너의 분깃이니라'),
(1465134,51,2,29,27,'너는 그 흔든 요제물 곧 아론과 그 아들들의 위임식 수양의 가슴과 넓적다리를 거룩하게 하라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465135,51,2,29,28,'이는 이스라엘 자손이 아론과 그 자손에게 돌릴 영원한 분깃이요, 거제물이니 곧 이스라엘 자손이 화목제의 희생 중에서 취한 거제물로서 여호와께 드리는 거제물이니라'),
(1465136,51,2,29,29,'아론의 성의는 아론의 후에 그 아들들에게 돌릴지니 그들이 그것을 입고 기름 부음으로 위임을 받을 것이며'),
(1465137,51,2,29,30,'그를 이어 제사장이 되는 아들이 회막에 들어가서 성소에서 섬길때에는 칠일 동안 그것을 입을지니라 !'),
(1465138,51,2,29,31,'너는 위임식 수양을 취하여 거룩한 곳에서 그 고기를 삶고'),
(1465139,51,2,29,32,'아론과 그 아들들이 회막문에서 그 수양의 고기와 광주리에 있는 떡을 먹을찌라'),
(1465140,51,2,29,33,'속죄물 곧 그들을 위임하며 그들은 거룩하게 하는데 쓰는것은 그들은 먹되 타인은 먹지 못할지니 이는 성물이 됨이며'),
(1465141,51,2,29,34,'위임식 고기나 떡이 아침까지 남았으면 그것을 불에 사를지니 이는 거룩한즉 먹지 못할지니라 !'),
(1465142,51,2,29,35,'너는 내가 무릇 네게 명한대로 아론과 그 아들들에게 그같이 하여 칠일동안 위임식을 행하되'),
(1465143,51,2,29,36,'매일 수송아지 하나로 속죄하기 위하여 속죄제를 드리며 또 단을 위하여 깨끗케 하고 그것에 기름을 부어 거룩하게 하라'),
(1465144,51,2,29,37,'네가 칠일 동안 단을 위하여 속죄하여 거룩하게 하라 ! 그리하면 지극히 거룩한 단이 되리니 무릇 단에 접촉하는 것이 거룩하리라'),
(1465145,51,2,29,38,'네가 단 위에 드릴 것은 이러하니라 매일 일년 된 어린 양 두 마리니'),
(1465146,51,2,29,39,'한 어린 양은 아침에 드리고, 한 어린 양은 저녁 때에 드릴지며'),
(1465147,51,2,29,40,'한 어린 양에 고운 밀가루 에바 십분 일과, 찧은 기름 힌의 사분 일을 더하고 또 전제로 포도주 힌의 사분 일을 더할지며'),
(1465148,51,2,29,41,'한 어린 양은 저녁 때에 드리되 아침과 일반으로 소제와 전제를 그것과 함께 드려 향기로운 냄새가 되게 하여 여호와께 화제를 삼을지니'),
(1465149,51,2,29,42,'이는 너희가 대대로 여호와 앞 회막문에서 늘 드릴 번제라 내가 거기서 너희와 만나고 네게 말하리라'),
(1465150,51,2,29,43,'내가 거기서 이스라엘 자손을 만나리니 내 영광을 인하여 회막이 거룩하게 될지라 !'),
(1465151,51,2,29,44,'내가 그 회막과 단을 거룩하게 하며 아론과 그 아들들도 거룩하게 하여 내게 제사장 직분을 행하게 하며'),
(1465152,51,2,29,45,'내가 이스라엘 자손 중에 거하여 그들의 하나님이 되리니'),
(1465153,51,2,29,46,'그들은 내가 그들의 하나님 여호와로서 그들 중에 거하려고 그들을 애굽 땅에서 인도하여 낸 줄을 알리라 나는 그들의 하나님 여호와니라 !'),
(1465154,51,2,30,1,'너는 분향할 단을 만들지니 곧 조각목으로 만들되'),
(1465155,51,2,30,2,'장이 일 규빗,광이 일 규빗으로 네모 반듯하게 하고 고는 이 규빗으로 하며 그 뿔을 그것과 연하게 하고'),
(1465156,51,2,30,3,'단 상면과 전후 좌우면과 뿔을 정금으로 싸고 주위에 금테를 두를지며'),
(1465157,51,2,30,4,'금테 아래 양편에 금고리 둘을 만들되 곧 그 양편에 만들지니 이는 단을 메는 채를 꿸 곳이며'),
(1465158,51,2,30,5,'그 채를 조각목으로 만들고 금으로 싸고'),
(1465159,51,2,30,6,'그 단을 증거궤 위 속죄소 맞은편 곧 증거궤 앞에 있는 장 밖에 두라 그 속죄소는 내가 너와 만날 곳이며'),
(1465160,51,2,30,7,'아론이 아침마다 그 위에 향기로운 향을 사르되 등불을 정리할 때에 사를지며'),
(1465161,51,2,30,8,'또 저녁때 등불을 켤때에 사를지니 이향은 너희가 대대로 여호와앞에 끊지 못할지며'),
(1465162,51,2,30,9,'너희는 그 위에 다른 향을 사르지 말며 번제나 소제를 드리지 말며 전제의 술을 붓지 말며'),
(1465163,51,2,30,10,'아론이 일년 일차씩 이 향단 뿔을 위하여 속죄하되 속죄제의 피로 일년 일차씩 대대로 속죄할지니라 ! 이 단은 여호와께 지극히 거룩하니라'),
(1465164,51,2,30,11,'여호와께서 모세에게 일러 가라사대'),
(1465165,51,2,30,12,'네가 이스라엘 자손의 수효를 따라 조사할 때에 조사 받은 각 사람은 그 생명의 속전을 여호와께 드릴지니 이는 그 계수할 때에 그들 중에 온역이 없게 하려 함이라'),
(1465166,51,2,30,13,'무릇 계수 중에 드는 자마다 성소에 세겔대로 반 세겔을 낼지니 한 세겔은 이 십 게라라 그 반 세겔을 여호와께 드릴지며'),
(1465167,51,2,30,14,'무릇 계수 중에 드는 자 곧 이십세 이상 된 자가 여호와께 드리되'),
(1465168,51,2,30,15,'너희의 생명을 속하기 위하여 여호와께 드릴 때에 부자라고 반 세겔에서 더 내지 말고, 가난한 자라고 덜 내지 말지며'),
(1465169,51,2,30,16,'너는 이스라엘 자손에게서 속전을 취하여 회막의 봉사에 쓰라 이것이 여호와 앞에서 이스라엘 자손의 기념이 되어서 너희의 생명을 속하리라'),
(1465170,51,2,30,17,'여호와께서 모세에게 일러 가라사대'),
(1465171,51,2,30,18,'너는 물두멍을 놋으로 만들어 씻게 하되 그것을 회막과 단 사이에 두고 그 속에 물을 담으라'),
(1465172,51,2,30,19,'아론과 그 아들들이 그 두멍에서 수족을 씻되'),
(1465173,51,2,30,20,'그들이 회막에 들어갈 때에 물로 씻어 죽기를 면할 것이요 단에 가까이 가서 그 직분을 행하여 화제를 여호와 앞에 사를 때에도 그리할지니라'),
(1465174,51,2,30,21,'이와 같이 그들이 그 수족을 씻어 죽기를 면할지니 이는 그와 그 자손이 대대로 영원히 지킬 규례니라'),
(1465175,51,2,30,22,'여호와께서 모세에게 또 일러 가라사대'),
(1465176,51,2,30,23,'너는 상등 향품을 취하되 액체 몰약 오백 세겔과, 그 반수의 향기로운 육계 이백 오십세겔과, 향기로운 창포 이백 오십세겔과,'),
(1465177,51,2,30,24,'계피 오백 세겔을 성소의 세겔대로 하고 감람 기름 한 힌을 취하여'),
(1465178,51,2,30,25,'그것으로 거룩한 관유를 만들되 향을 제조하는 법대로 향기름을 만들지니 그것이 거룩한 관유가 될지라'),
(1465179,51,2,30,26,'너는 그것으로 회막과 증거궤에 바르고'),
(1465180,51,2,30,27,'상과 그 모든 기구며 등대와 그 기구며 분향단과'),
(1465181,51,2,30,28,'및 번제단과 그 모든 기구와 물두멍과 그 받침에 발라'),
(1465182,51,2,30,29,'그것들을 지성물로 구별하라 ! 무릇 이것에 접촉하는 것이 거룩하리라'),
(1465183,51,2,30,30,'너는 아론과 그 아들들에게 기름을 발라 그들을 거룩하게 하고 그들로 내게 제사장 직분을 행하게 하고'),
(1465184,51,2,30,31,'이스라엘 자손에게 고하여 이르기를 이것은 너희 대대로 내게 거룩한 관유니');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465185,51,2,30,32,'사람의 몸에 붓지 말며 이 방법대로 이와 같은 것을 만들지 말라 이는 거룩하니 너희는 거룩히 여기라'),
(1465186,51,2,30,33,'무릇 이와 같은 것을 만드는 자나 무릇 이것을 타인에게 붓는 자는 그 백성중에서 끊쳐지리라 하라'),
(1465187,51,2,30,34,'여호와께서 모세에게 이르시되 너는 소합향과, 나감향과, 풍자향의 향품을 취하고 그 향품을 유향에 섞되 각기 동일한 중수로 하고'),
(1465188,51,2,30,35,'그것으로 향을 만들되 향 만드는 법대로 만들고 그것에 소금을 쳐서 성결하게 하고'),
(1465189,51,2,30,36,'그 향 얼마를 곱게 찧어 내가 너와 만날 회막 안 증거궤 앞에 두라 이 향은 너희에게 지극히 거룩하니라 !'),
(1465190,51,2,30,37,'네가 만들 향은 여호와를 위하여 거룩한 것이니 그 방법대로 너희를 위하여 만들지 말라 !'),
(1465191,51,2,30,38,'무릇 맡으려고 이같은 것을 만드는 자는 그 백성 중에서 끊쳐지리라 !'),
(1465192,51,2,31,1,'여호와께서 모세에게 일러 가라사대'),
(1465193,51,2,31,2,'내가 유다 지파 훌의 손자요 우리의 아들인 브사렐을 지명하여 부르고'),
(1465194,51,2,31,3,'하나님의 신을 그에게 충만하게 하여 지혜와 총명과 지식과 여러가지 재주로'),
(1465195,51,2,31,4,'공교한 일을 연구하여 금과 은과 놋으로 만들게 하며'),
(1465196,51,2,31,5,'보석을 깍아 물리며 나무를 새겨서 여러가지 일을 하게 하고'),
(1465197,51,2,31,6,'내가 또 단 지파 아히사막의 아들 오홀리압을 세워 그와 함께 하게 하며 무릇 지혜로운 마음이 있는 자에게 내가 지혜를 주어 그들로 내가 네게 명한 것을 다 만들게 할지니'),
(1465198,51,2,31,7,'곧 회막과, 증거궤와, 그 위의 속죄소와, 회막의 모든 기구와'),
(1465199,51,2,31,8,'상과, 그 기구와, 정금 등대와, 그 모든 기구와, 분향단과'),
(1465200,51,2,31,9,'번제단과, 그 모든 기구와, 물두멍과, 그 받침과'),
(1465201,51,2,31,10,'제사직을 행할 때에 입는 공교히 짠 의복 곧 제사장 아론의 성의와 그 아들들의 옷과'),
(1465202,51,2,31,11,'관유와 성소의 향기로운 향이라 무릇 내가 네게 명한대로 그들이 만들지니라 !'),
(1465203,51,2,31,12,'여호와께서 모세에게 일러 가라사대'),
(1465204,51,2,31,13,'너는 이스라엘 자손에게 고하여 이르기를 너희는 나의 안식일을 지키라 ! 이는 나와 너희 사이에 너희 대대의 표징이니 나는 너희를 거룩하게 하는 여호와인 줄 너희로 알게 함이라'),
(1465205,51,2,31,14,'너희는 안식일을 지킬지니 이는 너희에게 성일이 됨이라 무릇 그날에 일하는 자는 그 백성 중에서 그 생명이 끊쳐지리라'),
(1465206,51,2,31,15,'엿새 동안은 일할 것이나 제 칠일은 큰 안식일이니 여호와께 거룩한 것이라 무릇 안식일에 일하는 자를 반드시 죽일지니라 !'),
(1465207,51,2,31,16,'이같이 이스라엘 자손이 안식일을 지켜서 그것으로 대대로 영원한 언약을 삼을 것이니'),
(1465208,51,2,31,17,'이는 나와 이스라엘 자손 사이에 영원한 표징이며 나 여호와가 엿새 동안에 천지를 창조하고 제 칠일에 쉬어 평안하였음이니라 하라'),
(1465209,51,2,31,18,'여호와께서 시내산 위에서 모세에게 이르시기를 마치신 때에 증거판 둘을 모세에게 주시니 이는 돌판이요 하나님이 친히 쓰신 것이더라'),
(1465210,51,2,32,1,'백성이 모세가 산에서 내려옴이 더딤을 보고 모여 아론에게 이르러 가로되 ''일어나라 우리를 인도할 신을 우리를 위하여 만들라 이 모세 곧 우리를 애굽 땅에서 인도하여 낸 사람은 어찌 되었는지 알지 못함이라'''),
(1465211,51,2,32,2,'아론이 그들에게 이르되 `너희 아내와 자녀의 귀의 금고리를 빼어 내게로 가져 오라'''),
(1465212,51,2,32,3,'모든 백성이 그 귀에서 금고리를 빼어 아론에게로 가져 오매'),
(1465213,51,2,32,4,'아론이 그들의 손에서 그 고리를 받아 부어서 각도로 새겨 송아지 형상을 만드니 그들이 말하되 ''이스라엘아 ! 이는 너희를 애굽 땅에서 인도하여 낸 너희 신이로다'' 하는지라'),
(1465214,51,2,32,5,'아론이 보고 그 앞에 단을 쌓고 이에 공포하여 가로되 `내일은 여호와의 절일이니라'' 하니'),
(1465215,51,2,32,6,'이튿날에 그들이 일찌기 일어나 번제를 드리며 화목제를 드리고 앉아서 먹고 마시며 일어나서 뛰놀더라'),
(1465216,51,2,32,7,'여호와께서 모세에게 이르시되 너는 내려가라 네가 애굽 땅에서 인도하여 낸 네 백성이 부패하였도다'),
(1465217,51,2,32,8,'그들이 내가 그들에게 명한 길을 속히 떠나 자기를 위하여 송아지를 부어 만들고 그것을 숭배하며 그것에게 희생을 드리며 말하기를 애굽 땅에서 인도하여 낸 너희 신이라 하였도다'),
(1465218,51,2,32,9,'여호와께서 또 모세에게 이르시되 내가 이 백성을 보니 목이 곧은 백성이로다'),
(1465219,51,2,32,10,'그런즉 나대로 하게 하라 ! 내가 그들에게 진노하여 그들을 진멸하고 너로 큰 나라가 되게 하리라'),
(1465220,51,2,32,11,'모세가 그 하나님 여호와께 구하여 가로되 ''여호와여 ! 어찌하여 애굽 땅에서 인도하여 내신 주의 백성에게 진노하시나이까 ?'),
(1465221,51,2,32,12,'어찌하여 애굽 사람으로 이르기를 여호와가 화를 내려 그 백성을 산에서 죽이고 지면에서 진멸하려고 인도하여 내었다 하게 하려 하시나이까 ? 주의 맹렬한 노를 그치시고 뜻을 돌이키사 주의 백성에게 이 화를 내리지 마옵소서 !'),
(1465222,51,2,32,13,'주의 종 아브라함과 이삭과 이스라엘을 기억하소서 ! 주께서 주를 가리켜 그들에게 맹세하여 이르시기를 내가 너희 자손을 하늘의 별처럼 많게 하고 나의 허락한 이 온 땅을 너희의 자손에게 주어 영원한 기업이 되게 하리라 하셨나이다'''),
(1465223,51,2,32,14,'여호와께서 뜻을 돌이키사 말씀하신 화를 그 백성에게 내리지 아니하시니라'),
(1465224,51,2,32,15,'모세가 돌이켜 산에서 내려 오는데 증거의 두 판이 그 손에 있고 그 판의 양면 이편 저편에 글자가 있으니'),
(1465225,51,2,32,16,'그 판은 하나님이 만드신 것이요, 글자는 하나님이 쓰셔서 판에 새기신 것이더라'),
(1465226,51,2,32,17,'여호수아가 백성의 떠듦을 듣고 모세에게 말하되 `진중에서 싸우는 소리가 나나이다'''),
(1465227,51,2,32,18,'모세가 가로되 `이는 승전가도 아니요, 패하여 부르짖는 소리도 아니라 나의 듣기에는 노래하는 소리로다'' 하고'),
(1465228,51,2,32,19,'진에 가까이 이르러 송아지와 그 춤 추는 것을 보고 대노하여 손에서 그 판들을 산 아래로 던져 깨뜨리니라'),
(1465229,51,2,32,20,'모세가 그들의 만든 송아지를 가져 불살라 부수어 가루를 만들어 물에 뿌려 이스라엘 자손에게 마시우니라'),
(1465230,51,2,32,21,'모세가 아론에게 이르되 `이 백성이 네게 어떻게 하였기에 네가 그들로 중죄에 빠지게 하였느뇨 ?'''),
(1465231,51,2,32,22,'아론이 가로되 `내 주여, 노하지 마소서 이 백성의 악함을 당신이 아나이다'),
(1465232,51,2,32,23,'그들이 내게 말하기를 우리를 위하여 우리를 인도할 신을 만들라 이 모세 곧 우리를 애굽 땅에서 인도하여 낸 사람은 어찌 되었는지 알 수 없노라 하기에'),
(1465233,51,2,32,24,'내가 그들에게 이르기를 금이 있는 자는 빼어내라 한즉 그들이 그것을 내게로 가져왔기로 내가 불에 던졌더니 이 송아지가 나왔나이다'''),
(1465234,51,2,32,25,'모세가 본즉 백성이 방자하니 이는 아론이 그들로 방자하게 하여 원수에게 조롱거리가 되게 하였음이라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465235,51,2,32,26,'이에 모세가 진문에 서서 가로되 `누구든지 여호와의 편에 있는 자는 내게로 나아오라 !'' 하매 레위 자손이 다 모여 그에게로 오는 지라'),
(1465236,51,2,32,27,'모세가 그들에게 이르되 `이스라엘의 하나님 여호와께서 이같이 말씀하시기를 너희는 각각 허리에 칼을 차고 진 이 문에서 저 문까지 왕래하며 각 사람이 그 형제를,각 사람이 그 친구를,각 사람이 그 이웃을 도륙하라 하셨느니라'''),
(1465237,51,2,32,28,'레위 자손이 모세의 말대로 행하매 이 날에 백성 중에 삼천명 가량이 죽인 바 된지라'),
(1465238,51,2,32,29,'모세가 이르되 `각 사람이 그 아들과 그 형제를 쳤으니 오늘날 여호와께 헌신하게 되었느니라 그가 오늘날 너희에게 복을 내리시리라'''),
(1465239,51,2,32,30,'이튿날 모세가 백성에게 이르되 `너희가 큰 죄를 범하였도다 내가 이제 여호와께로 올라가노니 혹 너희의 죄를 속할까 하노라'' 하고'),
(1465240,51,2,32,31,'여호와께로 다시 나아가 여짜오되 `슬프도소이다 ! 이 백성이 자기들을 위하여 금신을 만들었사오니 큰 죄를 범하였나이다'),
(1465241,51,2,32,32,'그러나 합의하시면 이제 그들의 죄를 사하시옵소서 ! 그렇지 않사오면 원컨대 주의 기록하신 책에서 내 이름을 지워 버려주옵소서 !'''),
(1465242,51,2,32,33,'여호와께서 모세에게 이르시되 누구든지 내게 범죄하면 그는 내가 내 책에서 지워버리리라'),
(1465243,51,2,32,34,'이제 가서 내가 네게 말한 곳으로 백성을 인도하라 내 사자가 네 앞서 가리라 그러나 내가 보응할 날에는 그들의 죄를 보응하리라'),
(1465244,51,2,32,35,'여호와께서 백성을 치시니 이는 그들이 아론의 만든바 그 송아지를 만들었음이더라'),
(1465245,51,2,33,1,'여호와께서 모세에게 이르시되 너는 네가 애굽 땅에서 인도하여 낸 백성과 함께 여기서 떠나서 내가 아브라함과 이삭과 야곱에게 맹세하기를 네 자손에게 주마 한 그 땅으로 올라가라'),
(1465246,51,2,33,2,'내가 사자를 네 앞서 보내어 가나안 사람과, 아모리 사람과, 헷 사람과, 브리스 사람과, 히위 사람과, 여부스 사람을 쫓아내고'),
(1465247,51,2,33,3,'너희로 젖과 꿀이 흐르는 땅에 이르게 하려니와 나는 너희와 함께 올라가지 아니하리니 너희는 목이 곧은 백성인즉 내가 중로에서 너희를 진멸할까 염려함이니라 하시니'),
(1465248,51,2,33,4,'백성이 이 황송한 말씀을 듣고 슬퍼하여 한 사람도 그 몸을 단장하지 아니하니'),
(1465249,51,2,33,5,'여호와께서 모세에게 이르시기를 이스라엘 자손에게 이르라 너희는 목이 곧은 백성인즉 내가 순식간이라도 너희 중에 행하면 너희를 진멸하리니 너희 단장품을 제하라 ! 그리하면 내가 너희에게 어떻게 할 일을 알겠노라 하셨음이라'),
(1465250,51,2,33,6,'이스라엘 자손이 호렙 산에서부터 그 단장품을 제하니라'),
(1465251,51,2,33,7,'모세가 항상 장막을 취하여 진 밖에 쳐서 진과 멀리 떠나게 하고 회막이라 이름하니 여호와를 앙모하는 자는 다 진 바깥 회막으로 나아가며'),
(1465252,51,2,33,8,'모세가 회막으로 나아갈 때에는 백성이 다 일어나 자기 장막문에 서서 모세가 회막에 들어가기까지 바라보며'),
(1465253,51,2,33,9,'모세가 회막에 들어갈 때에 구름 기둥이 내려 회막문에 서며 여호와께서 모세와 말씀하시니'),
(1465254,51,2,33,10,'모든 백성이 회막문에 구름 기둥이 섰음을 보고 다 일어나 각기 장막문에 서서 경배하며'),
(1465255,51,2,33,11,'사람이 그 친구와 이야기함 같이 여호와께서는 모세와 대면하여 말씀하시며 모세는 진으로 돌아오나 그 수종자 눈의 아들 청년 여호수아는 회막을 떠나지 아니하니라'),
(1465256,51,2,33,12,'모세가 여호와께 고하되 `보시옵소서 ! 주께서 나더러 이 백성을 인도하여 올라가라 하시면서 나와 함께 보낼 자를 내게 지시하지 아니하시나이다 주께서 전에 말씀하시기를 나는 이름으로도 너를 알고 너도 내 앞에 은총을 입었다 하셨사온즉'),
(1465257,51,2,33,13,'내가 참으로 주의 목전에 은총을 입게 하시며 이 족속을 주의 백성으로 여기소서 !'''),
(1465258,51,2,33,14,'여호와께서 가라사대 내가 친히 가리라 ! 내가 너로 편케 하리라 !'),
(1465259,51,2,33,15,'모세가 여호와께 고하되 `주께서 친히 가지 아니하시려거든 우리를 이곳에서 올려 보내지 마옵소서'),
(1465260,51,2,33,16,'나와 주의 백성이 주의 목전에 은총 입은 줄을 무엇으로 알리이까 ? 주께서 우리와 함께 행하심으로 나와 주의 백성을 천하 만민 중에 구별하심이 아니니이까 ?'''),
(1465261,51,2,33,17,'여호와께서 모세에게 이르시되 너의 말하는 이 일도 내가 하리니 너는 내 목전에 은총을 입었고 내가 이름으로도 너를 앎이니라'),
(1465262,51,2,33,18,'모세가 가로되 `원컨대 주의 영광을 내게 보이소서 !'''),
(1465263,51,2,33,19,'여호와께서 가라사대 내가 나의 모든 선한 형상을 네 앞으로 지나게 하고 여호와의 이름을 네 앞에 반포하리라 나는 은혜 줄 자에게 은혜를 주고 긍휼히 여길자에게 긍휼을 베푸느니라'),
(1465264,51,2,33,20,'또 가라사대 네가 내 얼굴을 보지 못하리니 나를 보고 살 자가 없음이니라'),
(1465265,51,2,33,21,'여호와께서 가라사대 보라 내 곁에 한 곳이 있으니 너는 그 반석 위에 섰으라'),
(1465266,51,2,33,22,'내 영광이 지날 때에 내가 너를 반석 틈에 두고 내가 지나도록 내 손으로 너를 덮었다가'),
(1465267,51,2,33,23,'손을 거두리니 네가 내 등을 볼 것이요 얼굴은 보지 못하리라'),
(1465268,51,2,34,1,'여호와께서 모세에게 이르시되 너는 돌판 둘을 처음 것과 같이 깍아 만들라 네가 깨뜨린바 처음 것과 같이 깎아 만들라 네가 깨뜨린바 처음 판에 있던 말을 내가 그 판에 쓰리니'),
(1465269,51,2,34,2,'아침 전에 예비하고 아침에 시내 산에 올라와 산꼭대기에서 내게 보이되'),
(1465270,51,2,34,3,'아무도 너와 함께 오르지 말며 온 산에 인적을 금하고 양과 소도 산 앞에서 먹지 못하게 하라'),
(1465271,51,2,34,4,'모세가 돌판 둘을 처음 것과 같이 깎아 만들고 아침에 일찌기 일어나 그 두 돌판을 손에 들고 여호와의 명대로 시내산에 올라가니'),
(1465272,51,2,34,5,'여호와께서 구름 가운데 강림하사 그와 함께 거기 서서 여호와의 이름을 반포하실쌔'),
(1465273,51,2,34,6,'여호와께서 그의 앞으로 지나시며 반포하시되 여호와로라 ! 여호와로라 ! 자비롭고 은혜롭고 노하기를 더디하고 인자와 진실이 많은 하나님이로라'),
(1465274,51,2,34,7,'인자를 천대까지 베풀며 악과 과실과 죄를 용서하나 형벌 받을 자는 결단코 면죄하지 않고 아비의 악을 자여손 삼사대까지 보응하리라'),
(1465275,51,2,34,8,'모세가 급히 땅에 엎드리어 경배하며'),
(1465276,51,2,34,9,'가로되 `주여 ! 내가 주께 은총을 입었거든 원컨대 주는 우리 중에서 행하옵소서 이는 목이 곧은 백성이니이다 우리의 악과 죄를 사하시고 우리로 주의 기업을 삼으소서 !'''),
(1465277,51,2,34,10,'여호와께서 가라사대 보라 내가 언약을 세우나니 곧 내가 아직 온 땅 아무 국민에게도 행치 아니한 이적을 너희 전체 백성 앞에 행할 것이라 너의 머무는 나라 백성이 다 여호와의 소위를 보리니 내가 너를 위하여 행할 일이 두려운 것임이니라'),
(1465278,51,2,34,11,'너는 내가 오늘 네게 명하는 것을 삼가 지키라 보라 ! 내가 네 앞에서 아모리 사람과, 가나안 사람과, 헷 사람과, 브리스 사람과, 히위 사람과, 여부스 사람을 쫓아내리니'),
(1465279,51,2,34,12,'너는 스스로 삼가 네가 들어가는 땅의 거민과 언약을 세우지 말라 그들이 너희 중에 올무가 될까 하노라'),
(1465280,51,2,34,13,'너희는 도리어 그들의 단들을 헐고 그들의 주상을 깨뜨리고 그들의 아세라 상을 찍을지어다 !'),
(1465281,51,2,34,14,'너는 다른 신에게 절하지 말라 ! 여호와는 질투라 이름하는 질투의 하나님임이니라 !'),
(1465282,51,2,34,15,'너는 삼가 그 땅의 거민과 언약을 세우지 말지니 이는 그들이 모든 신을 음란히 섬기며 그 신들에게 희생을 드리고 너를 청하면 네가 그 희생을 먹을까 함이며'),
(1465283,51,2,34,16,'또 네가 그들의 딸들로 네 아들들의 아내를 삼음으로 그들의 딸들이 그 신들을 음란히 섬기며 네 아들로 그들의 신들을 음란히 섬기게 할까 함이니라'),
(1465284,51,2,34,17,'너는 신상들을 부어 만들지 말지니라 !');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465285,51,2,34,18,'너는 무교절을 지키되 내가 네게 명한대로 아빕월 그 기한에 칠일 동안 무교병을 먹으라 이는 네가 아빕월에 애굽에서 나왔음이니라'),
(1465286,51,2,34,19,'무릇 초태생은 다 내 것이며 무릇 네 가축의 수컷 처음 난 우양도 다 그러하며'),
(1465287,51,2,34,20,'나귀의 첫새끼는 어린 양으로 대속할 것이요 그렇게 아니하려면 그 목을 꺾을 것이며 네 아들 중 장자는 다 대속할지며 빈손으로 내 얼굴을 보지 말지니라 !'),
(1465288,51,2,34,21,'너는 엿새동안 일하고 제 칠일에는 쉴지니 밭 갈 때에나 거둘 때에도 쉴지며'),
(1465289,51,2,34,22,'칠칠절 곧 맥추의 초실절을 지키고 가을에는 수장절을 지키라 !'),
(1465290,51,2,34,23,'너희 모든 남자는 매년 세번씩 주 여호와 이스라엘의 하나님 앞에 보일지라'),
(1465291,51,2,34,24,'내가 열방을 네 앞에서 쫓아내고 네 지경을 넓히리니 네가 매년 세번씩 여호와 너희 하나님께 보이러 올 때에 아무 사람도 네 땅을 탐내어 엿보지 못하리라 !'),
(1465292,51,2,34,25,'너는 내 희생의 피를 유교병과 함께 드리지 말며 유월절 희생을 아침까지 두지 말지며'),
(1465293,51,2,34,26,'너의 토지 소산의 처음 익은 것을 가져다가 너의 하나님 여호와의 전에 드릴지며 너는 염소 새끼를 그 어미의 젖으로 삶지 말지니라'),
(1465294,51,2,34,27,'여호와께서 모세에게 이르시되 너는 이 말들을 기록하라 내가 이 말들의 뜻대로 너와 이스라엘과 언약을 세웠음이니라 하시니라'),
(1465295,51,2,34,28,'모세가 여호와와 함께 사십일 사십야를 거기 있으면서 떡도 먹지 아니하였고 물도 마시지 아니하였으며 여호와께서는 언약의 말씀 곧 십계를 그 판들에 기록하셨더라'),
(1465296,51,2,34,29,'모세가 그 증거의 두 판을 자기 손에 들고 시내산에서 내려오니 그 산에서 내려올 때에 모세는 자기가 여호와와 말씀하였음을 인하여 얼굴 꺼풀에 광채가 나나 깨닫지 못하였더라'),
(1465297,51,2,34,30,'아론과 온 이스라엘 자손이 모세를 볼 때에 모세의 얼굴 꺼풀에 광채 남을 보고 그에게 가까이 하기를 두려워하더니'),
(1465298,51,2,34,31,'모세가 그들을 부르니 아론과 회중의 모든 어른이 모세에게로 오고 모세가 그들과 말하니'),
(1465299,51,2,34,32,'그 후에야 온 이스라엘 자손이 가까이 오는지라 모세가 여호와께서 시내산에서 자기에게 이르신 말씀을 다 그들에게 명하고'),
(1465300,51,2,34,33,'그들에게 말하기를 마치고 수건으로 자기 얼굴을 가리웠더라'),
(1465301,51,2,34,34,'그러나 모세가 여호와 앞에 들어가서 함께 말씀할 때에는 나오기까지 수건을 벗고 있다가 나와서는 그 명하신 일을 이스라엘 자손에게 고하며'),
(1465302,51,2,34,35,'이스라엘 자손이 모세의 얼굴의 광채를 보는고로 모세가 여호와께 말씀하러 들어가기까지 다시 수건으로 자기 얼굴을 가리웠더라'),
(1465303,51,2,35,1,'모세가 이스라엘의 온 회중을 모으고 그들에게 이르되 `여호와께서 너희에게 명하사 행하게 하신 말씀이 이러하니라'),
(1465304,51,2,35,2,'엿새 동안은 일하고 제 칠일은 너희에게 성일이니 여호와께 특별한 안식일이라 무릇 이날에 일하는 자를 죽일지니'),
(1465305,51,2,35,3,'안식일에는 너희의 모든 처소에서 불도 피우지 말지니라 !'''),
(1465306,51,2,35,4,'모세가 이스라엘 자손의 온 회중에게 고하여 가로되 `여호와의 명하신 일이 이러하니라 이르시기를'),
(1465307,51,2,35,5,'너희의 소유 중에서 너희는 여호와께 드릴 것을 취하되 무릇 마음에 원하는 자는 그것을 가져다가 여호와께 드릴지니 곧 금과 은과 놋과'),
(1465308,51,2,35,6,'청색, 자색, 홍색실과, 가는 베실과, 염소털과'),
(1465309,51,2,35,7,'붉은 물 들인 수양의 가죽과, 해달의 가죽과, 조각목과'),
(1465310,51,2,35,8,'등유와, 및 관유에 드는 향품과, 분향할 향을 만드는 향품과'),
(1465311,51,2,35,9,'호마노며, 에봇과, 흉패에 물릴 보석이니라'),
(1465312,51,2,35,10,'무릇 너희 중 마음이 지혜로운 자는 와서 여호와의 명하신 것을 다 만들지니'),
(1465313,51,2,35,11,'곧 성막과, 그 막과, 그 덮개와, 그 갈고리와, 그 널판과, 그 띠와, 그 기둥과, 그 받침과,'),
(1465314,51,2,35,12,'증거궤와, 그 채와, 속죄소와, 그 가리는 장과,'),
(1465315,51,2,35,13,'상과, 그 채와, 그 모든 기구와, 진설병과,'),
(1465316,51,2,35,14,'불 켜는 등대와, 그 기구와, 그 등잔과, 등유와,'),
(1465317,51,2,35,15,'분향단과, 그 채와, 관유와, 분향할 향품과, 성막문의 장과,'),
(1465318,51,2,35,16,'번제단과, 그 놋 그물과, 그 채와, 그 모든 기구와, 물두멍과, 그 받침과,'),
(1465319,51,2,35,17,'뜰의 포장과, 그 기둥과, 그 받침과, 뜰문의 장과,'),
(1465320,51,2,35,18,'장막 말뚝과, 뜰의 포장 말뚝과, 그 줄과,'),
(1465321,51,2,35,19,'성소에서 섬기기 위하여 공교히 만든 옷 곧 제사 직분을 행할 때에 입는 제사장 아론의 거룩한 옷과 그 아들들의 옷이니라'),
(1465322,51,2,35,20,'이스라엘 자손의 온 회중이 모세 앞에서 물러갔더니'),
(1465323,51,2,35,21,'무릇 마음이 감동된 자와 무릇 자원하는 자가 와서 성막을 짓기 위하여 그 속에서 쓸 모든 것을 위하여, 거룩한 옷을 위하여 예물을 가져 여호와께 드렸으니'),
(1465324,51,2,35,22,'곧 마음에 원하는 남녀가 와서 가슴 핀과, 귀고리와, 가락지와, 목거리와, 여러가지 금품을 가져 왔으되 사람마다 여호와께 금 예물을 드렸으며'),
(1465325,51,2,35,23,'무릇 청색, 자색, 홍색실과, 가는 베실과, 염소털과, 붉은 물 들인 수양의 가죽과, 해달의 가죽이 있는 자도 가져 왔으며'),
(1465326,51,2,35,24,'무릇 은과 놋으로 예물을 삼는 자는 가져다가 여호와께 드렸으며 무릇 섬기는 일에 소용되는 조각목이 있는 자는 가져 왔으며'),
(1465327,51,2,35,25,'마음이 슬기로운 모든 여인은 손수 실을 낳고 그 낳은 청색, 자색, 홍색실과, 가는 베실을 가져 왔으며'),
(1465328,51,2,35,26,'마음에 감동을 받아 슬기로운 모든 여인은 염소털로 실을 낳았으며'),
(1465329,51,2,35,27,'모든 족장은 호마노와 및 에봇과 흉패에 물릴 보석을 가져 왔으며'),
(1465330,51,2,35,28,'등불과, 관유와, 분향할 향에 소용되는 기름과, 향품을 가져 왔으니'),
(1465331,51,2,35,29,'마음에 원하는 이스라엘 자손의 남녀마다 여호와께서 모세의 손을 빙자하여 명하신 모든 것을 만들기 위하여 물품을 가져다가 여호와께 즐거이 드림이 이러하였더라'),
(1465332,51,2,35,30,'모세가 이스라엘 자손에게 이르되 `볼지어다 여호와께서 유다 지파 훌의 손자요 우리의 아들인 브사렐을 지명하여 부르시고'),
(1465333,51,2,35,31,'하나님의 신을 그에게 충만케 하여 지혜와 총명과 지식으로 여러가지 일을 하게 하시되'),
(1465334,51,2,35,32,'공교한 일을 연구하여 금과 은과 놋으로 일하게 하시며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465335,51,2,35,33,'보석을 깎아 물리며 나무를 새기는 여러가지 공교한 일을 하게 하셨고'),
(1465336,51,2,35,34,'또 그와 단 지파 아히사막의 아들 오홀리압을 감동시키사 가르치게 하시며'),
(1465337,51,2,35,35,'지혜로운 마음을 그들에게 충만하게 하사 여러가지 일을 하게 하시되 조각하는 일과, 공교로운 일과, 청색, 자색, 홍색실과, 가는 베실로 수 놓은 일과 짜는 일과 그 외에 여러가지 일을 하게 하시고 공교로운 일을 연구하게 하셨나니'),
(1465338,51,2,36,1,'브사렐과 오홀리압과 및 마음이 지혜로운 사람 곧 여호와께서 지혜와 총명을 부으사 성소에 쓸 모든 일을 할 줄 알게 하심을 입은 자들은 여호와의 무릇 명하신 대로 할 것이니라'''),
(1465339,51,2,36,2,'모세가 브살렐과 오홀리압과 및 마음이 지혜로운 사람 곧 그 마음에 여호와께로 지혜를 얻고 와서 그 일을 하려고 마음에 원하는 모든 자를 부르매'),
(1465340,51,2,36,3,'그들이 이스라엘 자손의 성소의 모든 것을 만들기 위하여 가져 온 예물을 모세에게서 받으니라 그러나 백성이 아침마다 자원하는 예물을 연하여 가져오는 고로'),
(1465341,51,2,36,4,'성소의 모든 일을 하는 지혜로운 자들이 각기 하는 일을 정지하고 와서'),
(1465342,51,2,36,5,'모세에게 고하여 가로되 `백성이 너무 많이 가져 오므로 여호와의 명하신 일에 쓰기에 남음이 있나이다'''),
(1465343,51,2,36,6,'모세가 명을 내리매 그들이 진중에 공포하여 가로되 `무론 남녀하고 성소에 드릴 예물을 다시 만들지 말라'' 하매 백성이 가져오기를 정지하니'),
(1465344,51,2,36,7,'있는 재료가 모든 일을 하기에 넉넉하여 남음이 있었더라'),
(1465345,51,2,36,8,'일하는 사람 중에 마음이 지혜로운 모든 사람이 열 폭 앙장으로 성막을 지었으니 곧 가늘게 꼰 베실과, 청색, 자색, 홍색실로 그룹들을 무늬 놓아 짜서 지은 것이라'),
(1465346,51,2,36,9,'매폭의 장은 이십 팔 규빗,광은 사 규빗으로 각 폭의 장단을 같게 하여'),
(1465347,51,2,36,10,'그 다섯 폭을 서로 연하며, 또 그 다섯 폭을 서로 연하고'),
(1465348,51,2,36,11,'연락할 말폭 가에 청색 고를 만들며, 다른 연락할 말폭 가에도 고를 만들되'),
(1465349,51,2,36,12,'그 연락할 한 폭에 고 오십을 달고, 다른 연락할 한 폭의 가에도 고 오십을 달아, 그 고들이 서로 대하게 하고'),
(1465350,51,2,36,13,'금 갈고리 오십을 만들어, 그 갈고리로 두 앙장을 연하여 한 막을 이루었더라'),
(1465351,51,2,36,14,'그 성막을 덮는 막 곧 앙장을 염소털로 만들되 십 일폭을 만들었으니'),
(1465352,51,2,36,15,'각 폭의 장은 삼십 규빗,광은 사 규빗으로 십 일폭의 장단을 같게 하여'),
(1465353,51,2,36,16,'그 앙장 다섯 폭을 서로 연하며, 또 여섯 폭을 서로 연하고'),
(1465354,51,2,36,17,'앙장을 연락할 말폭 가에도 고 오십을 달며, 다른 연락할 말폭 가에도 고 오십을 달고'),
(1465355,51,2,36,18,'놋 갈고리 오십을 만들어, 그 앙장을 연합하여 한 막이 되게 하고'),
(1465356,51,2,36,19,'붉은 물 들인 수양의 가죽으로 막의 덮개를 만들고 해달의 가죽으로 그 웃덮개를 만들었더라'),
(1465357,51,2,36,20,'그가 또 조각목으로 성막에 세울 널판들을 만들었으니'),
(1465358,51,2,36,21,'각 판의 장은 십 규빗,광은 일 규빗 반이며'),
(1465359,51,2,36,22,'각 판에 두 촉이 있어 서로 연하게 하였으니 성막의 모든 판이 그러하며'),
(1465360,51,2,36,23,'성막을 위하여 널판을 만들었으되, 남으로는 남편에 널판이 이십이라'),
(1465361,51,2,36,24,'그 이십 널판 밑에 은받침 사십을 만들었으되, 곧 이 널판 밑에도 두 받침이 그 두 촉을 받게 하였으며'),
(1465362,51,2,36,25,'성막 다른 편 곧 북편을 위하여도 널판 이십을 만들고'),
(1465363,51,2,36,26,'또 은받침 사십을 만들었으니 곧 이 판 밑에도 두 받침이요, 저 판 밑에도 두 받침이며'),
(1465364,51,2,36,27,'장막 뒤 곧 서편을 위하여는 널판 여섯을 만들었고'),
(1465365,51,2,36,28,'장막 뒤 두 모퉁이 편을 위하여는 널판 둘을 만들되'),
(1465366,51,2,36,29,'아래서부터 위까지 각기 두 겹 두께로 하여 윗고리에 이르게 하고 두 모퉁이 편을 다 그리하며'),
(1465367,51,2,36,30,'그 널판은 여덟이요, 그 받침은 은받침 열 여섯이라, 각 널판 밑에 둘씩이었더라'),
(1465368,51,2,36,31,'그가 또 조각목으로 띠를 만들었으니 곧 성막 이편 널판을 위하여 다섯이요'),
(1465369,51,2,36,32,'성막 저편 널판을 위하여 다섯이요, 성막 뒤 곧 서편 널판을 위하여 다섯이며'),
(1465370,51,2,36,33,'그 중간 띠를 만들되, 널판 중간 이 끝에서 저 끝에 미치게 하였으며'),
(1465371,51,2,36,34,'그 널판들을 금으로 싸고 그 널판에 띠를 꿸 금고리를 만들고, 그 띠도 금으로 쌌더라'),
(1465372,51,2,36,35,'그가 또 청색, 자색, 홍색실과, 가늘게 꼰 베실로 장을 짜고 그 위에 그룹들을 공교히 수 놓고'),
(1465373,51,2,36,36,'조각목으로 네 기둥을 만들어 금으로 쌌으며, 그 갈고리는 금이며 기둥의 네 받침은 은으로 부어 만들었으며'),
(1465374,51,2,36,37,'청색, 자색, 홍색실과, 가늘게 꼰 베실로 수 놓아 장막 문을 위하여 장을 만들고'),
(1465375,51,2,36,38,'문장의 기둥 다섯과 그 갈고리를 만들고, 기둥머리와 그 가름대를 금으로 쌌으며 그 다섯 받침은 놋이었더라'),
(1465376,51,2,37,1,'브사렐이 조각목으로 궤를 만들었으니 장이 이 규빗 반, 광이 일 규빗 반, 고가 일 규빗 반이며'),
(1465377,51,2,37,2,'정금으로 안팎을 싸고 윗가로 돌아가며 금테를 만들었으며'),
(1465378,51,2,37,3,'금고리 넷을 부어 만들어 네 발에 달았으니 곧 이편에 두 고리요, 저편에 두 고리며'),
(1465379,51,2,37,4,'조각목으로 채를 만들어 금으로 싸고'),
(1465380,51,2,37,5,'그 채를 궤 양편 고리에 꿰어 궤를 메게 하였으며'),
(1465381,51,2,37,6,'정금으로 속죄소를 만들었으니 장이 이 규빗 반, 광이 일 규빗 반이며'),
(1465382,51,2,37,7,'금으로 그룹 둘을 속죄소 양편에 쳐서 만들었으되'),
(1465383,51,2,37,8,'한 그룹은 이편 끝에, 한 그룹은 저편 끝에 곧 속죄소와 한 덩이로 그 양편에 만들었으니'),
(1465384,51,2,37,9,'그룹들이 그 날개를 높이 펴서 그 날개로 속죄소를 덮으며 그 얼굴을 서로 대하여 속죄소를 향하였더라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465385,51,2,37,10,'그가 또 조각목으로 상을 만들었으니 장이 이 규빗, 광이 일 규빗, 고가 일 규빗 반이며'),
(1465386,51,2,37,11,'정금으로 싸고 윗가로 돌아가며 금테를 둘렀으며'),
(1465387,51,2,37,12,'그 사면에 손바닥 넓이만한 턱을 만들고 그 턱 주위에 금으로 테를 만들었고'),
(1465388,51,2,37,13,'상을 위하여 금고리 넷을 부어 만들어 네 발 위 네 모퉁이에 달았으니'),
(1465389,51,2,37,14,'그 고리가 턱 곁에 있어서 상을 메는 채를 꿰게 하였으며'),
(1465390,51,2,37,15,'또 조각목으로 상 멜 채를 만들어 금으로 쌌으며'),
(1465391,51,2,37,16,'상 위의 기구 곧 대접과, 숟가락과, 잔과, 붓는 병을 정금으로 만들었더라'),
(1465392,51,2,37,17,'그가 또 정금으로 등대를 만들되 그것을 쳐서 만들었으니 그 밑판과, 줄기와, 잔과, 꽃받침과, 꽃이 그것과 한 덩이로 되었고'),
(1465393,51,2,37,18,'여섯 가지가 그 곁에서 나왔으니 곧 등대의 세 가지는 저편으로 나왔고, 등대의 세 가지는 이 편으로 나왔으며'),
(1465394,51,2,37,19,'이 편 가지에 살구꽃 형상의 잔 셋과, 꽃받침과, 꽃이 있고 저편 가지에 살구꽃 형상의 잔 셋과, 꽃받침과, 꽃이 있어 등대에서 나온 여섯 가지가 그러하며'),
(1465395,51,2,37,20,'등대 줄기에는 살구꽃 형상의 잔 넷과, 꽃받침과, 꽃이 있고'),
(1465396,51,2,37,21,'등대에서 나온 여섯 가지를 위하여는 꽃받침이 있게 하였으되 두가지 아래 한 꽃받침이 있어 줄기와 연하였고 또 두 가지 아래 한 꽃받침이 있어 줄기와 연하게 하였으니'),
(1465397,51,2,37,22,'이 꽃받침과 가지들을 줄기와 연하여 전부를 정금으로 쳐서 만들었으며'),
(1465398,51,2,37,23,'등잔 일곱과, 그 불집게와, 불똥 그릇을 정금으로 만들었으니'),
(1465399,51,2,37,24,'등대와 그 모든 기구는 정금 한 달란트로 만들었더라'),
(1465400,51,2,37,25,'그가 또 조각목으로 분향할 단을 만들었으니 장이 일 규빗이요, 광이 일 규빗이라 네모 반듯하고 고는 이 규빗이며 그 뿔들이 단과 연하였으며'),
(1465401,51,2,37,26,'단 상면과 전후 좌우면과 그 뿔을 정금으로 싸고 주위에 금테를 둘렀고'),
(1465402,51,2,37,27,'그 테 아래 양 편에 금고리 둘을 만들었으되 곧 그 양 편에 만들어 단을 메는 채를 꿰게 하였으며'),
(1465403,51,2,37,28,'조각목으로 그 채를 만들어 금으로 쌌으며'),
(1465404,51,2,37,29,'거룩한 관유와 향품으로 정결한 향을 만들었으되 향을 만드는 법대로 하였더라'),
(1465405,51,2,38,1,'그가 또 조각목으로 번제단을 만들었으니 장이 오 규빗이요, 광이 오 규빗이라 네모 반듯하고 고는 삼 규빗이며'),
(1465406,51,2,38,2,'그 네 모퉁이 위에 그 뿔을 만들되 그 뿔을 단과 연하게 하고 단을 놋으로 쌌으며'),
(1465407,51,2,38,3,'단의 모든 기구 곧 통과, 부삽과, 대야와, 고기 갈고리와, 불 옮기는 그릇을 다 놋으로 만들고'),
(1465408,51,2,38,4,'단을 위하여 놋 그물을 만들어 단 사면 가장자리 아래 두되 단 절반에 오르게 하고'),
(1465409,51,2,38,5,'그 놋 그물 네 모퉁이에 채를 꿸 고리 넷을 부어 만들었으며'),
(1465410,51,2,38,6,'채를 조각목으로 만들어 놋으로 싸고'),
(1465411,51,2,38,7,'단 양편 고리에 그 채를 꿰어 메게 하였으며 단은 널판으로 비게 만들었더라'),
(1465412,51,2,38,8,'그가 놋으로 물두멍을 만들고 그 받침도 놋으로 하였으니 곧 회막문에서 수종드는 여인들의 거울로 만들었더라'),
(1465413,51,2,38,9,'그가 또 뜰을 만들었으니 남으로 뜰의 남편에는 세마포 포장이 백 규빗이라'),
(1465414,51,2,38,10,'그 기둥이 스물이며, 그 받침이 스물이니, 놋이요 기둥의 갈고리와 가름대는 은이며'),
(1465415,51,2,38,11,'그 북편에도 백 규빗이라, 그 기둥이 스물이며, 그 받침이 스물이니, 놋이요 기둥의 갈고리와 가름대는 은이며'),
(1465416,51,2,38,12,'서편에 포장은 오십 규빗이라, 그 기둥이 열이요, 받침이 열이며, 기둥의 갈고리와, 가름대는 은이며'),
(1465417,51,2,38,13,'동으로 동편에도 오십 규빗이라'),
(1465418,51,2,38,14,'문 이편의 포장이 십 오 규빗이요, 그 기둥이 셋이요, 받침이 셋이며'),
(1465419,51,2,38,15,'문 저편도 그와 같으니 뜰문 이편,저편의 포장이 십 오 규빗씩이요, 그 기둥이 셋씩, 받침이 셋씩이라'),
(1465420,51,2,38,16,'뜰 사면의 포장은 세마포요'),
(1465421,51,2,38,17,'기둥 받침은 놋이요, 기둥의 갈고리와 가름대는 은이요, 기둥머리 싸개는 은이며, 뜰의 모든 기둥에 은 가름대를 꿰었으며'),
(1465422,51,2,38,18,'뜰의 문장을 청색, 자색, 홍색실과, 가늘게 꼰 베실로 수 놓아 짰으니 장은 이십 규빗이요, 광 곧 고는 뜰의 포장과 같이 오 규빗이며'),
(1465423,51,2,38,19,'그 기둥은 넷인데 그 받침 넷은 놋이요, 그 갈고리는 은이요, 그 머리 싸개와 가름대도 은이며'),
(1465424,51,2,38,20,'성막 말뚝과 뜰의 사면 포장 말뚝은 다 놋이더라'),
(1465425,51,2,38,21,'성막 곧 증거막을 위하여 레위 사람의 쓴 재료의 물목은 제사장 아론의 아들 이다말이 모세의 명대로 계산하였으며'),
(1465426,51,2,38,22,'유다 지파 훌의 손자요 우리의 아들인 브사렐은 여호와께서 모세에게 명하신 모든 것을 만들었고'),
(1465427,51,2,38,23,'단 지파 아히사막의 아들 오홀리압은 그와 함께 하였으니 오홀리압은 재능이 있어서 조각하며 또 청색, 자색, 홍색실과, 가는 베실로 수 놓은 자더라'),
(1465428,51,2,38,24,'성소 건축 비용으로 드린 금은 성소의 세겔대로 이십 구 달란트와 칠백 삼십 세겔이며'),
(1465429,51,2,38,25,'조사를 받은 회중의 드린 은은 성소의 세겔대로 일백 달란트와 일천 칠백 칠십 오 세겔이니'),
(1465430,51,2,38,26,'조사를 받은 자가 이십세 이상으로 육십만 삼천 오백 오십명인즉 성소의 세겔대로 매인에게 은 한 베가 곧 반 세겔씩이라'),
(1465431,51,2,38,27,'은 일백 달란트로 성소의 판장 받침과 문장 기둥 받침 합 일백을 부어 만들었으니 매 받침에 한 달란트씩 합 일백 달란트요'),
(1465432,51,2,38,28,'일천 칠백 칠십오 세겔로 기둥 갈고리를 만들고 기둥머리를 싸고 기둥 가름대를 만들었으며'),
(1465433,51,2,38,29,'드린 놋은 칠십 달란트와 이천 사백 세겔이라'),
(1465434,51,2,38,30,'이것으로 회막 문기둥 받침과, 놋 단과, 놋그물과, 단의 모든 기구를 만들었으며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465435,51,2,38,31,'뜰 사면의 기둥 받침과 그 문장 기둥 받침이며 성막의 모든 말뚝과 뜰 사면의 모든 말뚝을 만들었더라'),
(1465436,51,2,39,1,'그들이 여호와께서 모세에게 명하신대로 청색, 자색, 홍색실로 성소에서 섬기기 위한 정교한 옷을 만들고 또 아론을 위한 거룩한 옷을 만들었더라'),
(1465437,51,2,39,2,'그가 또 금실과, 청색, 자색, 홍색실과, 가늘게 꼰 베실로 에봇을 만들었으되'),
(1465438,51,2,39,3,'금실을 얇게 쳐서 오려서 실을 만들어 청색, 자색, 홍색실과, 가는 베실에 섞어 공교히 짜고'),
(1465439,51,2,39,4,'에봇을 위하여 견대를 만들어 그 두 끝에 달아 서로 연하게 하고'),
(1465440,51,2,39,5,'에봇 위에 에봇을 매는 띠를 에봇과 같은 모양으로 금실과, 청색, 자색, 홍색실과, 가늘게 꼰 베실로 에봇에 붙여 짰으니 여호와께서 모세에게 명하신대로 하였더라'),
(1465441,51,2,39,6,'그들이 또 호마노를 깎아 금테에 물려 인을 새김 같이 이스라엘의 아들들의 이름을 그것에 새겨'),
(1465442,51,2,39,7,'에봇 견대에 달아 이스라엘 자손의 기념 보석을 삼았으니 여호와께서 모세에게 명하신대로 하였더라'),
(1465443,51,2,39,8,'그가 또 흉패를 공교히 짜되 에봇과 같은 모양으로 금실과, 청색, 자색, 홍색실과, 가늘게 꼰 베실로 하였으니'),
(1465444,51,2,39,9,'그것의 장이 한 뼘, 광이 한 뼘으로 네모 반듯하고 두 겹이며'),
(1465445,51,2,39,10,'그것에 네 줄 보석을 물렸으니 곧 홍보석, 황옥, 녹주옥이 첫 줄이요'),
(1465446,51,2,39,11,'둘째 줄은 석류석, 남보석, 홍마노요'),
(1465447,51,2,39,12,'세째 줄은 호박, 백마노, 자수정이요'),
(1465448,51,2,39,13,'네째 줄은 녹보석, 호마노, 벽옥이라 다 금테에 물렸으니'),
(1465449,51,2,39,14,'이 보석들은 이스라엘 아들들의 이름 곧 그들의 이름대로 열 둘이라 인을 새김 같이 그 열 두 지파의 각 이름을 새겼으며'),
(1465450,51,2,39,15,'그들이 또 정금으로 사슬을 노끈처럼 땋아 흉패에 붙이고'),
(1465451,51,2,39,16,'또 금테 둘과 금고리 둘을 만들어 그 두 고리를 흉패 두 끝에 달고'),
(1465452,51,2,39,17,'그 두 땋은 금사슬을 흉패 끝 두 고리에 꿰어 매었으며'),
(1465453,51,2,39,18,'그 땋은 두 사슬의 다른 두 끝을 에봇 앞 두 견대의 금테에 매고'),
(1465454,51,2,39,19,'또 금고리 둘을 만들어 흉패 두 끝에 달았으니 곧 그 에봇에 대한 안쪽 가에 달았으며'),
(1465455,51,2,39,20,'또 금고리 둘을 만들어 에봇 앞 두 견대 아래 매는 자리 가까운편 곧 공교히 짠 에봇띠 윗편에 달고'),
(1465456,51,2,39,21,'청색 끈으로 흉패 고리와 에봇 고리에 꿰어 흉패로 공교히 짠 에봇 띠 위에 붙여서 에봇을 떠나지 않게 하였으니 여호와께서 모세에게 명하신대로 하였더라'),
(1465457,51,2,39,22,'그가 에봇 받침 긴 옷을 전부 청색으로 짜서 만들되'),
(1465458,51,2,39,23,'그 옷의 두 어깨 사이에 구멍을 내고 갑옷 깃 같이 그 구멍 주위에 깃을 짜서 찢어지지 않게 하고'),
(1465459,51,2,39,24,'청색, 자색, 홍색실과, 가는 베실로 그 옷 가장자리에 석류를 수 놓고'),
(1465460,51,2,39,25,'정금으로 방울을 만들어 그 옷 가장자리로 돌아가며 석류 사이 사이에 달되'),
(1465461,51,2,39,26,'방울과 석류를 서로 간격하여 공직하는 그 옷 가장자리로 돌아가며 달았으니 여호와께서 모세에게 명하신대로 하였더라'),
(1465462,51,2,39,27,'그들이 또 직조한 가는 베로 아론과 그 아들들을 위하여 속옷을 짓고'),
(1465463,51,2,39,28,'세마포로 두건을 짓고 세마포로 빛난 관을 만들고 가는 베실로 짜서 세마포 고의들을 만들고'),
(1465464,51,2,39,29,'가는 베실과, 청색, 자색, 홍색실로 수 놓아 띠를 만들었으니 여호와께서 모세에게 명하신대로 하였더라'),
(1465465,51,2,39,30,'그들이 또 정금으로 거룩한 패를 만들고 인을 새김 같이 그 위에 여호와께 성결이라 새기고'),
(1465466,51,2,39,31,'그 패를 청색 끈으로 관 전면에 달았으니 여호와께서 모세에게 명하신 대로 하였더라'),
(1465467,51,2,39,32,'이스라엘 자손이 이와 같이 성막 곧 회막의 모든 역사를 준공하여 여호와께서 모세에게 명하신대로 다 행하고'),
(1465468,51,2,39,33,'그들이 성막을 모세에게로 가져왔으니 곧 막과, 그 모든 기구와, 그 갈고리들과, 그 널판들과, 그 띠들과, 그 기둥들과, 그 받침들과,'),
(1465469,51,2,39,34,'붉은 물 들인 수양의 가죽 덮개와, 해달의 가죽 덮개와, 가리우는 장과,'),
(1465470,51,2,39,35,'증거궤와, 그 채들과, 속죄소와,'),
(1465471,51,2,39,36,'상과, 그 모든 기구와, 진설병과,'),
(1465472,51,2,39,37,'정금 등대와, 그 잔 곧 벌여놓은 등잔과, 그 모든 기구와, 등유와,'),
(1465473,51,2,39,38,'금단과, 관유와, 향기로운 향과, 장막 문장과,'),
(1465474,51,2,39,39,'놋단과, 그 놋 그물과, 그 채들과, 그 모든 기구와, 물두멍과, 그 받침과,'),
(1465475,51,2,39,40,'뜰의 포장들과, 그 기둥들과, 그 받침들과, 뜰문의 장과, 그 줄들과, 그 말뚝들과, 회막의 소용 곧 성막의 모든 기구와,'),
(1465476,51,2,39,41,'성소에서 섬기기 위한 정교한 옷 곧 제사 직분을 행할 때에 입는 제사장 아론의 거룩한 옷과 그 아들들의 옷이라'),
(1465477,51,2,39,42,'여호와께서 모세에게 명하신대로 이스라엘 자손이 모든 역사를 필하매'),
(1465478,51,2,39,43,'모세가 그 필한 모든 것을 본즉 여호와께서 명하신대로 되었으므로 그들에게 축복하였더라'),
(1465479,51,2,40,1,'여호와께서 모세에게 일러 가라사대'),
(1465480,51,2,40,2,'너는 정월 초일일에 성막 곧 회막을 세우고'),
(1465481,51,2,40,3,'또 증거궤를 들여 놓고 또 장으로 그 궤를 가리우고'),
(1465482,51,2,40,4,'또 상을 들여 놓고 그 위에 물품을 진설하고 등대를 들여 놓고 불을 켜고'),
(1465483,51,2,40,5,'또 금 향단을 증거궤 앞에 두고 성막 문에 장을 달고'),
(1465484,51,2,40,6,'또 번제단을 회막의 성막 문 앞에 놓고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465485,51,2,40,7,'또 물두멍을 회막과 단 사이에 놓고 그 속에 물을 담고'),
(1465486,51,2,40,8,'또 뜰 주위에 포장을 치고 뜰 문에 장을 달고'),
(1465487,51,2,40,9,'또 관유를 취하여 성막과 그 안에 있는 모든 것에 발라 그것과 그 모든 기구를 거룩하게 하라 ! 그것이 거룩하리라'),
(1465488,51,2,40,10,'너는 또 번제단과 그 모든 기구에 발라 그 안을 거룩하게 하라 ! 그 단이 지극히 거룩하리라'),
(1465489,51,2,40,11,'너는 또 물두멍과 그 받침에 발라 거룩하게 하고'),
(1465490,51,2,40,12,'또 아론과 그 아들들을 회막문으로 데려다가 물로 씻기고'),
(1465491,51,2,40,13,'아론에게 거룩한 옷을 입히고 그에게 기름을 부어 거룩하게 하여 그로 내게 제사장의 직분을 행하게 하라'),
(1465492,51,2,40,14,'너는 또 그 아들들을 데려다가 그들에게 겉옷을 입히고'),
(1465493,51,2,40,15,'그 아비에게 기름을 부음 같이 그들에게도 부어서 그들로 내게 제사장 직분을 행하게 하라 그들이 기름 부음을 받았은즉 대대로 영영히 제사장이 되리라 하시매'),
(1465494,51,2,40,16,'모세가 그같이 행하되 곧 여호와께서 자기에게 명하신대로 다 행하였더라'),
(1465495,51,2,40,17,'제 이년 정월 곧 그 달 초일일에 성막을 세우니라'),
(1465496,51,2,40,18,'모세가 성막을 세우되, 그 받침들을 놓고 그 널판들을 세우고, 그 띠를 띠우고 그 기둥들을 세우고,'),
(1465497,51,2,40,19,'또 성막 위에 막을 펴고 그 위에 덮개를 덮으니 여호와께서 모세에게 명하신 대로 되니라'),
(1465498,51,2,40,20,'그가 또 증거판을 궤 속에 넣고 채를 궤에 꿰고 속죄소를 궤 위에 두고'),
(1465499,51,2,40,21,'또 그 궤를 성막에 들여 놓고 장을 드리워서 그 증거궤를 가리우니 여호와께서 모세에게 명하신 대로 되니라'),
(1465500,51,2,40,22,'그가 또 회막 안 곧 성막 북편으로 장 밖에 상을 놓고'),
(1465501,51,2,40,23,'또 여호와 앞 그 상 위에 떡을 진설하니 여호와께서 모세에게 명하신 대로 되니라'),
(1465502,51,2,40,24,'그가 또 회막 안 곧 성막 남편에 등대를 놓아 상과 대하게 하고'),
(1465503,51,2,40,25,'또 여호와 앞에 등잔에 불을 켜니 여호와께서 모세에게 명하신 대로 되니라'),
(1465504,51,2,40,26,'그가 또 금 향단을 회막 안 장 앞에 두고'),
(1465505,51,2,40,27,'그 위에 향기로운 향을 사르니 여호와께서 모세에게 명하신 대로 되니라'),
(1465506,51,2,40,28,'그가 또 성막문에 장을 달고'),
(1465507,51,2,40,29,'또 회막의 성막 문 앞에 번제단을 두고 번제와 소제를 그 위에 드리니 여호와께서 모세에게 명하신 대로 되니라'),
(1465508,51,2,40,30,'그가 또 물두멍을 회막과 단 사이에 두고 거기 씻을 물을 담고'),
(1465509,51,2,40,31,'자기와 아론과 그 아들들이 거기서 수족을 씻되'),
(1465510,51,2,40,32,'그들이 회막에 들어갈 때와 단에 가까이 갈 때에 씻었으니 여호와께서 모세에게 명하신 대로 되니라'),
(1465511,51,2,40,33,'그가 또 성막과 단 사면 뜰에 포장을 치고 뜰문의 장을 다니라 모세가 이같이 역사를 필하였더라'),
(1465512,51,2,40,34,'그 후에 구름이 회막에 덮이고 여호와의 영광이 성막에 충만하매'),
(1465513,51,2,40,35,'모세가 회막에 들어갈 수 없었으니 이는 구름이 회막 위에 덮이고 여호와의 영광이 성막에 충만함이었으며'),
(1465514,51,2,40,36,'구름이 성막 위에서 떠오를 때에는 이스라엘 자손이 그 모든 행하는 길에 앞으로 발행하였고'),
(1465515,51,2,40,37,'구름이 떠오르지 않을 때에는 떠오르는 날까지 발행하지 아니하였으며'),
(1465516,51,2,40,38,'낮에는 여호와의 구름이 성막 위에 있고 밤에는 불이 그 구름 가운데 있음을 이스라엘의 온 족속이 그 모든 행하는 길에서 친히 보았더라'),
(1465517,51,3,1,1,'여호와께서 회막에서 모세를 부르시고 그에게 일러 가라사대'),
(1465518,51,3,1,2,'이스라엘 자손에게 고하여 이르라 너희 중에 누구든지 여호와께 예물을 드리려거든 생축 중에서 소나 양으로 예물을 드릴지니라 !'),
(1465519,51,3,1,3,'그 예물이 소의 번제이면 흠 없는 수컷으로 회막 문에서 여호와 앞에 열납하시도록 드릴지니라 !'),
(1465520,51,3,1,4,'그가 번제물의 머리에 안수할지니 그리하면 열납되어 그를 위하여 속죄가 될 것이라'),
(1465521,51,3,1,5,'그는 여호와 앞에서 그 수송아지를 잡을 것이요, 아론의 자손 제사장들은 그 피를 가져다가 회막 문 앞 단 사면에 뿌릴 것이며'),
(1465522,51,3,1,6,'그는 또 그 번제 희생의 가죽을 벗기고 각을 뜰 것이요,'),
(1465523,51,3,1,7,'제사장 아론의 자손들은 단 위에 불을 두고 불 위에 나무를 벌여 놓고'),
(1465524,51,3,1,8,'아론의 자손 제사장들은 그 뜬 각과 머리와 기름을 단 윗불 위에 있는 나무에 벌여 놓을 것이며'),
(1465525,51,3,1,9,'그 내장과 정갱이를 물로 씻을 것이요, 제사장은 그 전부를 단 위에 불살라 번제를 삼을지니 이는 화제라 여호와께 향기로운 냄새니라.'),
(1465526,51,3,1,10,'만일 그 예물이 떼의 양이나 염소의 번제이면 흠없는 수컷으로 드릴지니'),
(1465527,51,3,1,11,'그가 단 북편에서 여호와 앞에서 잡을 것이요,아론의 자손 제사장들은 그 피를 단 사면에 뿌릴 것이며'),
(1465528,51,3,1,12,'그는 그것의 각을 뜨고 그 머리와 그 기름을 베어 낼 것이요, 제사장은 그것을 다 단 윗불 위에 있는 나무에 벌여 놓을 것이며'),
(1465529,51,3,1,13,'그 내장과 정갱이를 물로 씻을 것이요, 제사장은 그 전부를 가져다가 단 위에 불살라 번제를 삼을지니 이는 화제라 여호와께 향기로운 냄새니라.'),
(1465530,51,3,1,14,'만일 여호와께 드리는 예물이 새의 번제이면 산비둘기나 집비둘기 새끼로 예물을 삼을 것이요,'),
(1465531,51,3,1,15,'제사장은 그것을 단으로 가져다가 그 머리를 비틀어 끊고 단 위에 불사르고 피는 단 곁에 흘릴 것이며'),
(1465532,51,3,1,16,'멱통과 그 더러운 것은 제하여 단 동편 재 버리는 곳에 던지고'),
(1465533,51,3,1,17,'또 그 날개 자리에서 그 몸을 찢되 아주 찢지 말고 제사장이 그것을 단 윗불 위의 나무 위에 살라 번제를 삼을지니 이는 화제라 여호와께 향기로운 냄새니라'),
(1465534,51,3,2,1,'누구든지 소제의 예물을 여호와께 드리려거든 고운 가루로 예물을 삼아 그 위에 기름을 붓고 또 그 위에 유향을 놓아');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465535,51,3,2,2,'아론의 자손 제사장들에게로 가져 올 것이요 제사장은 그 고운 기름 가루 한 줌과 그 모든 유향을 취하여 기념물로 단 위에 불 사를지니 이는 화제라 여호와께 향기로운 냄새니라.'),
(1465536,51,3,2,3,'그 소제물의 남은 것은 아론과 그 자손에게 돌릴지니 이는 여호와의 화제 중에 지극히 거룩한 것이니라'),
(1465537,51,3,2,4,'네가 화덕에 구운 것으로 소제의 예물을 드리려거든 고운 가루에 기름을 섞어 만든 무교병이나 기름을 바른 무교병을 드릴 것이요,'),
(1465538,51,3,2,5,'번철에 부친 것으로 소제의 예물을 드리려거든 고운 가루에 누룩을 넣지 말고 기름을 섞어'),
(1465539,51,3,2,6,'조각으로 나누고 그 위에 기름을 부을지니 이는 소제니라'),
(1465540,51,3,2,7,'네가 솥에 삶은 것으로 소제를 드리려거든 고운 가루와 기름을 섞어 만들지니라 !'),
(1465541,51,3,2,8,'너는 이것들로 만든 소제물을 여호와께로 가져다가 제사장에게 줄 것이요, 제사장은 그것을 단으로 가져다가'),
(1465542,51,3,2,9,'그 소제물 중에서 기념할 것을 취하여 단 위에 불사를지니 이는 화제라 여호와께 향기로운 냄새니라.'),
(1465543,51,3,2,10,'소제물의 남은 것은 아론과 그 자손에게 돌릴찌니 이는 여호와의 화제 중에 지극히 거룩한 것이니라'),
(1465544,51,3,2,11,'무릇 너희가 여호와께 드리는 소제물에는 모두 누룩을 넣지 말지니 너희가 누룩이나 꿀을 여호와께 화제로 드려 사르지 못할지니라'),
(1465545,51,3,2,12,'처음 익은 것으로는 그것을 여호와께 드릴지나 향기로운 냄새를 위하여는 단에 올리지 말지며'),
(1465546,51,3,2,13,'네 모든 소제물에 소금을 치라 ! 네 하나님의 언약의 소금을 네 소제에 빼지 못할지니 네 모든 예물에 소금을 드릴지니라 !'),
(1465547,51,3,2,14,'너는 첫 이삭의 소제를 여호와께 드리거든 첫 이삭을 볶아 찧은 것으로 너의 소제를 삼되'),
(1465548,51,3,2,15,'그 위에 기름을 붓고 그 위에 유향을 더할지니 이는 소제니라 !'),
(1465549,51,3,2,16,'제사장은 찧은 곡식 얼마와, 기름의 얼마와, 모든 유향을 기념물로 불사를지니 이는 여호와께 드리는 화제니라'),
(1465550,51,3,3,1,'사람이 만일 화목제의 희생을 예물로 드리되 소로 드리려거든 수컷이나 암컷이나 흠 없는 것으로 여호와 앞에 드릴지니'),
(1465551,51,3,3,2,'그 예물의 머리에 안수하고 회막 문에서 잡을 것이요, 아론의 자손 제사장들은 그 피를 제단 사면에 뿌릴 것이며'),
(1465552,51,3,3,3,'그는 또 그 화목제의 희생중에서 여호와께 화제를 드릴지니 곧 내장에 덮인 기름과, 내장에 붙은 모든 기름과,'),
(1465553,51,3,3,4,'두 콩팥과, 그 위의 기름 곧 허리 근방에 있는 것과, 간에 덮인 꺼풀을 콩팥과 함께 취할 것이요'),
(1465554,51,3,3,5,'아론의 자손은 그것을 단 윗불 위에 있는 나무 위 번제물 위에 사를지니 이는 화제라 여호와께 향기로운 냄새니라'),
(1465555,51,3,3,6,'만일 여호와께 예물로 드리는 화목제의 희생이 양이면 수컷이나 암컷이나 흠 없는 것으로 드릴지며'),
(1465556,51,3,3,7,'만일 예물로 드리는 것이 어린 양이면 그것을 여호와 앞으로 끌어다가'),
(1465557,51,3,3,8,'그 예물의 머리에 안수하고 회막 앞에서 잡을 것이요, 아론의 자손은 그 피를 단 사면에 뿌릴 것이며'),
(1465558,51,3,3,9,'그는 그 화목제의 희생 중에서 여호와께 화제를 드릴지니 그 기름 곧 미려골에서 벤바 기름진 꼬리와, 내장에 덮힌 기름과, 내장에 붙은 모든 기름과,'),
(1465559,51,3,3,10,'두 콩팥과, 그 위의 기름 곧 허리 근방에 있는 것과, 간에 덮인 꺼풀을 콩팥과 함께 취할 것이요'),
(1465560,51,3,3,11,'제사장은 그것을 단 위에 불사를지니 이는 화제로 여호와께 드리는 식물이니라'),
(1465561,51,3,3,12,'만일 예물이 염소면 그것을 여호와 앞으로 끌어다가'),
(1465562,51,3,3,13,'그 머리에 안수하고 회막 앞에서 잡을 것이요, 아론의 자손은 그 피를 단 사면에 뿌릴 것이며'),
(1465563,51,3,3,14,'그는 그 중에서 예물을 취하여 여호와께 화제를 드릴지니 곧 내장에 덮인 기름과, 내장에 붙은 모든 기름과,'),
(1465564,51,3,3,15,'두 콩팥과, 그 위의 기름 곧 허리 근방에 있는 것과, 간에 덮인 꺼풀을 콩팥과 함께 취할 것이요'),
(1465565,51,3,3,16,'제사장은 그것을 단 위에 불사를지니 이는 화제로 드리는 식물이요, 향기로운 냄새라 모든 기름은 여호와의 것이니라'),
(1465566,51,3,3,17,'너희는 기름과 피를 먹지 말라 ! 이는 너희 모든 처소에서 대대로 영원한 규례니라 !'),
(1465567,51,3,4,1,'여호와께서 모세에게 일러 가라사대'),
(1465568,51,3,4,2,'이스라엘 자손에게 고하여 이르라 누구든지 여호와의 금령 중 하나라도 그릇 범하였으되'),
(1465569,51,3,4,3,'만일 기름 부음을 받은 제사장이 범죄하여 백성으로 죄얼을 입게 하였으면 그 범한 죄를 인하여 흠 없는 수송아지로 속죄 제물을 삼아 여호와께 드릴지니'),
(1465570,51,3,4,4,'곧 그 수송아지를 회막문 여호와 앞으로 끌어다가 그 수송아지 머리에 안수하고 그것을 여호와 앞에서 잡을 것이요'),
(1465571,51,3,4,5,'기름 부음을 받은 제사장은 그 수송아지의 피를 가지고 회막에 들어가서'),
(1465572,51,3,4,6,'그 제사장이 손가락에 그 피를 찍어 여호와 앞 곧 성소 장 앞에 일곱번 뿌릴 것이며'),
(1465573,51,3,4,7,'제사장은 또 그 피를 여호와 앞 곧 회막 안 향단 뿔에 바르고 그 송아지의 피 전부를 회막문 앞 번제단 밑에 쏟을 것이며'),
(1465574,51,3,4,8,'또 그 속죄 제물 된 수송아지의 모든 기름을 취할지니 곧 내장에 덮인 기름과, 내장에 붙은 모든 기름과,'),
(1465575,51,3,4,9,'두 콩팥과, 그 위의 기름 곧 허리 근방에 있는 것과, 간에 덮인 꺼풀을 콩팥과, 함께 취하되'),
(1465576,51,3,4,10,'화목제 희생의 소에게서 취함 같이 할 것이요, 제사장은 그것을 번제단 위에 불사를 것이며'),
(1465577,51,3,4,11,'그 수송아지의 가죽과, 그 모든 고기와, 그 머리와, 다리와, 내장과,'),
(1465578,51,3,4,12,'곧 그 송아지의 전체를 진 바깥 재 버리는 곳인 청결한 곳으로 가져다가 불로 나무 위에 사르되 곧 재 버리는 곳에서 사를지니라'),
(1465579,51,3,4,13,'만일 이스라엘 온 회중이 여호와의 금령 중 하나라도 그릇 범하여 허물이 있으나 스스로 깨닫지 못하다가'),
(1465580,51,3,4,14,'그 범한 죄를 깨달으면 회중은 수송아지를 속죄제로 드릴지니 그것을 회막 앞으로 끌어다가'),
(1465581,51,3,4,15,'회중의 장로들이 여호와 앞에서 그 수송아지 머리에 안수하고 그것을 여호와 앞에서 잡을 것이요'),
(1465582,51,3,4,16,'기름 부음을 받은 제사장은 그 수송아지의 피를 가지고 회막에 들어가서'),
(1465583,51,3,4,17,'그 제사장이 손가락으로 그 피를 찍어 여호와 앞 장 앞에 일곱번 뿌릴 것이며'),
(1465584,51,3,4,18,'또 그 피로 회막 안 여호와 앞에 있는 단 뿔에 바르고 그 피 전부는 회막문 앞 번제단 밑에 쏟을 것이며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465585,51,3,4,19,'그 기름은 다 취하여 단 위에 불사르되'),
(1465586,51,3,4,20,'그 송아지를 속제죄의 수송아지에게 한 것 같이 할지며 제사장이 그것으로 회중을 위하여 속죄한즉 그들이 사함을 얻으리라 !'),
(1465587,51,3,4,21,'그는 그 수송아지를 진 밖으로 가져다가 첫번 수송아지를 사름같이 사를지니 이는 회중의 속죄제니라'),
(1465588,51,3,4,22,'만일 족장이 그 하나님 여호와의 금령 중 하나라도 부지중에 범하여 허물이 있었다가'),
(1465589,51,3,4,23,'그 범한 죄에 깨우침을 받거든 그는 흠 없는 수염소를 예물로 가져다가'),
(1465590,51,3,4,24,'그 수염소의 머리에 안수하고 여호와 앞 번제 희생을 잡는 곳에서 잡을지니 이는 속죄제라'),
(1465591,51,3,4,25,'제사장은 그 속죄 희생의 피를 손가락으로 찍어 번제단 뿔에 바르고 그 피는 번제단 밑에 쏟고'),
(1465592,51,3,4,26,'그 모든 기름은 화목제 희생의 기름같이 단 위에 불사를지니 이같이 제사장이 그 범한 죄에 대하여 그를 위하여 속죄한즉 그가 사함을 얻으리라 !'),
(1465593,51,3,4,27,'만일 평민의 하나가 여호와의 금령 중 하나라도 부지중에 범하여 허물이 있었다가'),
(1465594,51,3,4,28,'그 범한 죄에 깨우침을 받거든 그는 흠 없는 암염소를 끌고와서 그 범한 죄를 인하여 그것을 예물로 삼아'),
(1465595,51,3,4,29,'그 속죄제 희생의 머리에 안수하고 그 희생을 번제소에서 잡을 것이요'),
(1465596,51,3,4,30,'제사장은 손가락으로 그 피를 찍어 번제단 뿔에 바르고 그 피 전부를 단 밑에 쏟고'),
(1465597,51,3,4,31,'그 모든 기름을 화목제 희생의 기름을 취한 것 같이 취하여 단 위에 불 살라 여호와께 향기롭게 할지니 제사장이 그를 위하여 속죄 한즉 그가 사함을 얻으리라 !'),
(1465598,51,3,4,32,'그가 만일 어린 양을 속죄 제물로 가져 오려거든 흠 없는 암컷을 끌어다가'),
(1465599,51,3,4,33,'그 속죄제 희생의 머리에 안수하고 번제 희생을 잡는 곳에서 잡아 속죄제를 삼을 것이요'),
(1465600,51,3,4,34,'제사장은 그 속죄제 희생의 피를 손가락으로 찍어 번제단 뿔에 바르고 그 피는 전부를 단 밑에 쏟고'),
(1465601,51,3,4,35,'그 모든 기름을 화목제 어린 양의 기름을 취한것 같이 취하여 단 위 여호와의 화제물 위에 불사를지니 이같이 제사장이 그의 범한죄에 대하여 그를 위하여 속죄한즉 그가 사함을 얻으리라 !'),
(1465602,51,3,5,1,'누구든지 증인이 되어 맹세시키는 소리를 듣고도 그 본 일이나 아는 일을 진술치 아니하면 죄가 있나니 그 허물이 그에게로 돌아갈 것이요'),
(1465603,51,3,5,2,'누구든지 부정한 들짐승의 사체나, 부정한 가축의 사체나, 부정한 곤충의 사체들, 무릇 부정한 것을 만졌으면 부지중에라 할지라도 그 몸이 더러워져서 허물이 있을 것이요'),
(1465604,51,3,5,3,'혹시 부지중에 사람의 부정에 다닥쳤는데 그 사람의 부정이 어떠한 부정이든지 그것을 깨달을 때에는 허물이 있을 것이요'),
(1465605,51,3,5,4,'혹 누구든지 무심중에 입으로 맹세를 발하여 악을 하리라 하든지, 선을 하리라 하면 그 사람의 무심중에 맹세를 발하여 말한 것이 어떠한 일이든지 깨닫지 못하다가 그것을 깨달을 때에는 그 중 하나에 허물이 있을 것이니'),
(1465606,51,3,5,5,'이 중 하나에 허물이 있을 때에는 아무 일에 범과하였노라 자복하고'),
(1465607,51,3,5,6,'그 범과를 인하여 여호와께 속건제를 드리되 양떼의 암컷 어린 양이나 염소를 끌어다가 속죄제를 드릴 것이요 제사장은 그의 허물을 위하여 속죄할지니라 !'),
(1465608,51,3,5,7,'만일 힘이 어린 양에 미치지 못하거든 그 범과를 속하기 위하여 산비둘기 둘이나 집비둘기 새끼 둘을 여호와께로 가져 가되 하나는 속죄제물을 삼고, 하나는 번제물을 삼아'),
(1465609,51,3,5,8,'제사장에게로 가져 갈 것이요, 제사장은 그 속죄 제물을 먼저 드리되 그 머리를 목에서 비틀어 끊고 몸은 아주 쪼개지 말며'),
(1465610,51,3,5,9,'그 속죄 제물의 피를 단 곁에 뿌리고 그 남은 피는 단 밑에 흘릴지니 이는 속죄제요'),
(1465611,51,3,5,10,'그 다음 것은 규례대로 번제를 드릴지니 제사장이 그의 범과를 위하여 속한즉 그가 사함을 얻으리라 !'),
(1465612,51,3,5,11,'만일 힘이 산비둘기 둘이나 집비둘기 둘에도 미치지 못하거든 그 범과를 인하여 고운 가루 에바 십분 일을 예물로 가져다가 속죄 제물로 드리되 이는 속죄제인즉 그 위에 기름을 붓지 말며 유향을 놓지 말고'),
(1465613,51,3,5,12,'그것을 제사장에게로 가져갈 것이요, 제사장은 그것을 기념물로 한 움큼을 취하여 단 위 여호와의 화제물 위에 불사를지니 이는 속죄제라'),
(1465614,51,3,5,13,'제사장이 그가 이 중에 하나를 범하여 얻은 허물을 위하여 속한즉 그가 사함을 얻으리라 ! 그 나머지는 소제물같이 제사장에게 돌릴지니라 !'),
(1465615,51,3,5,14,'여호와께서 모세에게 일러 가라사대'),
(1465616,51,3,5,15,'누구든지 여호와의 성물에 대하여 그릇 범과하였거든 여호와께 속건제를 드리되 너의 지정한 가치를 따라 성소의 세겔로 몇 세겔 은에 상당한 흠 없는 수양을 떼 중에서 끌어다가 속건제로 드려서'),
(1465617,51,3,5,16,'성물에 대한 범과를 갚되 그것에 오분 일을 더하여 제사장에게 줄 것이요 제사장은 그 속건제의 수양으로 그를 위하여 속한즉 그가 사함을 얻으리라 !'),
(1465618,51,3,5,17,'만일 누구든지 여호와의 금령 중 하나를 부지중에 범하여도 허물이라 벌을 당할 것이니'),
(1465619,51,3,5,18,'그는 너의 지정한 가치대로 떼 중 흠 없는 수양을 속건 제물로 제사장에게로 가져올 것이요, 제사장은 그의 부지중에 그릇 범한 허물을 위하여 속한즉 그가 사함을 얻으리라 !'),
(1465620,51,3,5,19,'이는 속건제니 그가 실로 여호와 앞에 범과함이니라'),
(1465621,51,3,6,1,'여호와께서 모세에게 일러 가라사대'),
(1465622,51,3,6,2,'누구든지 여호와께 신실치 못하여 범죄하되 곧 남의 물건을 맡거나 전당 잡거나 강도질하거나 늑봉하고도 사실을 부인하거나'),
(1465623,51,3,6,3,'남의 잃은 물건을 얻고도 사실을 부인하여 거짓 맹세하는 등 사람이 이 모든 일 중에 하나라도 행하여 범죄하면'),
(1465624,51,3,6,4,'이는 죄를 범하였고 죄가 있는 자니 그 빼앗은 것이나 늑봉한 것이나 맡은 것이나 얻은 유실물이나'),
(1465625,51,3,6,5,'무릇 그 거짓 맹세한 물건을 돌려 보내되 곧 그 본물에 오분 일을 더하여 돌려 보낼 것이니 그 죄가 드러나는 날에 그 임자에게 줄 것이요'),
(1465626,51,3,6,6,'그는 또 그 속건제를 여호와께 가져 올지니 곧 너의 지정한 가치대로 떼 중 흠 없는 수양을 속건 제물을 위하여 제사장에게로 끌어 올 것이요'),
(1465627,51,3,6,7,'제사장은 여호와 앞에서 그를 위하여 속죄한즉 그는 무슨 허물이든지 사함을 얻으리라 !'),
(1465628,51,3,6,8,'여호와께서 모세에게 일러 가라사대'),
(1465629,51,3,6,9,'아론과 그 자손에게 명하여 이르라 번제의 규례는 이러하니라 번제물은 단 위 석쇠 위에 아침까지 두고 단의 불로 그 위에서 꺼지지 않게 할 것이요'),
(1465630,51,3,6,10,'제사장은 세마포 긴 옷을 입고 세마포 고의로 하체를 가리우고 단 위에서 탄 번제의 재를 가져다가 단 곁에 두고'),
(1465631,51,3,6,11,'그 옷을 벗고 다른 옷을 입고 그 재를 진 바깥 정결한 곳으로 가져 갈 것이요'),
(1465632,51,3,6,12,'단 위에 불은 항상 피워 꺼지지 않게 할지니 제사장은 아침마다 나무를 그 위에 태우고 번제물을 그 위에 벌여놓고 화목제의 기름을 그 위에 사를지며'),
(1465633,51,3,6,13,'불은 끊이지 않고 단 위에 피워 꺼지지 않게 할지니라'),
(1465634,51,3,6,14,'소제의 규례는 이러하니라 아론의 자손은 그것을 단 앞 여호와 앞에 드리되');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465635,51,3,6,15,'그 소제의 고운 기름 가루 한 웅큼과 소제물 위의 유향을 다 취하여 기념물로 단 위에 불살라 여호와 앞에 향기로운 냄새가 되게 하고'),
(1465636,51,3,6,16,'그 나머지는 아론과 그 자손이 먹되 누룩을 넣지 말고 거룩한 곳 회막 뜰에서 먹을지니라 !'),
(1465637,51,3,6,17,'그것에 누룩을 넣어 굽지 말라 ! 이는 나의 화제 중에서 내가 그들에게 주어 그 소득이 되게 하는 것이라 속죄제와 속건제같이 지극히 거룩한즉'),
(1465638,51,3,6,18,'무릇 아론 자손의 남자는 이를 먹을지니 이는 여호와의 화제 중에서 그들의 대대로 영원한 소득이 됨이라 이를 만지는 자마다 거룩하니라 !'),
(1465639,51,3,6,19,'여호와께서 모세에게 일러 가라사대'),
(1465640,51,3,6,20,'아론과 그 자손이 기름 부음을 받는 날에 여호와께 드릴 예물은 이러하니라 고운 가루 에바 십분 일을 항상 드리는 소제물로 삼아 그 절반은 아침에,절반은 저녁에 드리되'),
(1465641,51,3,6,21,'그것을 기름으로 반죽하여 번철에 굽고 기름에 적시어다가 썰어 소제로 여호와께 드려 향기로운 냄새가 되게 하라'),
(1465642,51,3,6,22,'이 소제는 아론의 자손 중 기름 부음을 받고 그를 이어 제사장 된 자가 드릴 것이요, 영원한 규례로 여호와께 온전히 불사를 것이니'),
(1465643,51,3,6,23,'무릇 제사장의 소제물은 온전히 불사르고 먹지 말지니라 !'),
(1465644,51,3,6,24,'여호와께서 모세에게 일러 가라사대'),
(1465645,51,3,6,25,'아론과 그 아들들에게 고하여 이르라 ! 속죄제의 규례는 이러하니라 속죄제 희생은 지극히 거룩하니 여호와 앞 번제 희생을 잡는 곳에서 그 속죄제 희생을 잡을 것이요'),
(1465646,51,3,6,26,'죄를 위하여 제사드리는 제사장이 그것을 먹되 곧 회막 뜰 거룩한 곳에서 먹을 것이며'),
(1465647,51,3,6,27,'무릇 그 고기에 접촉하는 자는 거룩할 것이며 그 피가 어떤 옷에든지 묻었으면 묻은 그것을 거룩한 곳에서 빨 것이요'),
(1465648,51,3,6,28,'그 고기를 토기에 삶았으면 그 그릇을 깨뜨릴 것이요, 유기에 삶았으면 그 그릇을 닦고 물에 씻을 것이며'),
(1465649,51,3,6,29,'그 고기는 지극히 거룩하니 제사장의 남자마다 먹을 것이니라'),
(1465650,51,3,6,30,'그러나 피를 가지고 회막에 들어가 성소에서 속하게 한 속죄제 희생의 고기는 먹지 못할지니 불사를지니라'),
(1465651,51,3,7,1,'속건제의 규례는 이러하니라 이는 지극히 거룩하니'),
(1465652,51,3,7,2,'번제 희생을 잡는 곳에서 속건제의 희생을 잡을 것이요 제사장은 그 피를 단 사면에 뿌릴 것이며'),
(1465653,51,3,7,3,'그 모든 기름을 드리되 곧 그 기름진 꼬리와, 내장에 덮인 기름과,'),
(1465654,51,3,7,4,'두 콩팥과, 그 위의 기름 곧 허리 근방에 있는 것과, 간에 덮인 꺼풀을 콩팥과 함께 취하고'),
(1465655,51,3,7,5,'제사장은 그것을 다 단 위에 불살라 여호와께 화제로 드릴 것이니라 이는 속건제요'),
(1465656,51,3,7,6,'지극히 거룩하니 이것을 제사장의 남자마다 먹되 거룩한 곳에서 먹을지며'),
(1465657,51,3,7,7,'속건제나 속죄제는 일례니 그 제육은 속하는 제사장에게로 돌아갈 것이요'),
(1465658,51,3,7,8,'사람의 번제를 드리는 제사장 곧 그 제사장은 그 드린 번제물의 가죽을 자기가 얻을 것이며'),
(1465659,51,3,7,9,'무릇 화덕에 구운 소제물과 솥에나 번철에 만든 소제물은 그 드린 제사장에게로 돌아갈 것이니'),
(1465660,51,3,7,10,'무릇 소제물은 기름 섞은 것이나 마른 것이나 아론의 모든 자손이 평균히 분배할 것이니라'),
(1465661,51,3,7,11,'여호와께 드릴 화목제 희생의 규례는 이러하니라'),
(1465662,51,3,7,12,'만일 그것을 감사하므로 드리거든 기름 섞은 무교병과 기름 바른 무교병과 고운 가루에 기름 섞어 구운 과자를 그 감사 희생과 함께 드리고'),
(1465663,51,3,7,13,'또 유교병을 화목제의 감사 희생과 함께 그 예물에 드리되'),
(1465664,51,3,7,14,'그 전체의 예물 중에서 하나씩 여호와께 거제로 드리고 그것을 화목제의 피를 뿌린 제사장들에게로 돌릴지니라 !'),
(1465665,51,3,7,15,'감사함으로 드리는 화목제 희생의 고기는 드리는 그 날에 먹을 것이요, 조금이라도 이튿날 아침까지 두지 말 것이니라'),
(1465666,51,3,7,16,'그러나 그 희생의 예물이 서원이나 자원의 예물이면 그 희생을 드린 날에 먹을 것이요, 그 남은 것은 이튿날에도 먹되'),
(1465667,51,3,7,17,'그 희생의 고기가 제 삼일까지 남았으면 불사를지니'),
(1465668,51,3,7,18,'만일 그 화목제 희생의 고기를 제 삼일에 조금이라도 먹으면 그 제사는 열납되지 않을 것이라 드린 자에게도 예물답게 못되고 도리어 가증한 것이 될 것이며 그것을 먹는 자는 죄를 당하리라'),
(1465669,51,3,7,19,'그 고기가 부정한 물건에 접촉되었으면 먹지 말고 불사를 것이라 그 고기는 깨끗한 자만 먹을 것이니'),
(1465670,51,3,7,20,'만일 몸이 부정한 자가 여호와께 속한 화목제 희생의 고기를 먹으면 그 사람은 자기 백성 중에서 끊쳐질 것이요'),
(1465671,51,3,7,21,'만일 누구든지 부정한 것 곧 사람의 부정이나 부정한 짐승이나 부정하고 가증한 아무 물건이든지 만지고 여호와께 속한 화목제 희생의 고기를 먹으면 그 사람도 자기 백성 중에서 끊쳐지리라 !'),
(1465672,51,3,7,22,'여호와께서 모세에게 일러 가라사대'),
(1465673,51,3,7,23,'이스라엘 자손에게 고하여 이르라 너희는 소나 양이나 염소의 기름을 먹지 말 것이요'),
(1465674,51,3,7,24,'스스로 죽은 것의 기름이나 짐승에게 찢긴 것의 기름은 달리는 쓰려니와 결단코 먹지 말지니라'),
(1465675,51,3,7,25,'사람이 여호와께 화제로 드리는 희생의 기름을 먹으면 그 먹는 자는 자기 백성 중에서 끊쳐지리라 !'),
(1465676,51,3,7,26,'너희의 사는 모든 곳에서 무슨 피든지 새나 짐승의 피를 먹지 말라 !'),
(1465677,51,3,7,27,'무슨 피든지 먹는 사람이 있으면 그 사람은 다 자기 백성 중에서 끊쳐지리라 !'),
(1465678,51,3,7,28,'여호와께서 모세에게 일러 가라사대'),
(1465679,51,3,7,29,'이스라엘 자손에게 고하여 이르라 화목제의 희생을 여호와께 드리려는 자는 그 화목제 희생 중에서 그 예물을 취하여 여호와께 가져오되'),
(1465680,51,3,7,30,'여호와의 화제는 그 사람이 자기 손으로 가져올지니 곧 그 제물의 기름과 가슴을 가져올 것이요 제사장은 그 가슴을 여호와 앞에 흔들어 요제를 삼고'),
(1465681,51,3,7,31,'그 기름은 단 위에 불사를 것이며 가슴은 아론과 그 자손들에게 돌릴 것이며'),
(1465682,51,3,7,32,'또 너희는 그 화목제 희생의 우편 뒷다리를 제사장에게 주어 거제를 삼을지니'),
(1465683,51,3,7,33,'아론의 자손 중 화목제 희생의 피와 기름을 드리는 자가 그 우편 뒷다리를 자기의 소득으로 삼을 것이라'),
(1465684,51,3,7,34,'내가 이스라엘 자손의 화목제 중에서 그 흔든 가슴과 든 뒷다리를 취하여 제사장 아론과 그 자손에게 주었나니 이는 이스라엘 자손에게 받을 영원한 소득이니라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465685,51,3,7,35,'이는 여호와의 화제 중에서 아론에게 돌릴 것과 그 자손에게 돌릴 것이니 그들을 세워 여호와의 제사장의 직분을 행하게 한 날'),
(1465686,51,3,7,36,'곧 그들에게 기름 부은 날에 여호와께서 명하사 이스라엘 자손 중에서 그들에게 돌리게 하신 것이라 대대로 영원히 받을 소득이니라'),
(1465687,51,3,7,37,'이는 번제와, 소제와, 속죄제와, 속건제와, 위임제와, 화목제의 규례라'),
(1465688,51,3,7,38,'여호와께서 시내 광야에서 이스라엘 자손에게 그 예물을 여호와께 드리라 명하신 날에 시내산에서 이같이 모세에게 명하셨더라'),
(1465689,51,3,8,1,'여호와께서 모세에게 일러 가라사대'),
(1465690,51,3,8,2,'너는 아론과, 그 아들들과, 그 의복과, 관유와, 속죄제의 수송아지와 수양 둘과 무교병 한 광주리를 이끌고'),
(1465691,51,3,8,3,'온 회중을 회막 문에 모으라'),
(1465692,51,3,8,4,'모세가 여호와꼐서 자기에게 명하신 대로 하매 회중이 회막 문에 모인지라'),
(1465693,51,3,8,5,'모세가 회중에게 이르되 ''여호와께서 행하라고 명하신 것이 이러하니라'' 하고'),
(1465694,51,3,8,6,'아론과 그 아들들을 데려다가 물로 그들을 씻기고'),
(1465695,51,3,8,7,'아론에게 속옷을 입히며 띠를 띠우고 겉옷을 입히며 에봇을 더하고 에봇의 기묘하게 짠 띠를 띠워서 에봇을 몸에 매고'),
(1465696,51,3,8,8,'흉패를 붙이고 흉패에 우림과 둠밈을 넣고'),
(1465697,51,3,8,9,'그 머리에 관을 씌우고 그 관 위 전면에 금패를 붙이니 곧 거룩한 관이라 여호와께서 모세에게 명하심과 같았더라'),
(1465698,51,3,8,10,'모세가 관유를 취하여 장막과 그 안에 있는 모든 것에 발라 거룩하게 하고'),
(1465699,51,3,8,11,'또 단에 일곱번 뿌리고 또 그 단과 그 모든 기구와 물두멍과 그 받침에 발라 거룩하게 하고'),
(1465700,51,3,8,12,'또 관유로 아론의 머리에 부어 발라 거룩하게 하고'),
(1465701,51,3,8,13,'모세가 또 아론의 아들들을 데려다가 그들에게 속옷을 입히고 띠를 띠우며 관을 씌웠으니 여호와께서 모세에게 명하심과 같았더라'),
(1465702,51,3,8,14,'모세가 또 속죄제의 수송아지를 끌어오니 아론과 그 아들들이 그 속죄제 수송아지 머리에 안수하매'),
(1465703,51,3,8,15,'모세가 잡고 그 피를 취하여 손가락으로 그 피를 단의 네 귀퉁이 뿔에 발라 단을 깨끗하게 하고 그 피는 단 밑에 쏟아 단을 속하여 거룩하게 하고'),
(1465704,51,3,8,16,'또 내장에 덮인 모든 기름과, 간 꺼풀과, 두 콩팥과, 그 기름을 취하여 단 위에 불사르고'),
(1465705,51,3,8,17,'그 수송아지 곧 그 가죽과 고기와 똥은 진 밖에 불살랐으니 여호와께서 모세에게 명하심과 같았더라'),
(1465706,51,3,8,18,'또 번제의 수양을 드릴새 아론과 그 아들들이 그 수양의 머리에 안수하매'),
(1465707,51,3,8,19,'모세가 잡아 그 피를 단 주위에 뿌리고'),
(1465708,51,3,8,20,'그 수양의 각을 뜨고 그 머리와 각뜬 것과 기름을 불사르고'),
(1465709,51,3,8,21,'물로 내장과 정갱이들을 씻고 그 수양의 전부를 단 위에 불사르니 이는 향기로운 냄새를 위하여 드리는 번제로 여호와께 드리는 화제라 여호와께서 모세에게 명하심과 같았더라'),
(1465710,51,3,8,22,'또 다른 수양 곧 위임식의 수양을 드릴새 아론과 그 아들들이 그 수양의 머리에 안수하매'),
(1465711,51,3,8,23,'모세가 잡고 그 피를 취하여 아론의 오른 귓부리와, 오른손 엄지 가락과, 오른발 엄지가락에 바르고'),
(1465712,51,3,8,24,'아론의 아들들을 데려다가 그 오른 귓부리와, 오른손 엄지가락과, 오른발 엄지가락에 그 피를 바르고 또 그 피를 단 주위에 뿌리고'),
(1465713,51,3,8,25,'그가 또 그 기름과, 기름진 꼬리와, 내장에 덮인 모든 기름과, 간 꺼풀과, 두 콩팥과, 기름과, 우편 뒷다리를 취하고'),
(1465714,51,3,8,26,'여호와 앞 무교병 광주리에서 무교병 한개와 기름 섞은 떡 한개와 전병 한개를 취하여 그 기름 위에와 우편 뒷다리 위에 놓아'),
(1465715,51,3,8,27,'그 전부를 아론의 손과 그 아들들의 손에 두어 여호와 앞에 흔들어 요제를 삼게 하고'),
(1465716,51,3,8,28,'모세가 그것을 그들의 손에서 취하여 단 윗 번제물 위에 불사르니 이는 향기로운 냄새를 위하여 드리는 위임식 제사로 여호와께 드리는 화제라'),
(1465717,51,3,8,29,'이에 모세가 그 가슴을 취하여 여호와 앞에 흔들어 요제를 삼았으니 이는 위임식 수양의 모세의 응식이라 여호와께서 모세에게 명하심과 같았더라'),
(1465718,51,3,8,30,'모세가 관유와 단 위의 피를 취하여 아론과 그 옷과 그 아들들과 그 아들들의 옷에 뿌려서 아론과 그 옷과 그 아들들과 그 아들들의 옷을 거룩하게 하고'),
(1465719,51,3,8,31,'아론과 그 아들들에게 이르되 `내게 이미 명하시기를 아론과 그 아들들은 먹으라 하셨은즉 너희는 회막 문에서 그 고기를 삶아 위임식 광주리 안의 떡과 아울러 그 곳에서 먹고'),
(1465720,51,3,8,32,'고기와 떡의 나머지는 불사를지며'),
(1465721,51,3,8,33,'위임식은 칠일 동안 행하나니 위임식이 마치는 날까지 칠일 동안은 회막 문에 나가지 말라'),
(1465722,51,3,8,34,'오늘날 행한 것은 여호와께서 너희를 위하여 속하게 하시려고 명하신 것이니'),
(1465723,51,3,8,35,'너희는 칠 주야를 회막 문에 거하여 여호와의 부탁을 지키라 ! 그리하면 사망을 면하리라 내가 이같이 명령을 받았느니라'''),
(1465724,51,3,8,36,'아론과 그 아들들이 여호와께서 모세로 명하신 모든 일을 준행하니라'),
(1465725,51,3,9,1,'제 팔일에 모세가 아론과 그 아들들과 이스라엘 장로들을 불러다가'),
(1465726,51,3,9,2,'아론에게 이르되 `흠 없는 송아지를 속죄제를 위하여 취하고 흠 없는 수양을 번제를 위하여 취하여 여호와 앞에 드리고'),
(1465727,51,3,9,3,'이스라엘 자손에게 고하여 이르기를 너희는 수염소를 속죄제를 위하여 취하고 또 송아지와 어린 양의 일년 되고 흠 없는 것을 번제를 위하여 취하고'),
(1465728,51,3,9,4,'또 화목제를 위하여 여호와 앞에 드릴 수소와 수양을 취하고 또 기름 섞은 소제물을 가져오라 하라 오늘 여호와께서 너희에게 나타나실 것임이니라'' 하매'),
(1465729,51,3,9,5,'그들이 모세의 명한 모든 것을 회막 앞으로 가져 오고 온 회중이 나아와 여호와 앞에 선지라'),
(1465730,51,3,9,6,'모세가 가로되 `이는 여호와께서 너희에게 하라고 명하신 것이니 여호와의 영광이 너희에게 나타나리라'''),
(1465731,51,3,9,7,'그가 또 아론에게 이르되 `너는 단에 나아가 네 속죄제와 네 번제를 드려서 너를 위하여,백성을 위하여 속하고 또 백성의 예물을 드려서 그들을 위하여 속하되 무릇 여호와의 명대로 하라'''),
(1465732,51,3,9,8,'이에 아론이 단에 나아가 자기를 위한 속죄제 송아지를 잡으매'),
(1465733,51,3,9,9,'아론의 아들들이 그 피를 아론에게 받들어 주니 아론이 손가락으로 그 피를 찍어 단 뿔들에 바르고 그 피는 단 밑에 쏟고'),
(1465734,51,3,9,10,'그 속죄제 희생의 기름과 콩팥과 간 꺼풀을 단 위에 불사르니 여호와께서 모세에게 명하심과 같았고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465735,51,3,9,11,'그 고기와 가죽은 진 밖에서 불사르니라'),
(1465736,51,3,9,12,'아론이 또 번제 희생을 잡으매 아론의 아들들이 그 피를 그에게로 가져오니 그가 그 피를 단 주위에 뿌리고'),
(1465737,51,3,9,13,'그들이 또 번제의 희생 곧 그 각과 머리를 그에게로 가져오매 그가 단 위에 불사르고'),
(1465738,51,3,9,14,'또 내장과 정갱이는 씻어서 단 윗 번제물 위에 불사르니라'),
(1465739,51,3,9,15,'그가 또 백성의 예물을 드리되 곧 백성을 위한 속죄제의 염소를 취하여 잡아 전과 같이 죄를 위하여 드리고'),
(1465740,51,3,9,16,'또 번제 희생을 드리되 규례대로 드리고'),
(1465741,51,3,9,17,'또 소제를 드리되 그 중에서 한 움큼을 취하여 아침 번제물에 더하여 단 위에 불사르고'),
(1465742,51,3,9,18,'또 백성을 위하는 화목제 희생의 수소와 수양을 잡으매 아론의 아들들이 그 피를 그에게로 가져오니 그가 단 주위에 뿌리고'),
(1465743,51,3,9,19,'그들이 또 수소와, 수양의 기름과, 기름진 꼬리와, 내장에 덮인 것과, 콩팥과, 간 꺼풀을 아론에게로 가져다가'),
(1465744,51,3,9,20,'그 기름을 가슴들 위에 놓으매 아론이 그 기름을 단위에 불사르고'),
(1465745,51,3,9,21,'가슴들과 우편 뒷다리를 그가 여호와 앞에 요제로 흔드니 모세의 명한 것과 같았더라'),
(1465746,51,3,9,22,'아론이 백성을 향하여 손을 들어 축복함으로 속죄제와 번제와 화목제를 필하고 내려오니라'),
(1465747,51,3,9,23,'모세와 아론이 회막에 들어 갔다가 나와서 백성에게 축복하매 여호와의 영광이 온 백성에게 나타나며'),
(1465748,51,3,9,24,'불이 여호와 앞에서 나와 단 위의 번제물과 기름을 사른지라 온 백성이 이를 보고 소리지르며 엎드렸더라'),
(1465749,51,3,10,1,'아론의 아들 나답과 아비후가 각기 향로를 가져다가 여호와의 명하시지 않은 다른 불을 담아 여호와 앞에 분향하였더니'),
(1465750,51,3,10,2,'불이 여호와 앞에서 나와 그들을 삼키매 그들이 여호와 앞에서 죽은지라'),
(1465751,51,3,10,3,'모세가 아론에게 이르되 `이는 여호와의 말씀이라 ! 이르시기를 나는 나를 가까이 하는 자 중에 내가 거룩하다 함을 얻겠고 온 백성 앞에 내가 영광을 얻으리라 하셨느니라'' 아론이 잠잠하니'),
(1465752,51,3,10,4,'모세가 아론의 아자비 웃시엘의 아들 미사엘과 엘사반을 불러 그들에게 이르되 ''나아와 너희 형제들을 성소 앞에서 진 밖으로 메어 가라'' 하매'),
(1465753,51,3,10,5,'그들이 나아와 모세의 명대로 그들을 옷 입은 채 진 밖으로 메어내니'),
(1465754,51,3,10,6,'모세가 아론과 그 아들 엘르아살과 이다말에게 이르되 `너희는 머리를 풀거나 옷을 찢지 말아서 너희 죽음을 면하고 여호와의 진노가 온 회중에게 미침을 면케 하라 오직 너희 형제 이스라엘 온 족속이 여호와의 치신 불로 인하여 슬퍼할 것이니라'),
(1465755,51,3,10,7,'여호와의 관유가 너희에게 있은즉 너희는 회막 문에 나가지 말아서 죽음을 면할지니라'' 그들이 모세의 명대로 하니라'),
(1465756,51,3,10,8,'여호와께서 아론에게 일러 가라사대'),
(1465757,51,3,10,9,'너나 네 자손들이 회막에 들어갈 때에는 포도주나 독주를 마시지 말아서 너희 사망을 면하라 ! 이는 너희 대대로 영영한 규례라'),
(1465758,51,3,10,10,'그리하여야 너희가 거룩하고 속된 것을 분별하며 부정하고 정한 것을 분별하고'),
(1465759,51,3,10,11,'또 여호와가 모세로 명한 모든 규례를 이스라엘 자손에게 가르치리라'),
(1465760,51,3,10,12,'모세가 아론과 그 남은 아들 엘르아살에게와 이다말에게 이르되 여호와께 드린 화제중 소제의 남은 것은 지극히 거룩하니 너희는 그것을 취하여 누룩을 넣지 말고 단 곁에서 먹되'),
(1465761,51,3,10,13,'이는 여호와의 화제 중 네 응식과 네 아들의 응식인즉 너희는 그것을 거룩한 곳에서 먹으라 ! 내가 명령을 받았느니라'),
(1465762,51,3,10,14,'흔든 가슴과 든 뒷다리는 너와 네 자녀가 너와 함께 정결한 곳에서 먹을지니 이는 이스라엘 자손의 화목제 희생 중에서 네 응식과 네 자손의 응식으로 주신 것임이니라'),
(1465763,51,3,10,15,'그 든 뒷다리와 흔든 가슴으로 화제의 기름과 함께 가져다가 여호와 앞에 흔들어 요제를 삼을지니 이는 여호와의 명령대로 너와 네 자손의 영원한 응식이니라'''),
(1465764,51,3,10,16,'모세가 속죄제 드린 염소를 찾은즉 이미 불살랐는지라 그가 아론의 남은 아들 엘르아살과 이다말에게 노하여 가로되'),
(1465765,51,3,10,17,'`이 속죄제 희생은 지극히 거룩하거늘 너희가 어찌하여 거룩한 곳에서 먹지 아니하였느뇨 ? 이는 너희로 회중의 죄를 담당하여 그들을 위하여 여호와 앞에 속하게 하려고 너희에게 주신 것이니라'),
(1465766,51,3,10,18,'그 피를 성소에 들여오지 아니하였으니 그 제육은 너희가 나의 명한 대로 거룩한 곳에서 먹었어야 할 것이니라'''),
(1465767,51,3,10,19,'아론이 모세에게 이르되 `오늘 그들이 그 속죄제와 번제를 여호와께 드렸어도 이런 일이 내게 임하였거늘 오늘 내가 속죄 제육을 먹었더면 여호와께서 어찌 선히 여기셨으리요'''),
(1465768,51,3,10,20,'모세가 그 말을 듣고 좋게 여겼더라'),
(1465769,51,3,11,1,'여호와께서 모세와 아론에게 고하여 그들에게 이르시되'),
(1465770,51,3,11,2,'이스라엘 자손에게 고하여 이르라 육지 모든 짐승 중 너희의 먹을만한 생물은 이러하니'),
(1465771,51,3,11,3,'짐승중 무릇 굽이 갈라져 쪽발이 되고 새김질하는 것은 너희가 먹되'),
(1465772,51,3,11,4,'새김질하는 것이나 굽이 갈라진 짐승 중에도 너희가 먹지 못할 것은 이러하니 약대는 새김질은 하되 굽이 갈라지지 아니하였으므로 너희에게 부정하고'),
(1465773,51,3,11,5,'사반도 새김질은 하되 굽이 갈라지지 아니하였으므로 너희에게 부정하고'),
(1465774,51,3,11,6,'토끼도 새김질은 하되 굽이 갈라지지 아니하였으므로 너희에게 부정하고'),
(1465775,51,3,11,7,'돼지는 굽이 갈라져 쪽발이로되 새김질을 못하므로 너희에게 부정하니'),
(1465776,51,3,11,8,'너희는 이 고기를 먹지 말고 그 주검도 만지지 말라 이것들은 너희에게 부정하니라'),
(1465777,51,3,11,9,'물에 있는 모든 것 중 너희의 먹을 만한 것은 이것이니 무릇 강과 바다와 다른 물에 있는 것 중에 지느러미와 비늘 있는 것은 너희가 먹되'),
(1465778,51,3,11,10,'무릇 물에서 동하는 것과, 무릇 물에서 사는 것 곧 무릇 강과, 바다에 있는 것으로서 지느러미와 비늘 없는 것은 너희에게 가증한 것이라'),
(1465779,51,3,11,11,'이들은 너희에게 가증한 것이니 너희는 그 고기를 먹지 말고 그 주검을 가증히 여기라'),
(1465780,51,3,11,12,'수중 생물에 지느러미와 비늘 없는 것은 너희에게 가증하니라'),
(1465781,51,3,11,13,'새 중에 너희가 가증히 여길 것은 이것이라 이것들이 가증한즉 먹지 말지니 곧 독수리와, 솔개와, 어응과,'),
(1465782,51,3,11,14,'매와, 매 종류와,'),
(1465783,51,3,11,15,'까마귀 종류와'),
(1465784,51,3,11,16,'타조와, 다호마스와, 갈매기와, 새매 종류와,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465785,51,3,11,17,'올빼미와, 노자와, 부엉이와,'),
(1465786,51,3,11,18,'따오기와, 당아와, 올응과,'),
(1465787,51,3,11,19,'학과, 황새 종류와, 대승과, 박쥐니라'),
(1465788,51,3,11,20,'날개가 있고 네 발로기어 다니는 곤충은 너희에게 가증하되'),
(1465789,51,3,11,21,'오직 날개가 있고 네 발로 기어다니는 모든 곤충중에 그 발에 뛰는 다리가 있어서 땅에서 뛰는 것은 너희가 먹을지니'),
(1465790,51,3,11,22,'곧 그 중에 메뚜기 종류와, 베짱이 종류와, 귀뚜라미 종류와, 팟종이 종류는 너희가 먹으려니와'),
(1465791,51,3,11,23,'오직 날개가 있고 기어다니는 곤충은 다 너희에게 가증하니라'),
(1465792,51,3,11,24,'이런 유는 너희를 부정케 하나니 누구든지 이것들의 주검을 만지면 저녁까지 부정할 것이며'),
(1465793,51,3,11,25,'무릇 그 주검을 옮기는 자는 그 옷을 빨지니 저녁까지 부정하리라'),
(1465794,51,3,11,26,'무릇 굽이 갈라진 짐승 중에 쪽발이 아닌 것이나 새김질 아니하는 것의 주검은 다 네게 부정하니 만지는 자는 부정할 것이요'),
(1465795,51,3,11,27,'네 발로 다니는 모든 짐승 중 발바닥으로 다니는 것은 다 네게 부정하니 그 주검을 만지는 자는 저녁까지 부정할 것이며'),
(1465796,51,3,11,28,'그 주검을 옮기는 자는 그 옷을 빨지니 저녁까지 부정하리라 그것들이 네게 부정하니라'),
(1465797,51,3,11,29,'땅에 기는 바 기는 것 중에 네게 부정한 것은 이러하니 곧 쪽제비와, 쥐와, 도마뱀 종류와,'),
(1465798,51,3,11,30,'합개와, 육지 악어와, 수궁과, 사막 도마뱀과, 칠면석척이라'),
(1465799,51,3,11,31,'모든 기는 것 중 이것들은 네게 부정하니 무릇 그 주검을 만지는 자는 저녁까지 부정할 것이며'),
(1465800,51,3,11,32,'이런 것 중 어떤 것의 주검이 목기에든지, 의복에든지, 가죽에든지, 부대에든지, 무론 무엇에 쓰는 그릇에든지 떨어지면 부정하여지리니 물에 담그라 저녁까지 부정하다가 정할 것이며'),
(1465801,51,3,11,33,'그것 중 어떤 것이 어느 질그릇에 떨어지면 그 속에 있는 것이 다 부정하여지나니 너는 그 그릇을 깨뜨리라'),
(1465802,51,3,11,34,'먹을 만한 축축한 식물이 거기 담겼으면 부정하여질 것이요, 그 같은 그릇의 마실 만한 마실 것도 부정할 것이며'),
(1465803,51,3,11,35,'이런 것의 주검이 물건 위에 떨어지면 그것이 모두 부정하여지리니 화덕이든지, 질탕관이든지 깨뜨려 버리라 ! 이것이 부정하여져서 너희에게 부정한 것이 되리라'),
(1465804,51,3,11,36,'샘물이나 방축물 웅덩이는 부정하여지지 아니하되 그 주검에 다닥치는 것만 부정하여 질 것이요'),
(1465805,51,3,11,37,'이것들의 주검이 심을 종자에 떨어질지라도 그것이 정하거니와'),
(1465806,51,3,11,38,'종자에 물을 더할 때에 그것이 그 위에 떨어지면 너희에게 부정하리라'),
(1465807,51,3,11,39,'너희의 먹을 만한 짐승이 죽은 때에 그 사체를 만지는 자는 저녁까지 부정할 것이며'),
(1465808,51,3,11,40,'그것을 먹는 자는 그 옷을 빨 것이요 저녁까지 부정할 것이며 그 주검을 옮기는 자도 그 옷을 빨것이요 저녁까지 부정하리라'),
(1465809,51,3,11,41,'땅에 기어 다니는 모든 기는 것은 가증한즉 먹지 못할지니'),
(1465810,51,3,11,42,'곧 땅에 기어다니는 모든 기는 것 중에 배로 밀어 다니는 것이나 네 발로 걷는 것이나 여러 발을 가진 것이라 너희가 먹지 말지니 이는 가증함이니라'),
(1465811,51,3,11,43,'너희는 기는바 기어다니는 것을 인하여 자기로 가증하게 되게 말며 또한 그것을 인하여 스스로 더럽혀 부정하게 되게 말라'),
(1465812,51,3,11,44,'나는 여호와 너희 하나님이라 ! 내가 거룩하니 너희도 몸을 구별하여 거룩하게 하고 땅에 기는바 기어다니는 것으로 인하여 스스로 더럽히지 말라'),
(1465813,51,3,11,45,'나는 너희의 하나님이 되려고 너희를 애굽 땅에서 인도하여 낸 여호와라 내가 거룩하니 너희도 거룩할지어다 !'),
(1465814,51,3,11,46,'이는 짐승과 새와 물에서 움직이는 모든 생물과 땅에 기는 모든 기어다니는 것에 대한 규례니'),
(1465815,51,3,11,47,'부정하고 정한 것과 먹을 생물과 먹지 못할 생물을 분별한 것이니라'),
(1465816,51,3,12,1,'여호와께서 모세에게 일러 가라사대'),
(1465817,51,3,12,2,'이스라엘 자손에게 고하여 이르라 여인이 잉태하여 남자를 낳으면 그는 칠일 동안 부정하리니 곧 경도할 때와 같이 부정할 것이며'),
(1465818,51,3,12,3,'제 팔일에는 그 아이의 양피를 벨 것이요'),
(1465819,51,3,12,4,'그 여인은 오히려 삼십 삼일을 지나야 산혈이 깨끗하리니 정결케 되는 기한이 차기 전에는 성물을 만지지도 말며 성소에 들어가지도 말 것이며'),
(1465820,51,3,12,5,'여자를 낳으면 그는 이 칠일 동안 부정하리니 경도할 때와 같을 것이며 산혈이 깨끗하게 됨은 육십 육일을 지나야 하리라'),
(1465821,51,3,12,6,'자녀간 정결케 되는 기한이 차거든 그 여인은 번제를 위하여 일년된 어린 양을 취하고 속죄제를 위하여 집 비둘기 새끼나 산비둘기를 취하여 회막 문 제사장에게로 가져갈 것이요'),
(1465822,51,3,12,7,'제사장은 그것을 여호와 앞에 드려서 여인을 위하여 속죄할지니 그리하면 산혈이 깨끗하리라 이는 자녀간 생산한 여인에게 대한 규례니라'),
(1465823,51,3,12,8,'그 여인의 힘이 어린 양에 미치지 못하거든 산비둘기 둘이나 집비둘기 새끼 둘을 가져다가 하나는 번제물로,하나는 속죄 제물로 삼을 것이요 제사장은 그를 위하여 속할지니 그가 정결하리라'),
(1465824,51,3,13,1,'여호와께서 모세와 아론에게 일러 가라사대'),
(1465825,51,3,13,2,'사람의 피부에 무엇이 돋거나 딱지가 앉거나 색점이 생겨서 그 피부에 문둥병같이 되거든 곧 제사장 아론에게나 그 자손중 한 제사장에게로 데리고 갈 것이요'),
(1465826,51,3,13,3,'제사장은 그 피부의 병을 진찰할지니 환처의 털이 희어졌고 환처가 피부보다 우묵하여졌으면 이는 문둥병의 환처라 제사장이 진단하여 그를 부정하다 할 것이요'),
(1465827,51,3,13,4,'피부에 색점이 희나 우묵하지 아니하고 그 털이 희지 아니하면 제사장은 그 환자를 칠일동안 금고할 것이며'),
(1465828,51,3,13,5,'칠일만에 제사장이 그를 진찰할지니 그의 보기에 그 환처가 변하지 아니하고 병색이 피부에 퍼지지 아니하였으면 제사장이 그를 또 칠일 동안을 금고할 것이며'),
(1465829,51,3,13,6,'칠일만에 제사장이 또 진찰할지니 그 환처가 엷어졌고 병색이 피부에 퍼지지 아니하였으면 피부병이라 제사장이 그를 정하다 할 것이요 그는 옷을 빨 것이라 그리하면 정하리라'),
(1465830,51,3,13,7,'그러나 정결한 여부를 위하여 제사장에게 보인 후에 병이 피부에 퍼지면 제사장에게 다시 보일 것이요'),
(1465831,51,3,13,8,'제사장은 진찰할지니 그 병이 피부에 퍼졌으면 그를 부정하다 진단할 것이라 이는 문둥병임이니라'),
(1465832,51,3,13,9,'사람에게 문둥병이 들었거든 그를 제사장에게로 데려갈 것이요'),
(1465833,51,3,13,10,'제사장은 진찰할지니 피부에 흰 점이 돋고 털이 희어지고 거기 난육이 생겼으면'),
(1465834,51,3,13,11,'이는 그의 피부의 오랜 문둥병이라 제사장이 부정하다 진단할 것이요 그가 이미 부정하였은즉 금고하지는 않을 것이며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465835,51,3,13,12,'제사장의 보기에 문둥병이 그 피부에 크게 발하였으되 그 환자의 머리부터 발까지 퍼졌거든'),
(1465836,51,3,13,13,'그가 진찰할 것이요 문둥병이 과연 그 전신에 퍼졌으면 그 환자를 정하다 할지니 다 희어진 자인즉 정하거니와'),
(1465837,51,3,13,14,'아무 때든지 그에게 난육이 발생하면 그는 부정한즉'),
(1465838,51,3,13,15,'제사장이 난육을 보고 그를 부정하다 진단할지니 그 난육은 부정한 것인즉 이는 문둥병이며'),
(1465839,51,3,13,16,'그 난육이 변하여 다시 희어지면 제사장에게로 갈 것이요'),
(1465840,51,3,13,17,'제사장은 그를 진찰하여서 그 환처가 희어졌으면 환자를 정하다 할지니 그는 정하니라'),
(1465841,51,3,13,18,'피부에 종기가 생겼다가 나았고'),
(1465842,51,3,13,19,'그 종처에 흰 점이 돋거나 희고 불그스름한 색점이 생겼으면 제사장에게 보일 것이요'),
(1465843,51,3,13,20,'그는 진찰하여 피부보다 얕고 그 털이 희면 그를 부정하다 진단할지니 이는 종기로 된 문둥병의 환처임이니라'),
(1465844,51,3,13,21,'그러나 제사장의 보기에 거기 흰 털이 없고 피부보다 얕지 아니하고 빛이 엷으면 제사장은 그를 칠일 동안 금고할 것이며'),
(1465845,51,3,13,22,'그 병이 크게 피부에 퍼졌으면 제사장은 그를 부정하다 진단할지니 이는 그 환처임이니라'),
(1465846,51,3,13,23,'그러나 그 색점이 여전하고 퍼지지 아니하였으면 이는 종기 흔적이니 제사장은 그를 정하다 진단할지니라'),
(1465847,51,3,13,24,'피부를 불에 데었는데 그 덴 곳에 불그스름하고 희거나 순전히 흰 색점이 생기면'),
(1465848,51,3,13,25,'제사장은 진찰할지니 그 색점의 털이 희고 그 자리가 피부보다 우묵하면 이는 화상에서 발한 문둥병인즉 제사장은 그를 부정하다 할 것은 문둥병의 환처가 됨이니라'),
(1465849,51,3,13,26,'그러나 제사장의 보기에 그 색점에 흰 털이 없으며 그 자리가 피부보다 얕지 아니하고 빛이 엷으면 그는 그를 칠일동안 금고할 것이며'),
(1465850,51,3,13,27,'칠일만에 제사장이 그를 진찰할지니 만일 병이 크게 피부에 퍼졌으면 그는 그를 부정하다 진단할 것은 문둥병의 환처임이니라'),
(1465851,51,3,13,28,'만일 색점이 여전하여 피부에 퍼지지 아니하고 빛이 엷으면 화상으로 부은 것이니 제사장은 그를 정하다 할 것은 이는 화상의 흔적임이니라'),
(1465852,51,3,13,29,'남자나 여자의 머리에나 수염에 환처가 있으면'),
(1465853,51,3,13,30,'제사장은 진찰할지니 환처가 피부보다 우묵하고 그 자리에 누르고 가는 털이 있으면 그는 그를 부정하다 할 것은 이는 옴이라 머리에나 수염에 발한 문둥병임이니라'),
(1465854,51,3,13,31,'만일 제사장의 보기에 그 옴의 환처가 피부보다 우묵하지 아니하고 그 자리에 검은 털이 없으면 제사장은 그 옴 환자를 칠일 동안 금고할 것이며'),
(1465855,51,3,13,32,'칠일만에 제사장은 그 환처를 진찰할지니 그 옴이 퍼지지 아니하고 그 자리에 누른 털이 없고 피부보다 우묵하지 아니하거든'),
(1465856,51,3,13,33,'그는 모발을 밀되 환처는 밀지 말 것이요 제사장은 옴 환자를 또 칠일 동안 금고할 것이며'),
(1465857,51,3,13,34,'칠일만에 제사장은 그 옴을 또 진찰할지니 그 옴이 피부에 퍼지지 아니하고 피부보다 우묵하지 아니하면 그는 그를 정하다 진단할 것이요 그는 그 옷을 빨지니 정하려니와'),
(1465858,51,3,13,35,'깨끗한 후에라도 옴이 크게 피부에 퍼지면'),
(1465859,51,3,13,36,'제사장은 그를 진찰할지니 과연 옴이 피부에 퍼졌으면 누른 털을 찾을 것 없이 그는 부정하니라'),
(1465860,51,3,13,37,'그러나 제사장의 보기에 옴이 여전하고 그 자리에 검은 털이 났으면 그 옴은 나았고 그 사람은 정하니 제사장은 그를 정하다 진단할지니라'),
(1465861,51,3,13,38,'남자나 여자의 피부에 색점 곧 흰 색점이 있으면'),
(1465862,51,3,13,39,'제사장은 진찰할지니 그 피부의 색점이 부유스름하면 이는 피부에 발한 어루러기라 그는 정하니라'),
(1465863,51,3,13,40,'누구든지 그 머리털이 빠지면 그는 대머리니 정하고'),
(1465864,51,3,13,41,'앞머리가 빠져도 그는 이마 대머리니 정하니라'),
(1465865,51,3,13,42,'그러나 대머리나 이마 대머리에 희고 불그스름한 색점이 있으면 이는 문둥병이 대머리에나 이마 대머리에 발함이라'),
(1465866,51,3,13,43,'제사장은 그를 진찰할지니 그 대머리에나 이마 대머리에 돋은 색점이 희고 불그스름하여 피부에 발한 문둥병과 같으면'),
(1465867,51,3,13,44,'이는 문둥 환자라 부정하니 제사장은 그를 부정하다 확실히 진단할 것은 그 환처가 그 머리에 있음이니라'),
(1465868,51,3,13,45,'문둥 환자는 옷을 찢고 머리를 풀며 윗 입술을 가리우고 외치기를 부정하다 부정하다 할 것이요'),
(1465869,51,3,13,46,'병 있는 날 동안은 늘 부정할 것이라 그가 부정한즉 혼자 살되 진 밖에 살지니라 !'),
(1465870,51,3,13,47,'만일 의복에 문둥병 색점이 발하여 털옷에나, 베옷에나'),
(1465871,51,3,13,48,'베나, 털의 날에나, 씨에나, 혹 가죽에나, 무릇 가죽으로 만든 것에 있되'),
(1465872,51,3,13,49,'그 의복에나, 가죽에나, 그 날에나, 씨에나, 무릇 가죽으로 만든 것에 병색이 푸르거나 붉으면 이는 문둥병의 색점이라 제사장에게 보일 것이요'),
(1465873,51,3,13,50,'제사장은 그 색점을 살피고 그것을 칠일 동안 간직하였다가'),
(1465874,51,3,13,51,'칠일만에 그 색점을 살필지니 그 색점이 그 의복의 날에나, 씨에나, 가죽에나, 가죽으로 만든 것에 퍼졌으면 이는 악성 문둥병이라 그것이 부정하니'),
(1465875,51,3,13,52,'그는 그 색점 있는 의복이나, 털이나, 베의 날이나, 씨나, 무릇 가죽으로 만든 것을 불사를지니 이는 악성 문둥병인즉 그것을 불사를지니라 !'),
(1465876,51,3,13,53,'그러나 제사장의 보기에 그 색점이 그 의복의 날에나, 씨에나, 무릇 가죽으로 만든 것에 퍼지지 아니하였으면'),
(1465877,51,3,13,54,'제사장은 명하여 그 색점 있는 것을 빨게하고 또 칠일 동안 간직하였다가'),
(1465878,51,3,13,55,'그 빤 곳을 볼지니 그 색점의 빛이 변치 아니하고 그 색점이 퍼지지 아니하였으면 부정하니 너는 그것을 불사르라 이는 거죽에 있든지, 속에 있든지, 악성 문둥병이니라'),
(1465879,51,3,13,56,'빤 후에 제사장의 보기에 그 색점이 엷으면 그 의복에서나, 가죽에서나, 그 날에서나, 씨에서나, 그 색점을 찢어 버릴 것이요'),
(1465880,51,3,13,57,'그 의복의 날에나 씨에나 무릇 가죽으로 만든 것에 색점이 여전히 보이면 복발하는 것이니 너는 그 색점있는 것을 불사를지니라'),
(1465881,51,3,13,58,'네가 빤 의복의 날에나, 씨에나, 무릇 가죽으로 만든 것에 그 색점이 벗어졌으면 그것을 다시 빨아야 정하리라'),
(1465882,51,3,13,59,'이는 털옷에나, 베옷에나, 그 날에나, 씨에나, 무릇 가죽으로 만든 것에 발한 문둥병 색점의 정하고 부정한 것을 단정하는 규례니라'),
(1465883,51,3,14,1,'여호와께서 모세에게 일러 가라사대'),
(1465884,51,3,14,2,'문둥 환자의 정결케 되는 날의 규례는 이러하니 곧 그 사람을 제사장에게로 데려갈 것이요');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465885,51,3,14,3,'제사장은 진에서 나가서 진찰할지니 그 환자에게 있던 문둥병 환처가 나았으면'),
(1465886,51,3,14,4,'제사장은 그를 위하여 명하여 정한 산 새 두마리와, 백향목과, 홍색실과, 우슬초를 가져오게 하고'),
(1465887,51,3,14,5,'제사장은 또 명하여 그 새 하나는 흐르는 물 위 질그릇 안에서 잡게 하고'),
(1465888,51,3,14,6,'다른 새는 산대로 취하여 백향목과, 홍색실과, 우슬초와 함께 가져다가 흐르는 물 위에서 잡은 새 피를 찍어'),
(1465889,51,3,14,7,'문둥병에서 정결함을 받을 자에게 일곱번 뿌려 정하다 하고 그 산 새는 들에 놓을지며'),
(1465890,51,3,14,8,'정결함을 받는 자는 그 옷을 빨고 모든 털을 밀고 물로 몸을 씻을 것이라 그리하면 정하리니 그 후에 진에 들어올 것이나 자기 장막 밖에 칠일을 거할 것이요'),
(1465891,51,3,14,9,'칠일만에 그 모든 털을 밀되 머리털과 수염과 눈썹을 다 밀고 그 옷을 빨고 몸을 물에 씻을 것이라 그리하면 정하리라'),
(1465892,51,3,14,10,'제 팔일에 그는 흠 없는 어린 수양 둘과 일년 된 흠 없는 어린 암양 하나와 또 고운 가루 에바 십분 삼에 기름 섞은 소제물과 기름 한 록을 취할 것이요'),
(1465893,51,3,14,11,'정결케 하는 제사장은 정결함을 받을 자와 그 물건들을 회막 문 여호와 앞에 두고'),
(1465894,51,3,14,12,'어린 수양 하나를 취하여 기름 한 록과 아울러 속건제로 드리되 여호와 앞에 흔들어 요제를 삼고'),
(1465895,51,3,14,13,'그 어린 수양은 거룩한 장소 곧 속죄제와 번제 희생 잡는 곳에서 잡을 것이며 속건 제물은 속죄 제물과 일례로 제사장에게 돌릴지니 이는 지극히 거룩한 것이니라'),
(1465896,51,3,14,14,'제사장은 그 속건제 희생의 피를 취하여 정결함을 받을 자의 우편 귓부리와, 우편 손 엄지가락과, 우편 발 엄지가락에 바를 것이요'),
(1465897,51,3,14,15,'제사장은 또 그 한 록의 기름을 취하여 자기 좌편 손바닥에 따르고'),
(1465898,51,3,14,16,'우편 손가락으로 좌편 손의 기름을 찍어 그 손가락으로 그것을 여호와 앞에 일곱번 뿌릴 것이요'),
(1465899,51,3,14,17,'손에 남은 기름은 제사장이 정결함을 받는 자의 우편 귓부리와, 우편 손 엄지가락과, 우편 발 엄지가락 곧 속건제 희생의 피 위에 바를 것이며'),
(1465900,51,3,14,18,'오히려 그 손에 남은 기름은 제사장이 그 정결함을 받는 자의 머리에 바르고 여호와 앞에서 제사장은 그를 위하여 속죄하고'),
(1465901,51,3,14,19,'또 제사장은 속죄제를 드려 그 부정함을 인하여 정결함을 받으려는 자를 위하여 속죄하고 그 후에 번제 희생을 잡을 것이요'),
(1465902,51,3,14,20,'제사장은 그 번제와 소제를 단에 드려 그를 위하여 속죄할 것이라 그리하면 그가 정결하리라 !'),
(1465903,51,3,14,21,'그가 가난하여 이에 힘이 미치지 못하면 그는 흔들어 자기를 속할 속건제를 위하여 어린 수양 하나와 소제를 위하여 고운 가루 에바 십분 일에 기름 섞은 것과 기름 한 록을 취하고'),
(1465904,51,3,14,22,'그 힘이 미치는 대로 산비둘기 둘이나 집비둘기 새끼 둘을 취하되 하나는 속죄 제물로,하나는 번제물로 삼아'),
(1465905,51,3,14,23,'제 팔일에 그 결례를 위하여 그것들을 회막 문 여호와 앞 제사장에게로 가져갈 것이요'),
(1465906,51,3,14,24,'제사장은 속건제 어린 양과 기름 한 록을 취하여 여호와 앞에 흔들어 요제를 삼고'),
(1465907,51,3,14,25,'속건제의 어린 양을 잡아서 제사장은 그 속건제 희생의 피를 취하여 정결함을 받을 자의 우편 손 엄지 가락과, 우편 발 엄지가락에 바를 것이요'),
(1465908,51,3,14,26,'제사장은 그 기름을 자기 좌편 손바닥에 따르고'),
(1465909,51,3,14,27,'우편 손가락으로 좌편 손의 기름을 조금 찍어 여호와 앞에 일곱번 뿌릴 것이요'),
(1465910,51,3,14,28,'그 손의 기름은 제사장이 정결함을 받을 자의 우편 귓부리와, 우편 손 엄지가락과, 우편 발 엄지가락 곧 속건제 희생의 피를 바른 곳에 바를 것이며'),
(1465911,51,3,14,29,'또 그 손에 남은 기름은 제사장이 그 정결함을 받는 자의 머리에 발라 여호와 앞에서 그를 위하여 속죄할 것이며'),
(1465912,51,3,14,30,'그는 힘이 미치는 대로 산비둘기 하나나 집비둘기 새끼 하나를 드리되'),
(1465913,51,3,14,31,'곧 그 힘이 미치는 것의 하나는 속죄제로, 나는 소제와 함께 번제로 드릴 것이요, 제사장은 정결함을 받을 자를 위하여 여호와 앞에 속죄할지니'),
(1465914,51,3,14,32,'문둥병 환자로서 그 결례에 힘이 부족한 자의 규례가 이러하니라'),
(1465915,51,3,14,33,'여호와께서 모세와 아론에게 일러 가라사대'),
(1465916,51,3,14,34,'내가 네게 기업으로 주는 가나안 땅에 너희가 이른 때에 내가 너희 기업의 땅에서 어느 집에 문둥병 색점을 발하게 하거든'),
(1465917,51,3,14,35,'그 집 주인은 제사장에게 와서 고하기를 무슨 색점이 집에 생겼다 할 것이요'),
(1465918,51,3,14,36,'제사장은 그 색점을 보러 가기 전에 그 가장 집물에 부정을 면케하기 위하여 명하여 그 집을 비게 한 후에 들어가서 그 집을 볼지니'),
(1465919,51,3,14,37,'그 색점을 볼 때에 그 집 벽에 푸르거나 붉은 무늬의 색점이 있어 벽보다 우묵하면'),
(1465920,51,3,14,38,'제사장은 그 집 문으로 나와 그 집을 칠일 동안 폐쇄하였다가'),
(1465921,51,3,14,39,'칠일만에 또 와서 살펴볼 것이요 그 색점이 벽에 퍼졌으면'),
(1465922,51,3,14,40,'그는 명하여 색점 있는 돌을 빼어 성 밖 부정한 곳에 버리게 하고'),
(1465923,51,3,14,41,'또 집안 사면을 긁게 하고 그 긁은 흙을 성 밖 부정한 곳에 쏟아버리게 할 것이요'),
(1465924,51,3,14,42,'그들은 다른 돌로 그 돌을 대신하며 다른 흙으로 집에 바를지니라'),
(1465925,51,3,14,43,'돌을 빼며 집을 긁고 고쳐 바른 후에 색점이 집에 복발하거든'),
(1465926,51,3,14,44,'제사장은 또 와서 살펴볼 것이요 그 색점이 만일 집에 퍼졌으면 악성 문둥병인즉 이는 부정하니'),
(1465927,51,3,14,45,'그는 그 집을 헐고 돌과 그 재목과 그 집의 모든 흙을 성 밖 부정한 곳으로 내어갈 것이며'),
(1465928,51,3,14,46,'그 집을 폐쇄한 날 동안에 들어가는 자는 저녁까지 부정할 것이요'),
(1465929,51,3,14,47,'그 집에서 자는 자는 그 옷을 빨 것이요 그 집에서 먹는 자도 그 옷을 빨 것이니라'),
(1465930,51,3,14,48,'그 집을 고쳐 바른 후에 제사장이 들어가 살펴 보아서 색점이 집에 퍼지지 아니하였으면 이는 색점이 나은 것이니 제사장은 그 집을 정하다 하고'),
(1465931,51,3,14,49,'그는 그 집을 정결케 하기 위하여 새 두마리와, 백향목과, 홍색실과, 우슬초를 취하고'),
(1465932,51,3,14,50,'그 새 하나를 흐르는 물 위 질그릇 안에서 잡고'),
(1465933,51,3,14,51,'백향목과, 우슬초와, 홍색실과, 산새를 가져다가 잡은 새의 피와 흐르는 물을 찍어 그 집에 일곱번 뿌릴 것이요'),
(1465934,51,3,14,52,'그는 새의 피와, 흐르는 물과, 산새와, 백향목과, 우슬초와, 홍색실로 집을 정결케 하고');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465935,51,3,14,53,'그 산새는 성 밖 들에 놓아 그 집을 위하여 속할 것이라 그리하면 정결하리라 !'),
(1465936,51,3,14,54,'이는 각종 문둥병 환처에 대한 규례니 곧 옴과'),
(1465937,51,3,14,55,'의복과 가옥의 문둥병과'),
(1465938,51,3,14,56,'붓는 것과 피부병과 색점의'),
(1465939,51,3,14,57,'언제는 부정하고 언제는 정함을 가르치는 것이니 문둥병의 규례가 이러하니라'),
(1465940,51,3,15,1,'여호와께서 모세와 아론에게 일러 가라사대'),
(1465941,51,3,15,2,'이스라엘 자손에게 고하여 이르라 누구든지 몸에 유출병이 있으면 그 유출병을 인하여 부정한 자라'),
(1465942,51,3,15,3,'그 유출병으로 말미암아 부정함이 이러하니 곧 몸에서 흘러 나오든지 그것이 엉겼든지 부정한즉'),
(1465943,51,3,15,4,'유출병 있는 자의 눕는 상은 다 부정하고 그의 앉았던 자리도 다 부정하니'),
(1465944,51,3,15,5,'그 침상에 접촉하는 자는 옷을 빨고 물로 몸을 씻을 것이며 저녁까지 부정하리라'),
(1465945,51,3,15,6,'유출병 있는 자의 앉았던 자리에 앉는 자는 옷을 빨고 물로 몸을 씻을 것이며 저녁까지 부정하리라'),
(1465946,51,3,15,7,'유출병 있는 자의 몸에 접촉하는 자는 옷을 빨고 물로 몸을 씻을 것이며 저녁까지 부정하리라'),
(1465947,51,3,15,8,'유출병 있는 자가 정한 자에게 침을 뱉으면 정한 자는 옷을 빨고 물로 몸을 씻을 것이며 저녁까지 부정하리라'),
(1465948,51,3,15,9,'유출병 있는 자의 탔던 안장은 다 부정하며'),
(1465949,51,3,15,10,'그 몸 아래 닿았던 것에 접촉한 자는 다 저녁까지 부정하며 그런 것을 옮기는 자는 옷을 빨고 물로 몸을 씻을 것이며 저녁까지 부정하리라'),
(1465950,51,3,15,11,'유출병 있는 자가 물로 손을 씻지 아니하고 아무든지 만지면 그 자는 옷을 빨고 물로 몸을 씻을 것이며 저녁까지 부정하리라'),
(1465951,51,3,15,12,'유출병 있는 자의 만진 질그릇은 깨뜨리고 목기는 다 물로 씻을지니라'),
(1465952,51,3,15,13,'유출병 있는 자는 그 유출이 깨끗하여지거든 그 몸이 정결하기 위하여 칠일을 계산하여 옷을 빨고 흐르는 물에 몸을 씻을 것이요 그리하면 정하리니'),
(1465953,51,3,15,14,'제 팔일에 산비둘기 둘이나 집비둘기 새끼 둘을 자기를 위하여 취하고 회막 문 여호와 앞으로 가서 제사장에게 줄 것이요'),
(1465954,51,3,15,15,'제사장은 그 하나는 속죄제로, 하나는 번제로 드려 그의 유출병을 인하여 여호와 앞에 속죄할지니라 !'),
(1465955,51,3,15,16,'설정한 자는 전신을 물로 씻을 것이며 저녁까지 부정하리라'),
(1465956,51,3,15,17,'무릇 정수가 묻은 옷이나 가죽은 물에 빨 것이며 저녁까지 부정하리라'),
(1465957,51,3,15,18,'남녀가 동침하여 설정하였거든 둘 다 물로 몸을 씻을 것이며 저까지 부정하리라'),
(1465958,51,3,15,19,'어떤 여인이 유출을 하되 그 유출이 피면 칠일 동안 불결하니 무릇 그를 만지는 자는 저녁까지 부정할 것이요'),
(1465959,51,3,15,20,'그 불결할 동안에 그의 누웠던 자리는 다 부정하며 그의 앉았던 자리도 다 부정한즉'),
(1465960,51,3,15,21,'그 침상을 만지는 자는 다 옷을 빨고 물로 몸을 씻을 것이요 저녁까지 부정할 것이며'),
(1465961,51,3,15,22,'그 좌석을 만지는 자도 다 옷을 빨고 물로 몸을 씻을 것이요 저녁까지 부정할 것이며'),
(1465962,51,3,15,23,'그의 침상과 무릇 그 좌석에 있는 것을 만지는 자도 저녁까지 부정할 것이며'),
(1465963,51,3,15,24,'누구든지 이 여인과 동침하여 그 불결에 전염되면 칠일 동안 부정할 것이라 그의 눕는 상은 무릇 부정하니라'),
(1465964,51,3,15,25,'여인의 피의 유출이 그 불결기 외에 있어서 여러 날이 간다든지 그 유출이 불결기를 지나든지 하면 그 부정을 유출하는 날 동안은 무릇 그 불결한 때와 같이 부정한즉'),
(1465965,51,3,15,26,'무릇 그 유출이 있는 날 동안에 그의 눕는 침상은 그에게 불결한 때의 침상과 같고 무릇 그의 앉는 자리도 부정함이 불결의 부정 과 같으니'),
(1465966,51,3,15,27,'이런 것을 만지는 자는 무릇 부정한즉 옷을 빨고 물로 몸을 씻을 것이며 저녁까지 부정할 것이요'),
(1465967,51,3,15,28,'그의 유출이 그치면 칠일을 센 후에야 정하리니'),
(1465968,51,3,15,29,'그는 제 팔일에 산비둘기 둘이나 집비둘기 새끼 둘을 자기를 위하여 취하여 회막 문 앞 제사장에게로 가져올 것이요'),
(1465969,51,3,15,30,'제사장은 그 하나는 속죄제로, 하나는 번제로 드려 유출로 부정한 여인을 위하여 여호와 앞에 속할지니라'),
(1465970,51,3,15,31,'너희는 이와 같이 이스라엘 자손으로 그 부정에서 떠나게하여 그들로 그 가운데 있는 내 장막을 더럽히고 그 부정한 중에서 죽음을 면케 할찌니라'),
(1465971,51,3,15,32,'이 규례는 유출병이 있는 자와 설정함으로 부정을 입은 자와'),
(1465972,51,3,15,33,'불결을 앓는 여인과 유출병이 있는 남녀와 불결한 여인과 동침한 자에게 관한 것이니라'),
(1465973,51,3,16,1,'아론의 두 아들이 여호와 앞에 나아가다가 죽은 후에 여호와께서 모세에게 말씀하시니라'),
(1465974,51,3,16,2,'여호와께서 모세에게 이르시되 네 형 아론에게 이르라 성소의 장안 법궤 위 속죄소 앞에 무시로 들어오지 말아서 사망을 면하라 내가 구름 가운데서 속죄소 위에 나타남이니라'),
(1465975,51,3,16,3,'아론이 성소에 들어오려면 수송아지로 속죄 제물을 삼고 수양으로 번제물을 삼고'),
(1465976,51,3,16,4,'거룩한 세마포 속옷을 입으며 세마포 고의를 살에 입고 세마포 띠를 띠며 세마포 관을 쓸지니 이것들은 거룩한 옷이라 물로 몸을 씻고 입을 것이며'),
(1465977,51,3,16,5,'이스라엘 자손의 회중에게서 속죄 제물을 위하여 수염소 둘과 번제물을 위하여 수양 하나를 취할지니라'),
(1465978,51,3,16,6,'아론은 자기를 위한 속죄제의 수송아지를 드리되 자기와 권속을 위하여 속죄하고'),
(1465979,51,3,16,7,'또 그 두 염소를 취하여 회막 문 여호와 앞에 두고'),
(1465980,51,3,16,8,'두 염소를 위하여 제비 뽑되 한 제비는 여호와를 위하고, 한 제비는 아사셀을 위하여 할지며'),
(1465981,51,3,16,9,'아론은 여호와를 위하여 제비 뽑은 염소를 속죄제로 드리고'),
(1465982,51,3,16,10,'아사셀을 위하여 제비 뽑은 염소는 산 대로 여호와 앞에 두었다가 그것으로 속죄하고 아사셀을 위하여 광야로 보낼지니라'),
(1465983,51,3,16,11,'아론은 자기를 위한 속죄제의 수송아지를 드리되 자기와 권속을 위하여 속죄하고 자기를 위한 그 속죄제 수송아지를 잡고'),
(1465984,51,3,16,12,'향로를 취하여 여호와 앞 단 위에서 피운 불을 그것에 채우고 또 두손에 곱게 간 향기로운 향을 채워 가지고 장 안에 들어가서');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1465985,51,3,16,13,'여호와 앞에서 분향하여 향연으로 증거궤 위 속죄소를 가리우게 할지니 그리하면 그가 죽음을 면할 것이며'),
(1465986,51,3,16,14,'그는 또 수송아지의 피를 취하여 손가락으로 속죄소 동편에 뿌리고 또 손가락으로 그 피를 속죄소 앞에 일곱번 뿌릴 것이며'),
(1465987,51,3,16,15,'또 백성을 위한 속죄제 염소를 잡아 그 피를 가지고 장 안에 들어가서 그 수송아지 피로 행함 같이 그 피로 행하여 속죄소 위와 속죄소 앞에 뿌릴지니'),
(1465988,51,3,16,16,'곧 이스라엘 자손의 부정과 그 범한 모든 죄를 인하여 지성소를 위하여 속죄하고 또 그들의 부정한 중에 있는 회막을 위하여 그같이 할 것이요'),
(1465989,51,3,16,17,'그가 지성소에 속죄하러 들어가서 자기와 그 권속과 이스라엘 온회중을 위하여 속죄하고 나오기까지는 누구든지 회막에 있지 못할 것이며'),
(1465990,51,3,16,18,'그는 여호와 앞 단으로 나와서 그것을 위하여 속죄할지니 곧 그 수송아지의 피와 염소의 피를 취하여 단 귀퉁이 뿔들에 바르고'),
(1465991,51,3,16,19,'또 손가락으로 그 피를 그 위에 일곱번 뿌려 이스라엘 자손의 부정에서 단을 성결케 할 것이요'),
(1465992,51,3,16,20,'그 지성소와 회막과 단을 위하여 속죄하기를 마친 후에 산 염소를 드리되'),
(1465993,51,3,16,21,'아론은 두 손으로 산 염소의 머리에 안수하여 이스라엘 자손의 모든 불의와 그 범한 모든 죄를 고하고 그 죄를 염소의 머리에 두어 미리 정한 사람에게 맡겨 광야로 보낼지니'),
(1465994,51,3,16,22,'염소가 그들의 모든 불의를 지고 무인지경에 이르거든 그는 그 염소를 광야에 놓을지니라'),
(1465995,51,3,16,23,'아론은 회막에 들어가서 지성소에 들어갈 때에 입었던 세마포 옷을 벗어 거기 두고'),
(1465996,51,3,16,24,'거룩한 곳에서 물로 몸을 씻고 자기 옷을 입고 나와서 자기의 번제와 백성의 번제를 드려 자기와 백성을 위하여 속죄하고'),
(1465997,51,3,16,25,'속죄제 희생의 기름을 단에 불사를 것이요'),
(1465998,51,3,16,26,'염소를 아사셀에게 보낸 자는 옷을 빨고 물로 몸을 씻은 후에 진에 들어올 것이며'),
(1465999,51,3,16,27,'속죄제 수송아지와 속죄제 염소의 피를 성소로 들여다가 속죄하였은즉 그 가죽과 고기와 똥을 밖으로 내어다가 불사를 것이요'),
(1466000,51,3,16,28,'불사른 자는 옷을 빨고 물로 몸을 씻은 후에 진에 들어올지니라'),
(1466001,51,3,16,29,'너희는 영원히 이 규례를 지킬지니라 ! 칠월 곧 그 달 십일에 너희는 스스로 괴롭게 하고 아무 일도 하지 말되 본토인이든지 너희 중에 우거하는 객이든지 그리하라'),
(1466002,51,3,16,30,'이 날에 너희를 위하여 속죄하여 너희로 정결케 하리니 너희 모든 죄에서 너희가 여호와 앞에 정결하리라'),
(1466003,51,3,16,31,'이는 너희에게 큰 안식일인즉 너희는 스스로 괴롭게 할지니 영원히 지킬 규례라'),
(1466004,51,3,16,32,'그 기름 부음을 받고 위임되어 그 아비를 대신하여 제사장의 직분을 행하는 제사장은 속죄하되 세마포 옷 곧 성의를 입고'),
(1466005,51,3,16,33,'지성소를 위하여 속죄하며 회막과 단을 위하여 속죄하고 또 제사장들과 백성의 회중을 위하여 속죄할지니'),
(1466006,51,3,16,34,'이는 너희의 영원히 지킬 규례라 이스라엘 자손의 모든 죄를 위하여 일년 일차 속죄할 것이니라 아론이 여호와께서 모세에게 명하신 대로 행하니라'),
(1466007,51,3,17,1,'여호와께서 모세에게 일러 가라사대'),
(1466008,51,3,17,2,'아론과 그 아들들과 이스라엘 모든 자손에게 고하여 그들에게 이르기를 여호와의 명령이 이러하시다 하라'),
(1466009,51,3,17,3,'무릇 이스라엘 집의 누구든지 소나 어린 양이나 염소를 진 안에서 잡든지 진 밖에서 잡든지'),
(1466010,51,3,17,4,'먼저 회막문으로 끌어다가 여호와의 장막 앞에서 여호와께 예물로 드리지 아니하는 자는 피흘린 자로 여길 것이라 그가 피를 흘렸은즉 자기 백성 중에서 끊쳐지리라 !'),
(1466011,51,3,17,5,'그런즉 이스라엘 자손이 들에서 잡던 희생을 회막 문 여호와께로 끌어다가 제사장에게 주어 화목제로 여호와께 드려야 할 것이요'),
(1466012,51,3,17,6,'제사장은 그 피를 회막 문 여호와의 단에 뿌리고 그 기름을 불살라 여호와께 향기로운 냄새가 되게 할 것이라'),
(1466013,51,3,17,7,'그들은 전에 음란히 섬기던 수염소에게 다시 제사하지 말 것이니라 이는 그들이 대대로 지킬 영원한 규례니라 !'),
(1466014,51,3,17,8,'너는 또 그들에게 이르라 무릇 이스라엘 집 사람이나 혹시 그들중에 우거하는 타국인이 번제나 희생을 드리되'),
(1466015,51,3,17,9,'회막 문으로 가져다가 여호와께 드리지 아니하면 그는 백성 중에서 끊쳐지리라 !'),
(1466016,51,3,17,10,'무릇 이스라엘 집 사람이나 그들 중에 우거하는 타국인 중에 어떤 피든지 먹는 자가 있으면 내가 그 피 먹는 사람에게 진노하여 그를 백성중에서 끊으리니'),
(1466017,51,3,17,11,'육체의 생명은 피에 있음이라 내가 이 피를 너희에게 주어 단에 뿌려 너희의 생명을 위하여 속하게 하였나니 생명이 피에 있으므로 피가 죄를 속하느니라'),
(1466018,51,3,17,12,'그러므로 내가 이스라엘 자손에게 말하기를 너희 중에 아무도 피를 먹지 말며 너희 중에 우거하는 타국인이라도 피를 먹지 말라 하였나니'),
(1466019,51,3,17,13,'무릇 이스라엘 자손이나 그들 중에 우거하는 타국인이 먹을 만한 짐승이나 새를 사냥하여 잡거든 그 피를 흘리고 흙으로 덮을지니라'),
(1466020,51,3,17,14,'모든 생물은 그 피가 생명과 일체라 그러므로 내가 이스라엘 자손에게 이르기를 너희는 어느 육체의 피든지 먹지 말라 하였나니 모든 육체의 생명은 그 피인즉 무릇 피를 먹는 자는 끊쳐지리라 !'),
(1466021,51,3,17,15,'무릇 스스로 죽은 것이나 들짐승에게 찢겨 죽은 것을 먹은 자는 본토인이나 타국인이나 물론하고 그 옷을 빨고 물로 몸을 씻을 것이며 저녁까지 부정하고 그 후에 정하려니와'),
(1466022,51,3,17,16,'그가 빨지 아니하거나 몸을 물로 씻지 아니하면 죄를 당하리라'),
(1466023,51,3,18,1,'여호와께서 모세에게 일러 가라사대'),
(1466024,51,3,18,2,'너는 이스라엘 자손에게 고하여 이르라 나는 여호와 너희 하나님이라 !'),
(1466025,51,3,18,3,'너희는 그 거하던 애굽 땅의 풍속을 좇지 말며 내가 너희를 인도할 가나안 땅의 풍속과 규례도 행하지 말고'),
(1466026,51,3,18,4,'너희는 나의 법도를 좇으며 나의 규례를 지켜 그대로 행하라 ! 나는 너희의 하나님 여호와니라 !'),
(1466027,51,3,18,5,'너희는 나의 규례와 법도를 지키라 ! 사람이 이를 행하면 그로 인하여 살리라 ! 나는 여호와니라 !'),
(1466028,51,3,18,6,'너희는 골육지친을 가까이하여 그 하체를 범치 말라 나는 여호와니라 !'),
(1466029,51,3,18,7,'네 어미의 하체는 곧 네 아비의 하체니 너는 범치 말라 그는 네 어미인즉 너는 그의 하체를 너는 범치 말지니라'),
(1466030,51,3,18,8,'너는 계모의 하체를 범치 말라 이는 네 아비의 하체니라'),
(1466031,51,3,18,9,'너는 네 자매 곧 네 아비의 딸이나 네 어미의 딸이나 집에서나 타처에서 출생하였음을 물론하고 그들의 하체를 범치 말지니라'),
(1466032,51,3,18,10,'너는 손녀나 외손녀의 하체를 범치 말라 이는 너의 하체니라'),
(1466033,51,3,18,11,'네 계모가 네 아비에게 낳은 딸은 네 누이니 너는 그 하체를 범치 말지니라'),
(1466034,51,3,18,12,'너는 고모의 하체를 범치 말라 그는 네 아비의 골육지친이니라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466035,51,3,18,13,'너는 이모의 하체를 범치 말라 그는 네 어미의 골육지친이니라'),
(1466036,51,3,18,14,'너는 네 아비 형제의 아내를 가까이하여 그 하체를 범치 말라 그는 네 백숙모니라'),
(1466037,51,3,18,15,'너는 자부의 하체를 범치 말라 그는 네 아들의 아내니 그 하체를 범치 말지니라'),
(1466038,51,3,18,16,'너는 형제의 아내의 하체를 범치 말라 이는 네 형제의 하체니라'),
(1466039,51,3,18,17,'너는 여인과 그 여인의 딸의 하체를 아울러 범치 말며 또 그 여인의 손녀나 외손녀를 아울러 취하여 그 하체를 범치 말라 그들은 그의 골육지친이니 이는 악행이니라'),
(1466040,51,3,18,18,'너는 아내가 생존할 동안에 그 형제를 취하여 하체를 범하여 그로 투기케 하지 말지니라'),
(1466041,51,3,18,19,'너는 여인이 경도로 불결할 동안에 그에게 가까이하여 그 하체를 범치 말지니라'),
(1466042,51,3,18,20,'너는 타인의 아내와 통간하여 그로 자기를 더럽히지 말지니라'),
(1466043,51,3,18,21,'너는 결단코 자녀를 몰렉에게 주어 불로 통과케 말아서 네 하나님의 이름을 욕되게 하지 말라 나는 여호와니라 !'),
(1466044,51,3,18,22,'너는 여자와 교합함 같이 남자와 교합하지 말라 이는 가증한 일이니라'),
(1466045,51,3,18,23,'너는 짐승과 교합하여 자기를 더럽히지 말며 여자가 된 자는 짐승 앞에 서서 그것과 교접하지 말라 이는 문란한 일이니라'),
(1466046,51,3,18,24,'너희는 이 모든 일로 스스로 더럽히지 말라 내가 너희의 앞에서 쫓아내는 족속들이 이 모든 일로 인하여 더러워졌고'),
(1466047,51,3,18,25,'그 땅도 더러워졌으므로 내가 그 악을 인하여 벌하고 그 땅도 스스로 그 거민을 토하여 내느니라'),
(1466048,51,3,18,26,'그러므로 너희 곧 너희의 동족이나 혹시 너희 중에 우거하는 타국인이나 나의 규례와 법도를 지키고 이런 가증한 일의 하나도 행하지 말라'),
(1466049,51,3,18,27,'너희의 전에 있던 그 땅 거민이 이 모든 가증한 일을 행하였고 그 땅도 더러워졌느니라'),
(1466050,51,3,18,28,'너희도 더럽히면 그 땅이 너희 있기 전 거민을 토함같이 너희를 토할까 하노라'),
(1466051,51,3,18,29,'무릇 이 가증한 일을 하나라도 행하는 자는 그 백성 중에서 끊쳐지리라 !'),
(1466052,51,3,18,30,'그러므로 너희는 내 명령을 지키고 너희 있기 전에 행하던 가증한 풍속을 하나라도 좇음으로 스스로 더럽히지 말라 ! 나는 너희 하나님 여호와니라 !'),
(1466053,51,3,19,1,'여호와께서 모세에게 일러 가라사대'),
(1466054,51,3,19,2,'너는 이스라엘 자손의 온 회중에게 고하여 이르라 너희는 거룩하라 ! 나 여호와 너희 하나님이 거룩함이니라'),
(1466055,51,3,19,3,'너희 각 사람은 부모를 경외하고 나의 안식일을 지키라 ! 나는 너희 하나님 여호와니라 !'),
(1466056,51,3,19,4,'너희는 헛것을 위하지 말며 너희를 위하여 신상들을 부어 만들지 말라 ! 나는 너희 하나님 여호와니라 !'),
(1466057,51,3,19,5,'너희는 화목제 희생을 여호와께 드릴 때에 열납되도록 드리고'),
(1466058,51,3,19,6,'그 제물은 드리는 날과 이튿날에 먹고 제 삼일까지 남았거든 불사르라'),
(1466059,51,3,19,7,'제 삼일에 조금이라도 먹으면 가증한 것이 되어 열납되지 못하고'),
(1466060,51,3,19,8,'그것을 먹는 자는 여호와의 성물 더럽힘을 인하여 죄를 당하리니 그가 그 백성 중에서 끊쳐지리라 !'),
(1466061,51,3,19,9,'너희 땅의 곡물을 벨 때에 너는 밭 모퉁이까지 다 거두지 말고 너의 떨어진 이삭도 줍지 말며'),
(1466062,51,3,19,10,'너의 포도원의 열매를 다 따지 말며 너의 포도원에 떨어진 열매도 줍지 말고 가난한 사람과 타국인을 위하여 버려 두라 나는 너희 하나님 여호와니라 !'),
(1466063,51,3,19,11,'너희는 도적질하지 말며 속이지 말며 서로 거짓말하지 말며'),
(1466064,51,3,19,12,'너희는 내 이름으로 거짓 맹세함으로 네 하나님의 이름을 욕되게 하지 말라 ! 나는 여호와니라 !'),
(1466065,51,3,19,13,'너는 네 이웃을 압제하지 말며 늑탈하지 말며 품군의 삯을 아침까지 밤새도록 네게 두지 말며'),
(1466066,51,3,19,14,'너는 귀먹은 자를 저주하지 말며 소경 앞에 장애물을 놓지 말고 네 하나님을 경외하라 ! 나는 여호와니라 !'),
(1466067,51,3,19,15,'너희는 재판할 때에 불의를 행치 말며 가난한 자의 편을 들지 말며 세력있는 자라고 두호하지 말고 공의로 사람을 재판할지며'),
(1466068,51,3,19,16,'너는 네 백성 중으로 돌아다니며 사람을 논단하지 말며 네 이웃을 대적하여 죽을 지경에 이르게 하지 말라 나는 여호와니라 !'),
(1466069,51,3,19,17,'너는 네 형제를 마음으로 미워하지 말며 이웃을 인하여 죄를 당치 않도록 그를 반드시 책선하라'),
(1466070,51,3,19,18,'원수를 갚지 말며 동포를 원망하지 말며 이웃 사랑하기를 네 몸과 같이 하라 ! 나는 여호와니라 !'),
(1466071,51,3,19,19,'너희는 내 규례를 지킬지어다 ! 네 육축을 다른 종류와 교합시키지 말며 네 밭에 두 종자를 섞어 뿌리지 말며 두 재료로 직조한 옷을 입지 말지며'),
(1466072,51,3,19,20,'무릇 아직 속량도 되지 못하고 해방도 되지 못하고 정혼한 씨종과 사람이 행음하면 두 사람이 형벌은 받으려니와 그들이 죽임을 당치 아니할 것은 그 여인은 아직 해방되지 못하였음이라'),
(1466073,51,3,19,21,'그 남자는 그 속건 제물 곧 속건제 수양을 회막 문 여호와께로 끌어올 것이요'),
(1466074,51,3,19,22,'제사장은 그의 범한 죄를 위하여 그 속건제의 수양으로 여호와 앞에 속죄할 것이요 그리하면 그의 범한 죄의 사함을 받으리라 !'),
(1466075,51,3,19,23,'너희가 그 땅에 들어가 각종 과목을 심거든 그 열매는 아직 할례받지 못한 것으로 여기되 곧 삼년 동안 너희는 그것을 할례 받지 못한 것으로 아껴 먹지 말 것이요'),
(1466076,51,3,19,24,'제 사년에는 그 모든 과실이 거룩하니 여호와께 드려 찬송할 것이며'),
(1466077,51,3,19,25,'제 오년에는 그 열매를 먹을지니 그리하면 너희에게 그 소산이 풍성하리라 나는 너희 하나님 여호와니라 !'),
(1466078,51,3,19,26,'너희는 무엇이든지 피 채 먹지 말며 복술을 하지 말며 술수를 행치 말며'),
(1466079,51,3,19,27,'머리 가를 둥글게 깎지 말며 수염 끝을 손상치 말며'),
(1466080,51,3,19,28,'죽은 자를 위하여 너희는 살을 베지 말며 몸에 무늬를 놓지 말라 ! 나는 여호와니라 !'),
(1466081,51,3,19,29,'네 딸을 더럽혀 기생이 되게 말라 ! 음풍이 전국에 퍼져 죄악이 가득할까 하노라'),
(1466082,51,3,19,30,'내 안식일을 지키고 내 성소를 공경하라 ! 나는 여호와니라 !'),
(1466083,51,3,19,31,'너희는 신접한 자와 박수를 믿지 말며 그들을 추종하여 스스로 더럽히지 말라 ! 나는 너희 하나님 여호와니라 !'),
(1466084,51,3,19,32,'너는 센 머리 앞에 일어서고 노인의 얼굴을 공경하며 네 하나님을 경외하라 ! 나는 여호와니라 !');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466085,51,3,19,33,'타국인이 너희 땅에 우거하여 함께 있거든 너희는 그를 학대하지 말고'),
(1466086,51,3,19,34,'너희와 함께 있는 타국인을 너희 중에서 낳은 자 같이 여기며 자기같이 사랑하라 ! 너희도 애굽 땅에서 객이 되었더니라 나는 너희 하나님 여호와니라 !'),
(1466087,51,3,19,35,'너희는 재판에든지 도량형에든지 불의를 행치 말고'),
(1466088,51,3,19,36,'공평한 저울과, 공평한 추와, 공평한 에바와, 공평한 힌을 사용하라 ! 나는 너희를 인도하여 애굽 땅에서 나오게 한 너희 하나님 여호와니라 !'),
(1466089,51,3,19,37,'너희는 나의 모든 규례와 나의 모든 법도를 지켜 행하라 ! 나는 여호와니라 !'),
(1466090,51,3,20,1,'여호와께서 모세에게 일러 가라사대'),
(1466091,51,3,20,2,'너는 이스라엘 자손에게 또 이르라 무릇 그가 이스라엘 자손이든지 이스라엘에 우거한 타국인이든지 그 자식을 몰렉에게 주거든 반드시 죽이되 그 지방 사람이 돌로 칠 것이요'),
(1466092,51,3,20,3,'나도 그 사람에게 진노하여 그를 그 백성 중에서 끊으리니 이는 그가 그 자식을 몰렉에게 주어서 내 성소를 더럽히고 내 성호를 욕되게 하였음이라'),
(1466093,51,3,20,4,'그가 그 자식을 몰렉에게 주는 것을 그 지방 사람이 못본체하고 그를 죽이지 아니하면'),
(1466094,51,3,20,5,'내가 그 사람과 그 권속에게 진노하여 그와 무릇 그를 본받아 몰렉을 음란히 섬기는 모든 사람을 그 백성 중에서 끊으리라 !'),
(1466095,51,3,20,6,'음란하듯 신접한 자와 박수를 추종하는 자에게는 내가 진노하여 그를 그 백성 중에서 끊으리니'),
(1466096,51,3,20,7,'너희는 스스로 깨끗케 하여 거룩할지어다 ! 나는 너희 하나님 여호와니라 !'),
(1466097,51,3,20,8,'너희는 내 규례를 지켜 행하라 ! 나는 너희를 거룩케 하는 여호와니라 !'),
(1466098,51,3,20,9,'무릇 그 아비나 어미를 저주하는 자는 반드시 죽일지니 그가 그 아비나 어미를 저주하였은즉 그 피가 자기에게로 돌아가리라'),
(1466099,51,3,20,10,'누구든지 남의 아내와 간음하는 자 곧 그 이웃의 아내와 간음하는 자는 그 간부와 음부를 반드시 죽일지니라 !'),
(1466100,51,3,20,11,'누구든지 그 계모와 동침하는 자는 그 아비의 하체를 범하였은즉 둘다 반드시 죽일지니 그 피가 자기에게로 돌아가리라'),
(1466101,51,3,20,12,'누구든지 그 자부와 동침하거든 둘 다 반드시 죽일지니 그들이 가증한 일을 행하였음이라 그 피가 자기에게로 돌아가리라'),
(1466102,51,3,20,13,'누구든지 여인과 교합하듯 남자와 교합하면 둘 다 가증한 일을 행함인즉 반드시 죽일지니 그 피가 자기에게로 돌아가리라'),
(1466103,51,3,20,14,'누구든지 아내와 그 장모를 아울러 취하면 악행인즉 그와 그들을 함께 불사를지니 이는 너희중에 악행이 없게 하려 함이니라'),
(1466104,51,3,20,15,'남자가 짐승과 교합하면 반드시 죽이고 너희는 그 짐승도 죽일 것이며'),
(1466105,51,3,20,16,'여자가 짐승에게 가까이하여 교합하거든 너는 여자와 짐승을 죽이되 이들을 반드시 죽일지니 그 피가 자기에게로 돌아가리라'),
(1466106,51,3,20,17,'누구든지 그 자매 곧 아비의 딸이나 어미의 딸을 취하여 그 여자의 하체를 보고 여자는 그 남자의 하체를 보면 부끄러운 일이라 그 민족 앞에서 그들이 끊어질지니 그가 그 자매의 하체를 범하였은즉 그 죄를 당하리라'),
(1466107,51,3,20,18,'누구든지 경도하는 여인과 동침하여 그의 하체를 범하면 남자는 그 여인의 근원을 드러내었고 여인은 자기의 피 근원을 드러내었음인즉 둘 다 백성 중에서 끊어지리라'),
(1466108,51,3,20,19,'너의 이모나 고모의 하체를 범하지 말지니 이는 골육지친의 하체인즉 그들이 그 죄를 당하리라'),
(1466109,51,3,20,20,'누구든지 백숙모와 동침하면 그 백숙부의 하체를 범함이니 그들이 그 죄를 당하여 무자히 죽으리라'),
(1466110,51,3,20,21,'누구든지 그 형제의 아내를 취하면 더러운 일이라 그가 그 형제의 하체를 범함이니 그들이 무자하리라'),
(1466111,51,3,20,22,'너희는 나의 모든 규례와 법도를 지켜 행하라 ! 그리하여야 내가 너희를 인도하여 거하게 하는 땅이 너희를 토하지 아니하리라'),
(1466112,51,3,20,23,'너희는 내가 너희 앞에서 쫓아내는 족속의 풍속을 좇지 말라 ! 그들이 이 모든 일을 행하므로 내가 그들을 가증히 여기노라'),
(1466113,51,3,20,24,'내가 전에 너희에게 이르기를 너희가 그들의 땅을 기업으로 얻을 것이라 내가 그 땅 곧 젖과 꿀이 흐르는 땅으로 너희에게 주어 유업을 삼게 하리라 하였노라 나는 너희를 만민 중에서 구별한 너희 하나님 여호와라 !'),
(1466114,51,3,20,25,'너희는 짐승의 정하고 부정함과 새의 정하고 부정함을 구별하고 내가 너희를 위하여 부정한 것으로 구별한 짐승이나 새나 땅에 기는 곤충으로 인하여 너희 몸을 더럽히지 말라 !'),
(1466115,51,3,20,26,'너희는 내게 거룩할지어다 ! 이는 나 여호와가 거룩하고 내가 또 너희로 나의 소유를 삼으려고 너희를 만민 중에서 구별하였음이니라'),
(1466116,51,3,20,27,'남자나 여자가 신접하거나 박수가 되거든 반드시 죽일지니 곧 돌로 그를 치라 그 피가 자기에게로 돌아가리라'),
(1466117,51,3,21,1,'여호와께서 모세에게 이르시되 아론의 자손 제사장들에게 고하여 이르라 백성 중의 죽은 자로 인하여 스스로 더럽히지 말려니와'),
(1466118,51,3,21,2,'골육지친인 부모나 자녀나 형제나'),
(1466119,51,3,21,3,'출가하지 아니한 처녀인 친 자매로 인하여는 몸을 더럽힐 수 있느니라'),
(1466120,51,3,21,4,'제사장은 백성의 어른인즉 스스로 더럽혀 욕되게 하지 말지니라'),
(1466121,51,3,21,5,'제사장은 머리털을 깎아 대머리 같게 하지 말며 그 수염 양편을 깎지 말며 살을 베지 말고'),
(1466122,51,3,21,6,'그 하나님께 대하여 거룩하고 그 하나님의 이름을 욕되게 하지 말 것이며 그들은 여호와의 화제 곧 그 하나님의 식물을 드리는 자인즉 거룩할 것이라'),
(1466123,51,3,21,7,'그들은 기생이나 부정한 여인을 취하지 말 것이며 이혼 당한 여인을 취하지 말지니 이는 그가 여호와께 거룩함이니라'),
(1466124,51,3,21,8,'너는 그를 거룩하게 하라 ! 그는 네 하나님의 식물을 드림이니라 너는 그를 거룩히 여기라 ! 나 여호와 너희를 거룩하게 하는 자는 거룩함이니라'),
(1466125,51,3,21,9,'아무 제사장의 딸이든지 행음하여 스스로 더럽히면 그 아비를 욕되게 함이니 그를 불사를지니라'),
(1466126,51,3,21,10,'자기 형제 중 관유로 부음을 받고 위임되어 예복을 입은 대제사장은 그 머리를 풀지 말며 그 옷을 찢지 말며'),
(1466127,51,3,21,11,'어떤 시체에든지 가까이 말지니 부모로 인하여도 더러워지게 말며'),
(1466128,51,3,21,12,'성소에서 나오지 말며 그 하나님의 성소를 더럽히지 말라 ! 이는 하나님의 위임한 관유가 그 위에 있음이니라 나는 여호와니라 !'),
(1466129,51,3,21,13,'그는 처녀를 취하여 아내를 삼을지니'),
(1466130,51,3,21,14,'과부나 이혼된 여인이나 더러운 여인이나 기생을 취하지 말고 자기 백성 중 처녀를 취하여 아내를 삼아'),
(1466131,51,3,21,15,'그 자손으로 백성 중에서 더럽히지 말지니 나는 그를 거룩하게 하는 여호와임이니라'),
(1466132,51,3,21,16,'여호와께서 모세에게 일러 가라사대'),
(1466133,51,3,21,17,'아론에게 고하여 이르라 무릇 너의 대대 자손 중 육체에 흠이 있는 자는 그 하나님의 식물을 드리려고 가까이 오지 못할 것이라'),
(1466134,51,3,21,18,'무릇 흠이 있는 자는 가까이 못할지니 곧 소경이나, 절뚝발이나, 코가 불완전한 자나, 지체가 더한 자나,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466135,51,3,21,19,'발 부러진 자나, 손 부러진 자나,'),
(1466136,51,3,21,20,'곱사등이나, 난장이나, 눈에 백막이 있는 자나, 괴혈병이나, 버짐이 있는 자나, 불알 상한 자나,'),
(1466137,51,3,21,21,'제사장 아론의 자손 중에 흠이 있는 자는 나아와 여호와의 화제를 드리지 못할지니 그는 흠이 있은즉 나아와 하나님의 식물을 드리지 못하느니라'),
(1466138,51,3,21,22,'그는 하나님의 식물의 지성물이든지 성물이든지 먹을 것이나'),
(1466139,51,3,21,23,'장 안에 들어가지 못할 것이요 단에 가까이 못할지니 이는 그가 흠이 있음이라 이와 같이 그가 나의 성소를 더럽히지 못할 것은 나는 그들을 거룩하게 하는 여호와임이니라 !'),
(1466140,51,3,21,24,'모세가 이대로 아론과 그 아들들과 온 이스라엘 자손에게 고하였더라'),
(1466141,51,3,22,1,'여호와께서 모세에게 일러 가라사대'),
(1466142,51,3,22,2,'아론과 그 아들들에게 고하여 그들로 이스라엘 자손이 내게 드리는 성물에 대하여 스스로 구별하여 내 성호를 욕되게 함이 없게 하라 나는 여호와니라 !'),
(1466143,51,3,22,3,'그들에게 이르라 무릇 너의 대대 자손 중에 그 몸이 부정하고도 이스라엘 자손이 구별하여 여호와께 드리는 성물에 가까이하는 자는 내 앞에서 끊어지리라 나는 여호와니라 !'),
(1466144,51,3,22,4,'아론의 자손 중 문둥 환자나 유출병이 있는 자는 정하기 전에는 성물을 먹지말 것이요 시체로 부정하게 된 자나 설정한 자나'),
(1466145,51,3,22,5,'무릇 사람을 부정하게 하는 벌레에 접촉된 자나 무슨 부정이든지 사람을 더럽힐 만한 자에게 접촉된 자'),
(1466146,51,3,22,6,'곧 이런 것에 접촉된 자는 저녁까지 부정하니 몸을 물로 씻지 아니하면 성물을 먹지 못할지며'),
(1466147,51,3,22,7,'해 질 때에야 정하리니 그 후에 성물을 먹을 것이라 이는 자기의 응식이 됨이니라'),
(1466148,51,3,22,8,'절로 죽은 것이나 들짐승에게 찢긴 것을 먹음으로 자기를 더럽히지 말라 ! 나는 여호와니라 !'),
(1466149,51,3,22,9,'그들은 나의 명을 지킬 것이라 그것을 욕되게 하면 그로 인하여 죄를 짓고 그 가운데서 죽을까 하노라 나는 그들을 거룩하게 하는 여호와니라 !'),
(1466150,51,3,22,10,'외국인은 성물을 먹지 못할 것이며 제사장의 객이나 품군은 다 성물을 먹지 못할 것이니라'),
(1466151,51,3,22,11,'그러나 제사장이 돈으로 사람을 샀으면 그 자는 그것을 먹을 것이고 그 집에서 출생한 자도 그러하여 그들이 제사장의 식물을 먹을 것이며'),
(1466152,51,3,22,12,'제사장의 딸은 외국인에게 출가하였으면 거제의 성물을 먹지 못하되'),
(1466153,51,3,22,13,'그가 과부가 되든지 이혼을 당하든지 자식이 없이 친정에 돌아와서 어릴 때와 같으면 그는 그 아비의 응식을 먹을 것이나 외국인은 먹지 못할 것이니라'),
(1466154,51,3,22,14,'사람이 부지중 성물을 먹으면 그 성물에 그 오분 일을 더하여 제사장에게 줄지니라'),
(1466155,51,3,22,15,'이스라엘 자손이 여호와께 드리는 성물을 그들은 더럽히지 말지니'),
(1466156,51,3,22,16,'그들이 성물을 먹으면 그 죄로 인하여 형벌을 받게 할 것이니라 나는 그들을 거룩하게 하는 여호와니라 !'),
(1466157,51,3,22,17,'여호와께서 모세에게 일러 가라사대'),
(1466158,51,3,22,18,'아론과 그 아들들과 이스라엘 온 족속에게 고하여 이르라 이스라엘 자손이나 그 중에 우거하는 자가 서원제나 낙헌제로 번제를 여호와께 예물로 드리려거든'),
(1466159,51,3,22,19,'열납되도록 소나 양이나 염소의 흠 없는 수컷으로 드릴지니'),
(1466160,51,3,22,20,'무릇 흠 있는 것을 너희는 드리지 말 것은 그것이 열납되지 못할 것임이니라'),
(1466161,51,3,22,21,'무릇 서원한 것을 갚으려든지 자의로 예물을 드리려든지 하여 소나 양으로 화목제 희생을 여호와께 드리는 자는 열납되도록 아무 흠이 없는 온전한 것으로 할지니'),
(1466162,51,3,22,22,'눈먼 것이나, 상한 것이나, 지체에 베임을 당한 것이나, 종기 있는 것이나, 괴혈병 있는 것이나, 비루먹은 것을 너희는 여호와께 드리지 말며 단 위에 화제로 여호와께 드리지 말라'),
(1466163,51,3,22,23,'우양의 지체가 더하거나 덜하거나 한 것은 너희가 낙헌 예물로는 쓰려니와 서원한 것을 갚음으로 드리면 열납되지 못하리라'),
(1466164,51,3,22,24,'너희는 불알이 상하였거나, 치었거나, 터졌거나, 베임을 당한 것은 여호와께 드리지 말며 너희 땅에서는 이런 일을 행치도 말지며'),
(1466165,51,3,22,25,'너희는 외방인에게서도 이런 것을 받아 너희의 하나님의 식물로 드리지 말라 이는 결점이 있고 흠이 있는 것인즉 너희를 위하여 열납되지 못할 것임이니라'),
(1466166,51,3,22,26,'여호와께서 모세에게 일러 가라사대'),
(1466167,51,3,22,27,'수소나 양이나 염소가 나거든 칠일동안 그 어미와 같이 있게하라 제 팔일 이후로는 여호와께 화제로 예물을 드리면 열납되리라'),
(1466168,51,3,22,28,'암소나 암양을 무론하고 어미와 새끼를 동일에 잡지 말지니라'),
(1466169,51,3,22,29,'너희가 여호와께 감사 희생을 드리거든 너희가 열납되도록 드릴지며'),
(1466170,51,3,22,30,'그 제물은 당일에 먹고 이튿날까지 두지 말라 나는 여호와니라 !'),
(1466171,51,3,22,31,'너희는 나의 계명을 지키며 행하라 ! 나는 여호와니라 !'),
(1466172,51,3,22,32,'너희는 나의 성호를 욕되게 말라 ! 나는 이스라엘 자손 중에서 거룩하게 함을 받을 것이니라 나는 너희를 거룩하게 하는 여호와요'),
(1466173,51,3,22,33,'너희 하나님이 되려고 너희를 애굽 땅에서 인도하여 낸 자니 나는 여호와니라 !'),
(1466174,51,3,23,1,'여호와께서 모세에게 일러 가라사대'),
(1466175,51,3,23,2,'이스라엘 자손에게 고하여 이르라 너희가 공포하여 성회를 삼을 여호와의 절기는 이러하니라'),
(1466176,51,3,23,3,'엿새 동안은 일할 것이요 일곱째 날은 쉴 안식일이니 성회라 너희는 무슨 일이든지 하지 말라 이는 너희 거하는 각처에서 지킬 여호와의 안식일이니라'),
(1466177,51,3,23,4,'기한에 미쳐 너희가 공포하여 성회로 삼을 여호와의 절기는 이러하니라'),
(1466178,51,3,23,5,'정월 십사일 저녁은 여호와의 유월절이요'),
(1466179,51,3,23,6,'이 달 십오일은 여호와의 무교절이니 칠일 동안 너희는 무교병을 먹을 것이요'),
(1466180,51,3,23,7,'그 첫날에는 너희가 성회로 모이고 아무 노동도 하지 말지며'),
(1466181,51,3,23,8,'너희는 칠일 동안 여호와께 화제를 드릴 것이요 제 칠일에도 성회로 모이고 아무 노동도 하지 말지니라'),
(1466182,51,3,23,9,'여호와께서 모세에게 일러 가라사대'),
(1466183,51,3,23,10,'이스라엘 자손에게 고하여 이르라 너희는 내가 너희에게 주는 땅에 들어가서 너희의 곡물을 거둘 때에 위선 너희의 곡물의 첫 이삭 한 단을 제사장에게로 가져갈 것이요'),
(1466184,51,3,23,11,'제사장은 너희를 위하여 그 단을 여호와 앞에 열납되도록 흔들되 안식일 이튿날에 흔들 것이며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466185,51,3,23,12,'너희가 그 단을 흔드는 날에 일년 되고 흠 없는 수양을 번제로 여호와께 드리고'),
(1466186,51,3,23,13,'그 소제로는 기름 섞은 고운 가루 에바 십분 이를 여호와께 드려 화제를 삼아 향기로운 냄새가 되게 하고 전제로는 포도주 힌 사분 일을 쓸 것이며'),
(1466187,51,3,23,14,'너희는 너희 하나님께 예물을 가져오는 그 날까지 떡이든지 볶은 곡식이든지 생 이삭이든지 먹지 말지니 이는 너희가 그 거하는 각처에서 대대로 지킬 영원한 규례니라 !'),
(1466188,51,3,23,15,'안식일 이튿날 곧 너희가 요제로 단을 가져온 날부터 세어서 칠안식일의 수효를 채우고'),
(1466189,51,3,23,16,'제 칠 안식일 이튿날까지 합 오십일을 계수하여 새 소제를 여호와께 드리되'),
(1466190,51,3,23,17,'너희 처소에서 에바 십분 이로 만든 떡 두개를 가져다가 흔들지니 이는 고운 가루에 누룩을 넣어서 구운 것이요 이는 첫 요제로 여호와께 드리는 것이며'),
(1466191,51,3,23,18,'너희는 또 이 떡과 함께 일년 되고 흠 없는 어린 양 일곱과 젊은 수소 하나와 수양 둘을 드리되 이들을 그 소제와 그 전제와 함께 여호와께 드려서 번제를 삼을지니 이는 화제라 여호와께 향기로운 냄새며'),
(1466192,51,3,23,19,'또 수염소 하나로 속죄제를 드리며 일년된 어린 수양 둘을 화목제 희생으로 드릴 것이요'),
(1466193,51,3,23,20,'제사장은 그 첫이삭의 떡과 함께 그 두 어린 양을 여호와 앞에 흔들어 요제를 삼을 것이요 이것들은 여호와께 드리는 성물인즉 제사장에게 돌릴 것이며'),
(1466194,51,3,23,21,'이 날에 너희는 너희 중에 성회를 공포하고 아무 노동도 하지 말지니 이는 너희가 그 거하는 각처에서 대대로 지킬 영원한 규례니라 !'),
(1466195,51,3,23,22,'너희 땅의 곡물을 벨 때에 밭 모퉁이까지 다 베지 말며 떨어진 진을 줍지 말고 너는 그것을 가난한 자와 객을 위하여 버려 두라 나는 너희 하나님 여호와니라 !'),
(1466196,51,3,23,23,'여호와께서 모세에게 일러 가라사대'),
(1466197,51,3,23,24,'이스라엘 자손에게 고하여 이르라 칠월 곧 그 달 일일로 안식일을 삼을지니 이는 나팔을 불어 기념할 날이요 성회라'),
(1466198,51,3,23,25,'아무 노동도 하지 말고 여호와께 화제를 드릴지니라'),
(1466199,51,3,23,26,'여호와께서 모세에게 일러 가라사대'),
(1466200,51,3,23,27,'칠월 십일은 속죄일이니 너희에게 성회라 너희는 스스로 괴롭게하며 여호와께 화제를 드리고'),
(1466201,51,3,23,28,'이 날에는 아무 일도 하지 말 것은 너희를 위하여 너희 하나님 여호와 앞에 속죄할 속죄일이 됨이니라'),
(1466202,51,3,23,29,'이 날에 스스로 괴롭게 하지 아니하는 자는 그 백성 중에서 끊쳐질 것이라'),
(1466203,51,3,23,30,'이 날에 누구든지 아무 일이나 하는 자는 내가 백성 중에서 멸절시키리니'),
(1466204,51,3,23,31,'너희는 아무 일이든지 하지 말라 이는 너희가 그 거하는 각처에서 대대로 지킬 영원한 규례니라 !'),
(1466205,51,3,23,32,'이는 너희의 쉴 안식일이라 너희는 스스로 괴롭게 하고 이 달 구일 저녁 곧 그 저녁부터 이튿날 저녁까지 안식을 지킬지니라 !'),
(1466206,51,3,23,33,'여호와께서 모세에게 일러 가라사대'),
(1466207,51,3,23,34,'이스라엘 자손에게 고하여 이르라 칠월 십오일은 초막절이니 여호와를 위하여 칠일동안 지킬 것이라'),
(1466208,51,3,23,35,'첫 날에는 성회가 있을지니 너희는 아무 노동도 하지 말지며'),
(1466209,51,3,23,36,'칠일 동안에 너희는 화제를 여호와께 드릴 것이요 제 팔일에도 너희에게 성회가 될 것이며 화제를 여호와께 드릴지니 이는 거룩한 대회라 너희는 아무 노동도 하지 말지니라 !'),
(1466210,51,3,23,37,'이것들은 여호와의 절기라 너희는 공포하여 성회를 삼고 번제와 소제와 희생과 전제를 각각 그 날에 여호와께 화제로 드릴지니'),
(1466211,51,3,23,38,'이는 여호와의 안식일 외에, 너희의 헌물 외에, 너희의 모든 서원 예물외에,너희의 모든 낙헌 예물 외에 너희가 여호와께 드리는 것이니라'),
(1466212,51,3,23,39,'너희가 토지 소산 거두기를 마치거든 칠월 십오일부터 칠일 동안 여호와의 절기를 지키되 첫날에도 안식하고 제 팔일에도 안식할 것이요'),
(1466213,51,3,23,40,'첫날에는 너희가 아름다운 나무 실과와, 종려 가지와, 무성한 가지와, 시내 버들을 취하여 너희 하나님 여호와 앞에서 칠일동안 즐거워할 것이라'),
(1466214,51,3,23,41,'너희는 매년에 칠일 동안 여호와께 이 절기를 지킬지니 너희 대대로의 영원한 규례라 ! 너희는 칠월에 이를 지킬지니라 !'),
(1466215,51,3,23,42,'너희는 칠일 동안 초막에 거하되 이스라엘에서 난 자는 다 초막에 거할지니'),
(1466216,51,3,23,43,'이는 내가 이스라엘 자손을 애굽 땅에서 인도하여 내던 때에 초막에 거하게 한 줄을 너희 대대로 알게 함이니라 나는 너희 하나님 여호와니라 !'),
(1466217,51,3,23,44,'모세가 여호와의 절기를 이스라엘 자손에게 공포하였더라'),
(1466218,51,3,24,1,'여호와께서 모세에게 일러 가라사대'),
(1466219,51,3,24,2,'이스라엘 자손에게 명하여 감람을 찧어 낸 순결한 기름을 켜기 위하여 네게로 가져오게 하고 끊이지 말고 등잔불을 켤지며'),
(1466220,51,3,24,3,'아론은 회막 안 증거궤 장 밖에서 저녁부터 아침까지 여호와 앞에 항상 등잔불을 정리할지니 너희 대대로 지킬 영원한 규례라'),
(1466221,51,3,24,4,'그가 여호와 앞에서 순결한 등대 위의 등잔들을 끊이지 않고 정리할지니라'),
(1466222,51,3,24,5,'너는 고운 가루를 취하여 떡 열 둘을 굽되 매 덩이를 에바 십분 이로 하여'),
(1466223,51,3,24,6,'여호와 앞 순결한 상 위에 두 줄로 한 줄에 여섯씩 진설하고'),
(1466224,51,3,24,7,'너는 또 정결한 유향을 그 매 줄 위에 두어 기념물로 여호와께 화제를 삼을 것이며'),
(1466225,51,3,24,8,'항상 매 안식일에 이 떡을 여호와 앞에 진설할지니 이는 이스라엘 자손을 위한 것이요 영원한 언약이니라'),
(1466226,51,3,24,9,'이 떡은 아론과 그 자손에게 돌리고 그들은 그것을 거룩한 곳에서 먹을지니 이는 여호와의 화제 중 그에게 돌리는 것으로서 지극히 거룩함이니라 이는 영원한 규례니라'),
(1466227,51,3,24,10,'이스라엘 여인의 아들이요 그 아비는 애굽 사람된 자가 이스라엘 자손 중에 나가서 한 이스라엘 사람과 진중에서 싸우다가'),
(1466228,51,3,24,11,'그 이스라엘 여인의 아들이 여호와의 이름을 훼방하며 저주하므로 무리가 끌고 모세에게로 가니라 그 어미의 이름은 슬로밋이요 단 지파 디브리의 딸이었더라'),
(1466229,51,3,24,12,'그들이 그를 가두고 여호와의 명령을 기다리더니'),
(1466230,51,3,24,13,'여호와께서 모세에게 일러 가라사대'),
(1466231,51,3,24,14,'저주한 사람을 진 밖에 끌어 내어 그 말을 들은 모든 자로 그 머리에 안수하게 하고 온 회중이 돌로 그를 칠지니라'),
(1466232,51,3,24,15,'너는 이스라엘 자손에게 고하여 이르라 누구든지 자기 하나님을 저주하면 죄를 당할 것이요'),
(1466233,51,3,24,16,'여호와의 이름을 훼방하면 그를 반드시 죽일지니 온 회중이 돌로 그를 칠 것이라 외국인이든지 본토인이든지 여호와의 이름을 훼방하면 그를 죽일지니라'),
(1466234,51,3,24,17,'사람을 쳐 죽인 자는 반드시 죽일 것이요');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466235,51,3,24,18,'짐승을 쳐 죽인 자는 짐승으로 짐승을 갚을 것이며'),
(1466236,51,3,24,19,'사람이 만일 그 이웃을 상하였으면 그 행한 대로 그에게 행할 것이니'),
(1466237,51,3,24,20,'파상은 파상으로, 눈은 눈으로, 이는 이로 갚을지라 남에게 손상을 입힌대로 그에게 그렇게 할것이며'),
(1466238,51,3,24,21,'짐승을 죽인 자는 그것을 물어 줄 것이요 사람을 죽인 자는 죽일지니'),
(1466239,51,3,24,22,'외국인에게든지 본토인에게든지 그 법을 동일히 할 것은 나는 너희 하나님 여호와임이니라 !'),
(1466240,51,3,24,23,'모세가 이스라엘 자손에게 고하니 그들이 저주한 자를 진 밖에 끌어내어 돌로 쳤더라 이스라엘 자손이 여호와께서 모세에게 명하신 대로 행하였더라'),
(1466241,51,3,25,1,'여호와께서 시내산에서 모세에게 일러 가라사대'),
(1466242,51,3,25,2,'이스라엘 자손에게 고하여 이르라 너희는 내가 너희에게 주는 땅에 들어간 후에 그 땅으로 여호와 앞에 안식하게 하라'),
(1466243,51,3,25,3,'너는 육년 동안 그 밭에 파종하며 육년 동안 그 포도원을 다스려 그 열매를 거둘 것이나'),
(1466244,51,3,25,4,'제 칠년에는 땅으로 쉬어 안식하게 할지니 여호와께 대한 안식이라 너는 그 밭에 파종하거나 포도원을 다스리지 말며'),
(1466245,51,3,25,5,'너의 곡물의 스스로 난 것을 거두지 말고 다스리지 아니한 포도나무의 맺은 열매를 거두지 말라 이는 땅의 안식년임이니라'),
(1466246,51,3,25,6,'안식년의 소출은 너희의 먹을 것이니 너와 네 남종과, 네 여종과, 네 품군과, 너와 함께 거하는 객과,'),
(1466247,51,3,25,7,'네 육축과 네 땅에 있는 들짐승들이 다 그 소산으로 식물을 삼을지니라'),
(1466248,51,3,25,8,'너는 일곱 안식년을 계수할지니 이는 칠년이 일곱번인즉 안식년 일곱번 동안 곧 사십 구년이라'),
(1466249,51,3,25,9,'칠월 십일은 속죄일이니 너는 나팔 소리를 내되 전국에서 나팔을 크게 불지며'),
(1466250,51,3,25,10,'제 오십년을 거룩하게 하여 전국 거민에게 자유를 공포하라 ! 이 해는 너희에게 희년이니 너희는 각각 그 기업으로 돌아가며 각각 그 가족에게로 돌아갈지며'),
(1466251,51,3,25,11,'그 오십년은 너희의 희년이니 너희는 파종하지 말며 스스로 난 것을 거두지 말며 다스리지 아니한 포도를 거두지 말라'),
(1466252,51,3,25,12,'이는 희년이니 너희에게 거룩함이니라 너희가 밭의 소산을 먹으리라'),
(1466253,51,3,25,13,'이 희년에는 너희가 각기 기업으로 돌아갈지라'),
(1466254,51,3,25,14,'네 이웃에게 팔든지 네 이웃의 손에서 사거든 너희는 서로 속이지 말라'),
(1466255,51,3,25,15,'희년 후의 연수를 따라서 너는 이웃에게 살 것이요 그도 그 열매를 얻을 연수를 따라서 네게 팔 것인즉'),
(1466256,51,3,25,16,'연수가 많으면 너는 그 값을 많게 하고 연수가 적으면 너는 그 값을 적게 할지니 곧 그가 그 열매의 다소를 따라서 네게 팔 것이라'),
(1466257,51,3,25,17,'너희는 서로 속이지 말고 너희의 하나님을 경외하라 ! 나는 너희 하나님 여호와니라 !'),
(1466258,51,3,25,18,'너희는 내 법도를 행하며 내 규례를 지켜 행하라 ! 그리하면 너희가 그 땅에 안전히 거할 것이라'),
(1466259,51,3,25,19,'땅은 그 산물을 내리니 너희가 배불리 먹고 거기 안전히 거하리라'),
(1466260,51,3,25,20,'혹 너희 말이 우리가 만일 제 칠년에 심지도 못하고 그 산물을 거두지도 못하면 무엇을 먹으리요 하겠으나'),
(1466261,51,3,25,21,'내가 명하여 제 육년에 내 복을 너희에게 내려 그 소출이 삼년 쓰기에 족하게 할지라'),
(1466262,51,3,25,22,'너희가 제 팔년에는 파종하려니와 묵은 곡식을 먹을 것이며 제 구년 곧 추수하기까지 묵은 곡식을 먹으리라'),
(1466263,51,3,25,23,'토지를 영영히 팔지 말 것은 토지는 다 내 것임이라 너희는 나그네요 우거하는 자로서 나와 함께 있느니라'),
(1466264,51,3,25,24,'너희 기업의 온 땅에서 그 토지 무르기를 허락할지니'),
(1466265,51,3,25,25,'만일 너희 형제가 가난하여 그 기업 얼마를 팔았으면 그 근족이 와서 동족의 판 것을 무를 것이요'),
(1466266,51,3,25,26,'만일 그것을 무를 사람이 없고 자기가 부요하게 되어 무를 힘이 있거든'),
(1466267,51,3,25,27,'그 판 해를 계수하여 그 남은 값을 산 자에게 주고 그 기업으로 돌아갈 것이니라'),
(1466268,51,3,25,28,'그러나 자기가 무를 힘이 없으면 그 판것이 희년이 이르기까지 산자의 손에 있다가 희년에 미쳐 돌아올지니 그가 곧 그 기업으로 돌아갈 것이니라'),
(1466269,51,3,25,29,'성벽 있는 성내의 가옥을 팔았으면 판 지 만 일년 안에는 무를 수 있나니 곧 그 기한 안에 무르려니와'),
(1466270,51,3,25,30,'주년 내에 무르지 못하면 그 성내 가옥은 산 자의 소유로 확정되어 대대로 영영히 그에게 속하고 희년에라도 돌려 보내지 아니할 것이니라'),
(1466271,51,3,25,31,'그러나 성벽이 둘리지 아니한 촌락의 가옥은 나라의 전토 일례로 물러주기도 할 것이요 희년에 돌려 보내기도 할 것이니라'),
(1466272,51,3,25,32,'레위 족속의 성읍 곧 그 기업의 성읍의 가옥은 레위 사람이 언제든지 무를 수 있으나'),
(1466273,51,3,25,33,'레위 사람이 만일 무르지 아니하면 그 기업된 성읍의 판 가옥은 희년에 돌려 보낼지니 대저 레위 사람의 성읍의 가옥은 이스라엘 자손 중에서 얻을 기업이 됨이니라'),
(1466274,51,3,25,34,'그러나 그 성읍의 들의 사면 밭은 그의 영원한 기업이니 팔지 못할지니라'),
(1466275,51,3,25,35,'네 동족이 빈한하게 되어 빈 손으로 네 곁에 있거든 너는 그를 도와 객이나 우거하는 자처럼 너와 함께 생활하게 하되'),
(1466276,51,3,25,36,'너는 그에게 이식을 취하지 말고 네 하나님을 경외하여 네 형제로 너와 함께 생활하게 할 것인즉'),
(1466277,51,3,25,37,'너는 그에게 이식을 위하여 돈을 꾸이지 말고 이익을 위하여 식물을 꾸이지 말라'),
(1466278,51,3,25,38,'나는 너희 하나님이 되려고 또는 가나안 땅으로 너희에게 주려고 애굽 땅에서 너희를 인도하여 낸 너희 하나님 여호와니라 !'),
(1466279,51,3,25,39,'네 동족이 반한하게 되어 네게 몸이 팔리거든 너는 그를 종으로 부리지 말고'),
(1466280,51,3,25,40,'품군이나 우거하는 자같이 너와 함께 있게 하여 희년까지 너를 섬기게 하라'),
(1466281,51,3,25,41,'그 때에는 그와 그 자녀가 함께 네게서 떠나 그 본족에게로 돌아가서 조상의 기업을 회복하리라'),
(1466282,51,3,25,42,'그들은 내가 애굽 땅에서 인도하여 낸바 나의 품군인즉 종으로 팔리지 말 것이라'),
(1466283,51,3,25,43,'너는 그를 엄하게 부리지 말고 너의 하나님을 경외하라 !'),
(1466284,51,3,25,44,'너의 종은 남녀를 무론하고 너의 사면 이방인 중에서 취할지니 남녀 종은 이런 자 중에서 살 것이며');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466285,51,3,25,45,'또 너희 중에 우거한 이방인의 자녀 중에서도 너희가 살 수 있고 또 그들이 너희 중에서 살아서 너희 땅에서 가정을 이룬 그 중에서도 그리할 수 있은즉 그들이 너희 소유가 될찌니'),
(1466286,51,3,25,46,'너희는 그들을 너희 후손에게 기업으로 주어 소유가 되게 할 것이라 이방인 중에서는 너희가 영원한 종을 삼으려니와 너희 동족 이스라엘 자손은 너희 피차 엄하게 부리지 말지니라'),
(1466287,51,3,25,47,'너희 중에 우거하는 이방인은 부요하게 되고 그 곁에 사는 너희 동족은 빈한하게 됨으로 너희 중에 우거하는 그 이방인에게나 그 족속에게 몸이 팔렸으면'),
(1466288,51,3,25,48,'팔린 후에 그를 속량할 수 있나니 그 형제 중 하나가 속하거나'),
(1466289,51,3,25,49,'삼촌이나 사촌이 속하거나 그 근족 중 누구든지 속할 것이요 그가 부요하게 되면 스스로 속하되'),
(1466290,51,3,25,50,'자기 몸이 팔린 해로부터 희년까지를 그 산 자와 계산하여 그 년수를 따라서 그 몸의 값을 정할 때에 그 사람을 섬긴 날을 그 사람에게 고용된 날로 여길 것이라'),
(1466291,51,3,25,51,'만일 남은 해가 많으면 그 연수대로 팔린 값에서 속하는 값을 그 사람에게 도로 주고'),
(1466292,51,3,25,52,'만일 희년까지 남은 해가 적으면 그 사람과 계산하여 그 연수대로 속하는 그 값을 그에게 도로 줄지며'),
(1466293,51,3,25,53,'주인은 그를 매년의 삯군과 같이 여기고 너의 목전에서 엄하게 부리지 못하리라'),
(1466294,51,3,25,54,'그가 이같이 속하지 못하면 희년에 이르러 그와 그 자녀가 자유하리니'),
(1466295,51,3,25,55,'이스라엘 자손은 나의 품군이 됨이라 그들은 내가 애굽 땅에서 인도하여 낸 나의 품군이요 나는 너희 하나님 여호와니라 !'),
(1466296,51,3,26,1,'너희는 자기를 위하여 우상을 만들지 말지니 목상이나 주상을 세우지 말며 너희 땅에 조각한 석상을 세우고 그에게 경배하지 말라 나는 너희 하나님 여호와임이니라 !'),
(1466297,51,3,26,2,'너희는 나의 안식일을 지키며 나의 성소를 공경하라 ! 나는 여호와니라 !'),
(1466298,51,3,26,3,'너희가 나의 규례와 계명을 준행하면'),
(1466299,51,3,26,4,'내가 너희 비를 그 시후에 주리니 땅은 그 산물을 내고 밭의 수목은 열매를 맺을지라'),
(1466300,51,3,26,5,'너희의 타작은 포도 딸 때까지 미치며 너희의 포도 따는 것은 파종할 때까지 미치리니 너희가 음식을 배불리 먹고 너희 땅에 안전히 거하리라'),
(1466301,51,3,26,6,'내가 그 땅에 평화를 줄 것인즉 너희가 누우나 너희를 두렵게 할자가 없을 것이며 내가 사나운 짐승을 그 땅에서 제할 것이요 칼이 너희 땅에 두루 행하지 아니할 것이며'),
(1466302,51,3,26,7,'너희가 대적을 쫓으리니 그들이 너희 앞에서 칼에 엎드러질 것이라'),
(1466303,51,3,26,8,'너희 다섯이 백을 쫓고, 너희 백이 만을 쫓으리니 너희 대적들이 너희 앞에서 칼에 엎드러질 것이며'),
(1466304,51,3,26,9,'내가 너희를 권고하여 나의 너희와 세운 언약을 이행하여 너희로 번성케 하고 너희로 창대케 할 것이며'),
(1466305,51,3,26,10,'너희는 오래 두었던 묵은 곡식을 먹다가 새 곡식을 인하여 묵은 곡식을 치우게 될 것이며'),
(1466306,51,3,26,11,'내가 내 장막을 너희 중에 세우리니 내 마음이 너희를 싫어하지 아니할 것이며'),
(1466307,51,3,26,12,'나는 너희 중에 행하여 너희 하나님이 되고 너희는 나의 백성이 될 것이니라'),
(1466308,51,3,26,13,'나는 너희를 애굽 땅에서 인도하여 내어 그 종된 것을 면케 한 너희 하나님 여호와라 ! 내가 너희 멍에 빗장목을 깨뜨리고 너희로 바로 서서 걷게 하였느니라'),
(1466309,51,3,26,14,'그러나 너희가 내게 청종치 아니하여 이 모든 명령을 준행치 아니하며'),
(1466310,51,3,26,15,'나의 규례를 멸시하며 마음에 나의 법도를 싫어하여 나의 모든 계명을 준행치 아니하며 나의 언약을 배반할진대'),
(1466311,51,3,26,16,'내가 이같이 너희에게 행하리니 곧 내가 너희에게 놀라운 재앙을 내려 폐병과 열병으로 눈이 어둡고 생명이 쇠약하게 할것이요 너희의 파종은 헛되리니 너희의 대적이 그것을 먹을 것임이며'),
(1466312,51,3,26,17,'내가 너희를 치리니 너희가 너희 대적에게 패할 것이요 너희를 미워하는 자가 너희를 다스릴 것이며 너희는 쫓는 자가 없어도 도망하리라'),
(1466313,51,3,26,18,'너희가 그렇게 되어도 내게 청종치 아니하면 너희 죄를 인하여 내가 너희를 칠배나 더 징치할지라'),
(1466314,51,3,26,19,'내가 너희의 세력을 인한 교만을 꺾고 너희 하늘로 철과 같게 하며 너희 땅으로 놋과 같게 하리니'),
(1466315,51,3,26,20,'너희 수고가 헛될지라 땅은 그 산물을 내지 아니하고 땅의 나무는 그 열매를 맺지 아니하리라'),
(1466316,51,3,26,21,'너희가 나를 거스려 내게 청종치 않을진대 내가 너희 죄대로 너희에게 칠배나 더 재앙을 내릴 것이라'),
(1466317,51,3,26,22,'내가 들짐승을 너희 중에 보내리니 그것들이 너희 자녀를 움키고 너희 육축을 멸하며 너희 수효를 감소케 할지라 너희 도로가 황폐하리라'),
(1466318,51,3,26,23,'이런 일을 당하여도 너희가 내게로 돌아오지 아니하고 나를 대항할진대'),
(1466319,51,3,26,24,'나 곧 나도 너희에게 대항하여 너희 죄를 인하여 너희를 칠배나 더 칠지라'),
(1466320,51,3,26,25,'내가 칼을 너희에게로 가져다가 너희의 배약한 원수를 갚을 것이며 너희가 성읍에 모일지라도 너희 중에 염병을 보내고 너희를 대적의 손에 붙일 것이며'),
(1466321,51,3,26,26,'내가 너희 의뢰하는 양식을 끊을 때에 열 여인이 한 화덕에서 너희 떡을 구워 저울에 달아 주리니 너희가 먹어도 배부르지 아니하리라'),
(1466322,51,3,26,27,'너희가 이같이 될지라도 내게 청종치 아니하고 내게 대항할진대'),
(1466323,51,3,26,28,'내가 진노로 너희에게 대항하되 너희 죄를 인하여 칠배나 더 징책하리니'),
(1466324,51,3,26,29,'너희가 아들의 고기를 먹을 것이요 딸의 고기를 먹을 것이며'),
(1466325,51,3,26,30,'내가 너희의 산당을 헐며 너희의 태양 주상을 찍어 넘기며 너희 시체를 파상한 우상 위에 던지고 내 마음이 너희를 싫어할 것이며'),
(1466326,51,3,26,31,'내가 너희 성읍으로 황폐케 하고 너희 성소들로 황량케 할 것이요 너희의 향기로운 향을 흠향치 아니하고'),
(1466327,51,3,26,32,'그 땅을 황무케 하리니 거기 거하는 너희 대적들이 그것을 인하여 놀랄 것이며'),
(1466328,51,3,26,33,'내가 너희를 열방 중에 흩을 것이요 내가 칼을 빼어 너희를 따르게 하리니 너희의 땅이 황무하며 너희의 성읍이 황폐하리라'),
(1466329,51,3,26,34,'너희가 대적의 땅에 거할 동안에 너희 본토가 황무할 것이므로 땅이 안식을 누릴 것이라 그 때에 땅이 쉬어 안식을 누리리니'),
(1466330,51,3,26,35,'너희가 그 땅에 거한 동안 너희 안식시에 쉼을 얻지 못하던 땅이 그 황무할 동안에는 쉬리라'),
(1466331,51,3,26,36,'너희 남은 자에게는 그 대적의 땅에서 내가 그들의 마음으로 약하게 하리니 그들은 바람에 불린 잎사귀 소리에도 놀라 도망하기를 칼을 피하여 도망하듯 할 것이요 쫓는 자가 없어도 엎드러질 것이라'),
(1466332,51,3,26,37,'그들은 쫓는 자가 없어도 칼 앞에 있음같이 서로 천답하여 넘어지리니 너희가 대적을 당할 힘이 없을 것이요'),
(1466333,51,3,26,38,'너희가 열방 중에서 망하리니 너희 대적의 땅이 너희를 삼킬 것이라'),
(1466334,51,3,26,39,'너희 남은 자가 너희 대적의 땅에서 자기의 죄로 인하여 쇠잔하며 그 열조의 죄로 인하여 그 열조 같이 쇠잔하리라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466335,51,3,26,40,'그들이 자기 죄와 그 열조의 죄와 및 그들이 나를 거스린 허물을 자복하고 또 자기들이 나를 대항하였으므로'),
(1466336,51,3,26,41,'나도 그들을 대항하여 그 대적의 땅으로 끌어 갔음을 깨닫고 그 할례받지 아니한 마음이 낮아져서 그 죄악의 형벌을 순히 받으면'),
(1466337,51,3,26,42,'내가 야곱과 맺은 내 언약과 이삭과 맺은 내 언약을 생각하며 아브라함과 맺은 내 언약을 생각하고 그 땅을 권고하리라'),
(1466338,51,3,26,43,'그들이 나의 법도를 싫어하며 나의 규례를 멸시하였으므로 그 땅을 떠나서 사람이 없을 때에 땅이 황폐하여 안식을 누릴 것이요 그들은 자기 죄악으로 형벌을 순히 받으리라'),
(1466339,51,3,26,44,'그런즉 그들이 대적의 땅에 거할 때에 내가 싫어 버리지 아니하며, 미워하지 아니하며, 아주 멸하지 아니하여 나의 그들과 세운 언약을 폐하지 아니하리니 나는 여호와 그들의 하나님이 됨이라'),
(1466340,51,3,26,45,'내가 그들의 하나님이 되기 위하여 열방의 목전에 애굽에서 인도하여 낸 그들의 열조와 맺은 언약을 그들을 위하여 기억하리라 나는 여호와니라 !'),
(1466341,51,3,26,46,'이상은 여호와께서 시내산에서 자기와 이스라엘 자손 사이에 모세로 세우신 규례와 법도와 율법이니라'),
(1466342,51,3,27,1,'여호와께서 모세에게 일러 가라사대'),
(1466343,51,3,27,2,'이스라엘 자손에게 고하여 이르라 사람을 여호와께 드리기로 서원하였으면 너는 그 값을 정할지니'),
(1466344,51,3,27,3,'너의 정한 값은 이십세로 육십세까지는 남자이면 성소의 세겔대로 은 오십 세겔로 하고'),
(1466345,51,3,27,4,'여자이면 그 값을 삼십 세겔로 하며'),
(1466346,51,3,27,5,'오세로 이십세까지는 남자이면 그 값을 이십 세겔로 하고 여자이면 십 세겔로 하며'),
(1466347,51,3,27,6,'일개월로 오세까지는 남자이면 그 값을 은 오 세겔로 하고 여자이면 그 값을 은 삼 세겔로 하며'),
(1466348,51,3,27,7,'육십세 이상은 남자이면 그 값을 십 오 세겔로 하고 여자는 십 세겔로 하라'),
(1466349,51,3,27,8,'그러나 서원자가 가난하여 너의 정가를 감당치 못하겠으면 그를 제사장의 앞으로 데리고 갈 것이요 제사장은 그 값을 정하되 그 서원자의 형세대로 값을 정할지니라'),
(1466350,51,3,27,9,'사람이 예물로 여호와께 드리는 것이 생축이면 서원물로 여호와께 드릴 때는 다 거룩하니'),
(1466351,51,3,27,10,'그것을 변개하여 우열간 바꾸지 못할 것이요 혹 생축으로 생축을 바꾸면 둘 다 거룩할 것이며'),
(1466352,51,3,27,11,'부정하여 여호와께 예물로 드리지 못할 생축이면 그 생축을 제사장 앞으로 끌어 갈 것이요'),
(1466353,51,3,27,12,'제사장은 그 우열간에 정가할지니 그 값이 제사장의 정한 대로 될것이며'),
(1466354,51,3,27,13,'그가 그것을 무르려면 정가에 그 오분 일을 더할지니라'),
(1466355,51,3,27,14,'사람이 자기 집을 구별하여 여호와께 드리려면 제사장이 그 우열간에 정가할지니 그 값이 제사장의 정한 대로 될 것이며'),
(1466356,51,3,27,15,'그 사람이 자기 집을 무르려면 정가한 돈에 그 오분 일을 더할지니 그리하면 자기 소유가 되리라'),
(1466357,51,3,27,16,'사람이 자기 기업된 밭 얼마를 구별하여 여호와께 드리려면 두락수대로 정가하되 보리 한 호멜지기에는 은 오십 세겔로 계산할지며'),
(1466358,51,3,27,17,'그가 그 밭을 희년부터 구별하여 드렸으면 그 값을 네가 정한대로 할 것이요'),
(1466359,51,3,27,18,'그 밭을 희년 후에 구별하여 드렸으면 제사장이 다음 희년까지 남은 연수를 따라 그 값을 계산하고 정가에서 그 값에 상당하게 감할 것이며'),
(1466360,51,3,27,19,'밭을 구별하여 드린 자가 그것을 무르려면 정가한 돈에 그 오분일을 더할지니 그리하면 그것이 자기 소유가 될 것이요'),
(1466361,51,3,27,20,'그가 그 밭을 무르지 아니하려거나 타인에게 팔았으면 다시는 무르지 못하고'),
(1466362,51,3,27,21,'희년이 되어서 그 밭이 돌아오게 될 때에는 여호와께 바친 성물이 되어 영영히 드린 땅과 같이 제사장의 기업이 될 것이며'),
(1466363,51,3,27,22,'사람에게 샀고 자기 기업이 아닌 밭을 여호와께 구별하여 드렸으면'),
(1466364,51,3,27,23,'너는 정가하고 제사장은 그를 위하여 희년까지 계산하고 그는 너의 정가한 돈을 그 날에 여호와께 드려 성물을 삼을지며'),
(1466365,51,3,27,24,'그 밭은 희년에 판 사람 곧 그 기업의 본주에게로 돌아 갈지니라'),
(1466366,51,3,27,25,'너의 모든 정가를 성소의 세겔대로 하되 이십 게라를 한 세겔로 할지니라'),
(1466367,51,3,27,26,'오직 생축의 첫새끼는 여호와께 돌릴 첫새끼라 우양을 물론하고 여호와의 것이니 누구든지 그것으로는 구별하여 드리지 못할 것이며'),
(1466368,51,3,27,27,'부정한 짐승이면 너의 정가에 그 오분 일을 더하여 속할 것이요 만일 속하지 아니하거든 너의 정가대로 팔지니라'),
(1466369,51,3,27,28,'오직 여호와께 아주 바친 그 물건은 사람이든지 생축이든지 기업의 밭이든지 팔지도 못하고 속하지도 못하나니 바친 것은 다 여호와께 지극히 거룩함이며'),
(1466370,51,3,27,29,'아주 바친 그 사람은 다시 속하지 못하나니 반드시 죽일지니라 !'),
(1466371,51,3,27,30,'땅의 십분 일 곧 땅의 곡식이나 나무의 과실이나 그 십분 일은 여호와의 것이니 여호와께 성물이라'),
(1466372,51,3,27,31,'사람이 그 십분 일을 속하려면 그것에 그 오분 일을 더할 것이요'),
(1466373,51,3,27,32,'소나 양의 십분 일은 막대기 아래로 통과하는 것의 열째마다 여호와의 거룩한 것이 되리니'),
(1466374,51,3,27,33,'그 우열을 교계하거나 바꾸거나 하지 말라 바꾸면 둘 다 거룩하리니 속하지 못하리라'),
(1466375,51,3,27,34,'이상은 여호와께서 시내산에서 이스라엘 자손을 위하여 모세에게 명하신 계명이니라'),
(1466376,51,4,1,1,'이스라엘 자손이 애굽 땅에서 나온 후 제 이년 이월 일일에 여호와께서 시내 광야 회막에서 모세에게 일러 가라사대'),
(1466377,51,4,1,2,'너희는 이스라엘 자손의 모든 회중 각 남자의 수를 그들의 가족과 종족을 따라 그 명수대로 계수할지니'),
(1466378,51,4,1,3,'이스라엘 중 이십세 이상으로 싸움에 나갈만한 모든 자를 너와 아론은 그 군대대로 계수하되'),
(1466379,51,4,1,4,'매 지파의 각기 종족의 두령 한 사람씩 너희와 함께 하라'),
(1466380,51,4,1,5,'너희와 함께 설 사람들의 이름은 이러하니 르우벤에게서는 스데울의 아들 엘리술이요'),
(1466381,51,4,1,6,'시므온에게서는 수리삿대의 아들 슬루미엘이요'),
(1466382,51,4,1,7,'유다에게서는 암미나답의 아들 나손이요'),
(1466383,51,4,1,8,'잇사갈에게서는 수리알의 아들 느다넬이요'),
(1466384,51,4,1,9,'스불론에게서는 헬론의 아들 엘리압이요');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466385,51,4,1,10,'요셉 자손에게서는 에브라임에 암미훗의 아들 엘리사마와, 므낫세에 브다술의 아들 가말리엘이요'),
(1466386,51,4,1,11,'베냐민에게서는 기드오니의 아들 아비단이요'),
(1466387,51,4,1,12,'단에게서는 암미삿대의 아들 아히에셀이요'),
(1466388,51,4,1,13,'아셀에게서는 오그란의 아들 바기엘이요'),
(1466389,51,4,1,14,'갓에게서는 드우엘의 아들 엘리아삽이요'),
(1466390,51,4,1,15,'납달리에게서는 에난의 아들 아히라니라 하시니'),
(1466391,51,4,1,16,'그들은 회중에서 부름을 받은 자요 그 조상 지파의 족장으로서 이스라엘 천만인의 두령이라'),
(1466392,51,4,1,17,'모세와 아론이 지명된 이 사람들을 데리고'),
(1466393,51,4,1,18,'이월 일일에 온 회중을 모으니 그들이 각기 가족과 종족을 따라 이십세 이상으로 그 명수를 의지하여 자기 계통을 말하매'),
(1466394,51,4,1,19,'여호와께서 모세에게 명하신 대로 그가 시내 광야에서 그들을 계수하였더라'),
(1466395,51,4,1,20,'이스라엘의 장자 르우벤의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈만한 각 남자를 그 명수대로 다 계수하니'),
(1466396,51,4,1,21,'르우벤 지파의 계수함을 입은 자가 사만 육천 오백명이었더라'),
(1466397,51,4,1,22,'시드몬의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈만한 각 남자를 그 명수대로 다 계수하니'),
(1466398,51,4,1,23,'시므온 지파의 계수함을 입은 자가 오만 구천 삼백명이었더라'),
(1466399,51,4,1,24,'갓의 아들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466400,51,4,1,25,'갓 지파의 계수함을 입은 자가 사만 오천 육백 오십명이었더라'),
(1466401,51,4,1,26,'유다의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466402,51,4,1,27,'유다 지파의 계수함을 입은자가 칠만 사천 육백명이었더라'),
(1466403,51,4,1,28,'잇사갈의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466404,51,4,1,29,'잇사갈 지파의 계수함을 입은자가 오만 사천 사백명이었더라'),
(1466405,51,4,1,30,'스불론의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466406,51,4,1,31,'스불론 지파의 계수함을 입은 자가 오만 칠천 사백명이었더라'),
(1466407,51,4,1,32,'요셉의 아들 에브라임의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466408,51,4,1,33,'에브라임 지파의 계수함을 입은 자가 사만 오백명이었더라'),
(1466409,51,4,1,34,'므낫세의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466410,51,4,1,35,'므낫세 지파의 계수함을 입은 자가 삼만 이천 이백명이었더라'),
(1466411,51,4,1,36,'베냐민의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466412,51,4,1,37,'단의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466413,51,4,1,38,'베냐민 지파의 계수함을 입은 자가 삼만 오천 사백명이었더라'),
(1466414,51,4,1,39,'단의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466415,51,4,1,40,'베냐민 지파의 계수함을 입은 자가 삼만 오천 사백명이었더라'),
(1466416,51,4,1,41,'단 지파의 계수함을 입은 자가 육만 이천 칠백명이었더라'),
(1466417,51,4,1,42,'아셀의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466418,51,4,1,43,'아셀 지파의 계수함을 입은 자가 사만 일천 오백명이었더라'),
(1466419,51,4,1,44,'납달리의 아들들에게서 난 자를 그들의 가족과 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자를 그 명수대로 다 계수하니'),
(1466420,51,4,1,45,'납달리 지파의 계수함을 입은 자가 오만 삼천 사백명이었더라'),
(1466421,51,4,1,46,'이 계수함을 입은 자는 모세와 아론과 각기 이스라엘 종족을 대표한 족장 십 이인이 계수한 자라'),
(1466422,51,4,1,47,'이같이 이스라엘 자손의 그 종족을 따라 이십세 이상으로 싸움에 나갈 만한 자가 이스라엘 중에서 다 계수함을 입었으니'),
(1466423,51,4,1,48,'계수함을 입은 자의 총계가 육십만 삼천 오백 오십명이었더라'),
(1466424,51,4,1,49,'오직 레위인은 그 조상의 지파대로 그 계수에 들지 아니하였으니'),
(1466425,51,4,1,50,'이는 여호와께서 모세에게 일러 가라사대'),
(1466426,51,4,1,51,'레위 지파만은 너는 계수치 말며 그들을 이스라엘 자손 계수중에 넣지 말고'),
(1466427,51,4,1,52,'그들을 증거막과 그 모든 기구와 그 모든 부속품을 관리하게 하라'),
(1466428,51,4,1,53,'그들은 그 장막과 그 모든 기구를 운반하며 거기서 봉사하며 장막 사면에 진을 칠지며'),
(1466429,51,4,1,54,'장막을 운반할 때에는 레위인이 그것을 걷고 장막을 세울 때에는 레위인이 그것을 세울 것이요 외인이 가까이 오면 죽일지며'),
(1466430,51,4,1,55,'레위인은 증거막 사면에 진을 쳐서 이스라엘 자손의 회중에게 진노가 임하지 않게 할 것이라 레위인은 증거막에 대한 책임을 지킬지니라 ! 하셨음이라'),
(1466431,51,4,1,56,'이스라엘 자손이 그대로 행하되 여호와께서 모세에게 명하신 대로 행하였더라'),
(1466432,51,4,2,1,'여호와께서 모세와 아론에게 일러 가라사대'),
(1466433,51,4,2,2,'이스라엘 자손은 각각 그 기와 그 종족의 기호 곁에 진을 치되 회막을 사면으로 대하여 치라'),
(1466434,51,4,2,3,'동방 해 돋는 편에 진 칠 자는 그 군대대로 유다의 진기에 속한자라 유다 자손의 족장은 암미나답의 아들 나손이요');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466435,51,4,2,4,'그 군대는 계수함을 입은 자가 칠만 사천 육백명이며'),
(1466436,51,4,2,5,'그 곁에 진 칠 자는 잇사갈 지파라 잇사갈 자손의 족장은 수알의 아들 느다넬이요'),
(1466437,51,4,2,6,'그 군대는 계수함을 입은 자 오만 사천 사백명이며'),
(1466438,51,4,2,7,'또 스불론 지파라 스불론 자손의 족장은 헬론의 아들 엘리압이요'),
(1466439,51,4,2,8,'그 군대는 계수함을 입은 자 오만 칠천 사백명이니'),
(1466440,51,4,2,9,'유다 진에 속한 군대의 계수함을 입은 군대의 총계가 십 팔만 육천 사백명이라 그들은 제 일대로 진행할지니라'),
(1466441,51,4,2,10,'남편에는 르우벤 군대의 진 기가 있을 것이라 르우벤 자손의 족장은 스데울의 아들 엘리술이요'),
(1466442,51,4,2,11,'그 군대는 계수함을 입은 자 사만 육천 오백명이며'),
(1466443,51,4,2,12,'그 곁에 진 칠 자는 시므온 지파라 시므온 자손의 족장은 수리삿대의 아들 슬루미엘이요'),
(1466444,51,4,2,13,'그 군대는 계수함을 입은 자 오만 구천 삼백명이며'),
(1466445,51,4,2,14,'또 갓 지파라 갓 자손의 족장은 르우엘의 아들 엘리아삽이요'),
(1466446,51,4,2,15,'그 군대는 계수함을 입은 자 사만 오천 육백 오십명이니'),
(1466447,51,4,2,16,'르우벤 진에 속한 계수함을 입은 군대의 총계가 십 오만 일천 사백 오십명이라 그들은 제 이대로 진행할지니라'),
(1466448,51,4,2,17,'그 다음에 회막이 레위인의 진과 함께 모든 진의 중앙에 있어 진행하되 그들의 진 친 순서대로 각 사람은 그 위치에서 그 기를 따라 앞으로 행할지니라'),
(1466449,51,4,2,18,'서편에는 에브라임의 군대의 진 기가 있을 것이라 에브라임 자손의 족장은 암미훗의 아들 엘리사마요'),
(1466450,51,4,2,19,'그 군대는 계수함을 입은 자 사만 오백명이며'),
(1466451,51,4,2,20,'그 곁에는 므낫세 지파가 있을 것이라 므낫세 자손의 족장은 브다술의 아들 가말리엘이요'),
(1466452,51,4,2,21,'그 군대는 계수함을 입은 자 삼만 이천 이백명이며'),
(1466453,51,4,2,22,'또 베냐민 지파라 베냐민 자손의 족장은 기드오니의 아들 아비단이요'),
(1466454,51,4,2,23,'그 군대는 계수함을 입은 자 삼만 오천 사백명이니'),
(1466455,51,4,2,24,'에브라임 진에 속한 계수함을 입은 군대의 총계가 십만 팔천 일백명이라 그들은 제 삼대로 진행할지니라'),
(1466456,51,4,2,25,'북편에는 단 군대의 진 기가 있을 것이라 단 자손의 족장은 암미삿대의 아들 아히에셀이요'),
(1466457,51,4,2,26,'그 군대는 계수함을 입은 자 육만 이천 칠백명이며'),
(1466458,51,4,2,27,'그 곁에 진 칠 자는 아셀 지파라 아셀 자손의 족장은 오그란의 아들 바기엘이요'),
(1466459,51,4,2,28,'그 군대는 계수함을 입은 자 사만 일천 오백명이며'),
(1466460,51,4,2,29,'또 납달리 지파라 납달리 자손의 족장은 에난의 아들 아히라요'),
(1466461,51,4,2,30,'그 군대는 계수함을 입은 자 오만 삼천 사백명이니'),
(1466462,51,4,2,31,'단의 진에 속한 계수함을 입은 군대의 총계가 십 오만 칠천 육백명이라 그들은 기를 따라 후대로 진행할지니라 하시니라'),
(1466463,51,4,2,32,'이상은 이스라엘 자손이 그 종족을 따라 계수함을 입은 자니 모든 진의 군대 곧 계수함을 입은 총계가 육십만 삼천 오백 오십명이었으며'),
(1466464,51,4,2,33,'레위인은 이스라엘 자손과 함께 계수되지 아니하였으니 여호와께서 모세에게 명하심과 같았느니라'),
(1466465,51,4,2,34,'이스라엘 자손이 여호와께서 모세에게 명하신대로 다 준행하여 각기 가족과 종족을 따르며 그 기를 따라 진 치기도 하며 진행하기도 하였더라'),
(1466466,51,4,3,1,'여호와께서 시내 산에서 모세와 말씀하실 때에 아론과 모세의 낳은 자가 이러하니라'),
(1466467,51,4,3,2,'아론의 아들들의 이름은 장자는 나답이요, 다음은 아비후와, 엘르아살과, 이다말이니'),
(1466468,51,4,3,3,'이는 아론의 아들들의 이름이며 그들은 기름을 발리우고 거룩히 구별되어 제사장 직분을 위임받은 제사장들이라'),
(1466469,51,4,3,4,'나답과 아비후는 시내 광야에서 다른 불을 여호와 앞에 드리다가 여호와 앞에서 죽었고 무자하였고 엘리아살과, 이다말이 그 아비 아론 앞에서 제사장의 직분을 행하였더라'),
(1466470,51,4,3,5,'여호와께서 또 모세에게 일러 가라사대'),
(1466471,51,4,3,6,'레위 지파로 나아와 제사장 아론 앞에 서서 그에게 시종하게 하라'),
(1466472,51,4,3,7,'그들이 회막 앞에서 아론의 직무와 온 회중의 직무를 위하여 회막에서 시무하되'),
(1466473,51,4,3,8,'곧 회막의 모든 기구를 수직하며 이스라엘 자손의 직무를 위하여 장막에서 시무할지니'),
(1466474,51,4,3,9,'너는 레위인을 아론과 그 아들들에게 주라 그들은 이스라엘 자손중에서 아론에게 온전히 돌리운 자니라'),
(1466475,51,4,3,10,'너는 아론과 그 아들들을 세워 제사장 직분을 행하게 하라 외인이 가까이 하면 죽임을 당할 것이니라'),
(1466476,51,4,3,11,'여호와께서 모세에게 일러 가라사대'),
(1466477,51,4,3,12,'보라 내가 이스라엘 자손 중에서 레위인을 택하여 이스라엘 자손 중 모든 첫 태에 처음 난 자를 대신케 하였은즉 레위인은 내 것이라 !'),
(1466478,51,4,3,13,'처음 난 자는 다 내 것임은 내가 애굽 땅에서 그 처음 난 자를 다 죽이던 날에 이스라엘의 처음 난 자는 사람이나 짐승을 다 거룩히 구별하였음이니 그들은 내 것이 될 것임이니라'),
(1466479,51,4,3,14,'여호와께서 시내 광야에서 모세에게 일러 가라사대'),
(1466480,51,4,3,15,'레위 자손을 그들의 종족과 가족을 따라 계수하되 일개월 이상의 남자를 다 계수하라'),
(1466481,51,4,3,16,'모세가 여호와의 말씀을 좇아 그 명하신 대로 계수하니라'),
(1466482,51,4,3,17,'레위의 아들들의 이름은 이러하니 게르손과, 고핫과, 므라리요'),
(1466483,51,4,3,18,'게르손의 아들들의 이름은 그 가족대로 이러하니 립니와, 시므이요'),
(1466484,51,4,3,19,'고핫의 아들들은 그 가족대로 이러하니 아므람과, 이스할과, 헤브론과, 웃시엘이요');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466485,51,4,3,20,'므라리의 아들들은 그 가족대로 말리와, 무시니 이는 그 종족대로된 레위인의 가족들이니라'),
(1466486,51,4,3,21,'게르손에게서는 립니 가족과, 시므이 가족이 났으니 이들이 곧 게르손의 가족들이라'),
(1466487,51,4,3,22,'계수함을 입은 자의 수효 곧 일개월 이상 남자의 수효 합계가 칠천 오백명이며'),
(1466488,51,4,3,23,'게르손 가족들은 장막 뒤 곧 서편에 진을 칠 것이요'),
(1466489,51,4,3,24,'라엘의 아들 엘리아삽은 게르손 사람의 종족의 족장이 될것이며'),
(1466490,51,4,3,25,'게르손 자손의 회막에 대하여 맡을 것은 성막과, 장막과, 그 덮개와, 회막 문장과,'),
(1466491,51,4,3,26,'뜰의 휘장과, 및 성막과, 단 사면에 있는 뜰의 문장과, 그 모든 것에 쓰는 줄들이니라'),
(1466492,51,4,3,27,'고핫에게서는 아므람 가족과, 이스할 가족과, 헤브론 가족과, 웃시엘 가족이 났으니 이들이 곧 고핫 가족들이라'),
(1466493,51,4,3,28,'계수함을 입은 일개월 이상 모든 남자의 수효가 팔천 육백명인데 성소를 맡을 것이며'),
(1466494,51,4,3,29,'고핫 자손의 가족들은 성막 남편에 진을 칠 것이요'),
(1466495,51,4,3,30,'웃시엘의 아들 엘리사반은 고핫 사람의 가족과, 종족의 족장이 될것이며'),
(1466496,51,4,3,31,'그들의 맡을 것은 증거궤와, 상과, 등대와, 단들과, 성소에서 봉사하는데 쓰는 기구들과 휘장과 그것에 쓰는 모든 것이며'),
(1466497,51,4,3,32,'제사장 아론의 아들 엘리아살은 레위인의 족장들의 어른이 되고 또 성소를 맡을 자를 통할할 것이니라'),
(1466498,51,4,3,33,'므라리에게서는 말리 가족과 무시 가족이 났으니 이들이 곧 므라리 가족들이라'),
(1466499,51,4,3,34,'그 계수함을 입은 자 곧 일개월 이상 남자의 수효 총계가 육천 이백명이며'),
(1466500,51,4,3,35,'아비하일의 아들 수리엘이 므라리 가족과 종족의 족장이 될 것이요 이 가족은 장막 북편에 진을 칠 것이며'),
(1466501,51,4,3,36,'므라리 자손의 맡을 것은 성막의 널판과, 그 띠와, 그 기둥과, 그 받침과, 그 모든 기구와, 그것에 쓰는 모든 것이며,'),
(1466502,51,4,3,37,'뜰 사면 기둥과, 그 받침과, 그 말뚝과, 그 줄들이니라'),
(1466503,51,4,3,38,'장막 앞 동편 곧 회막 앞 해 돋는 편에는 모세와, 아론과, 아론의 아들들이 진을 치고 이스라엘 자손의 직무를 대신하여 성소의 직무를 지킬 것이며 외인이 가까이 하면 죽일지니라 !'),
(1466504,51,4,3,39,'모세와 아론이 여호와의 명을 좇아 레위인을 각 가족대로 계수한즉 일개월 이상 남자의 수효가 이만 이천명이었더라'),
(1466505,51,4,3,40,'여호와께서 또 모세에게 이르시되 이스라엘 자손의 처음 난 남자를 일개월 이상으로 다 계수하여 그 명수를 기록하라'),
(1466506,51,4,3,41,'나는 여호와라 ! 이스라엘 자손 중 모든 처음 난 자의 대신에 레위인을 내게 돌리고 또 이스라엘 자손의 가축 중 모든 처음 난 것의 대신에 레위인의 가축을 내게 돌리라'),
(1466507,51,4,3,42,'모세가 여호와께서 자기에게 명하신 대로 이스라엘 자손 중 모든 처음 난 자를 계수하니'),
(1466508,51,4,3,43,'일개월 이상으로 계수함을 입은 처음 난 남자의 명수의 총계가 이만 이천 이백 칠십 삼명이었더라'),
(1466509,51,4,3,44,'여호와께서 모세에게 일러 가라사대'),
(1466510,51,4,3,45,'이스라엘 자손 중 모든 처음 난 자의 대신에 레위인을 취하고 또 그들의 가축 대신에 레위인의 가축을 취하라 레위인은 내 것이라 나는 여호와니라 !'),
(1466511,51,4,3,46,'이스라엘 자손의 처음 난 자가 레위인보다 이백 칠십 삼인이 더 한즉 속하기 위하여'),
(1466512,51,4,3,47,'매명에 오세겔씩 취하되 성소의 세겔대로 취하라 한 세겔은 이십 게라니라'),
(1466513,51,4,3,48,'그 더한 자의 속전을 아론과 그 아들들에게 줄 것이니라'),
(1466514,51,4,3,49,'모세가 레위인으로 대속한 이외의 사람들에게서 속전을 받았으니'),
(1466515,51,4,3,50,'곧 이스라엘 자손의 처음 난 자에게서 받은 돈이 성소의 세겔대로 일천 삼백 육십 오 세겔이라'),
(1466516,51,4,3,51,'이 속전을 여호와의 말씀대로 아론과 그 아들들에게 주었으니 여호와께서 모세에게 명하심과 같았느니라'),
(1466517,51,4,4,1,'여호와께서 또 모세와 아론에게 일러 가라사대'),
(1466518,51,4,4,2,'레위 자손 중에서 고핫 자손을 그들의 가족과 종족을 따라 총계할지니'),
(1466519,51,4,4,3,'곧 삼십세 이상으로 오십세까지 회막의 일을 하기 위하여 그 역사에 참가할 만한 모든 자를 계수하라'),
(1466520,51,4,4,4,'고핫 자손의 회막 안 지성물에 대하여 할 일은 이러하니라'),
(1466521,51,4,4,5,'행진할 때에 아론과 그 아들들이 들어가서 간 막는 장을 걷어 증거궤를 덮고'),
(1466522,51,4,4,6,'그 위에 해달의 가죽으로 덮고 그 위에 순청색 보자기를 덮은후에 그 채를 꿰고'),
(1466523,51,4,4,7,'또 진설병의 상에 청색 보자기를 펴고 대접들과, 숟가락들과, 주발들과, 붓는 잔들을 그 위에 두고 또 항상 진설하는 떡을 그 위에 두고'),
(1466524,51,4,4,8,'홍색 보자기를 그 위에 펴고 그것을 해달의 가죽 덮개로 덮은후에 그 채를 꿰고'),
(1466525,51,4,4,9,'또 청색 보자기를 취하여 등대와, 그 등잔들과, 그 불집게들과, 불똥 그릇들과, 그 쓰는 바 모든 기름 그릇을 덮고'),
(1466526,51,4,4,10,'등대와 그 모든 기구를 해달의 가죽 덮개 안에 넣어 메는 틀위에 두고'),
(1466527,51,4,4,11,'또 금단 위에 청색 보자기를 펴고 해달의 가죽 덮개로 덮고 그 채를 꿰고'),
(1466528,51,4,4,12,'또 성소에서 봉사하는 데 쓰는 모든 기명을 취하여 청색 보자기에 싸서 해달의 가죽 덮개로 덮어 메는 틀 위에 두고'),
(1466529,51,4,4,13,'또 단의 재를 버리고 그 단 위에 자색 보자기를 펴고'),
(1466530,51,4,4,14,'봉사하는 데 쓰는 모든 기구 곧 불 옮기는 그릇들과, 고기 갈고리들과, 부삽들과, 대야들과, 단의 모든 기구를 두고 해달의 가죽 덮개를 그 위에 덮고 그 채를 꿸 것이며'),
(1466531,51,4,4,15,'행진할 때에 아론과 그 아들들이 성소와 성소의 모든 기구 덮기를 필하거든 고핫 자손이 와서 멜 것이니라 그러나 성물은 만지지 말지니 죽을까 하노라 회막 물건 중에서 이것들은 고핫 자손이 멜 것이며'),
(1466532,51,4,4,16,'제사장 아론의 아들 엘르아살의 맡을 것은 등유와, 분향할 향품과, 항상 드리는 소제물과, 관유며, 또 장막의 전체와, 그 중에 있는 모든 것과, 성소와, 그 모든 기구니라'),
(1466533,51,4,4,17,'여호와께서 또 모세와 아론에게 일러 가라사대'),
(1466534,51,4,4,18,'너희는 고핫 족속의 지파를 레위인 중에서 끊어지게 말지니');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466535,51,4,4,19,'그들이 지성물에 접근할 때에 그 생명을 보존하고 죽지 않게 하기 위하여 너희는 이같이 하여 아론과 그 아들들이 들어가서 각 사람에게 그 할 일과 그 멜 것을 지휘할지니라'),
(1466536,51,4,4,20,'그들은 잠시라도 들어가서 성소를 보지 말것은 죽을까 함이니라'),
(1466537,51,4,4,21,'여호와께서 또 모세에게 일러 가라사대'),
(1466538,51,4,4,22,'게르손 자손도 그 종족과 가족을 따라 총계하되'),
(1466539,51,4,4,23,'삼십세 이상으로 오십세까지 회막 봉사에 입참하여 일할 만한 모든 자를 계수하라'),
(1466540,51,4,4,24,'게르손 가족의 할 일과 멜 것은 이러하니'),
(1466541,51,4,4,25,'곧 그들은 성막의 앙장들과, 회막과, 그 덮개와, 그 위의 해달의 가죽 덮개와, 회막 문장을 메이며'),
(1466542,51,4,4,26,'뜰의 휘장과, 및 성막과, 단 사면에 있는 뜰의 문장과, 그 줄들과, 그것에 사용하는 모든 기구를 메이며 이 모든 것을 어떻게 맡아 처리할 것이라'),
(1466543,51,4,4,27,'게르손 자손은 그 모든 일 곧 멜 것과 처리할 것에 아론과 그 아들들의 명대로 할 것이니 너희는 그들의 멜 짐을 그들에게 맡길 것이니라'),
(1466544,51,4,4,28,'게르손 자손의 가족들이 회막에서 할 일이 이러하며 그들의 직무는 제사장 아론의 아들 이다말이 감독할지니라'),
(1466545,51,4,4,29,'너는 므라리 자손도 그 가족과 종족을 따라 계수하되'),
(1466546,51,4,4,30,'삼십세 이상으로 오십세까지 회막 봉사에 입참하여 일할 만한 모든 자를 계수하라'),
(1466547,51,4,4,31,'그들이 직무를 따라 회막에서 할 모든 일 곧 그 멜 것이 이러하니 곧 장막의 널판들과, 그 띠들과, 그 기둥들과, 그 받침들과,'),
(1466548,51,4,4,32,'뜰 사면 기둥들과, 그 받침들과, 그 말뚝들과, 그 줄들과, 그 모든 기구들과, 무릇 그것에 쓰는 것이라 너희는 그들의 맡아 멜 모든 기구의 명목을 지정하라'),
(1466549,51,4,4,33,'이는 제사장 아론의 아들 이다말의 수하에 있을 므라리 자손의 가족들이 그 모든 사무대로 회막에서 행할 일이니라'),
(1466550,51,4,4,34,'모세와 아론과 회중의 족장들이 고핫 자손들을 그 가족과 종족대로 계수하니'),
(1466551,51,4,4,35,'삼십세 이상으로 오십세까지 회막 봉사에 입참하여 일할 만한 모든 자'),
(1466552,51,4,4,36,'곧 그 가족대로 계수함을 입은 자가 이천 칠백 오십이니'),
(1466553,51,4,4,37,'이는 모세와 아론이 여호와께서 모세로 명하신 대로 회막에서 종사하는 고핫인의 모든 가족 중 계수한 자니라'),
(1466554,51,4,4,38,'게르손 자손의 그 가족과 종족을 따라 계수함을 입은 자는'),
(1466555,51,4,4,39,'삼십세 이상으로 오십세까지 회막 봉사에 입참하여 일할 만한 모든 자라'),
(1466556,51,4,4,40,'그 가족과 종족을 따라 계수함을 입은 자가 이천 육백 삼십명이니'),
(1466557,51,4,4,41,'이는 모세와 아론이 여호와의 명대로 회막에서 종사하는 게르손 자손의 모든 가족 중 계수한 자니라'),
(1466558,51,4,4,42,'므라리 자손의 가족 중 그 가족과 종족을 따라 계수함을 입은 자는'),
(1466559,51,4,4,43,'삼십세 이상으로 오십세까지 회막 봉사에 입참하여 일할 만한 모든 자라'),
(1466560,51,4,4,44,'그 가족을 따라 계수함을 입은 자가 삼천 이백명이니'),
(1466561,51,4,4,45,'이는 모세와 아론이 여호와께서 모세로 명하신 대로 므라리 자손들의 가족 중 계수한 자니라'),
(1466562,51,4,4,46,'모세와 아론과 이스라엘 족장들이 레위인을 그 가족과 종족대로 다 계수하니'),
(1466563,51,4,4,47,'삼십세 이상으로 오십세까지 회막 봉사와 메는 일에 입참하여 일할 만한 모든 자'),
(1466564,51,4,4,48,'곧 그 계수함을 입은 자가 팔천 오백 팔십명이라'),
(1466565,51,4,4,49,'그들이 그 할 일과 멜일을 따라 모세에게 계수함을 입었으되 여호와께서 모세에게 명하신 대로 그들이 계수함을 입었더라'),
(1466566,51,4,5,1,'여호와께서 모세에게 일러 가라사대'),
(1466567,51,4,5,2,'이스라엘 자손에게 명하여 모든 문둥병 환자와 유출병이 있는 자와 주검으로 부정케 된 자를 다 진 밖으로 내어 보내되'),
(1466568,51,4,5,3,'무론 남녀하고 다 진 밖으로 내어 보내어 그들로 진을 더럽히게 말라 내가 그 진 가운데 거하느니라 하시매'),
(1466569,51,4,5,4,'이스라엘 자손이 그같이 행하여 그들을 진 밖으로 내어 보내었으니 곧 여호와께서 모세에게 이르신대로 이스라엘 자손이 행하였더라'),
(1466570,51,4,5,5,'여호와께서 또 모세에게 일러 가라사대'),
(1466571,51,4,5,6,'이스라엘 자손에게 이르라 남자나 여자나 사람들이 범하는 죄를 범하여 여호와께 패역하여 그 몸에 죄를 얻거든'),
(1466572,51,4,5,7,'그 지은 죄를 자복하고 그 죄 값을 온전히 갚되 오분지 일을 더하여 그가 죄를 얻었던 그 본주에게 돌려 줄 것이요'),
(1466573,51,4,5,8,'만일 죄 값을 받을 만한 친족이 없거든 그 죄 값을 여호와께 드려 제사장에게로 돌릴 것이니 이는 그를 위하여 속죄할 수양 외에 돌릴 것이니라'),
(1466574,51,4,5,9,'이스라엘 자손의 거제로 제사장에게 가져 오는 모든 성물은 그의 것이 될 것이라'),
(1466575,51,4,5,10,'각 사람의 구별한 물건은 그의 것이 되나니 누구든지 제사장에게 주는 것은 그의 것이 되느니라'),
(1466576,51,4,5,11,'여호와께서 모세에게 일러 가라사대'),
(1466577,51,4,5,12,'이스라엘 자손에게 고하여 그들에게 이르라 만일 어떤 사람의 아내가 실행하여 남편에게 범죄하여'),
(1466578,51,4,5,13,'타인과 정교를 하였으나 그 남편의 눈에 숨겨 드러나지 아니하였고 그 여자의 더러워진 일에 증인도 없고 그가 잡히지 아니하였어도'),
(1466579,51,4,5,14,'그 더러워짐을 인하여 남편이 의심이 생겨서 그 아내를 의심하든지 또는 아내가 더럽히지 아니하였어도 그 남편이 의심이 생겨서그 아내를 의심하거든'),
(1466580,51,4,5,15,'그 아내를 데리고 제사장에게로 가서 그를 위하여 보리 가루 에바 십분지 일을 예물로 드리되 그것에 기름도 붓지 말고 유향도 두지 말라 이는 의심의 소제요 생각하게 하는 소제니 곧 죄악을 생각하게 하는 것이니라'),
(1466581,51,4,5,16,'제사장은 그 여인으로 가까이 오게 하여 여호와 앞에 세우고'),
(1466582,51,4,5,17,'토기에 거룩한 물을 담고 성막 바닥의 티끌을 취하여 물에 넣고'),
(1466583,51,4,5,18,'여인을 여호와 앞에 세우고 그 머리를 풀게 하고 생각하게 하는 소제물 곧 의심의 소제물을 그 두 손에 두고 제사장은 저주가 되게 할 쓴 물을 자기 손에 들고'),
(1466584,51,4,5,19,'여인에게 맹세시켜 그에게 이르기를 네가 네 남편을 두고 실행하여 사람과 동침하여 더럽힌 일이 없으면 저주가 되게 하는 이 쓴물의 해독을 면하리라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466585,51,4,5,20,'그러나 네가 네 남편을 두고 실행하여 더럽혀서 네 남편 아닌 사람과 동침하였으면'),
(1466586,51,4,5,21,'제사장이 그 여인으로 저주의 맹세를 하게 하고 그 여인에게 말할지니라 여호와께서 네 넓적다리로 떨어지고 네 배로 부어서 너로 네 백성 중에 저줏거리, 맹셋거리가 되게 하실지라'),
(1466587,51,4,5,22,'이 저주가 되게 하는 이 물이 네 창자에 들어 가서 네 배로 붓게하고 네 넓적다리로 떨어지게 하리라 할 것이요 여인은 아멘, 아멘 할지니라'),
(1466588,51,4,5,23,'제사장이 저주의 말을 두루마리에 써서 그 글자를 그 쓴 물에 빨아 넣고'),
(1466589,51,4,5,24,'여인으로 그 저주가 되게 하는 쓴 물을 마시게 할지니 그 저주가 되게 하는 물이 그 속에 들어가서 쓰리라'),
(1466590,51,4,5,25,'제사장이 먼저 그 여인의 손에서 의심의 소제물을 취하여 그 소제물을 여호와 앞에 흔들고 가지고 단으로 가서'),
(1466591,51,4,5,26,'그 소제물 중에서 기념으로 한 움큼을 취하여 단 위에 소화하고 그 후에 여인에게 그 물을 마시울지라'),
(1466592,51,4,5,27,'그 물을 마시운 후에 만일 여인이 몸을 더럽혀서 그 남편에게 범죄하였으면 그 저주가 되게 하는 물이 그의 속에 들어가서 쓰게 되어 그 배가 부으며 그 넓적다리가 떨어지리니 그 여인이 백성 중에서 저줏거리가 될 것이니라'),
(1466593,51,4,5,28,'그러나 여인이 더럽힌 일이 없고 정결하면 해를 받지 않고 잉태하리라'),
(1466594,51,4,5,29,'이는 의심의 법이니 아내가 그 남편을 두고 실행하여 더럽힌 때나'),
(1466595,51,4,5,30,'또는 그 남편이 의심이 생겨서 그 아내를 의심할 때에 그 여인을 여호와 앞에 두고 제사장이 이 법대로 행할 것이라'),
(1466596,51,4,5,31,'남편은 무죄할 것이요 여인은 죄가 있으면 당하리라'),
(1466597,51,4,6,1,'여호와께서 모세에게 일러 가라사대'),
(1466598,51,4,6,2,'이스라엘 자손에게 고하여 그들에게 이르라 남자나 여자가 특별한 서원 곧 나실인의 서원을 하고 자기 몸을 구별하여 여호와께 드리거든'),
(1466599,51,4,6,3,'포도주와 독주를 멀리하며 포도주의 초나 독주의 초를 마시지 말며 포도즙도 마시지 말며 생포도나 건포도도 먹지 말지니'),
(1466600,51,4,6,4,'자기 몸을 구별하는 모든 날 동안에는 포도나무 소산은 씨나 껍질이라도 먹지말지며'),
(1466601,51,4,6,5,'그 서원을 하고 구별하는 모든 날 동안은 삭도를 도무지 그 머리에 대지 말 것이라 자기 몸을 구별하여 여호와께 드리는 날이 차기까지 그는 거룩한즉 그 머리털을 길게 자라게 할 것이며'),
(1466602,51,4,6,6,'자기 몸을 구별하여 여호와께 드리는 모든 날 동안은 시체를 가까이 하지 말 것이요'),
(1466603,51,4,6,7,'그 부모 형제 자매가 죽은 때에라도 그로 인하여 더럽히지 말것이니 이는 자기 몸을 구별하여 하나님께 드리는 표가 그 머리에 있음이라'),
(1466604,51,4,6,8,'자기 몸을 구별하는 모든 날 동안 그는 여호와께 거룩한 자니라'),
(1466605,51,4,6,9,'누가 홀연히 그 곁에서 죽어서 스스로 구별한 자의 머리를 더럽히거든 그 몸을 정결케 하는 날에 머리를 밀 것이니 곧 제 칠일에 밀 것이며'),
(1466606,51,4,6,10,'제 팔일에 산비둘기 두 마리나 집비둘기 새끼 두 마리를 가지고 회막 문에 와서 제사장에게 줄 것이요'),
(1466607,51,4,6,11,'제사장은 그 하나를 속죄제물로, 하나를 번제물로 드려서 그의 시체로 인하여 얻은 죄를 속하고 또 그는 당일에 그의 머리를 성결케 할 것이며'),
(1466608,51,4,6,12,'자기 몸을 구별하여 여호와께 드릴 날을 새로 정하고 일년 된 수양을 가져다가 속건제로 드릴지니라 자기 몸을 구별한 때에 그 몸을 더렵혔은즉 지나간 날은 무효니라'),
(1466609,51,4,6,13,'나실인의 법은 이러하니라 자기 몸을 구별한 날이 차면 그 사람을 회막 문으로 데리고 갈 것이요'),
(1466610,51,4,6,14,'그는 여호와께 예물을 드리되 번제물로 일년 된 흠 없는 수양 하나와 속죄제물로 일년 된 흠 없는 어린 암양 하나와 화목제물로 흠 없는 수양 하나와'),
(1466611,51,4,6,15,'무교병 한 광주리와 고운 가루에 기름 섞은 과자들과 기름 바른 무교전병들과 그 소제물과 전제물을 드릴 것이요'),
(1466612,51,4,6,16,'제사장은 그것들을 여호와 앞에 가져다가 속죄제와 번제를 드리고'),
(1466613,51,4,6,17,'화목제물로 수양에 무교병 한 광주리를 아울러 여호와께 드리고 그 소제와 전제를 드릴 것이요'),
(1466614,51,4,6,18,'자기 몸을 구별한 나실인은 회막 문에서 그 머리털을 밀고 그것을 화목제물 밑에 있는 불에 둘지며'),
(1466615,51,4,6,19,'자기 몸을 구별한 나실인이 그 머리털을 민 후에 제사장이 삶은 수양의 어깨와 광주리 가운데 무교병 하나와 무교전병 하나를 취하여 나실인의 두 손에 두고'),
(1466616,51,4,6,20,'여호와 앞에 요제로 흔들 것이며 그것과 흔든 가슴과 든 넓적다리는 성물이라 다 제사장에게 돌릴 것이니라 그 후에는 나실인이 포도주를 마실 수 있느니라'),
(1466617,51,4,6,21,'이는 곧 서원한 나실인이 자기 몸을 구별한 일로 인하여 여호와께 예물을 드림과 행할 법이며 이 외에도 힘이 미치는 대로 하려니와 그 서원 한대로 자기 몸을 구별하는 법을 따라 할 것이니라'),
(1466618,51,4,6,22,'여호와께서 모세에게 일러 가라사대'),
(1466619,51,4,6,23,'아론과 그 아들들에게 고하여 이르기를 너희는 이스라엘 자손을 위하여 이렇게 축복하여 이르되'),
(1466620,51,4,6,24,'여호와는 네게 복을 주시고 너를 지키시기를 원하며'),
(1466621,51,4,6,25,'여호와는 그 얼굴로 네게 비취사 은혜 베푸시기를 원하며'),
(1466622,51,4,6,26,'여호와는 그 얼굴을 네게로 향하여 드사 평강주시기를 원하노라 할지니라 하라'),
(1466623,51,4,6,27,'그들은 이같이 내 이름으로 이스라엘 자손에게 축복할지니 내가 그들에게 복을 주리라 !'),
(1466624,51,4,7,1,'모세가 장막 세우기를 필하고 그것에 기름을 발라 거룩히 구별하고 또 그 모든 기구와 단과 그 모든 기구에 기름을 발라 거룩히 구별한 날에'),
(1466625,51,4,7,2,'이스라엘 족장들 곧 그들의 종족의 두령들이요 그 지파의 족장으로서 그 계수함을 입은 자의 감독된 자들이 예물을 드렸으니'),
(1466626,51,4,7,3,'그들의 여호와께 드린 예물은 덮개 있는 수레 여섯과 소 열 둘이니 족장 둘에 수레가 하나씩이요 하나에 소가 하나씩이라 그것들을 장막 앞에 드린지라'),
(1466627,51,4,7,4,'여호와께서 모세에게 일러 가라사대'),
(1466628,51,4,7,5,'그것을 그들에게서 받아 레위인에게 주어 각기 직임대로 회막 봉사에 쓰게 할지니라'),
(1466629,51,4,7,6,'모세가 수레와 소를 받아 레위인에게 주었으니'),
(1466630,51,4,7,7,'곧 게르손 자손들에게는 그 직임대로 수레 둘과, 소 넷을 주었고'),
(1466631,51,4,7,8,'므라리 자손들에게는 그 직임대로 수레 넷과, 소 여덟을 주고 제사장 아론의 아들 이다말로 감독케 하였으나'),
(1466632,51,4,7,9,'고핫 자손에게는 주지 아니하였으니 그들의 성소의 직임은 그 어깨로 메는 일을 하는 까닭이었더라'),
(1466633,51,4,7,10,'단에 기름을 바르던 날에 족장들이 단의 봉헌을 위하여 예물을 가져다가 그 예물을 단 앞에 드리니라'),
(1466634,51,4,7,11,'여호와께서 모세에게 이르시기를 족장들은 하루 한 사람씩 단의 봉헌 예물을 드릴지니라 하셨더라');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1466635,51,4,7,12,'제 일일에 예물을 드린 자는 유다 지파 암미나답의 아들 나손이라'),
(1466636,51,4,7,13,'그 예물은 성소의 세겔대로 일백 삼십 세겔중 은반 하나와 칠십 세겔중 은바리 하나라 이 두 그릇에는 소제물로 기름 섞은 고운 가루를 채웠고'),
(1466637,51,4,7,14,'또 십 세겔중 금숟가락 하나라 그것에는 향을 채웠고'),
(1466638,51,4,7,15,'또 번제물로 수송아지 하나와, 수양 하나와, 일년 된 어린 수양 하나이며'),
(1466639,51,4,7,16,'속죄제물로 수염소 하나이며'),
(1466640,51,4,7,17,'화목제물로 소 둘과, 수양 다섯과, 수염소 다섯과, 일년 된 어린 수양 다섯이라 이는 암미나답의 아들 나손의 예물이었더라'),
(1466641,51,4,7,18,'제 이일에는 잇사갈의 족장 수알의 아들 느다넬이 드렸으니'),
(1466642,51,4,7,19,'그 드린 예물도 성소의 세겔대로 일백 삼십 세겔중 은반 하나와, 칠십 세겔중 은바리 하나라 이 두 그릇에는 소제물로 기름 섞은 고운 가루를 채웠고'),
(1466643,51,4,7,20,'또 십 세겔중 금숟가락 하나라 그것에는 향을 채웠고'),
(1466644,51,4,7,21,'또 번제물로 수송아지 하나와, 수양 하나와, 일년 된 어린 수양 하나이며'),
(1466645,51,4,7,22,'속죄제물로 수염소 하나이며'),
(1466646,51,4,7,23,'화목제물로 소 둘과, 수양 다섯과 수염소 다섯과, 일년된 어린 수양 다섯이라 이는 수알의 아들 느다넬의 예물이었더라'),
(1466647,51,4,7,24,'제 삼일에는 스불론 자손의 족장 헬론의 아들 엘리압이 드렸으니'),
(1466648,51,4,7,25,'그 예물도 성소의 세겔대로 일백 삼십 세겔중 은반 하나와 칠십 세겔중 은바리 하나라 이 두 그릇에는 소제물로 기름 섞은 고운 가루를 채웠고'),
(1466649,51,4,7,26,'또 십 세겔중 금숟가락 하나라 이것에는 향을 채웠고'),
(1466650,51,4,7,27,'또 번제물로 수송아지 하나와 수양 하나와, 일년 된 어린 수양 하나이며'),
(1466651,51,4,7,28,'속죄제물로 수염소 하나이며'),
(1466652,51,4,7,29,'화목제물로 소 둘과, 수양 다섯과, 수염소 다섯과, 일년 된 어린 수양 다섯이라 이는 헬론의 아들 엘리압의 예물이었더라'),
(1466653,51,4,7,30,'제 사일에는 르우벤 자손의 족장 스데울의 아들 엘리술이 드렸으니'),
(1466654,51,4,7,31,'그 예물도 성소의 세겔대로 일백 삼십 세겔중 은반 하나와 칠십 세겔중 은바리 하나라 이 두 그릇에는 소제물로 기름 섞은 고운 가루를 채웠고'),
(1466655,51,4,7,32,'또 십세겔중 금숟가락 하나라 이것에는 향을 채웠고'),
(1466656,51,4,7,33,'또 번제물로 수송아지 하나와 수양 하나와, 일년 된 어린 수양 하나이며'),
(1466657,51,4,7,34,'속죄제물로 수염소 하나이며'),
(1466658,51,4,7,35,'화목제물로 소 둘과, 수양 다섯과, 수염소 다섯과, 일년 된 어린 수양 다섯이라 이는 스데울의 아들 엘리술의 예물이었더라'),
(1466659,51,4,7,36,'제 오일에는 시므온 자손의 족장 수리삿대의 아들 슬루미엘이 드렸으니'),
(1466660,51,4,7,37,'그 예물도 성소의 세겔대로 일백 삼십 세겔중 은반 하나와 칠십 세겔중 은바리 하나라 이 두 그릇에는 소제물로 기름 섞은 고운 가루를 채웠고'),
(1466661,51,4,7,38,'또 십 세겔중 금숟가락 하나라 이것에는 향을 채웠고'),
(1466662,51,4,7,39,'또 번제물로 수송아지 하나와 수양 하나와, 일년 된 어린 수양 하나이며'),
(1466663,51,4,7,40,'속죄제물로 수염소 하나이며'),
(1466664,51,4,7,41,'화목제물로 소 둘과, 수양 다섯과, 수염소 다섯과, 일년 된 어린 수양 다섯이라 이는 수리삿대의 아들 슬루미엘의 예물이었더라'),
(1466665,51,4,7,42,'제 육일에는 갓 자손의 족장 드우엘의 아들 엘리아삽이 드렸으니'),
(1466666,51,4,7,43,'그 예물도 성소의 세겔대로 일백 삼십 세겔중 은반 하나와 칠십 세겔중 은바리 하나라 이 두 그릇에는 소제물로 기름 섞은 고운 가루를 채웠고'),
(1466667,51,4,7,44,'또 십 세겔중 금숟가락 하나라 이것에는 향을 채웠고'),
(1466668,51,4,7,45,'또 번제물로 수송아지 하나와, 수양 하나와, 일년 된 어린 수양 하나이며'),
(1466669,51,4,7,46,'속죄제물로 수염소 하나이며'),
(1466670,51,4,7,47,'화목제물로 소 둘과, 수양 다섯과, 수염소 다섯과, 일년 된 어린 수양 다섯이라 이는 드우엘의 아들 엘리아삽의 예물이었더라'),
(1466671,51,4,7,48,'제 칠일에는 에브라임 자손의 족장 암미훗의 아들 엘리사마가 드렸으니'),
(1466672,51,4,7,49,'그 예물도 성소의 세겔대로 일백 삼십 세겔중 은반 하나와 칠십 세겔중 은바리 하나라 이 두 그릇에는 소제물로 기름 섞은 고운 가루를 채웠고'),
